        this.authenticatedClassicSources = Set.of();
        this.classicTitle = "";
        this.classicPersistedTitle = "";
        this.showWorldChat = true;
        this.canWhisper = true;
        this.showTradeChat = true;
        this.excludedNames = ConcurrentHashMap.newKeySet();
        this.playerHp = 100;
        this.playerMaxHp = 100;
        this.playerMp = 10;
        this.playerMaxMp = 10;
        this.playerClassicLevel = 1;
        this.hellClock = new ClassicWorldHell.Clock();
        this.positionX = 100;
        this.positionY = 120;
        NativePlayerCommit.scene(this, -1, "classicWorldMapId");
