        this.classicWorldPinkName = new ClassicWorldPinkNameStatus();
        this.classicWorldPoisonKind = ClassicWorldMonsterPoisonAttack.Kind.NONE;
        this.currentChannelId = -1;
        this.tournamentShopOffers = TournamentShopCatalog.offers(true);
        this.hubChannelId = -1;
