        this.channelPortHandoffTarget = -1;
        this.channelPortHandoffCharacter = "";
        this.classicWorldPortalTransitionShowId = -1;
        Object portalLifecycleLock = new Object();
        this.sourceItemAdmissionGate = new Object();
        this.classicWorldPortalLifecycleLock = portalLifecycleLock;
        this.pendingTransition = PendingTransition.NONE;
        this.pendingNoticeAck = PendingNoticeAck.NONE;
        this.shopPoints = 5000L;
        NativeDeItemApplication.replace(this, new RuntimeInventory(), 0);
        this.activeMagicDollObjectIds = new LinkedHashSet<Long>();
