    private void openClassicWorldCkewEntrance(
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        int characterType = selectedCharacterType();
        if (classicWorldMapId != ClassicWorldDemonTempleCatalog.MAP_ID
                || battleLevel() < 50
                || ClassicWorldCkewCatalog.characterClass(characterType) == null
                || !hub.validClassicWorldCkewParty(this)) {
            System.out.println("[LiTo] C_DIALOG CKEW silent-reject player="
                    + playerName() + " type=" + characterType
                    + " party-mask15=false");
            return;
        }
        GameStateStore.StoryQuestState current =
                state.storyQuests(stateCharacter());
        int step = current.step(ClassicWorldCkewCatalog.QUEST_ID);
        if (step == 0) {
            Map<Integer, Integer> next = new LinkedHashMap<>(current.effective());
            next.put(ClassicWorldCkewCatalog.QUEST_ID,
                    ClassicWorldCkewCatalog.QUEST_STARTED);
            state.saveStoryQuestSteps(stateCharacter(), next);
            System.out.println("[LiTo] C_DIALOG CKEW quest-start player="
                    + playerName() + " quest=122 step=1 native-no-html");
            return;
        }
        if (step == ClassicWorldCkewCatalog.QUEST_ENDED
                || !ClassicWorldCkewCatalog.matchesEntrance(
                        characterType, npc.npcId())) {
            System.out.println("[LiTo] C_DIALOG CKEW silent-reject player="
                    + playerName() + " quest-step=" + step
                    + " entrance=" + npc.npcId());
            return;
        }
        String html = ClassicWorldCkewCatalog.characterClass(
                characterType).entranceHtml();
        sendEncrypted(Protocol.hypertext(npc.objectId(), html, "", List.of()),
                "S_HYPERTEXT CKEW quest=122 step=" + step
                        + " show=" + hub.classicWorldCkewInstances()
                                .showId(sourceCharacterIdentity())
                        + " html=" + html);
    }

