    /** Exact retained L1GuardInstance.onTalkAction response matrix. */
    private void openClassicWorldGuard(
            ClassicWorldNpcCatalog.StaticNpc source,
            ClassicWorldMonsterPopulation.Snapshot actor) throws IOException {
        if (!ClassicWorldGuardCatalog.isGuard(source)
                || !ClassicWorldGuardCatalog.isGuard(actor)
                || source.objectId() != actor.objectId()
                || classicNpcDistance(new ArenaMapCatalog.Point(
                        actor.x(), actor.y())) > 5) {
            System.out.println("[LiTo] C_DIALOG L1Guard rejected dynamic-distance"
                    + " object=" + (actor == null ? 0 : actor.objectId()));
            return;
        }
        ClassicWorldGuardCatalog.TalkProfile profile =
                ClassicWorldGuardCatalog.talkProfile(actor.npcId());
        String html;
        List<String> arguments = List.of();
        String authority = "ordinary";
        if (profile == null) {
            html = source.initialHtml(characterLawful());
        } else {
            CastleSummary castle;
            try {
                castle = effectiveClassicCastleById(profile.castleId());
            } catch (Exception error) {
                throw new IOException("cannot resolve L1Guard castle "
                        + profile.castleId(), error);
            }
            CharacterSummary character = selectedCharacterSummary();
            boolean member = castle != null && character != null
                    && character.clanName() != null
                    && !character.clanName().isBlank()
                    && castle.clanName().equalsIgnoreCase(character.clanName());
            html = member ? profile.memberHtml() : profile.outsiderHtml();
            authority = member ? "member" : "none";
            if (profile.arguments()
                    == ClassicWorldGuardCatalog.TalkArguments.PLAYER_NAME
                    && member) {
                arguments = List.of(playerName());
            } else if (profile.arguments()
                    == ClassicWorldGuardCatalog.TalkArguments.CASTLE_IDENTITY) {
                arguments = List.of(source.nameId(),
                        castle == null ? " " : castle.clanName(),
                        castle == null ? " " : castle.leaderName());
            }
        }
        if (html == null || html.isBlank()) {
            System.out.println("[LiTo] C_DIALOG L1Guard no selected talk row object="
                    + actor.objectId() + " npc=" + actor.npcId());
            return;
        }
        sendEncrypted(Protocol.hypertext(
                        actor.objectId(), html, "", arguments),
                "S_HYPERTEXT L1Guard=" + actor.objectId()
                        + " spawn=" + actor.spawnId() + " npc=" + actor.npcId()
                        + " html=" + html + " authority=" + authority
                        + " dynamic=" + actor.x() + "," + actor.y());
    }

