    private void sendHeineCastleDoorAttributes(
            ClassicWorldHeineCatalog.Door door, int passable, String reason)
            throws IOException {
        for (int edge = door.edgeLow(); edge <= door.edgeHigh(); edge++) {
            sendEncrypted(Protocol.doorAttribute(edge, door.y() + 1,
                            door.direction(), passable),
                    "S_CHANGE_ATTR Heine-castle-door=" + door.doorId()
                            + " x=" + edge + " y=" + (door.y() + 1)
                            + " direction=" + door.direction()
                            + " passable=" + passable + " reason=" + reason);
        }
    }

    private boolean handleClassicWorldStoryAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        if (!isSupportedClassicWorldStoryNpc(npc)) {
            return false;
        }
        ClassicWorldRescueFollowers.Definition rescue =
                ClassicWorldRescueFollowers.sourceDefinition(npc);
        if (rescue != null) {
            handleClassicWorldRescueStaticAction(request, npc, rescue);
            return true;
        }
        if (ClassicWorldDspyCatalog.sourceNpc(npc)) {
            handleClassicWorldDspyStaticAction(request, npc);
            return true;
        }
        GameStateStore.StoryQuestState current = state.storyQuests(stateCharacter());
        ClassicWorldStoryQuestCatalog.ActionResolution resolution =
                ClassicWorldStoryQuestCatalog.actionResolution(
                        npc.npcId(), request.action(), selectedCharacterSummary().type(),
                        battleLevel(), battleGfx(), Math.toIntExact(characterLawful()),
                        hub.classicWorldNpcGfx(npc), current.effective(),
                        inventory.catalogCounts());
        if (resolution == null) return false;
        ClassicWorldStoryQuestCatalog.Event event = resolution.event();
        boolean admitted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!admitted) {
            System.out.println("[LiTo] C_HACTION classic-world story rejected row="
                    + event.id() + " spawn=" + npc.spawnId()
                    + " action=" + request.action() + " result=state-or-distance");
            return true;
        }
        if (!resolution.admitted()) {
            String missingHtml = resolution.missingHtml();
            if (!missingHtml.isBlank()) {
                sendEncrypted(Protocol.hypertext(
                                npc.objectId(), missingHtml, "", List.of()),
                        "S_HYPERTEXT classic-world-story missing row="
                                + event.id() + " html=" + missingHtml);
            } else {
                ClassicWorldStoryQuestCatalog.ItemAmount missing =
                        resolution.missingItems().get(0);
                InventoryCatalog.Definition definition =
                        InventoryCatalog.find(missing.itemId());
                String name = definition == null
                        ? Long.toString(missing.itemId()) : definition.name();
                sendEncrypted(Protocol.messageCode(
                                337, name + " (" + missing.count() + ")"),
                        "S_MESSAGE_CODE classic-world-story-shortage=337 row="
                                + event.id() + " item=" + missing.itemId()
                                + " shortage=" + missing.count());
                sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                        "S_HYPERTEXT classic-world-story missing-close row="
                                + event.id());
            }
            System.out.println("[LiTo] C_HACTION classic-world story handled row="
                    + event.id() + " spawn=" + npc.spawnId()
                    + " action=" + request.action() + " result=missing-material");
            return true;
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        for (ClassicWorldStoryQuestCatalog.ItemAmount consumed : event.consumedItems()) {
            if (!next.removeCatalog(consumed.itemId(), consumed.count())) {
                throw new IOException("validated story item consumption failed row="
                        + event.id());
            }
        }
        for (ClassicWorldStoryQuestCatalog.ItemAmount cleanup : event.cleanupItems()) {
            int available = next.catalogCounts().getOrDefault(cleanup.itemId(), 0);
            int removed = Math.min(available, cleanup.count());
            if (removed > 0 && !next.removeCatalog(cleanup.itemId(), removed)) {
                throw new IOException("validated story cleanup failed row=" + event.id());
            }
        }
        for (ClassicWorldStoryQuestCatalog.ItemAmount reward : event.givenItems()) {
            InventoryCatalog.Definition definition = InventoryCatalog.find(reward.itemId());
            if (definition == null || !next.add(definition, reward.count())) {
                System.out.println("[LiTo] C_HACTION classic-world story rejected row="
                        + event.id() + " reward=" + reward.itemId()
                        + " result=unknown-item-or-inventory-capacity");
                return true;
            }
        }
        Map<Integer, Integer> nextQuests =
                ClassicWorldStoryQuestCatalog.applyQuestMutation(
                        event, current.effective());
        nextQuests = ClassicWorldCkewCatalog.bridgePredecessorCompletion(
                event, selectedCharacterSummary().type(), nextQuests);
        state.saveEconomyStateAndStoryQuests(
                stateCharacter(), shopPoints, next.catalogCounts(),
                next.catalogItemStates(), nextQuests);
        NativeDeItemApplication.replace(this, next, 0);
        for (int effectId : event.removedSkillEffects()) {
            storySkillEffectDeadlines.remove(effectId);
        }
        Map.Entry<Integer, Integer> newEffect = event.setSkillEffect();
        if (newEffect != null) {
            storySkillEffectDeadlines.put(newEffect.getKey(),
                    System.nanoTime() + newEffect.getValue() * 1_000_000L);
        }
        sendInventoryDelta(previous, inventory);
        String responseHtml = ClassicWorldStoryQuestCatalog.responseHtml(
                event, nextQuests);
        if (responseHtml.isBlank()) {
            sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                    "S_HYPERTEXT classic-world-story close row=" + event.id());
        } else {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), responseHtml, "", List.of()),
                    "S_HYPERTEXT classic-world-story row=" + event.id()
                            + " html=" + responseHtml);
        }
        System.out.println("[LiTo] C_HACTION classic-world story accepted player="
                + playerName() + " map=" + classicWorldMapId
                + " spawn=" + npc.spawnId() + " npc=" + npc.npcId()
                + " row=" + event.id() + " quest=" + event.questId()
                + " action=" + request.action() + " set-step=" + event.setStep()
                + " chain=" + event.chainedQuestId());
        return true;
    }

    /** Exact retained Kamyla/Francu quest-32 action family. */
    private boolean handleClassicWorldKamylaAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        if (!ClassicWorldKamylaQuestCatalog.isDialogueNpc(npc)) return false;
        GameStateStore.StoryQuestState current = state.storyQuests(stateCharacter());
        ClassicWorldKamylaQuestCatalog.ActionResult result =
                ClassicWorldKamylaQuestCatalog.action(
                        npc.npcId(), request.action(), current.effective(),
                        inventory.catalogCounts());
        boolean admitted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!admitted || result == null) {
            System.out.println("[LiTo] C_HACTION Kamyla-quest32 rejected map="
                    + classicWorldMapId + " npc=" + npc.npcId()
                    + " action=" + request.action()
                    + " result=state-kind-distance-or-transition");
            return true;
        }
        if (result.retainedSourceGap()) {
            System.out.println("[LiTo] C_HACTION Kamyla-quest32 retained-source-gap npc="
                    + npc.npcId() + " action=" + request.action()
                    + " Text.pak-visible=true C_NPCAction-implementation=false");
            return true;
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (result.consumedItemId() > 0
                && !next.removeCatalog(result.consumedItemId(), 1)) {
            throw new IOException("validated Kamyla item consumption failed item="
                    + result.consumedItemId());
        }
        InventoryCatalog.Definition reward = null;
        if (result.givenItemId() > 0) {
            reward = InventoryCatalog.find(result.givenItemId());
            if (reward == null || !next.add(reward, 1)) {
                System.out.println("[LiTo] C_HACTION Kamyla-quest32 rejected reward="
                        + result.givenItemId() + " result=unknown-item-or-capacity");
                return true;
            }
        }
        Map<Integer, Integer> nextQuests = current.effective();
        if (result.nextStep() > 0) {
            Map<Integer, Integer> changed = new LinkedHashMap<>(current.effective());
            changed.put(ClassicWorldKamylaQuestCatalog.QUEST_ID, result.nextStep());
            nextQuests = Map.copyOf(changed);
        }
        if (result.mutatesState()) {
            state.saveEconomyStateAndStoryQuests(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates(), nextQuests);
            NativeDeItemApplication.replace(this, next, 0);
            sendInventoryDelta(previous, inventory);
        }
        if (reward != null) {
            sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                    "S_MESSAGE_CODE Kamyla-quest32-reward=143 npc="
                            + npc.npcId() + " item=" + reward.catalogId());
        }
        if (!result.html().isBlank()) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), result.html(), "", List.of()),
                    "S_HYPERTEXT Kamyla-quest32 html=" + result.html()
                            + " npc=" + npc.npcId());
        }
        if (result.teleports()) {
            beginClassicWorldKamylaPortal(npc, request.action(), result);
        }
        System.out.println("[LiTo] C_HACTION Kamyla-quest32 accepted player="
                + playerName() + " map=" + classicWorldMapId + " npc="
                + npc.npcId() + " action=" + request.action()
                + " set-step=" + result.nextStep() + " consumed="
                + result.consumedItemId() + " given=" + result.givenItemId()
                + " portal=" + result.teleports());
        return true;
    }

    private void beginClassicWorldKamylaPortal(
            ClassicWorldNpcCatalog.StaticNpc npc, String action,
            ClassicWorldKamylaQuestCatalog.ActionResult result) throws IOException {
        Protocol.PortalDestination destination = result.destination();
        if (destination == null || !ClassicWorldMapCatalog.forMap(destination.mapId())
                .standingPassable(destination.x(), destination.y())) {
            throw new IOException("Kamyla quest destination is not passable");
        }
        if (npc.npcId() == ClassicWorldPirateBackHalfCatalog.FRANCU_NPC_ID
                && action.equals("b")) {
            ClassicWorldTeleportCatalog.Route route =
                    ClassicWorldTeleportCatalog.pirateBackHalfFrancuReturnRoute();
            if (route.sourceObjectId() != npc.objectId()
                    || route.destinationMapId() != destination.mapId()
                    || route.destinationX() != destination.x()
                    || route.destinationY() != destination.y()
                    || route.heading() != result.heading()) {
                throw new IOException("Francu route1160 disagrees with quest executor");
            }
        }
        clearPendingClassicList();
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, result.heading(), 0,
                "Kamyla-quest32-NPC-" + npc.npcId() + "-action-" + action);
        pendingPortal = destination;
        pendingPortalReady = true;
        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT Kamyla-quest32 target=" + playerObjectId());
            }
        }
        sendEncrypted(Protocol.portal(
                        destination.mapId(), destination.x(), destination.y()),
                "S_PORTAL Kamyla-quest32 npc=" + npc.npcId()
                        + " action=" + action + " map=" + destination.mapId()
                        + " x=" + destination.x() + " y=" + destination.y());
    }

    /** Retained fallen-voyager reward and post-2013 Aldran corpse portals. */
    private boolean handleClassicWorldShipGraveAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        ClassicWorldPirateShipGraveCatalog.AldranRoute aldranRoute =
                ClassicWorldPirateShipGraveCatalog.aldranRoute(request.action());
        if (ClassicWorldPirateShipGraveCatalog.isAldran(npc)
                && aldranRoute != null) {
            boolean admitted = request.kind() == Protocol.HypertextActionKind.GENERIC
                    && request.parameter().isEmpty()
                    && classicNpcDistance(new ArenaMapCatalog.Point(
                            npc.x(), npc.y())) <= 5
                    && pendingPortal == null && !movementLockPending
                    && !hub.hasPrivateShop(this);
            if (!admitted) {
                System.out.println("[LiTo] C_HACTION Ship-Grave Aldran rejected"
                        + " action=" + request.action()
                        + " result=kind-distance-or-transition");
                return true;
            }
            if (inventory.catalogCounts().getOrDefault(
                    (long) ClassicWorldPirateShipGraveCatalog.CREW_CORPSE, 0) < 1) {
                sendEncrypted(Protocol.hypertext(npc.objectId(),
                                ClassicWorldPirateShipGraveCatalog.ALDRAN_MISSING_HTML,
                                "", List.of()),
                        "S_HYPERTEXT Ship-Grave-Aldran missing-corpse html="
                                + ClassicWorldPirateShipGraveCatalog.ALDRAN_MISSING_HTML);
                return true;
            }
            Protocol.PortalDestination destination = aldranRoute.destination();
            if (!ClassicWorldMapCatalog.forMap(destination.mapId())
                    .standingPassable(destination.x(), destination.y())) {
                throw new IOException("Aldran destination is not passable action="
                        + request.action());
            }
            RuntimeInventory previous = inventory;
            RuntimeInventory next = inventory.copy();
            if (!next.removeCatalog(
                    ClassicWorldPirateShipGraveCatalog.CREW_CORPSE, 1)) {
                throw new IOException("validated Aldran corpse removal failed");
            }
            state.saveEconomyState(stateCharacter(), shopPoints,
                    next.catalogCounts(), next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            sendInventoryDelta(previous, inventory);

            clearPendingClassicList();
            pendingCallClanPortal = null;
            pendingRunClanPortal = null;
            pendingClassicWorldPortal = new PendingClassicWorldPortal(
                    destination, aldranRoute.heading(), 0,
                    "Ship-Grave-Aldran-action-" + request.action());
            pendingPortal = destination;
            pendingPortalReady = true;
            byte[] effect = Protocol.effectObject(
                    playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, positionX, positionY)) {
                    member.sendEncrypted(effect,
                            "S_EFFECT Ship-Grave-Aldran target=" + playerObjectId());
                }
            }
            sendEncrypted(Protocol.portal(destination.mapId(),
                            destination.x(), destination.y()),
                    "S_PORTAL Ship-Grave-Aldran action=" + request.action()
                            + " map=" + destination.mapId() + " x=" + destination.x()
                            + " y=" + destination.y());
            System.out.println("[LiTo] C_HACTION Ship-Grave Aldran accepted player="
                    + playerName() + " action=" + request.action()
                    + " label=" + aldranRoute.textLabel() + " consumed="
                    + ClassicWorldPirateShipGraveCatalog.CREW_CORPSE
                    + " destination=" + destination.mapId() + ":"
                    + destination.x() + "," + destination.y()
                    + " heading=" + aldranRoute.heading()
                    + " result=awaiting-C_GOTO_PORTAL");
            return true;
        }
        if (!ClassicWorldPirateShipGraveCatalog.isVoyager(npc)
                || !request.action().equals("a")) return false;
        boolean admitted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!admitted) {
            System.out.println("[LiTo] C_HACTION Ship-Grave voyager rejected"
                    + " result=kind-distance-or-transition");
            return true;
        }
        int rewardId = ClassicWorldPirateShipGraveCatalog.voyagerReward(
                ThreadLocalRandom.current().nextInt(2));
        InventoryCatalog.Definition reward = InventoryCatalog.find(rewardId);
        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        if (reward == null || !next.add(reward, 1)) {
            System.out.println("[LiTo] C_HACTION Ship-Grave voyager rejected reward="
                    + rewardId + " result=unknown-item-or-capacity");
            return true;
        }
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(143, npc.nameId(), reward.name()),
                "S_MESSAGE_CODE Ship-Grave-voyager-reward=143 item=" + rewardId);
        String html = ClassicWorldPirateShipGraveCatalog.voyagerRewardHtml(rewardId);
        sendEncrypted(Protocol.hypertext(npc.objectId(), html, "", List.of()),
                "S_HYPERTEXT Ship-Grave-voyager html=" + html);
        System.out.println("[LiTo] C_HACTION Ship-Grave voyager accepted player="
                + playerName() + " item=" + rewardId + " html=" + html);
        return true;
    }

    /** Exact retained Npc_Dicarding completion path for shared quest 122. */
    private boolean handleClassicWorldCkewCompletionAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        if (!ClassicWorldCkewCompletionCatalog.isDicarding(npc)) return false;
        int characterType = selectedCharacterSummary().type();
        String retryHtml = ClassicWorldCkewCompletionCatalog.retryHtml(
                characterType, request.action());
        ClassicWorldCkewCompletionCatalog.Completion completion =
                ClassicWorldCkewCompletionCatalog.completion(
                        characterType, request.action());
        if (retryHtml == null && completion == null) return false;

        GameStateStore.StoryQuestState current = state.storyQuests(stateCharacter());
        int questStep = current.step(ClassicWorldCkewCatalog.QUEST_ID);
        boolean admitted = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this)
                && ClassicWorldCkewCompletionCatalog.activeQuestStep(questStep);
        if (!admitted) {
            System.out.println("[LiTo] C_HACTION CKEW completion rejected player="
                    + playerName() + " type=" + characterType + " step=" + questStep
                    + " action=" + request.action() + " result=state-or-distance");
            return true;
        }
        if (retryHtml != null) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), retryHtml, "", List.of()),
                    "S_HYPERTEXT CKEW-completion-retry type="
                            + characterType + " html=" + retryHtml);
            return true;
        }

        if (!inventory.catalogCounts().containsKey(
                (long) ClassicWorldCkewCatalog.ALTAR_PROOF)) {
            sendEncrypted(Protocol.hypertext(
                            npc.objectId(), completion.missingHtml(), "", List.of()),
                    "S_HYPERTEXT CKEW-completion-missing-proof type="
                            + characterType + " html=" + completion.missingHtml());
            return true;
        }

        InventoryCatalog.Definition reward = InventoryCatalog.find(
                completion.rewardItemId());
        if (reward == null) {
            throw new IOException("CKEW completion reward definition vanished "
                    + completion.rewardItemId());
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory rewarded = inventory.copy();
        RuntimeInventory.Item proofItem = rewarded.items().stream()
                .filter(item -> item.definition().catalogId()
                        == ClassicWorldCkewCatalog.ALTAR_PROOF)
                .findFirst().orElseThrow(() -> new IOException(
                        "validated CKEW altar proof object vanished"));
        if (!rewarded.removeCatalog(ClassicWorldCkewCatalog.ALTAR_PROOF, 1)) {
            throw new IOException("validated CKEW altar proof removal failed");
        }
        boolean rewardStored = permitsInventoryAddition(rewarded, reward, 1)
                && rewarded.add(reward, 1);
        RuntimeInventory.Item rewardMessageItem = new RuntimeInventory.Item(
                1, reward, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);

        List<RuntimeInventory.Item> cleanupItems = new ArrayList<>();
        RuntimeInventory finalInventory = rewarded;
        for (long catalogId : ClassicWorldCkewCompletionCatalog.CLEANUP_ITEM_IDS) {
            RuntimeInventory.Item found = finalInventory.items().stream()
                    .filter(item -> item.definition().catalogId() == catalogId)
                    .findFirst().orElse(null);
            if (found == null) continue;
            cleanupItems.add(found);
            finalInventory = finalInventory.withoutObjects(Set.of(found.objectId()));
        }
        Set<Long> consumedSourceObjects = cleanupItems.stream()
                .filter(RuntimeInventory.Item::sourceBound)
                .map(RuntimeInventory.Item::objectId)
                .collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));
        if (proofItem.sourceBound()
                && rewarded.item(proofItem.objectId()) == null) {
            consumedSourceObjects.add(proofItem.objectId());
        }
        Map<Integer, Integer> quests = new LinkedHashMap<>(current.effective());
        quests.put(ClassicWorldCkewCatalog.QUEST_ID,
                ClassicWorldCkewCatalog.QUEST_ENDED);
        quests = new LinkedHashMap<>(
                ClassicWorldCkewCatalog.synchronizeSelectedCompletion(quests));
        state.saveEconomyStateAndStoryQuestsConsumingSourceObjects(
                stateCharacter(), shopPoints, finalInventory.catalogCounts(),
                finalInventory.catalogItemStates(), quests, consumedSourceObjects);
        NativeDeItemApplication.replace(this, finalInventory, 0);

        boolean removedEquippedWeapon = false;
        Map<Long, Long> retainedSourceEquipment = new LinkedHashMap<>(
                sourceEquipmentObjects);
        for (RuntimeInventory.Item removed : cleanupItems) {
            if (!removed.sourceBound()) continue;
            Long sourceEquipmentObject = retainedSourceEquipment.remove(
                    removed.objectId());
            if (sourceEquipmentObject != null) {
                Set<Long> consumed = new LinkedHashSet<>(
                        consumedSourceEquipmentObjects);
                consumed.add(sourceEquipmentObject);
                consumedSourceEquipmentObjects = Set.copyOf(consumed);
            }
            sourceProjectileObjects = sourceProjectileObjects.entrySet().stream()
                    .filter(entry -> entry.getValue() != removed.objectId())
                    .collect(java.util.stream.Collectors.toUnmodifiableMap(
                            Map.Entry::getKey, Map.Entry::getValue));
            if (removed.equipped() && removed.definition().weapon()) {
                sourceWeaponSuppressed = true;
                removedEquippedWeapon = true;
            }
        }
        sourceEquipmentObjects = Map.copyOf(retainedSourceEquipment);

        // Retained endQuest emits its quest-complete speech before returning
        // the success HTML and before inventory mutation packets.
        sendEncrypted(Protocol.questHelpMessage(
                        ClassicWorldCkewCompletionCatalog.COMPLETION_MESSAGE,
                        positionX, positionY),
                "S_SAY_CODE CKEW-quest122-complete type=" + characterType);
        sendEncrypted(Protocol.hypertext(
                        npc.objectId(), completion.successHtml(), "", List.of()),
                "S_HYPERTEXT CKEW-completion-success type="
                        + characterType + " html=" + completion.successHtml());
        sendInventoryDelta(previous, rewarded, false);

        if (!rewardStored) {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    classicWorldMapId, classicWorldInstanceId, rewardMessageItem, 1,
                    positionX, positionY, npc.npcId());
            if (ground == null) {
                throw new IOException("CKEW completion reward ground handoff failed");
            }
            broadcastClassicWorldGroundItem(ground, "CKEW-completion-overflow");
        }
        sendEncrypted(Protocol.questHelpMessage(
                        "\\fW" + npc.nameId() + "給你"
                                + rewardMessageItem.nativeLogName(),
                        positionX, positionY),
                "S_SAY_CODE CKEW-completion-reward=" + completion.rewardItemId()
                        + " stored=" + rewardStored);

        RuntimeInventory displayed = rewarded;
        for (RuntimeInventory.Item removed : cleanupItems) {
            if (removed.equipped()) {
                sendInventoryEquipmentState(removed.withEquipped(false),
                        "CKEW-completion-cleanup");
            }
            sendEncrypted(Protocol.messageCode(
                            165, removed.definition().name()),
                    "S_MESSAGE_CODE CKEW-completion-cleanup=165 catalog="
                            + removed.definition().catalogId());
            RuntimeInventory nextDisplay = displayed.withoutObjects(
                    Set.of(removed.objectId()));
            sendInventoryDelta(displayed, nextDisplay, false);
            displayed = nextDisplay;
        }
        if (removedEquippedWeapon) broadcastWieldState();
        if (sourceInventoryWeightStats != null
                && sourceEquipmentMagicStats != null) {
            sendNativeBattleStatus(System.nanoTime(), "CKEW-completion");
        }
        System.out.println("[LiTo] C_HACTION CKEW completion accepted player="
                + playerName() + " type=" + characterType + " action="
                + request.action() + " reward=" + completion.rewardItemId()
                + " stored=" + rewardStored + " cleanup=" + cleanupItems.size()
                + " source-tombstones=" + consumedSourceObjects.size());
        return true;
    }

    /**
     * The selected story table names native instance/follower operations, but
     * those operations have state beyond a generic quest mutation.  Own their
     * actions now so the client cannot receive rewards or advance quests until
     * map2000 instances and Roi's transformed follower lifecycle are present.
     */
    private boolean handleDemonTempleDeferredAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        boolean instance = ClassicWorldDemonTempleCatalog
                .isDeferredInstanceAction(npc, request.action());
        boolean follower = ClassicWorldDemonTempleCatalog
                .isDeferredRoiFollowerAction(npc, request.action());
        if (!instance && !follower) return false;
        if (follower) {
            handleClassicWorldRoiStaticStart(request, npc);
            return true;
        }
        handleClassicWorldCkewEntry(request, npc);
        return true;
    }

    private void handleClassicWorldCkewEntry(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc) throws IOException {
        sendEncrypted(Protocol.closeHypertext(npc.objectId()),
                "S_HYPERTEXT CKEW close spawn=" + npc.spawnId());
        int characterType = selectedCharacterType();
        GameStateStore.StoryQuestState current =
                state.storyQuests(stateCharacter());
        int step = current.step(ClassicWorldCkewCatalog.QUEST_ID);
        if (request.kind() != Protocol.HypertextActionKind.GENERIC
                || !request.parameter().isEmpty()
                || classicWorldMapId != ClassicWorldDemonTempleCatalog.MAP_ID
                || battleLevel() < 50 || pendingPortal != null
                || hub.hasPrivateShop(this)
                || step < ClassicWorldCkewCatalog.QUEST_STARTED
                || step == ClassicWorldCkewCatalog.QUEST_ENDED
                || !ClassicWorldCkewCatalog.matchesEntrance(
                        characterType, npc.npcId())) {
            System.out.println("[LiTo] C_HACTION CKEW rejected player="
                    + playerName() + " step=" + step + " type=" + characterType
                    + " npc=" + npc.npcId() + " result=source-or-state");
            return;
        }

        ClassicWorldCkewInstances.Admission admission =
                hub.admitClassicWorldCkew(this, System.nanoTime());
        if (!admission.admitted()) {
            System.out.println("[LiTo] C_HACTION CKEW rejected player="
                    + playerName() + " result=" + admission.status());
            return;
        }

        ClassicWorldCkewCatalog.CharacterClass nativeClass =
                ClassicWorldCkewCatalog.characterClass(characterType);
        ClassicWorldCkewCatalog.Location entry = nativeClass.firstFloor();
        if (!ClassicWorldMapCatalog.forMap(entry.mapId())
                .standingPassable(entry.x(), entry.y())) {
            hub.rollbackClassicWorldCkewAdmission(this, admission);
            throw new IOException("CKEW entry is not passable");
        }
        Map<Integer, Integer> mutableNext =
                new LinkedHashMap<>(current.effective());
        mutableNext.put(ClassicWorldCkewCatalog.QUEST_ID,
                ClassicWorldCkewCatalog.QUEST_ENTERED);
        Map<Integer, Integer> next = ClassicWorldCkewCatalog
                .synchronizeSelectedEntry(mutableNext);

        Protocol.PortalDestination destination = new Protocol.PortalDestination(
                entry.mapId(), entry.x(), entry.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                destination, entry.heading(), 0,
                "CKEW-quest122-show-" + admission.showId(), admission.showId());
        pendingPortal = destination;
        pendingPortalReady = true;
        try {
            if (!hub.commitClassicWorldCkewAdmission(
                    this, admission,
                    () -> state.saveStoryQuestSteps(stateCharacter(), next))) {
                throw new IOException("CKEW admission commit failed");
            }
        } catch (IOException | RuntimeException failure) {
            pendingClassicWorldPortal = null;
            pendingPortal = null;
            pendingPortalReady = false;
            hub.rollbackClassicWorldCkewAdmission(this, admission);
            throw failure;
        }

        try {
            if (!hub.publishClassicWorldCkewAdmission(
                    this, admission, () -> {
                        byte[] effect = Protocol.effectObject(
                                playerObjectId(), ClassicWorldTeleportCatalog
                                        .TELEPORT_EFFECT_GFX);
                        for (ClientSession member
                                : classicWorldMembers(classicWorldMapId)) {
                            if (BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    positionX, positionY)) {
                                member.sendEncrypted(effect,
                                        "S_EFFECT CKEW-entry target="
                                                + playerObjectId() + " show="
                                                + admission.showId());
                            }
                        }
                        sendEncrypted(Protocol.portal(destination.mapId(),
                                        destination.x(), destination.y()),
                                "S_PORTAL CKEW quest=122 show="
                                        + admission.showId() + " class="
                                        + nativeClass + " destination="
                                        + destination.x() + ","
                                        + destination.y());
                    })) {
                System.out.println("[LiTo] C_HACTION CKEW publication suppressed"
                        + " player=" + playerName() + " show="
                        + admission.showId() + " result=instance-ended");
                return;
            }
        } catch (IOException | RuntimeException failure) {
            synchronized (classicWorldPortalLifecycleLock) {
                invalidatePendingClassicWorldCkewEntry(admission.showId());
            }
            hub.endClassicWorldCkew(admission.showId(), "portal-send-failed");
            throw failure;
        }
        System.out.println("[LiTo] C_HACTION CKEW admitted player=" + playerName()
                + " quest=122 step=2 show=" + admission.showId()
                + " created=" + admission.created()
                + " deadline=" + admission.deadlineNanos()
                + " result=awaiting-C_GOTO_PORTAL");
    }

    private void handleClassicWorldRescueStaticAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldNpcCatalog.StaticNpc npc,
            ClassicWorldRescueFollowers.Definition definition) throws IOException {
        GameStateStore.StoryQuestState quests = state.storyQuests(stateCharacter());
        ClassicWorldStoryQuestCatalog.ActionResolution resolution =
                ClassicWorldStoryQuestCatalog.actionResolution(
                        definition.sourceNpcId(), request.action(),
                        selectedCharacterSummary().type(), battleLevel(), battleGfx(),
                        Math.toIntExact(characterLawful()), hub.classicWorldNpcGfx(npc),
                        quests.effective(), inventory.catalogCounts());
        boolean admittedShape = request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && "start".equalsIgnoreCase(request.action())
                && classicNpcDistance(new ArenaMapCatalog.Point(npc.x(), npc.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this);
        if (!admittedShape || resolution == null || !resolution.admitted()
                || resolution.event().id() != definition.completionEventId()) {
            System.out.println("[LiTo] C_HACTION rescue static rejected player="
                    + playerName() + " kind=" + definition.kind()
                    + " object=" + request.worldObjectId()
                    + " action=" + request.action()
                    + " result=shape-quest-material-or-state");
            return;
        }
        String owner = sourceCharacterIdentity();
        if (hasClassicWorldFollower(owner)) {
            System.out.println("[LiTo] C_HACTION rescue static rejected player="
                    + playerName() + " kind=" + definition.kind()
                    + " result=owner-already-has-follower");
            return;
        }
        ClassicWorldRescueFollowers.Snapshot claimed =
                hub.classicWorldRescueFollowers().claimStatic(
                        definition, owner, npc.x(), npc.y(),
                        hub.classicWorldNpcHeading(npc), System.nanoTime());
        if (claimed == null) return;

        boolean restoredSearcher = false;
        try {
            if (definition.kind() == ClassicWorldRescueFollowers.Kind.SEARCHER) {
                restoredSearcher = hub.restoreClassicWorldNpcGfx(
                        npc, ClassicWorldRescueFollowers.SEARCHER_RESTORED_GFX);
                if (!restoredSearcher) {
                    throw new IOException("Searcher static GFX changed during follower claim");
                }
            }
            broadcastClassicWorldRescueStaticClaim(npc, claimed);
            sendEncrypted(Protocol.hypertext(
                            request.worldObjectId(), definition.ownerHtml(), "", List.of()),
                    "S_HYPERTEXT rescue-start kind=" + definition.kind()
                            + " source=" + request.worldObjectId()
                            + " follower=" + claimed.objectId()
                            + " html=" + definition.ownerHtml());
        } catch (IOException | RuntimeException failure) {
            hub.classicWorldRescueFollowers().removeOwned(owner);
            if (restoredSearcher) {
                hub.transformClassicWorldNpcGfx(
                        npc, ClassicWorldRescueFollowers.SEARCHER_CURSED_GFX,
                        ClassicWorldRescueFollowers.SEARCHER_RESTORED_GFX);
            }
            throw failure;
        }
        System.out.println("[LiTo] C_HACTION rescue static accepted player="
                + playerName() + " kind=" + definition.kind()
                + " source=" + npc.objectId() + " follower=" + claimed.objectId()
                + " quest=" + definition.questId()
                + " completion-deferred=arrival");
    }

    private void handleClassicWorldDspyStaticAction(Protocol.HypertextActionRequest hypertextActionRequest, ClassicWorldNpcCatalog.StaticNpc staticNpc) throws IOException {
        boolean bl;
        ClassicWorldStoryQuestCatalog.ActionResolution actionResolution = ClassicWorldStoryQuestCatalog.actionResolution(80012, hypertextActionRequest.action(), this.selectedCharacterSummary().type(), this.battleLevel(), this.battleGfx(), Math.toIntExact(this.characterLawful()), NativeStaticNpcScene.gfx(this.hub, staticNpc, this), this.state.storyQuests(this.stateCharacter()).effective(), this.inventory.catalogCounts());
        boolean bl2 = bl = hypertextActionRequest.kind() == Protocol.HypertextActionKind.GENERIC && hypertextActionRequest.parameter().isEmpty() && "start".equalsIgnoreCase(hypertextActionRequest.action()) && this.classicNpcDistance(new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this))) <= 5 && this.pendingPortal == null && !this.hub.hasPrivateShop(this) && actionResolution != null && actionResolution.admitted() && actionResolution.event().id() == 40000261 && !this.hasClassicWorldFollower(this.sourceCharacterIdentity());
        if (!bl) {
            System.out.println("[LiTo] C_HACTION Dspy static rejected player=" + this.playerName() + " object=" + hypertextActionRequest.worldObjectId() + " result=shape-quest-material-state-or-existing-follower");
            return;
        }
        ClassicWorldDspyEscorts.Snapshot snapshot = this.hub.classicWorldDspyEscorts().claimStatic(this.sourceCharacterIdentity(), NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this), NativeStaticNpcScene.heading(this.hub, staticNpc, this), System.nanoTime());
        if (snapshot == null) {
            return;
        }
        try {
            this.broadcastClassicWorldDspyStaticClaim(staticNpc, snapshot);
            this.sendEncrypted(Protocol.hypertext(hypertextActionRequest.worldObjectId(), "dspy3", "", List.of()), "S_HYPERTEXT Dspy-start source=" + hypertextActionRequest.worldObjectId() + " follower=" + snapshot.objectId() + " html=dspy3");
        }
        catch (IOException | RuntimeException exception) {
            this.hub.classicWorldDspyEscorts().rollbackClaim(snapshot, null);
            throw exception;
        }
        System.out.println("[LiTo] C_HACTION Dspy static accepted player=" + this.playerName() + " source=" + staticNpc.objectId() + " follower=" + snapshot.objectId() + " quest=11603 completion-deferred=arrival");
    }

    private void handleClassicWorldDspyFollowerAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldDspyEscorts.Snapshot source) throws IOException {
        ClassicWorldStoryQuestCatalog.ActionResolution resolution =
                ClassicWorldStoryQuestCatalog.actionResolution(
                        ClassicWorldDspyCatalog.DSPY_NPC_ID, request.action(),
                        selectedCharacterSummary().type(), battleLevel(), battleGfx(),
                        Math.toIntExact(characterLawful()),
                        ClassicWorldDspyCatalog.DSPY_GFX_ID,
                        state.storyQuests(stateCharacter()).effective(),
                        inventory.catalogCounts());
        boolean admitted = source.mapId() == classicWorldMapId && source.alive()
                && !source.owned()
                && BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, source.x(), source.y())
                && request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && "start".equalsIgnoreCase(request.action())
                && classicNpcDistance(new ArenaMapCatalog.Point(
                        source.x(), source.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this)
                && resolution != null && resolution.admitted()
                && resolution.event().id()
                    == ClassicWorldDspyCatalog.COMPLETION_EVENT_ID
                && !hasClassicWorldFollower(sourceCharacterIdentity());
        if (!admitted) {
            System.out.println("[LiTo] C_HACTION Dspy free rejected player="
                    + playerName() + " object=" + source.objectId()
                    + " result=owned-shape-quest-material-state-or-existing-follower");
            return;
        }
        ClassicWorldDspyEscorts.Snapshot claimed =
                hub.classicWorldDspyEscorts().claimFree(
                        sourceCharacterIdentity(), source.objectId(),
                        System.nanoTime());
        if (claimed == null) return;
        try {
            sendEncrypted(Protocol.closeHypertext(request.worldObjectId()),
                    "S_HYPERTEXT Dspy start close free="
                            + request.worldObjectId());
            broadcastClassicWorldDspyReplacement(
                    source, claimed, "free-claim");
            sendEncrypted(Protocol.hypertext(
                            request.worldObjectId(),
                            ClassicWorldDspyCatalog.OWNER_HTML, "", List.of()),
                    "S_HYPERTEXT Dspy-start free=" + request.worldObjectId()
                            + " follower=" + claimed.objectId()
                            + " html=" + ClassicWorldDspyCatalog.OWNER_HTML);
        } catch (IOException | RuntimeException failure) {
            hub.classicWorldDspyEscorts().rollbackClaim(claimed, source);
            throw failure;
        }
        System.out.println("[LiTo] C_HACTION Dspy free accepted player="
                + playerName() + " source=" + source.objectId()
                + " follower=" + claimed.objectId() + " quest="
                + ClassicWorldDspyCatalog.QUEST_ID
                + " completion-deferred=arrival");
    }

    private boolean hasClassicWorldFollower(String ownerIdentity) {
        return hub.classicWorldDspyEscorts().owned(ownerIdentity) != null
                || hub.classicWorldRescueFollowers().owned(ownerIdentity) != null
                || hub.classicWorldRoiFollowers().owned(ownerIdentity) != null;
    }

    private void handleClassicWorldRescueFollowerAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldRescueFollowers.Snapshot source) throws IOException {
        ClassicWorldRescueFollowers.Definition definition = source.definition();
        GameStateStore.StoryQuestState quests = state.storyQuests(stateCharacter());
        ClassicWorldStoryQuestCatalog.ActionResolution resolution =
                ClassicWorldStoryQuestCatalog.actionResolution(
                        definition.followerNpcId(), request.action(),
                        selectedCharacterSummary().type(), battleLevel(), battleGfx(),
                        Math.toIntExact(characterLawful()), definition.gfxId(),
                        quests.effective(), inventory.catalogCounts());
        boolean admitted = source.mapId() == classicWorldMapId && !source.owned()
                && BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, source.x(), source.y())
                && request.kind() == Protocol.HypertextActionKind.GENERIC
                && request.parameter().isEmpty()
                && "start".equalsIgnoreCase(request.action())
                && classicNpcDistance(new ArenaMapCatalog.Point(
                        source.x(), source.y())) <= 5
                && pendingPortal == null && !hub.hasPrivateShop(this)
                && resolution != null && resolution.admitted()
                && ClassicWorldRescueFollowers.admitsStartEvent(
                    definition, definition.followerNpcId(), resolution.event().id())
                && !hasClassicWorldFollower(sourceCharacterIdentity());
        if (!admitted) {
            System.out.println("[LiTo] C_HACTION rescue free rejected player="
                    + playerName() + " kind=" + definition.kind()
                    + " object=" + source.objectId()
                    + " result=owned-shape-quest-material-or-state");
            return;
        }
        ClassicWorldRescueFollowers.Snapshot claimed =
                hub.classicWorldRescueFollowers().claimFree(
                        sourceCharacterIdentity(), source.objectId(), System.nanoTime());
        if (claimed == null) return;
        broadcastClassicWorldRescueReplacement(source, claimed, "free-claim");
        sendEncrypted(Protocol.hypertext(
                        source.objectId(), definition.ownerHtml(), "", List.of()),
                "S_HYPERTEXT rescue-free-start kind=" + definition.kind()
                        + " source=" + source.objectId()
                        + " follower=" + claimed.objectId()
                        + " html=" + definition.ownerHtml());
    }

    private void handleClassicWorldRoiStaticStart(Protocol.HypertextActionRequest hypertextActionRequest, ClassicWorldNpcCatalog.StaticNpc staticNpc) throws IOException {
        int n = NativeStaticNpcScene.gfx(this.hub, staticNpc, this);
        if (!this.admitClassicWorldRoiStart(hypertextActionRequest, NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this), staticNpc.objectId(), n)) {
            return;
        }
        long l = System.nanoTime();
        ClassicWorldRoiFollowers.Snapshot snapshot = this.hub.classicWorldRoiFollowers().claimStatic(this.sourceCharacterIdentity(), NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this), NativeStaticNpcScene.heading(this.hub, staticNpc, this), l);
        if (snapshot == null) {
            System.out.println("[LiTo] C_HACTION Roi static rejected owner-already-has-follower player=" + this.playerName());
            return;
        }
        try {
            this.saveClassicWorldRoiQuestStep(1);
        }
        catch (IOException | RuntimeException exception) {
            this.hub.classicWorldRoiFollowers().complete(this.sourceCharacterIdentity());
            throw exception;
        }
        if (!NativeStaticNpcScene.restore(this.hub, staticNpc, 4310, this)) {
            this.hub.classicWorldRoiFollowers().complete(this.sourceCharacterIdentity());
            throw new IOException("Roi static GFX changed during follower claim");
        }
        this.sendEncrypted(Protocol.closeHypertext(hypertextActionRequest.worldObjectId()), "S_HYPERTEXT Roi start close static=" + hypertextActionRequest.worldObjectId());
        this.broadcastClassicWorldRoiStaticClaim(staticNpc, snapshot);
        System.out.println("[LiTo] C_HACTION Roi static accepted player=" + this.playerName() + " follower=" + snapshot.objectId() + " quest=138 step=1");
    }

    private void handleClassicWorldRoiFollowerAction(
            Protocol.HypertextActionRequest request,
            ClassicWorldRoiFollowers.Snapshot source) throws IOException {
        if (source.mapId() != classicWorldMapId
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, source.x(), source.y())
                || source.owned()) {
            System.out.println("[LiTo] C_HACTION Roi dynamic rejected object="
                    + source.objectId() + " result=owned-or-out-of-screen");
            return;
        }
        if (!admitClassicWorldRoiStart(request, source.x(), source.y(),
                source.objectId(), ClassicWorldDemonTempleCatalog.ROI_RESTORED_GFX)) {
            return;
        }
        ClassicWorldRoiFollowers.Snapshot claimed = hub.classicWorldRoiFollowers()
                .claimFree(sourceCharacterIdentity(), source.objectId(), System.nanoTime());
        if (claimed == null) {
            System.out.println("[LiTo] C_HACTION Roi free rejected concurrent-claim object="
                    + source.objectId());
            return;
        }
        try {
            saveClassicWorldRoiQuestStep(ClassicWorldRoiFollowers.QUEST_STARTED);
        } catch (IOException | RuntimeException failure) {
            hub.classicWorldRoiFollowers().tick(
                    sourceCharacterIdentity(), ClassicWorldRoiFollowers.MAP_ID,
                    claimed.x(), claimed.y(), false, System.nanoTime(),
                    (fromX, fromY, toX, toY, objectId) -> true);
            throw failure;
        }
        sendEncrypted(Protocol.closeHypertext(request.worldObjectId()),
                "S_HYPERTEXT Roi start close free=" + request.worldObjectId());
        broadcastClassicWorldRoiReplacement(source, claimed, "free-claim");
        System.out.println("[LiTo] C_HACTION Roi free accepted player=" + playerName()
                + " source=" + source.objectId() + " follower=" + claimed.objectId()
                + " quest=138 step=1");
    }

    private boolean admitClassicWorldRoiStart(
            Protocol.HypertextActionRequest request, int targetX, int targetY,
            long targetObjectId, int currentGfx) throws IOException {
        if (request.kind() != Protocol.HypertextActionKind.GENERIC
                || !request.parameter().isEmpty()
                || !"start".equalsIgnoreCase(request.action())
                || classicNpcDistance(new ArenaMapCatalog.Point(targetX, targetY)) > 5
                || pendingPortal != null || hub.hasPrivateShop(this)) {
            System.out.println("[LiTo] C_HACTION Roi start rejected object="
                    + targetObjectId + " result=shape-distance-or-state");
            return false;
        }
        int questStep = state.storyQuests(stateCharacter())
                .step(ClassicWorldRoiFollowers.QUEST_ID);
        if (questStep == ClassicWorldRoiFollowers.QUEST_COMPLETE
                || battleLevel() < ClassicWorldDemonTempleCatalog.ROI_QUEST_LEVEL) {
            sendEncrypted(Protocol.hypertext(targetObjectId, "roi", "", List.of()),
                    "S_HYPERTEXT Roi start ineligible html=roi object=" + targetObjectId);
            return false;
        }
        if (hub.classicWorldRescueFollowers()
                    .owned(sourceCharacterIdentity()) != null
                || hub.classicWorldDspyEscorts()
                    .owned(sourceCharacterIdentity()) != null) {
            System.out.println("[LiTo] C_HACTION Roi start rejected object="
                    + targetObjectId + " result=owner-already-has-other-follower");
            return false;
        }
        if (currentGfx != ClassicWorldDemonTempleCatalog.ROI_RESTORED_GFX) {
            System.out.println("[LiTo] C_HACTION Roi start rejected object="
                    + targetObjectId + " result=not-restored gfx=" + currentGfx);
            return false;
        }
        return true;
    }

    private void saveClassicWorldRoiQuestStep(int step) throws IOException {
        Map<Integer, Integer> quests = new LinkedHashMap<>(
                state.storyQuests(stateCharacter()).effective());
        quests.put(ClassicWorldRoiFollowers.QUEST_ID, step);
        state.saveStoryQuestSteps(stateCharacter(), quests);
    }

    private boolean isSupportedClassicWorldStoryNpc(
            ClassicWorldNpcCatalog.StaticNpc npc) {
        if (npc == null) return false;
        return ClassicWorldRescueFollowers.sourceDefinition(npc) != null
                || (classicWorldMapId == ClassicWorldMapCatalog.GUNTER_HOUSE_MAP_ID
                && npc.npcId() == ClassicWorldStoryQuestCatalog.GUNTER_NPC_ID)
                || (classicWorldMapId == ClassicWorldMapCatalog.WORLD_TREE_MAP_ID
                && npc.npcId() == ClassicWorldStoryQuestCatalog.ZERO_NPC_ID)
                || (classicWorldMapId == ClassicWorldMapCatalog.JIM_SECRET_ROOM_MAP_ID
                && npc.npcId() == ClassicWorldStoryQuestCatalog.JIM_NPC_ID)
                || ClassicWorldIvoryTowerCatalog.isStoryNpc(npc)
                || ClassicWorldHeineCatalog.isStoryNpc(npc)
                || ClassicWorldSilentCavernCatalog.isStoryNpc(npc)
                || ClassicWorldDiadradCatalog.isStoryNpc(npc)
                || ClassicWorldDemonTempleCatalog.isStoryNpc(npc)
                || ClassicWorldBehemothSilveriaCatalog.isStoryNpc(npc);
    }

