    private void synchronizeRentalTownParticipantRows() throws IOException {
        for (ClientSession peer : rentalTownPeers()) {
            sendRoomParticipant(currentRoomId, peer, Protocol.LitoForce.FORCE_0,
                    "rental-town-existing-player");
            peer.sendRoomParticipant(currentRoomId, this, Protocol.LitoForce.FORCE_0,
                    "rental-town-player-joined");
        }
    }

    private void synchronizeRentalTownActors(String reason) throws IOException {
        for (ClientSession peer : rentalTownPeers()) {
            if (rentalTownInNativeScreen(peer, positionX, positionY)) {
                sendRentalTownActorOf(peer, reason + "-existing-peer");
                peer.sendRentalTownActorOf(this, reason + "-peer-joined");
            }
            sendEncrypted(Protocol.minimapPlayer(
                            peer.playerObjectId(), peer.positionX, peer.positionY, true),
                    "S_LITO_MINIMAP rental-town existing-peer=" + peer.playerName()
                            + " reason=" + reason);
            peer.sendEncrypted(Protocol.minimapPlayer(
                            playerObjectId(), positionX, positionY, true),
                    "S_LITO_MINIMAP rental-town peer-joined=" + playerName()
                            + " reason=" + reason);
        }
    }

    private void sendRentalTownActorOf(ClientSession actor, String reason)
            throws IOException {
        sendBattleObjectAtHeading(
                actor.playerObjectId(), actor.playerName(),
                actor.sourceCharacterIdentity(), actor.positionX, actor.positionY,
                actor.battleGfx(), actor.rentalTownWalkAction(), actor.playerHeading,
                actor.rentalTownLightRange(), actor.battleMoveSpeed(), 4,
                actor.battleLevel(), nativeLawful(actor.characterLawful()),
                actor.classicTitle, actor == this ? 0xFF : actor.battleHpRatio());
        System.out.println("[LiTo] rental-town actor visible recipient=" + playerName()
                + " actor=" + actor.playerName() + " map=" + rentalTownMapId
                + " x=" + actor.positionX + " y=" + actor.positionY
                + " heading=" + actor.playerHeading + " reason=" + reason);
    }

    private boolean rentalTownInNativeScreen(
            ClientSession actor, int viewerX, int viewerY) {
        return actor != null
                && actor.rentalTownRoomState
                && actor.phase == Phase.BATTLE
                && actor.currentRoomId == currentRoomId
                && actor.rentalTownMapId == rentalTownMapId
                && sameRentalTownVisibilityInstance(actor)
                && BattleSpellCatalog.isInNativeScreen(
                        viewerX, viewerY, actor.positionX, actor.positionY);
    }

    private void resetAndSendRentalTownStatus() throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) {
            throw new IOException("rental-town selected character snapshot is missing");
        }
        RentalEquipmentBonuses bonuses =
                RentalEquipmentBonuses.from(rentalTownInventory.items());
        RuntimeInventory.NativeArmorBonuses armor =
                rentalTownInventory.equippedNativeArmorBonuses();
        playerMaxHp = NativeCharacterStats.runtimeVital(
                (long) character.maxHp() + bonuses.maximumHp());
        playerMaxMp = NativeCharacterStats.runtimeVital(
                (long) character.maxMp() + bonuses.maximumMp());
        playerHp = playerMaxHp;
        playerMp = playerMaxMp;
        int strength = NativeCharacterStats.runtimeAbility(
                (long) character.strength() + bonuses.strength());
        int constitution = NativeCharacterStats.runtimeAbility(
                (long) character.constitution() + bonuses.constitution());
        int dexterity = NativeCharacterStats.runtimeAbility(
                (long) character.dexterity() + bonuses.dexterity());
        int charisma = NativeCharacterStats.runtimeAbility(
                (long) character.charisma() + bonuses.charisma());
        int intelligence = NativeCharacterStats.runtimeAbility(
                (long) character.intelligence() + bonuses.intelligence());
        int wisdom = NativeCharacterStats.runtimeAbility(
                (long) character.wisdom() + bonuses.wisdom());
        int armorClass = NumericBreakthrough.clampArmorClass(
                (long) character.armorClass() + armor.armorClassModifier());
        int level = NativeCharacterStats.nativeLevel(character.level());
        long experience = NativeCharacterStats.nativeExperience(character.experience());
        int lawful = nativeLawful(character.lawful());
        int food = Math.max(0, Math.min(0xFF, character.food()));
        int fireResistance = NumericBreakthrough.clampElementalResistance(
                bonuses.fireResistance());
        int waterResistance = NumericBreakthrough.clampElementalResistance(
                bonuses.waterResistance());
        int windResistance = NumericBreakthrough.clampElementalResistance(
                bonuses.windResistance());
        int earthResistance = NumericBreakthrough.clampElementalResistance(
                bonuses.earthResistance());
        int spellPowerModifier = NumericBreakthrough.clampMagicModifier(
                bonuses.spellPower());
        int magicResistanceModifier = NumericBreakthrough.clampMagicModifier(
                bonuses.magicResistance());
        sendEncrypted(Protocol.characterStatus(
                        playerObjectId(), level, experience,
                        strength, constitution, dexterity, charisma,
                        intelligence, wisdom, playerHp, playerMp,
                        playerMaxHp, playerMaxMp, armorClass, food, 0, lawful,
                        fireResistance, waterResistance,
                        windResistance, earthResistance),
                "S_STATUS rental-town player=" + playerName()
                        + " equipment=" + bonuses.matchedItems());
        sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                "S_MANA_POINT rental-town player=" + playerName());
        int weight240 = BattleInventoryWeight.weight240(
                rentalTownWeightProfile(rentalTownInventory, System.nanoTime()));
        sendEncrypted(Protocol.abilityScores(strength, constitution, dexterity,
                        charisma, intelligence, wisdom, weight240),
                "S_ABILITY_SCORES rental-town player=" + playerName());
        sendEncrypted(Protocol.experience(level, experience),
                "S_EXP rental-town player=" + playerName());
        sendEncrypted(Protocol.armorClass(armorClass,
                        fireResistance, waterResistance,
                        windResistance, earthResistance),
                "S_AC rental-town player=" + playerName());
        sendEncrypted(Protocol.magicStatus(
                        spellPowerModifier, magicResistanceModifier),
                "S_MAGIC_STATUS rental-town player=" + playerName());
        ExtendedCharacterStatsBridge.publishRuntime(
                selectedClassicServerName, "rental-town-status", character,
                new ExtendedCharacterStatsBridge.RuntimeProjection(
                        playerMaxHp, playerMaxMp, armorClass, level,
                        strength, dexterity, constitution, wisdom,
                        charisma, intelligence,
                        spellPowerModifier, magicResistanceModifier,
                        fireResistance, waterResistance,
                        windResistance, earthResistance));
    }

    private static int signedByte(int value) {
        return Math.max(-128, Math.min(127, value));
    }

    private void createRoom(byte[] payload) throws IOException {
        Protocol.LitoRoomSettingsRequest request = Protocol.litoRoomSettingsRequest(
                payload, Protocol.C_LITO_CREATE_ROOM);
        if (phase != Phase.CHANNEL) {
            System.out.println("[LiTo] C_LITO_CREATE_ROOM rejected invalid-phase=" + phase);
            rejectRoomRequest("create-invalid-phase");
            return;
        }
        if (!GameHub.canCreateRoom(currentChannelId, characterLevel())) {
            System.out.println("[LiTo] C_LITO_CREATE_ROOM rejected upper-tier player=" + playerName()
                    + " level=" + characterLevel() + " channel=" + currentChannelId);
            rejectRoomRequest("create-upper-tier");
            return;
        }
        if (!GameHub.nativeRoomCapacity(request.capacity())) {
            System.out.println("[LiTo] C_LITO_CREATE_ROOM rejected capacity="
                    + request.capacity() + " selected-Taiwan-range=2..100");
            rejectRoomRequest("create-capacity");
            return;
        }
        // C_CC never carries the S_D5 subtype-2 mode. A new room begins on
        // the native deathmatch default; its four editable option bytes start
        // after option0, which remains the independently managed mode field.
        long roomId = hub.createRoom(currentChannelId, new GameHub.RoomSettings(
                request.name(), request.password(), request.capacity(),
                request.attributes() | GameHub.RoomSettings.EQUAL_SIDES,
                BattleRules.Mode.DEATHMATCH.wireId(), request.option1(), request.option2(),
                request.option3(), request.option4(), request.selections()));
        BattleRules.RuleSet rules = hub.roomRules(roomId);
        System.out.println("[LiTo] C_LITO_CREATE_ROOM name=" + request.name()
                + " capacity=" + request.capacity()
                + " attributes=0x" + Integer.toHexString(request.attributes())
                + " layout=" + request.layout() + " mode=" + rules.mode().key()
                + " map=" + rules.mapId() + " selections=" + request.selections());
        Protocol.Writer syntheticJoin = new Protocol.Writer().c(Protocol.C_LITO_JOIN)
                .d(roomId).s(request.password());
        joinRoom(syntheticJoin.bytes(), "create-room");
        retryWaitingMatchMakingSessions("room-created=" + roomId);
    }

    private void rejectRoomRequest(String reason) throws IOException {
        rejectRoomRequest(reason, false);
    }

    private void rejectRoomRequest(String reason, boolean matchmaking) throws IOException {
        rejectRoomRequest(reason, matchmaking, Protocol.LitoJoinFailure.SILENT_CLEANUP);
    }

    private void rejectRoomRequest(String reason, boolean matchmaking,
                                   Protocol.LitoJoinFailure nativeFailure) throws IOException {
        if (matchmaking) {
            sendEncrypted(Protocol.litoAskMatchMakingResult(
                            Protocol.LitoMatchMakingResult.NO_TRANSITION),
                    "S_LITO_ASK_MATCH_MAKING_RESULT no-transition " + reason);
        } else {
            sendEncrypted(Protocol.joinRejected(nativeFailure),
                    "S_LITO_JOIN_RESULT result=" + nativeFailure.wireValue()
                            + " failure=" + nativeFailure + " reason=" + reason);
        }
    }

    private void sendRoomParticipant(long roomId, ClientSession participant,
                                     Protocol.LitoForce force, String note) throws IOException {
        CharacterSummary character = participant.selectedCharacterSummary();
        int characterType = character == null ? 0 : character.type();
        if (characterType < 0 || characterType > 6) {
            // The paired LiTo renderer now supports all seven source classes.
            // Retain a safe fallback only for invalid class identifiers.
            System.out.println("[LiTo] S_LITO_ROOM_USER class fallback player="
                    + participant.playerName() + " source-class=" + characterType
                    + " native-room-class=0 reason=selected-renderer-supports-0..4");
            characterType = 0;
        }
        int sex = character == null ? 0 : character.sex();
        GameStateStore.TournamentStatistics statistics =
                participant.state.tournamentStatistics(
                        participant.sourceCharacterIdentity());
        GameStateStore.TournamentAwards awards =
                participant.state.tournamentAwards(
                        participant.sourceCharacterIdentity());
        int channelRank = participant.state.characterRankings(
                participant.sourceCharacterIdentity()).channel();
        Protocol.LitoParticipantState readyState =
                hub.nativeRoomParticipantReadyState(roomId, participant);
        sendRoomParticipant(roomId, participant.litoDisplayName(), force, characterType, sex,
                statistics, participant.nativeTournamentAffiliationName(), channelRank,
                readyState, awards, note);
    }

    private void sendRoomParticipant(long roomId, String name, Protocol.LitoForce force,
                                     int characterType, int sex,
                                     String affiliationName, int channelRank,
                                     String note) throws IOException {
        sendRoomParticipant(roomId, name, force, characterType, sex,
                new GameStateStore.TournamentStatistics(0, 0, 0, 0),
                affiliationName, channelRank, Protocol.LitoParticipantState.NOT_READY,
                GameStateStore.TournamentAwards.none(), note);
    }

