    private void sendRoomParticipant(long roomId, String name, Protocol.LitoForce force,
                                     int characterType, int sex,
                                     GameStateStore.TournamentStatistics statistics,
                                     String affiliationName, int channelRank,
                                     Protocol.LitoParticipantState readyState,
                                     GameStateStore.TournamentAwards awards,
                                     String note) throws IOException {
        int channelSelector = nativeRoomChannelSelector(roomId);
        // Grade selector 0 is the native Onyx baseline.  The selected client
        // proves all 15 grade resources, but neither it nor the retained
        // classic database contains the original Tournament score thresholds;
        // do not fabricate promotions from rank position or source-server id.
        int tournamentGradeSelector = 0;
        sendEncrypted(Protocol.litoRoomParticipant(
                        roomId, name, force, characterType, sex,
                        statistics, affiliationName, channelSelector, channelRank,
                        readyState, tournamentGradeSelector, awards),
                "S_LITO_ROOM_USER room=" + roomId + " user=" + name
                        + " class=" + characterType + " sex=" + sex
                        + " battles=" + statistics.winRateDenominator()
                        + " wins=" + statistics.wins()
                        + " losses=" + statistics.losses()
                        + " disconnects=" + statistics.disconnects()
                        + " affiliation=" + affiliationName
                        + " channel-selector=" + channelSelector
                        + " channel-rank=" + channelRank
                        + " ready-state=" + readyState.wireValue()
                        + " grade-selector=" + tournamentGradeSelector
                        + " legacy-certificates=" + awards.legacyCertificateCodes()
                        + " victory-badge-editions=" + awards.victoryBadgeEditions()
                        + " lito-master=" + awards.litoMaster()
                        + " role=" + note);
    }

    /**
     * Native S_CD field 14 is the room's four-button Tournament channel,
     * not the pseudo-channel 99 used by /argo.  hubChannelId retains the
     * actual room channel after an /argo observer joins; while browsing the
     * /argo room list the authoritative RoomSnapshot supplies it.  Rental
     * towns do not belong to a Tournament channel and use the selected
     * renderer's signed-byte -1/blank sentinel.
     */
    private int nativeRoomChannelSelector(long roomId) {
        if (rentalTownRoomState) return -1;
        if (hubChannelId >= 0 && hubChannelId < GameHub.CHANNEL_COUNT) {
            return hubChannelId;
        }
        if (currentChannelId == ARGO_CHANNEL_ID) {
            GameHub.RoomSnapshot room = hub.argoRoomSnapshot(roomId);
            if (room != null && room.channelId() >= 0
                    && room.channelId() < GameHub.CHANNEL_COUNT) {
                return room.channelId();
            }
        }
        return -1;
    }

    private void setReady(byte[] payload) throws IOException {
        if (phase != Phase.ROOM) {
            NativeRoomRules.feedback(this);
            return;
        }
        Protocol.LitoReadyRequest request = Protocol.litoReadyRequest(payload);
        Protocol.LitoParticipantState requested = request.ownerStart()
                ? Protocol.LitoParticipantState.READY
                : request.participantState();
        if (rentalTownRoomState) {
            // Native town mode is a server-gated non-battle scene.  C_D2 value
            // 2 is still used while opening room shop/list UI, but value 1
            // must never create a GameHub countdown for this isolated room.
            ready = false;
            Protocol.LitoParticipantState publishedState =
                    requested == Protocol.LitoParticipantState.SHOP_LIST
                            ? Protocol.LitoParticipantState.SHOP_LIST
                            : Protocol.LitoParticipantState.NOT_READY;
            sendEncrypted(Protocol.readyState(litoDisplayName(), publishedState),
                    "S_LITO_READY_GAME rental-town player=" + playerName()
                            + " requested=" + requested.wireValue()
                            + " published=" + publishedState.wireValue());
            NativeRoomRules.feedback(this);
            return;
        }
        // Native value 2 is the room shop/list-entry state emitted before
        // C_DA or C_DE.  Only value 1 means ready; both 0 and 2 must cancel an
        // active countdown instead of accidentally starting one.
        GameHub.ReadyUpdate update = request.ownerStart()
                ? hub.requestOwnerStart(currentRoomId, this)
                : hub.setReady(currentRoomId, this, requested.ready());
        if (request.ownerStart() && !hub.isOwner(currentRoomId, this)) {
            System.out.println("[LiTo] ignored opcode-only C_D2 from non-owner player="
                    + playerName() + " room=" + currentRoomId);
        }
        ready = update.ready();
        Protocol.LitoParticipantState publishedState =
                requested == Protocol.LitoParticipantState.SHOP_LIST
                        ? Protocol.LitoParticipantState.SHOP_LIST
                        : ready ? Protocol.LitoParticipantState.READY
                                : Protocol.LitoParticipantState.NOT_READY;
        byte[] state = Protocol.readyState(litoDisplayName(), publishedState);
        List<ClientSession> members = hub.roomMembers(currentRoomId);
        for (ClientSession member : members) {
            member.sendEncrypted(state, "S_LITO_READY_GAME player=" + playerName()
                    + " ready=" + ready + " request=" + request.operation());
        }
        if (update.minimumPlayersPerForceWarning() > 0) {
            sendEncrypted(Protocol.litoForceMinimumWarning(
                            update.minimumPlayersPerForceWarning()),
                    "S_WARNING_CODE siege-force-minimum="
                            + update.minimumPlayersPerForceWarning());
        }
        if (ready && NativeRoomRules.bot(hub.roomRules(currentRoomId).mode(), this)
                && hub.roomCombatantCount(currentRoomId) < 2) {
            sendEncrypted(Protocol.readyState("ArenaBot", true),
                    "S_LITO_READY_GAME bot ready=true");
        }
        GameHub.ReadyTransition transition = update.transition();
        if (transition == GameHub.ReadyTransition.COUNTDOWN_STARTED) {
            for (ClientSession member : members) member.serverCountdown(3);
        } else if (transition == GameHub.ReadyTransition.COUNTDOWN_CANCELLED) {
            for (ClientSession member : members) member.serverCountdown(0);
        }
        NativeRoomRules.feedback(this);
    }

    void serverCountdown(int value) throws IOException {
        sendEncrypted(new Protocol.Writer().c(Protocol.S_LITO_COUNTDOWN).c(value).bytes(),
                "S_LITO_COUNTDOWN value=" + value);
    }

    void serverStartBattle() throws IOException {
        NativeRoomAdmission.hideStartedRoom(this);
        startBattle();
    }

    void serverPrepareBattle() {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$serverPrepareBattle(scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    void serverEndBattle(BattleRules.Resolution resolution) throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$serverEndBattle(resolution, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    private boolean isPetRaceBattle() {
        return phase == Phase.BATTLE && currentRoomId != 0 && petRaceBaseGfx != 0
                && hub.roomRules(currentRoomId).mode()
                        == BattleRules.Mode.PET_RACE;
    }

    private void awardPetRacePrize() throws IOException {
        InventoryCatalog.Definition definition = InventoryCatalog.require(41308L);
        RuntimeInventory runtimeInventory = this.inventory.copy();
        if (!runtimeInventory.addTournamentReward(definition, 1L)) {
            this.sendEncrypted(Protocol.messageCode(263, new String[0]), "S_MESSAGE_CODE PET_RACE-prize-inventory-full=263");
            System.out.println("[LiTo] PET_RACE prize rejected inventory-capacity player=" + this.playerName() + " catalog=" + definition.catalogId());
            return;
        }
        this.persistSqlTournamentRewards(runtimeInventory);
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, runtimeInventory.catalogCounts(), runtimeInventory.catalogItemStates());
        RuntimeInventory runtimeInventory2 = this.inventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 0);
        this.sendInventoryDelta(runtimeInventory2, this.inventory);
        this.sendEncrypted(Protocol.messageCode(403, definition.name()), "S_MESSAGE_CODE PET_RACE-prize-obtained=403 catalog=" + definition.catalogId());
        System.out.println("[LiTo] PET_RACE prize awarded player=" + this.playerName() + " catalog=" + definition.catalogId() + " quantity=1");
    }

    private void sendBattleResultWarning(int winningForce, String reason) throws IOException {
        String warning = winningForce < 0
                ? "\\f2此場對決雙方交戰平手"
                : "\\f2第" + (winningForce + 1) + "隊對決獲勝";
        sendEncrypted(Protocol.warningCode(166, warning),
                "S_WARNING_CODE code=166 winning-force=" + winningForce + " reason=" + reason);
        String detail = winningForce < 0
                ? "本場隊伍對決平手。"
                : "第" + (winningForce + 1) + "隊獲得本場隊伍對決優勝。";
        sendEncrypted(Protocol.systemMessage(9, detail),
                "S_MESSAGE type=9 winning-force=" + winningForce + " reason=" + reason);
    }

    private void startBattle() throws IOException {
        pendingWarehousePassword = null;
        pendingSlaveTarget = null;
        clearPendingAskCallbacks();
        pendingRepairNpc = null;
        pendingSpellShop = null;
        pendingSpellMaterialShop = null;
        pendingCastleAdmin = null;
        pendingMercenaryAdmin = null;
        pendingCastleSecurity = null;
        pendingHouseAuctionBid = null;
        pendingClientIntegrity = null;
        clientIntegrityVerified = false;
        clearPendingClassicList();
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(
                hub.battleMapId(currentRoomId, this));
        if (config.nativeTournamentEconomyEnabled() && nativeTournamentEconomyInitialized) {
            // Commit the unused round allowance before changing native scene.
            // Purchased items remain intact for the world inventory bootstrap.
            state.saveEconomyState(stateCharacter(), 0,
                    inventory.catalogCounts(), inventory.catalogItemStates());
            shopPoints = 0;
            pendingTournamentShop = null;
            // S_DB is the point receiver while the client is still in ROOM.
            sendPointStats();
            System.out.println("[LiTo] cleared unused Tournament allowance before world player=" + playerName());
        }
        if (config.nativeIntegrityPreWorldProbe()) {
            // Isolated diagnostics can prove the original C_ADDR producer
            // before a compatibility-only client reaches world rendering.
            // Production defaults false and retains the native post-bootstrap
            // challenge order below.
            NativePlayerCommit.scene(this, Phase.BATTLE, "phase");
            sendClientIntegrityChallenge();
        }
        // The native S_WORLD handler resolves dword_75A898 from the arena id.
        // S_D2 consumes that value immediately while replacing the room
        // callbacks, so WORLD must be sent first.  This is a state dependency,
        // not merely a cosmetic packet order.
        Protocol.BattleBootstrap bootstrap = Protocol.battleBootstrap(
                arena.mapId(), rules.timeLimitSeconds());
        sendEncrypted(bootstrap.world(),
                "S_WORLD arena-map=" + arena.mapId() + " mode=" + rules.mode().key());
        sendEncrypted(bootstrap.start(), "S_LITO_START_GAME");
        sendEncrypted(Protocol.observerBox(
                        arena.minX(), arena.minY(), arena.maxX() + 1, arena.maxY() + 1),
                "S_LITO_OBSERVER_BOX min=" + arena.minX() + "," + arena.minY()
                        + " max-exclusive=" + (arena.maxX() + 1) + "," + (arena.maxY() + 1));
        if (rules.mode() != BattleRules.Mode.TIME_ATTACK) {
            sendEncrypted(bootstrap.timeLimit(),
                    "S_LITO_TIMELIMIT battle-seconds=" + rules.timeLimitSeconds());
        }
        NativePlayerCommit.scene(this, Phase.BATTLE, "phase");
        notifyBuddyActivity(Protocol.LitoBuddyActivity.FIGHTING);
        int gameSeconds = ClassicLineageClock.now();
        sendEncrypted(Protocol.worldTime(gameSeconds),
                "S_TIME game-seconds=" + gameSeconds
                        + " native-second-of-day="
                        + ClassicLineageClock.nativeClientSecondOfDay(gameSeconds));
        // S_ADD_INVENTORY_BATCH is a world-state receiver in the protected
        // client. Sending it from the character/channel screen runs before
        // S_WORLD has constructed the native scene and terminates LiTo.bin.
        // Bootstrap the inventory only after WORLD/START/TIME establish the
        // battle phase; the client still receives the complete authoritative
        // inventory before status, objects, or player input are accepted.
        sendInventoryBootstrap();
        // GameHub prepares all initial combatants before dispatching the first
        // roster. This idempotent local reset also covers direct participant
        // entry paths without altering an already-running match for observers.
        if (!observer) resetBattleVitals();
        CombatPoisonLifecycle.last(this, null);
        deathConfirmationPending = false;
        terminalEffectResultNotBeforeNanos = 0;
        resultRecorded = false;
        pendingPortal = null;
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = null;
        List<ClientSession> battleMembers = NativeBattleVisibility.localFirst(hub.visibleBattleCombatants(
                currentRoomId, this), this);
        List<GameHub.RoomVirtualPlayer> virtualPlayers =
                hub.battleVirtualPlayers(currentRoomId);
        boolean includesBot = rules.mode() != BattleRules.Mode.PET_RACE
                && rules.mode() != BattleRules.Mode.QUEST_BATTLE
                && rules.mode() != BattleRules.Mode.TIME_ATTACK
                && battleMembers.size() < 2 && virtualPlayers.isEmpty();
        includesBot = NativeRoomRules.activeBot(this);
        if (rules.mode() == BattleRules.Mode.PET_RACE) {
            sendNativeRaceHud(battleMembers);
        }
        sendBattleStatus();
        if (!observer && !learnedSkills.isEmpty()) {
            sendEncrypted(Protocol.addSpells(learnedSkills),
                    "S_ADD_SPELL learned-count=" + learnedSkills.size());
        }
        sendStoredBookmarks();
        int roomWeather = hub.roomWeather(currentRoomId);
        if (roomWeather != 0) {
            sendEncrypted(Protocol.weather(roomWeather),
                    "S_WEATHER restored encoded=" + roomWeather);
        }
        int index = 0;
        for (ClientSession member : battleMembers) {
            int spawnIndex = hub.battleSpawnIndex(currentRoomId, member);
            ArenaMapCatalog.Point spawn = battleSpawn(arena, spawnIndex);
            if (member == this) {
                positionX = spawn.x();
                positionY = spawn.y();
            }
            // An observer may enter an already-running battle while a
            // combatant is hidden. Native world enumeration omits that actor;
            // only the hidden local actor may be rebuilt, with status bit 2.
            if (!member.invisible || member == this) {
                sendBattleObject(member.playerObjectId(), member.litoDisplayName(),
                        member.sourceCharacterIdentity(), spawn.x(), spawn.y(),
                        member.battleGfx(), member.battleWalkAction(), member.battleLightRange(),
                        member.battleMoveSpeed(),
                        4 | (member.invisible ? 2 : 0), member.battleLevel(),
                        nativeLawful(member.characterLawful()), member.classicTitle,
                        member == this ? 0xFF : member.battleHpRatio());
                if (member == this && config.cloneAppearanceProbeEnabled()) {
                    // Prove the update-only receiver against the local actor
                    // before companion, ArenaBot and optional fixture objects
                    // can affect the causal result.
                    sleepForBootstrap(1500, "local actor native object creation dwell");
                    serverCloneAppearanceProbeMutation(currentRoomId, false);
                    sleepForBootstrap(1500, "S_CLONE native receiver dwell");
                    serverCloneAppearanceProbeRestore(currentRoomId);
                }
            }
            sendBattleCompanion(member, arena, spawn, "battle-bootstrap");
            index++;
        }
        Map<Long, ArenaMapCatalog.Point> virtualSpawns = new LinkedHashMap<>();
        for (GameHub.RoomVirtualPlayer member : virtualPlayers) {
            ArenaMapCatalog.Point spawn = battleSpawn(arena, index++);
            virtualSpawns.put(member.objectId(), spawn);
            sendBattleObject(member.objectId(), member.name(), member.name(),
                    spawn.x(), spawn.y(), 61, BattleActionCodes.WALK, 0,
                    BattleTimedStatus.NORMAL, 0, 1, 0, "", 100);
        }
        sendCastleOwnerMappings(battleMembers, "battle-bootstrap");
        ArenaMapCatalog.Point bot = arena.botSpawn();
        if (includesBot) {
            sendBattleObject(2, "ArenaBot", "ArenaBot", bot.x(), bot.y(), 61,
                    BattleActionCodes.WALK, 0, BattleTimedStatus.NORMAL, 0, 1, 0, "", Protocol.healthRatio(
                            hub.botHp(currentRoomId), GameHub.ARENA_BOT_MAX_HP));
        }
        sendGuardianTowers("battle-bootstrap");
        sendQuestMonsters("battle-bootstrap");
        sendQuestBoundary("battle-bootstrap");
        sendTimeAttackActors("battle-bootstrap");
        sendBattleDoor("battle-bootstrap");
        sendSiegeGate("battle-bootstrap");
        sendRepairNpc("battle-bootstrap");
        sendSpellShopNpc("battle-bootstrap");
        sendSpellMaterialNpc("battle-bootstrap");
        sendClassicMerchantNpc("battle-bootstrap");
        sendWarehouseNpc("battle-bootstrap");
        sendCastleStewardNpc("battle-bootstrap");
        sendHouseAuctionBoard("battle-bootstrap");
        sendMercenaryCommanderNpc("battle-bootstrap");
        sendGroundItems("battle-bootstrap");
        sendCookingFires("battle-bootstrap");
        sendCubeIgnitions("battle-bootstrap");
        sendCubeQuakes("battle-bootstrap");
        sendCubeShocks("battle-bootstrap");
        sendCubeHarmonies("battle-bootstrap");
        sendShockStunEffects("battle-bootstrap");
        sendBoneBreakEffects("battle-bootstrap");
        sendFreezeEffects("battle-bootstrap");
        sendBattleCompanionMasters(battleMembers, "battle-bootstrap");
        sendBattleSpeedStates(battleMembers, "battle-bootstrap");
        sendBattleBraveStates(battleMembers, "battle-bootstrap");
        sendBattleBlindState("battle-bootstrap");
        sendBattleBreathState("battle-bootstrap");
        sendBattleDrunkenState("battle-bootstrap");
        sendBattlePoisonStates(battleMembers, "battle-bootstrap");
        sendBattleParalysisState("battle-bootstrap");
        sendBattleSleepState("battle-bootstrap");
        sendBattleFreezeState("battle-bootstrap");
        sendBattleShockStunState("battle-bootstrap");
        sendBattleThunderGrabState("battle-bootstrap");
        if (invisible && !observer) {
            sendEncrypted(Protocol.invisible(playerObjectId(), 1),
                    "S_INVISIBLE mode=1 reason=battle-bootstrap-local-rebuild");
        }
        // S_FA mutates an already-created world object, so all S_PUT_OBJECT
        // rows must precede the optional clan metadata pass.
        for (ClientSession member : battleMembers) {
            if (member.invisible && member != this) continue;
            GameHub.ClanData clan = hub.clanData(member.sourceCharacterIdentity());
            if (clan.name().isBlank()) continue;
            sendEncrypted(Protocol.battleClanMetadata(
                            member.playerObjectId(), 0, clan.name(), true),
                    "S_LITO_CLAN object=" + member.playerObjectId() + " clan=" + clan.name());
        }
        for (GameHub.RoomVirtualPlayer member : virtualPlayers) {
            ArenaMapCatalog.Point spawn = virtualSpawns.get(member.objectId());
            boolean allied = minimapAlliedWithForce(member.force());
            sendEncrypted(Protocol.minimapPlayer(
                            member.objectId(), spawn.x(), spawn.y(), allied),
                    "S_LITO_MINIMAP player=" + member.name() + " x=" + spawn.x()
                            + " y=" + spawn.y() + " allied=" + allied);
        }
        sendCurrentClassicClanWarState();
        for (ClientSession member : battleMembers) {
            ArenaMapCatalog.Point spawn = battleSpawn(
                    arena, hub.battleSpawnIndex(currentRoomId, member));
            boolean allied = minimapAlliedWith(member);
            sendEncrypted(Protocol.minimapPlayer(member.playerObjectId(), spawn.x(), spawn.y(), allied),
                    "S_LITO_MINIMAP player=" + member.playerName() + " x=" + spawn.x()
                            + " y=" + spawn.y() + " allied=" + allied);
        }
        if (includesBot) {
            boolean allied = minimapAlliedWithForce(1);
            sendEncrypted(Protocol.minimapPlayer(2, bot.x(), bot.y(), allied),
                    "S_LITO_MINIMAP player=ArenaBot x=" + bot.x() + " y=" + bot.y()
                            + " allied=" + allied);
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT player=" + playerHp + "/" + playerMaxHp);
        if (!config.nativeIntegrityPreWorldProbe()) sendClientIntegrityChallenge();
        System.out.println("[LiTo] battle started room=" + currentRoomId + " player=" + playerName()
                + " mode=" + rules.mode().key() + " map=" + arena.mapId()
                + " goal=" + rules.goal() + " seconds=" + rules.timeLimitSeconds());
    }

    private void sendClientIntegrityChallenge() throws IOException {
        long challengeId;
        do {
            challengeId = Integer.toUnsignedLong(ThreadLocalRandom.current().nextInt());
        } while (challengeId == 0);
        pendingClientIntegrity = new PendingClientIntegrity(challengeId, currentRoomId,
                System.nanoTime() + NativeClientIntegrity.RESPONSE_TIMEOUT_NANOS);
        sendEncrypted(Protocol.addressChallenge(challengeId,
                        NativeClientIntegrity.RANGE_START, NativeClientIntegrity.RANGE_LENGTH),
                "S_EVENT subtype=33 native-integrity range=0x"
                        + Long.toHexString(NativeClientIntegrity.RANGE_START).toUpperCase()
                        + " length=" + NativeClientIntegrity.RANGE_LENGTH);
    }

    private void submitAddressProof(byte[] payload) {
        Protocol.AddressProof proof = Protocol.addressProof(payload);
        PendingClientIntegrity pending = pendingClientIntegrity;
        String rejection = null;
        if (pending == null) rejection = "no-pending-challenge";
        else if (phase != Phase.BATTLE || currentRoomId == 0
                || pending.roomId() != currentRoomId) rejection = "invalid-phase";
        else if (System.nanoTime() > pending.expiresAtNanos()) {
            pendingClientIntegrity = null;
            rejection = "expired";
        } else if (proof.challengeId() != pending.challengeId()) {
            rejection = "challenge-mismatch";
        } else if (!NativeClientIntegrity.checksumMatches(proof.checksum())) {
            rejection = "checksum-mismatch";
        }
        if (rejection != null) {
            System.out.println("[LiTo] rejected C_ADDR native-integrity account=" + account
                    + " phase=" + phase + " reason=" + rejection);
            return;
        }
        pendingClientIntegrity = null;
        clientIntegrityVerified = true;
        System.out.println("[LiTo] verified C_ADDR native-integrity account=" + account
                + " room=" + currentRoomId + " protected-state=" + proof.protectedState());
    }

    private ArenaMapCatalog.Point battleSpawn(ArenaMapCatalog.Arena arena, int spawnIndex) {
        BattleRules.RuleSet rules = hub.roomRules(currentRoomId);
        if (rules.mapId() != arena.mapId()) {
            throw new IllegalStateException("room arena changed during player deployment");
        }
        return hub.battleSpawn(currentRoomId, spawnIndex);
    }

    private void sendNativeRaceHud(List<ClientSession> battleMembers)
            throws IOException {
        List<Protocol.RaceEntry> roster = new ArrayList<>();
        for (ClientSession member : battleMembers) {
            int force = hub.forceOf(currentRoomId, member);
            roster.add(new Protocol.RaceEntry(force >= 2 ? 1 : 0,
                    member.litoDisplayName()));
        }
        for (GameHub.RoomVirtualPlayer member : hub.battleVirtualPlayers(currentRoomId)) {
            roster.add(new Protocol.RaceEntry(member.force(), member.name()));
        }
        int localIndex = observer ? -1 : battleMembers.indexOf(this);
        sendEncrypted(Protocol.raceRoster(localIndex, roster),
                "S_LITO_RACE_INFO subtype=1 roster=" + roster.size()
                        + " local-index=" + localIndex);
        int currentLap = observer ? 0 : 1;
        sendEncrypted(Protocol.raceValues(BattlePetRaceCourseCatalog.LAPS, currentLap),
                "S_LITO_RACE_INFO subtype=2 maximum-laps="
                        + BattlePetRaceCourseCatalog.LAPS + " current-lap=" + currentLap);
        sendEncrypted(Protocol.raceTimerStart(),
                "S_LITO_RACE_INFO subtype=0 timer-start");
    }

    private void sendBattleStatus() throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        long now = System.nanoTime();
        BattleCookingStatus.Snapshot cooking = cookingStatus.active(now);
        int level = clientStatusLevel(character);
        int sourceBaseMaxHp = sourceBaseMaximumHp(character);
        int sourceBaseMaxMp = sourceBaseMaximumMp(character);
        int baseMaxHp = awakeningAdjustedMaximumHp(
                equipmentAdjustedBaseMaxHp(character));
        int baseMaxMp = equipmentAdjustedBaseMaxMp(character);
        int maxHp = battleMaximumWithAdvanceSpirit(
                baseMaxHp, sourceBaseMaxHp, cooking.maxHp(), now);
        int maxMp = battleMaximumWithAdvanceSpirit(
                baseMaxMp, sourceBaseMaxMp, cooking.maxMp(), now);
        int strength = battleStrength(now);
        int constitution = effectiveConstitution(now);
        int dexterity = battleDexterity(now);
        int charisma = effectiveCharisma(character);
        int intelligence = requiredEquipmentMagicStats()
                .effectiveIntelligence(baseIntelligence(now));
        int wisdom = effectiveWisdom(now);
        int armorClass = battleArmorClass(now);
        long experience = effectiveClassicExperience(character);
        playerMaxHp = NumericBreakthrough.clampVital(maxHp);
        playerMaxMp = NumericBreakthrough.clampVital(maxMp);
        playerHp = Math.min(playerHp, playerMaxHp);
        playerMp = Math.min(playerMp, playerMaxMp);

        sendNativeBattleStatus(now, "battle-status");
        sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                "S_MANA_POINT player=" + playerName() + " mp=" + playerMp
                        + "/" + playerMaxMp);
        sendEncrypted(Protocol.abilityScores(strength, constitution, dexterity,
                        charisma, intelligence, wisdom, currentWeight240(now)),
                "S_ABILITY_SCORES player=" + playerName());
        sendEncrypted(Protocol.experience(level, experience),
                "S_EXP player=" + playerName() + " level=" + level
                        + " experience=" + experience);
        sendEncrypted(ownCharacterAttrDef(armorClass, now),
                "S_AC player=" + playerName() + " base=" + armorClass);
        // Native S_SPMR semantics are modifier bytes, not total SP/MR.
        // Cooking contributes its exact active SP and MR modifiers.
        sendMagicStatus(now, "battle-status");
        sendActiveAbilityBuffs(now, "battle-status");
    }

    private void sendLobbyStatusIfQualified() throws IOException {
        if (sourceEquippedFireResistance == null
                || sourceBaseMagicResistance == null
                || sourceEquipmentMagicStats == null
                || sourceEquipmentVitalStats == null
                || sourcePhysicalGrowthStats == null
                || sourceInventoryWeightStats == null) {
            // Only synthetic/unit harnesses can enter CHANNEL without first
            // completing C_C9.  Keep those state-machine probes isolated; a
            // real selected character always owns every qualified snapshot.
            System.out.println("[LiTo] lobby status skipped without qualified character"
                    + " player=" + playerName());
            return;
        }
        sendBattleStatus();
    }

    private void sendEquipmentStatusRefresh(String reason) throws IOException {
        long now = System.nanoTime();
        rebuildMaximumVitals(now);
        CharacterSummary character = selectedCharacterSummary();
        int strength = battleStrength(now);
        int constitution = effectiveConstitution(now);
        int dexterity = battleDexterity(now);
        int charisma = effectiveCharisma(character);
        int intelligence = requiredEquipmentMagicStats()
                .effectiveIntelligence(baseIntelligence(now));
        int wisdom = effectiveWisdom(now);
        int armorClass = battleArmorClass(now);
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT player=" + playerName() + " hp=" + playerHp
                        + "/" + playerMaxHp + " reason=" + reason);
        sendNativeBattleStatus(now, reason);
        sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                "S_MANA_POINT player=" + playerName() + " mp=" + playerMp
                        + "/" + playerMaxMp + " reason=" + reason);
        sendEncrypted(Protocol.abilityScores(strength, constitution, dexterity,
                        charisma, intelligence, wisdom, currentWeight240(now)),
                "S_ABILITY_SCORES player=" + playerName() + " reason=" + reason);
        sendEncrypted(ownCharacterAttrDef(armorClass, now),
                "S_AC player=" + playerName() + " base=" + armorClass
                        + " reason=" + reason);
        sendMagicStatus(now, reason);
    }

    private void sendNativeBattleStatus(long nowNanos, String reason) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        BattleCookingStatus.Snapshot cooking = cookingStatus.active(nowNanos);
        int level = clientStatusLevel(character);
        long experience = effectiveClassicExperience(character);
        int strength = battleStrength(nowNanos);
        int constitution = effectiveConstitution(nowNanos);
        int dexterity = battleDexterity(nowNanos);
        int charisma = effectiveCharisma(character);
        int intelligence = requiredEquipmentMagicStats()
                .effectiveIntelligence(baseIntelligence(nowNanos));
        int wisdom = effectiveWisdom(nowNanos);
        int armorClass = battleArmorClass(nowNanos);
        int food = character == null ? 40 : Math.max(0, Math.min(0xFF, character.food()));
        int weight240 = currentWeight240(nowNanos);
        int lawful = character == null ? 0 : playerLawful;
        int fireResistance = effectiveSpellElementalResistance(
                BattleSpellCatalog.ATTRIBUTE_FIRE, nowNanos);
        int waterResistance = effectiveSpellElementalResistance(
                BattleSpellCatalog.ATTRIBUTE_WATER, nowNanos);
        int windResistance = effectiveSpellElementalResistance(
                BattleSpellCatalog.ATTRIBUTE_WIND, nowNanos);
        int earthResistance = effectiveSpellElementalResistance(
                BattleSpellCatalog.ATTRIBUTE_EARTH, nowNanos);

        // Exact LiTo sub_4A36F0: dcdcccccchhhhcdcchcccc. After AC it reads
        // game time, food, one-byte weight, lawful and four elemental
        // resistances. Schema 4 widens only those final four fields to dword.
        // LiTo has no PACKETBOX receiver because opcode FA is its Tournament
        // clan packet.
        byte[] packet = Protocol.characterStatus(
                playerObjectId(), level, experience,
                strength, constitution, dexterity, charisma, intelligence, wisdom,
                playerHp, playerMp, playerMaxHp, playerMaxMp,
                armorClass, food, weight240, lawful,
                fireResistance, waterResistance,
                windResistance, earthResistance);
        sendEncrypted(packet, "S_STATUS player=" + playerName()
                + " object=" + playerObjectId() + " level=" + level
                + " weight240=" + weight240 + " reason=" + reason);
        if (character != null) {
            ExtendedCharacterStatsBridge.publishRuntime(
                    selectedClassicServerName, reason, character,
                    new ExtendedCharacterStatsBridge.RuntimeProjection(
                            playerMaxHp, playerMaxMp, armorClass, level,
                            strength, dexterity, constitution, wisdom,
                            charisma, intelligence,
                            NumericBreakthrough.clampMagicModifier(
                                    spellPowerModifier(nowNanos)),
                            NumericBreakthrough.clampMagicModifier(
                                    magicResistanceModifier(nowNanos)),
                            fireResistance, waterResistance,
                            windResistance, earthResistance));
        }
    }

    private void sendWisdomStatusRefresh(long nowNanos, String reason)
            throws IOException {
        sendNativeBattleStatus(nowNanos, reason);
        sendAbilityScoresStatus(nowNanos, reason);
    }

    /** Exact selected-client equivalent of retained S_OwnCharStatus2. */
    private void sendAbilityScoresStatus(long nowNanos, String reason)
            throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        sendEncrypted(Protocol.abilityScores(
                        battleStrength(nowNanos), effectiveConstitution(nowNanos),
                        battleDexterity(nowNanos), effectiveCharisma(character),
                        requiredEquipmentMagicStats()
                                .effectiveIntelligence(baseIntelligence(nowNanos)),
                        effectiveWisdom(nowNanos), currentWeight240(nowNanos)),
                "S_ABILITY_SCORES player=" + playerName()
                        + " reason=" + reason);
    }

    private void sendSchema2AbilityScoresStatus(long nowNanos, String reason)
            throws IOException {
        if (NumericBreakthrough.levelAbilityEnabled()) {
            sendAbilityScoresStatus(nowNanos, reason);
        }
    }

    private void sendActiveAbilityBuffs(long nowNanos, String reason) throws IOException {
        // Native buff handlers require the world icon list at 0x00760744.
        // S_MAGE_SHIELD in CHANNEL calls 0x004875C0 with that list still null;
        // defer icon restoration until the world/battle UI has been created.
        if (phase != Phase.BATTLE && phase != Phase.WORLD) {
            return;
        }
        BattleAbilityStatus.ArmorProtection shield =
                abilityStatus.armorProtection(nowNanos);
        BattleAbilityStatus.Modifier dexterity = abilityStatus.dexterity(nowNanos);
        BattleAbilityStatus.Modifier strength = abilityStatus.strength(nowNanos);
        int dexteritySkillId = abilityStatus.dexteritySkillId(nowNanos);
        int strengthSkillId = abilityStatus.strengthSkillId(nowNanos);
        if (shield.remainingSeconds() > 0) {
            BattleSpellCatalog.ShieldSpell spell =
                    BattleSpellCatalog.shieldSpell(shield.skillId());
            if (spell == null) {
                throw new IllegalStateException(
                        "unknown active armor-protection skill " + shield.skillId());
            }
            sendEncrypted(Protocol.mageShield(shield.remainingSeconds(), spell.iconType()),
                    "S_MAGE_SHIELD restore duration=" + shield.remainingSeconds()
                            + " type=" + spell.iconType() + " reason=" + reason);
        }
        if (dexterity.remainingSeconds() > 0) {
            BattleSpellCatalog.AbilityBuffSpell spell = BattleSpellCatalog.abilityBuffSpell(
                    dexteritySkillId);
            if (spell == null) {
                throw new IllegalStateException(
                        "unknown active dexterity skill " + dexteritySkillId);
            }
            sendEncrypted(Protocol.mageDexterity(dexterity.remainingSeconds(),
                            battleDexterity(nowNanos), spell.activeType()),
                    "S_MAGE_DEXTERITY restore duration=" + dexterity.remainingSeconds()
                            + " value=" + battleDexterity(nowNanos)
                            + " reason=" + reason);
        }
        if (strength.remainingSeconds() > 0) {
            BattleSpellCatalog.AbilityBuffSpell spell = BattleSpellCatalog.abilityBuffSpell(
                    strengthSkillId);
            if (spell == null) {
                throw new IllegalStateException(
                        "unknown active strength skill " + strengthSkillId);
            }
            sendEncrypted(Protocol.mageStrength(strength.remainingSeconds(),
                            battleStrength(nowNanos), currentWeight240(nowNanos),
                            spell.activeType()),
                    "S_MAGE_STRENGTH restore duration=" + strength.remainingSeconds()
                            + " value=" + battleStrength(nowNanos)
                            + " weight240=" + currentWeight240(nowNanos)
                            + " reason=" + reason);
        }
    }

    private CharacterSummary selectedCharacterSummary() {
        return characters.stream()
                .filter(entry -> entry.name().equalsIgnoreCase(selectedCharacter))
                .findFirst()
                .orElse(characters.isEmpty() ? null : characters.get(0));
    }

    private void reconcileElfPk(CharacterSummary character) throws IOException {
        GameStateStore.ElfPkBalance balance = state.reconcileElfPk(
                stateCharacter(), character == null ? 0 : character.pkCountForElf(),
                character == null ? 0 : character.lastPkForElfEpochSeconds());
        elfPkCount = balance.effective().count();
        lastPkForElfEpochSeconds = balance.effective().lastPkEpochSeconds();
    }

    private void reconcileGeneralPk(CharacterSummary character) throws IOException {
        GameStateStore.GeneralPkBalance balance = state.reconcileGeneralPk(
                stateCharacter(), character == null ? 0 : character.pkCount(),
                character == null ? 0 : character.lastPkEpochSeconds());
        generalPkCount = balance.effective().count();
        lastPkEpochSeconds = balance.effective().lastPkEpochSeconds();
    }

    private void reconcileClassicKillDeath(SourceKillDeathCounts sourceCounts)
            throws IOException {
        GameStateStore.ClassicKillDeathBalance balance =
                state.reconcileClassicKillDeath(stateCharacter(), sourceCounts);
        classicKillCount = balance.effective().kills();
        classicDeathCount = balance.effective().deaths();
    }

    private void reconcileHell(int sourceTicks) throws IOException {
        GameStateStore.HellBalance balance = state.reconcileHell(
                stateCharacter(), Math.max(0, sourceTicks));
        hellRemainingTicks = balance.effective().remainingTicks();
        hellClock.clear();
    }

    private void reconcileClassicExperience(CharacterSummary character) throws IOException {
        long sourceExperience = character == null ? 0 : character.experience();
        int sourceLevel = character == null ? 1 : Math.max(1,
                Math.min(ClassicExperienceCatalog.MAXIMUM_LEVEL, character.level()));
        GameStateStore.ClassicExperienceBalance balance =
                state.reconcileClassicExperience(
                        stateCharacter(), sourceExperience, sourceLevel);
        playerClassicExperience = balance.effectiveExperience();
        playerClassicLevel = balance.effectiveLevel();
    }

    private int effectiveClassicLevel(CharacterSummary character) {
        return character == null ? 1 : Math.max(1, playerClassicLevel);
    }

    /**
     * Classic experience mechanics intentionally remain capped at level 99.
     * Schema 2 nevertheless publishes a database level above that native
     * rules ceiling losslessly to the patched client.
     */
    private int clientStatusLevel(CharacterSummary character) {
        int classicLevel = effectiveClassicLevel(character);
        int sourceLevel = character == null ? classicLevel : character.level();
        return NumericBreakthrough.clientStatusLevel(sourceLevel, classicLevel);
    }

    private long effectiveClassicExperience(CharacterSummary character) {
        return character == null ? 0 : playerClassicExperience;
    }

    private void resetBattleVitals() {
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        long l = System.nanoTime();
        BattleCookingStatus.Snapshot snapshot = this.cookingStatus.active(l);
        int n = ClientSession.sourceBaseMaximumHp(characterSummary);
        int n2 = ClientSession.sourceBaseMaximumMp(characterSummary);
        int n3 = this.awakeningAdjustedMaximumHp(this.equipmentAdjustedBaseMaxHp(characterSummary));
        int n4 = this.equipmentAdjustedBaseMaxMp(characterSummary);
        this.playerMaxHp = this.battleMaximumWithAdvanceSpirit(n3, n, snapshot.maxHp(), l);
        this.playerMaxMp = this.battleMaximumWithAdvanceSpirit(n4, n2, snapshot.maxMp(), l);
        int restoredHp = this.playerMaxHp;
        NativePlayerCommit.advance(this);
        this.playerHp = restoredHp;
        this.playerMp = this.playerMaxMp;
        this.terminalEffectResultNotBeforeNanos = 0L;
        this.lastCombatTargetObjectId = 0L;
        this.clearInvisibilityStateSilently();
        this.venomEnchantStatus.clear();
        this.naturalHpRegen.reset(l);
        this.naturalMpRegen.reset(l);
    }

    private void rebuildMaximumVitals(long nowNanos) {
        CharacterSummary character = selectedCharacterSummary();
        BattleCookingStatus.Snapshot cooking = cookingStatus.active(nowNanos);
        int sourceBaseMaxHp = sourceBaseMaximumHp(character);
        int sourceBaseMaxMp = sourceBaseMaximumMp(character);
        int baseMaxHp = awakeningAdjustedMaximumHp(
                equipmentAdjustedBaseMaxHp(character));
        int baseMaxMp = equipmentAdjustedBaseMaxMp(character);
        playerMaxHp = battleMaximumWithAdvanceSpirit(
                baseMaxHp, sourceBaseMaxHp, cooking.maxHp(), nowNanos);
        playerMaxMp = battleMaximumWithAdvanceSpirit(
                baseMaxMp, sourceBaseMaxMp, cooking.maxMp(), nowNanos);
        playerHp = Math.min(playerHp, playerMaxHp);
        playerMp = Math.min(playerMp, playerMaxMp);
    }

    private int battleMaximumWithAdvanceSpirit(
            int adjustedMaximum, int sourceBaseMaximum,
            int cookingBonus, long nowNanos) {
        long maximum = cookingAdjustedMaximum(adjustedMaximum, cookingBonus);
        if (timedStatus.advanceSpiritActive(nowNanos)) {
            BattleSpellCatalog.AdvanceSpiritSpell spell =
                    BattleSpellCatalog.advanceSpiritSpell(
                            BattleSpellCatalog.ADVANCE_SPIRIT);
            maximum = spell.maximumWithBonus(
                    (int) maximum, sourceBaseMaximum);
        }
        return NumericBreakthrough.clampVital(maximum);
    }

    private int awakeningAdjustedMaximumHp(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("invalid awakening maximum HP base");
        }
        return NumericBreakthrough.clampVital(Math.addExact((long)n, (long)CombatAwaken.ability(this.awakenStatus.snapshot(), "HP")));
    }

    private void sendBattleObject(long objectId, String name, String characterIdentity,
                                  int x, int y, int gfx,
                                  int requestedWalkAction, int lightRange, int moveSpeed,
                                  int status, int level, int lawful,
                                  String title, int hpRatio) throws IOException {
        sendBattleObjectAtHeading(objectId, name, characterIdentity,
                x, y, gfx, requestedWalkAction, 0, lightRange, moveSpeed,
                status, level, lawful, title, hpRatio);
    }

    private void sendBattleObjectAtHeading(
            long objectId, String name, String characterIdentity,
            int x, int y, int gfx, int requestedWalkAction, int heading,
            int lightRange, int moveSpeed, int status, int level, int lawful,
            String title, int hpRatio) throws IOException {
        BattleAnimationCatalog animations = BattleAnimationCatalog.get();
        int walkAction = animations.requireWalkAction(gfx, requestedWalkAction);
        int attackAction = animations.requireAttackAction(gfx, walkAction);
        // The first byte after gfx is the equipped weapon's WALK action.  The
        // status byte after title is independently 4 for PCs and 0 for
        // NPC/monsters; the former type/sex names at the tail were incorrect.
        boolean playerActor = (status & 4) != 0;
        GameHub.ClanData clan = playerActor
                ? hub.clanData(characterIdentity) : GameHub.ClanData.empty();
        long emblemId = playerActor ? hub.clanEmblemId(characterIdentity) : 0;
        byte[] packet = Protocol.battleActorWithHeading(
                objectId, x, y, gfx, walkAction, heading, lightRange,
                moveSpeed, name, title == null ? "" : title, status, emblemId,
                clan.name(), lawful, hpRatio, level);
        sendEncrypted(packet, "S_PUT_OBJECT object=" + objectId + " name=" + name
                + " gfx=" + gfx + " walk-action=" + walkAction
                + " heading=" + heading
                + " attack-action=" + attackAction + " status=" + status
                + " light-range=" + lightRange + " move-speed=" + moveSpeed
                + " lawful=" + lawful + " hp-ratio=" + hpRatio + " level=" + level
                + " clan=" + clan.name() + " emblem=" + emblemId);
    }

    private void sendBattleCompanion(ClientSession clientSession, ArenaMapCatalog.Arena arena, ArenaMapCatalog.Point point, String string) throws IOException {
        for (BattleCompanion.Snapshot snapshot : clientSession.controlledCompanionSnapshots()) {
            if (!snapshot.active()) continue;
            this.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(), snapshot.x(), snapshot.y(), snapshot.gfx(), 0, 0, snapshot.moveSpeed(), 0, snapshot.level(), 0, clientSession.playerName(), NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()));
            System.out.println("[LiTo] companion rebuilt object=" + snapshot.objectId() + " npc=" + snapshot.npcId() + " owner=" + clientSession.playerName() + " x=" + snapshot.x() + " y=" + snapshot.y() + " reason=" + string);
        }
    }

    private void sendBattleCompanionMasters(List<ClientSession> owners, String reason)
            throws IOException {
        for (ClientSession owner : owners) {
            for (BattleCompanion.Snapshot companion : owner.controlledCompanionSnapshots()) {
                if (!companion.active()) continue;
                sendEncrypted(Protocol.master(companion.objectId(), owner.playerName()),
                        "S_MASTER companion=" + companion.objectId()
                                + " owner=" + owner.playerName() + " reason=" + reason);
            }
        }
    }

