        if (door == null) return;
        sendEncrypted(Protocol.battleDoor(
                        door.objectId(), door.x(), door.y(), door.action()),
                "S_PUT_OBJECT door=" + door.objectId() + " gfx=" + BattleDoor.GFX
                        + " x=" + door.x() + " y=" + door.y()
                        + " action=" + door.action() + " reason=" + reason);
