    private ArenaMapCatalog.Point activeRepairNpcPoint(long l) {
        if (this.phase == Phase.BATTLE && l == this.repairNpcObjectId()) {
            return this.repairNpcPoint();
        }
        if (this.phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(this.classicWorldMapId)) {
            return null;
        }
        ClassicWorldNpcCatalog.StaticNpc staticNpc = ClassicWorldNpcCatalog.npc(this.classicWorldMapId, l);
        return ClassicWorldBehemothSilveriaCatalog.isRepairer(staticNpc) ? new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this)) : null;
    }

