    private long activeInteractionContext() {
        if (phase == Phase.WORLD && ClassicWorldMapCatalog.supports(classicWorldMapId)) {
            return -((long) classicWorldMapId + 1L);
        }
        if (phase == Phase.BATTLE) return currentRoomId;
        return 0;
    }

    private ArenaMapCatalog.Point activeWarehouseNpcPoint(long l) {
        if (this.phase == Phase.BATTLE && l == this.warehouseNpcObjectId()) {
            return this.warehouseNpcPoint();
        }
        if (this.phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(this.classicWorldMapId)) {
            return null;
        }
        ClassicWorldNpcCatalog.StaticNpc staticNpc = ClassicWorldNpcCatalog.fixedWarehouse(this.classicWorldMapId, l);
        return staticNpc == null ? null : new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this));
    }

    private ArenaMapCatalog.Point nearestActiveWarehouseNpcPoint() {
        if (this.phase == Phase.BATTLE) {
            return this.warehouseNpcPoint();
        }
        if (this.phase != Phase.WORLD || !ClassicWorldMapCatalog.supports(this.classicWorldMapId)) {
            return null;
        }
        ArenaMapCatalog.Point point = null;
        int n = Integer.MAX_VALUE;
        for (ClassicWorldNpcCatalog.StaticNpc staticNpc : ClassicWorldNpcCatalog.fixedWarehouses(this.classicWorldMapId)) {
            ArenaMapCatalog.Point point2 = new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this));
            int n2 = this.classicNpcDistance(point2);
            if (n2 >= n) continue;
            point = point2;
            n = n2;
        }
        return point;
    }

