    private void sendHouseAuctionList(String reason) throws IOException {
        long now = System.currentTimeMillis() / 1_000L;
        List<Protocol.HouseAuctionRow> rows = houseAuctions().stream()
                .filter(auction -> auction.deadlineEpochSeconds() >= now)
                .map(auction -> {
                    ZonedDateTime deadline = Instant.ofEpochSecond(
                            auction.deadlineEpochSeconds()).atZone(CLASSIC_BOARD_ZONE);
                    return new Protocol.HouseAuctionRow(
                            auction.houseId(), auction.name(), auction.area(),
                            deadline.getMonthValue(), deadline.getDayOfMonth(),
                            auction.price());
                }).toList();
        sendEncrypted(Protocol.agitList(houseAuctionBoardObjectId(), rows),
                "S_AGIT_LIST board=" + houseAuctionBoardObjectId()
                        + " rows=" + rows.size() + " reason=" + reason);
    }

    private List<GameStateStore.HouseAuction> houseAuctions() throws IOException {
        if (!"lito_mysql".equals(config.databaseMode())) {
            return state.houseAuctions(selectedClassicServerName);
        }
        try {
            RepositoryHouseAuctionSnapshot snapshot = selectedSourceAccounts()
                    .houseAuctions();
            if (!snapshot.authoritative()) {
                throw new IOException("selected SQL house auctions are unavailable");
            }
            return snapshot.auctions();
        } catch (IOException failure) {
            throw failure;
        } catch (Exception failure) {
            throw new IOException("cannot load selected SQL house auctions", failure);
        }
    }

    private GameStateStore.HouseAuction houseAuction(long houseId)
            throws IOException {
        return houseAuctions().stream()
                .filter(row -> row.houseId() == houseId)
                .findFirst().orElse(null);
    }

    private void sendHouseAuctionDetail(GameStateStore.HouseAuction auction)
            throws IOException {
        ZonedDateTime deadline = Instant.ofEpochSecond(
                auction.deadlineEpochSeconds()).atZone(CLASSIC_BOARD_ZONE);
        sendEncrypted(Protocol.hypertext(houseAuctionBoardObjectId(),
                        HOUSE_AUCTION_DETAIL_HTML, Long.toString(auction.houseId()),
                        List.of(auction.name(), auction.location() + "$1195",
                                Integer.toString(auction.area()), auction.oldOwner(),
                                auction.bidder(), Long.toString(auction.price()),
                                Integer.toString(deadline.getMonthValue()),
                                Integer.toString(deadline.getDayOfMonth()),
                                Integer.toString(deadline.getHour()))),
                "S_HYPERTEXT html=" + HOUSE_AUCTION_DETAIL_HTML
                        + " house=" + auction.houseId()
                        + " revision=" + auction.revision());
    }

    private void openHouseAuctionBid(GameStateStore.HouseAuction auction)
            throws IOException {
        pendingHouseAuctionBid = null;
        int eligibilityCode = houseAuctionEligibilityCode();
        if (eligibilityCode != 0) {
            sendEncrypted(Protocol.messageCode(eligibilityCode),
                    "S_MESSAGE_CODE house-auction-ineligible=" + eligibilityCode);
            return;
        }
        if (auction.bidder().equalsIgnoreCase(playerName())) {
            sendEncrypted(Protocol.messageCode(523),
                    "S_MESSAGE_CODE house-auction-already-bidder=523");
            return;
        }
        long now = System.currentTimeMillis() / 1_000L;
        long minimum = auction.bidder().isBlank()
                ? auction.price() : auction.price() + 1;
        long maximum = 2_000_000_000L;
        if (auction.deadlineEpochSeconds() < now
                || minimum <= 0 || minimum > maximum) {
            sendHouseAuctionList("expired-or-price-exhausted");
            return;
        }
        String callback = HOUSE_AUCTION_BID_HTML + " " + auction.houseId();
        int mode = 0;
        pendingHouseAuctionBid = new PendingHouseAuctionBid(
                houseAuctionBoardObjectId(), currentRoomId, auction.houseId(),
                auction.revision(), minimum, maximum, mode, callback,
                System.nanoTime() + HOUSE_AUCTION_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.hypertextInput(houseAuctionBoardObjectId(), 0,
                        minimum, minimum, maximum, mode,
                        HOUSE_AUCTION_BID_HTML, "", callback, List.of()),
                "S_HYPERTEXT_INPUT html=" + HOUSE_AUCTION_BID_HTML
                        + " house=" + auction.houseId() + " minimum=" + minimum
                        + " maximum=" + maximum + " revision=" + auction.revision());
    }

    private int houseAuctionEligibilityCode() {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || character.type() != 0
                || hub.clanRole(sourceCharacterIdentity())
                        != GameHub.CLAN_ROLE_OWNER) return 518;
        if (character.level() < 15) return 519;
        return selectedLegacyCastle() == null ? 0 : 521;
    }

    private static long houseAuctionHouseId(String parameter) {
        if (parameter == null || parameter.isEmpty() || parameter.length() > 10
                || !parameter.chars().allMatch(Character::isDigit)) return 0;
        try {
            long value = Long.parseLong(parameter);
            return value > 0 && value <= 0xFFFF_FFFFL ? value : 0;
        } catch (NumberFormatException invalid) {
            return 0;
        }
    }

    private long castleStewardNpcObjectId() {
        if (phase == Phase.WORLD
                && classicWorldMapId == ClassicWorldGiranCastleCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldNpcCatalog.objectId(
                    ClassicWorldGiranCastleCatalog.STEWARD_SPAWN_ID);
        }
        if (phase == Phase.WORLD && classicWorldMapId
                == ClassicWorldWindawoodCastleCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldNpcCatalog.objectId(
                    ClassicWorldWindawoodCastleCatalog.STEWARD_SPAWN_ID);
        }
        if (phase == Phase.WORLD && classicWorldMapId
                == ClassicWorldKentCastleCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldNpcCatalog.objectId(
                    ClassicWorldKentCastleCatalog.STEWARD_SPAWN_ID);
        }
        if (phase == Phase.WORLD
                && classicWorldMapId == ClassicWorldDwarfCastleCatalog.MAP_ID) {
            return ClassicWorldNpcCatalog.objectId(
                    ClassicWorldDwarfCastleCatalog.STEWARD_SPAWN_ID);
        }
        if (phase == Phase.WORLD && classicWorldMapId
                == ClassicWorldAdenToiCatalog.ADEN_INTERIOR_MAP_ID) {
            return ClassicWorldNpcCatalog.objectId(
                    ClassicWorldAdenToiCatalog.STEWARD_SPAWN_ID);
        }
        if (phase == Phase.WORLD
                && classicWorldMapId == ClassicWorldHeineCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldNpcCatalog.objectId(
                    ClassicWorldHeineCatalog.STEWARD_SPAWN_ID);
        }
        if (currentRoomId <= 0 || currentRoomId > 0x00FF_FFFFL) return 0;
        return CASTLE_STEWARD_NPC_OBJECT_BASE | currentRoomId;
    }

