    private boolean castleStewardSceneActive() {
        return (phase == Phase.BATTLE && currentRoomId != 0)
                || (phase == Phase.WORLD && classicCastleSceneId() != 0);
    }

    private boolean castleStewardSceneSupports(CastleSummary castle) {
        if (!castleStewardSceneActive() || castle == null) return false;
        return phase != Phase.WORLD || castle.castleId() == classicCastleSceneId();
    }

    private int classicCastleSceneId() {
        if (phase != Phase.WORLD) return 0;
        if (classicWorldMapId == ClassicWorldGiranCastleCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldGiranCastleCatalog.CASTLE_ID;
        }
        if (classicWorldMapId
                == ClassicWorldWindawoodCastleCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldWindawoodCastleCatalog.CASTLE_ID;
        }
        if (classicWorldMapId == ClassicWorldKentCastleCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldKentCastleCatalog.CASTLE_ID;
        }
        if (classicWorldMapId == ClassicWorldDwarfCastleCatalog.MAP_ID) {
            return ClassicWorldDwarfCastleCatalog.CASTLE_ID;
        }
        if (classicWorldMapId == ClassicWorldAdenToiCatalog.ADEN_INTERIOR_MAP_ID) {
            return ClassicWorldAdenToiCatalog.CASTLE_ID;
        }
        if (classicWorldMapId == ClassicWorldHeineCatalog.INTERIOR_MAP_ID) {
            return ClassicWorldHeineCatalog.CASTLE_ID;
        }
        return 0;
    }

