    private void broadcastMovementSpeed(int type, int localDurationSeconds, String reason)
            throws IOException {
        boolean classicWorld = phase == Phase.WORLD
                && ClassicWorldMapCatalog.supports(classicWorldMapId);
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession recipient : recipients) {
            if (classicWorld && !sameClassicWorldMap(recipient)) continue;
            if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                    recipient.positionX, recipient.positionY,
                    positionX, positionY)) continue;
            int duration = recipient == this ? localDurationSeconds : 0;
            recipient.sendEncrypted(Protocol.speed(playerObjectId(),
                            Protocol.SpeedMode.fromWire(type), duration),
                    "S_SPEED object=" + playerObjectId() + " type=" + type
                            + " duration=" + duration + " reason=" + reason);
        }
    }

    private void sendSlowStopMessage(int skillId, String reason) throws IOException {
        BattleSpellCatalog.EntangleSpell spell =
                BattleSpellCatalog.entangleSpell(skillId);
        if (spell == null || spell.stopMessage() == 0) return;
        sendEncrypted(Protocol.messageCode(spell.stopMessage()),
                "S_MESSAGE_CODE Entangle-stopped=" + spell.stopMessage()
                        + " reason=" + reason);
    }

    private void sendHasteStopMessage(int skillId, String reason) throws IOException {
        BattleSpellCatalog.HasteSpell ordinary =
                BattleSpellCatalog.hasteSpell(skillId);
        BattleSpellCatalog.SelfHasteSpell self =
                BattleSpellCatalog.selfHasteSpell(skillId);
        int stopMessage = ordinary != null ? ordinary.stopMessage()
                : self != null ? self.stopMessage() : 0;
        if (stopMessage == 0) return;
        sendEncrypted(Protocol.messageCode(stopMessage),
                "S_MESSAGE_CODE Haste-stopped=" + stopMessage
                        + " skill=" + skillId + " reason=" + reason);
    }

    private void broadcastBraveSpeed(
            Protocol.BraveMode mode, int localDurationSeconds, String reason)
            throws IOException {
        boolean world = phase == Phase.WORLD;
        List<ClientSession> recipients = world
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession recipient : recipients) {
            if (world && (recipient.classicWorldInstanceId != classicWorldInstanceId
                    || !BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY,
                            recipient.positionX, recipient.positionY))) continue;
            int duration = recipient == this ? localDurationSeconds : 0;
            recipient.sendEncrypted(Protocol.braveSpeed(playerObjectId(), mode, duration),
                    "S_EMOTION(brave) object=" + playerObjectId()
                            + " mode=" + mode.wireValue()
                            + " duration=" + duration + " reason=" + reason);
        }
    }

