    private void exitRoomBeforePolyMe(boolean bl) throws IOException {
        boolean bl2;
        GameHub.ReadyTransition readyTransition;
        if (this.phase == Phase.BATTLE) {
            this.settleRequestedBattleExit();
            return;
        }
        this.pendingWarehousePassword = null;
        this.pendingShapeChange = null;
        this.pendingSlaveTarget = null;
        this.pendingPetRename = null;
        PendingResurrection clearedResurrection;
        NativeResurrectionAnswerLife.capture(this, clearedResurrection = null);
        this.pendingResurrection = clearedResurrection;
        this.pendingHouseAuctionBid = null;
        this.clearControlledCompanionTargets();
        if (this.pendingTransition == PendingTransition.RESTART_AWAIT_RETURN) {
            this.completeRestartReturn(true);
            return;
        }
        if (this.phase == Phase.CHANNEL && this.currentRoomId == 0L) {
            this.nativeLobbyExitResumeDeadlineNanos = System.nanoTime() + 30000000000L;
            System.out.println("[LiTo] C_D0 armed native lobby-exit resume player=" + this.playerName() + " channel=" + this.currentChannelId);
            return;
        }
        if (this.phase != Phase.ROOM && this.phase != Phase.BATTLE && this.phase != Phase.RESULT) {
            return;
        }
        this.resetNativeTournamentEconomy("room-exit");
        this.closePersonalShopIfOpen("room-exit");
        this.cancelActivePlayerTrade("room-exit", true);
        if (this.rentalTownRoomState) {
            long l = this.currentRoomId;
            this.notifyRentalTownDeparture("room-exit");
            this.removeRentalTownSceneInventory("room-exit");
            this.sendEncrypted(new Protocol.Writer().c(208).d(l).s(this.litoDisplayName()).bytes(), "S_LITO_EXIT_ROOM rental-town player=" + this.playerName());
            this.clearRentalTownRoomState();
            NativePlayerCommit.scene(this, (Object)Phase.LOBBY, "phase");
            this.sendLitoServerList();
            System.out.println("[LiTo] exited rental-town room=" + l + " player=" + this.playerName() + " return=group-1-directory");
            return;
        }
        if (this.phase == Phase.ROOM && (readyTransition = this.hub.setReady(this.currentRoomId, this, false).transition()) == GameHub.ReadyTransition.COUNTDOWN_CANCELLED) {
            for (ClientSession clientSession : this.hub.roomMembers(this.currentRoomId)) {
                clientSession.serverCountdown(0);
            }
        }
        byte[] exitPacket = new Protocol.Writer().c(208).d(this.currentRoomId).s(this.litoDisplayName()).bytes();
        if (bl) {
            this.sendEncrypted(exitPacket, "S_LITO_EXIT_ROOM player=" + this.playerName());
        }
        for (ClientSession clientSession : this.hub.roomMembers(this.currentRoomId)) {
            if (clientSession == this) continue;
            try {
                clientSession.sendEncrypted(exitPacket, "S_LITO_EXIT_ROOM peer=" + this.playerName());
            }
            catch (IOException iOException) {
                System.out.println("[LiTo] room-exit peer notification failed recipient=" + clientSession.playerName() + ": " + iOException.getMessage());
            }
        }
        long l = this.currentRoomId;
        boolean bl3 = (this.phase == Phase.ROOM || this.phase == Phase.RESULT) && this.hub.isOwner(l, this);
        boolean bl4 = this.hub.leaveRoom(l, this);
        NativeRoomRules.restoreBot(this);
        boolean bl5 = bl4;
        boolean bl6 = bl2 = !bl5 && this.hub.roomMembers(l).isEmpty();
        if (bl3) {
            this.broadcastRoomOwner(l, "room-exit");
        }
        this.detachArgoRoomMembership();
        NativePlayerCommit.scene(this, 0L, "currentRoomId");
        this.pendingLitoRoomInvitation = null;
        this.acceptedLitoRoomInvitation = null;
        NativePlayerCommit.scene(this, (Object)Phase.CHANNEL, "phase");
        this.notifyBuddyActivity(Protocol.LitoBuddyActivity.WAITING);
        this.ready = false;
        if (bl5) {
            this.broadcastRoomDeleted(l);
        } else if (bl2) {
            this.broadcastDefaultRoomReset(l);
        }
        if (bl && this.config.nativeTournamentEconomyEnabled() && this.nativeTournamentEconomyInitialized) {
            this.sendPointStats();
        }
        this.sendRoomList();
        if (bl && this.config.nativeTournamentEconomyEnabled() && this.nativeTournamentEconomyInitialized) {
            this.sendTournamentShopNotice("\u5df2\u8fd4\u56de\u5927\u5ef3\uff1a\u672c\u8f2a\u5546\u5e97\u7269\u54c1\u5df2\u6e05\u9664\uff0c\u8cfc\u7269\u91d1\u91cd\u8a2d\u70ba " + this.shopPoints + "\u3002");
        }
        this.retryWaitingMatchMakingSessions("room-seat-released=" + l);
        LobbyRoomDirectory.refresh(this, "room-exited");
    }

