    private void builderMove(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != Protocol.C_LITO_MOVE) {
            throw new IllegalArgumentException("invalid C_LITO_MOVE opcode");
        }
        int x = in.h();
        int y = in.h();
        requireNoRemaining(in, "move");
        if (!requireAdministrator(Protocol.C_LITO_MOVE)) return;
        authoritativeMove(x, y, "builder-jump");
    }

    private void authoritativeMove(int n, int n2, String string) throws IOException {
        if (this.phase != Phase.BATTLE || this.currentRoomId == 0L) {
            System.out.println("[LiTo] authoritative move rejected phase=" + String.valueOf((Object)this.phase) + " reason=" + string);
            return;
        }
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(this.hub.battleMapId(this.currentRoomId, this));
        if (!arena.contains(n, n2)) {
            System.out.println("[LiTo] authoritative move rejected outside-map=" + n + "," + n2 + " map=" + arena.mapId() + " reason=" + string);
            return;
        }
        int n3 = this.positionX;
        int n4 = this.positionY;
        this.positionX = n;
        this.positionY = n2;
        this.cancelMeditation("authoritative-move");
        this.naturalHpRegen.noteMove();
        this.naturalMpRegen.noteMove();
        byte[] byArray = NativeMovement.legacyDestinationPacket(new Protocol.Writer().c(18).d(this.playerObjectId()).h(n).h(n2).c(0).bytes());
        for (ClientSession clientSession : this.hub.roomMembers(this.currentRoomId)) {
            clientSession.sendEncrypted(byArray, "S_MOVE_OBJECT " + string + " object=" + this.playerObjectId() + " x=" + n + " y=" + n2);
            clientSession.sendEncrypted(Protocol.minimapPlayer(this.playerObjectId(), n, n2, clientSession.minimapAlliedWith(this)), "S_LITO_MINIMAP " + string + " player=" + this.playerName() + " x=" + n + " y=" + n2);
        }
    }

    private void toggleRoomSilence(byte[] payload) {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != Protocol.C_LITO_SILENCE) {
            throw new IllegalArgumentException("invalid C_LITO_SILENCE opcode");
        }
        requireNoRemaining(in, "silence");
        if (!requireAdministrator(Protocol.C_LITO_SILENCE)) return;
        if (currentRoomId == 0 || (phase != Phase.ROOM && phase != Phase.BATTLE && phase != Phase.RESULT)) {
            System.out.println("[LiTo] C_LITO_SILENCE rejected phase=" + phase);
            return;
        }
        if (rentalTownRoomState) {
            // This command toggles a GameHub room-wide flag and has no
            // evidenced meaning for the isolated non-battle town.  Consume the
            // exact privileged envelope without looking up the synthetic id.
            System.out.println("[LiTo] C_LITO_SILENCE rejected rental-town room="
                    + currentRoomId);
            return;
        }
        boolean silenced = hub.toggleRoomSilence(currentRoomId);
        System.out.println("[LiTo] C_LITO_SILENCE room=" + currentRoomId + " silenced=" + silenced);
    }

    private void sendBuddyData(byte[] payload) throws IOException {
        Protocol.litoBuddyGroupQuery(payload);
        GameHub.BuddyData data = hub.buddyData(sourceCharacterIdentity(), currentChannelId);
        sendBuddyGroups(data);
        sendBuddyList(data);
    }

    private void sendBuddyList(GameHub.BuddyData data) throws IOException {
        List<Protocol.LitoBuddyRow> rows = data.buddies().stream()
                .map(buddy -> new Protocol.LitoBuddyRow(
                        buddy.name(), buddy.groupId(), buddy.relationshipStyle(),
                        buddy.paletteOffset(), buddy.origin(), buddy.activity()))
                .toList();
        sendEncrypted(Protocol.buddyList(rows),
                "S_LITO_BUDDY_LIST buddies=" + rows.size());
    }

    private void addBuddy(byte[] payload) throws IOException {
        BuddyTarget target = readBuddyTarget(payload, Protocol.C_ADD_BUDDY);
        ClientSession onlineTarget = hub.channelMemberByName(
                currentChannelId, this, target.name());
        String origin = onlineTarget == null ? originServerName() : onlineTarget.originServerName();
        String targetSource = buddyTargetSource(target, onlineTarget);
        GameHub.BuddyAddResult result = hub.addBuddy(
                sourceCharacterIdentity(), target.name(), origin, targetSource,
                onlineTarget != null);
        switch (result) {
            case ADDED -> {
                sendBuddyList(hub.buddyData(sourceCharacterIdentity(), currentChannelId));
                System.out.println("[LiTo] buddy added player=" + playerName()
                        + " buddy=" + target.name() + " source-index=" + target.serverIndex());
            }
            case DUPLICATE -> sendEncrypted(
                    Protocol.buddyError(Protocol.LitoBuddyError.ALREADY_REGISTERED),
                    "S_LITO_BUDDY_ERROR already-registered buddy=" + target.name());
            case FULL -> sendEncrypted(Protocol.buddyError(Protocol.LitoBuddyError.LIST_FULL),
                    "S_LITO_BUDDY_ERROR list-full buddy=" + target.name());
            case INVALID -> System.out.println("[LiTo] ignored invalid C_ADD_BUDDY player=" + playerName());
            case PERSISTENCE_REJECTED -> {
                sendEncrypted(Protocol.messageCode(79),
                        "S_MESSAGE_CODE buddy-persistence-rejected=79 buddy="
                                + target.name());
                System.out.println("[LiTo] buddy add rejected by persistence player="
                        + playerName() + " buddy=" + target.name());
            }
        }
    }

    private String buddyTargetSource(BuddyTarget target, ClientSession onlineTarget) {
        if (onlineTarget != null) return onlineTarget.selectedClassicServerName;
        if (target.serverIndex() <= 0) return selectedClassicServerName;
        for (int index = 0; index < config.classicServerIds().size(); index++) {
            if (config.classicServerIds().get(index) == target.serverIndex()) {
                return config.classicServerNames().get(index);
            }
        }
        if (target.serverIndex() < config.classicServerNames().size()) {
            return config.classicServerNames().get(target.serverIndex());
        }
        return "server-index:" + target.serverIndex();
    }

    private void removeBuddy(byte[] payload) throws IOException {
        BuddyTarget target = readBuddyTarget(payload, Protocol.C_REMOVE_BUDDY);
        if (!hub.removeBuddy(sourceCharacterIdentity(), target.name())) {
            System.out.println("[LiTo] buddy remove ignored player=" + playerName()
                    + " buddy=" + target.name() + " source-index=" + target.serverIndex());
            return;
        }
        sendBuddyList(hub.buddyData(sourceCharacterIdentity(), currentChannelId));
        System.out.println("[LiTo] buddy removed player=" + playerName()
                + " buddy=" + target.name() + " source-index=" + target.serverIndex());
    }

    private static BuddyTarget readBuddyTarget(byte[] payload, int expectedOpcode) {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != expectedOpcode) throw new IllegalArgumentException("unexpected buddy opcode");
        String encoded = in.s().trim();
        if (in.remaining() != 0) throw new IllegalArgumentException("invalid buddy payload");
        int serverIndex = 0;
        String name = encoded;
        int open = encoded.lastIndexOf('[');
        if (open > 0 && encoded.endsWith("]")) {
            String suffix = encoded.substring(open + 1, encoded.length() - 1);
            try {
                serverIndex = Integer.parseInt(suffix);
                name = encoded.substring(0, open).trim();
            } catch (NumberFormatException ignored) {
                // The command producer can send a plain name. Keep it intact
                // unless the native Name[index] suffix is syntactically valid.
            }
        }
        if (name.isBlank()) throw new IllegalArgumentException("buddy name is empty");
        return new BuddyTarget(name, serverIndex);
    }

    private void sendBuddyGroups(GameHub.BuddyData data) throws IOException {
        // Native S_ED parser: c(count), then hs for each group.
        Protocol.Writer groups = new Protocol.Writer().c(Protocol.S_LITO_BUDDY_GROUP_LIST)
                .c(data.groups().size());
        for (GameHub.BuddyGroup group : data.groups()) groups.h(group.id()).s(group.name());
        sendEncrypted(groups.bytes(), "S_LITO_BUDDY_GROUP_LIST groups=" + data.groups().size());
    }

    private void createBuddyGroup(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        String name = in.s();
        if (in.remaining() != 0) {
            throw new IllegalArgumentException("invalid C_LITO_CREATE_BUDDY_GROUP payload");
        }
        int groupId = hub.createBuddyGroup(sourceCharacterIdentity(), name);
        if (groupId < 0) {
            System.out.println("[LiTo] buddy group create rejected player=" + playerName()
                    + " name=" + name + "; no paired native group-error packet is proven");
            return;
        }
        sendBuddyGroups(hub.buddyData(sourceCharacterIdentity(), currentChannelId));
        System.out.println("[LiTo] buddy group created player=" + playerName()
                + " group=" + groupId + " name=" + name);
    }

    private void removeBuddyGroup(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        int groupId = in.h();
        if (in.remaining() != 0) {
            throw new IllegalArgumentException("invalid C_LITO_REMOVE_BUDDY_GROUP payload");
        }
        List<String> moved = hub.removeBuddyGroup(sourceCharacterIdentity(), groupId);
        if (moved == null) {
            System.out.println("[LiTo] buddy group remove rejected player=" + playerName()
                    + " group=" + groupId + "; no paired native group-error packet is proven");
            return;
        }
        for (String buddy : moved) {
            sendEncrypted(Protocol.buddyGroupChanged(buddy, 1),
                    "S_LITO_CHANGE_BUDDY_GROUP_RESULT buddy=" + buddy + " group=1 remove-reset");
        }
        sendBuddyGroups(hub.buddyData(sourceCharacterIdentity(), currentChannelId));
    }

    private void renameBuddyGroup(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        int groupId = in.h();
        String name = in.s();
        if (in.remaining() != 0) {
            throw new IllegalArgumentException("invalid C_LITO_RENAME_BUDDY_GROUP payload");
        }
        if (!hub.renameBuddyGroup(sourceCharacterIdentity(), groupId, name)) {
            System.out.println("[LiTo] buddy group rename rejected player=" + playerName()
                    + " group=" + groupId + " name=" + name
                    + "; no paired native group-error packet is proven");
            return;
        }
        sendBuddyGroups(hub.buddyData(sourceCharacterIdentity(), currentChannelId));
    }

    private void changeBuddyGroup(byte[] payload) throws IOException {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        String buddy = in.s();
        int groupId = in.h();
        if (in.remaining() != 0) {
            throw new IllegalArgumentException("invalid C_LITO_CHANGE_BUDDY_GROUP payload");
        }
        if (!hub.changeBuddyGroup(sourceCharacterIdentity(), buddy, groupId)) {
            System.out.println("[LiTo] buddy group change rejected player=" + playerName()
                    + " buddy=" + buddy + " group=" + groupId
                    + "; no paired native group-error packet is proven");
            return;
        }
        sendEncrypted(Protocol.buddyGroupChanged(buddy, groupId),
                "S_LITO_CHANGE_BUDDY_GROUP_RESULT buddy=" + buddy + " group=" + groupId);
    }

