    private void exchangeSpells(byte[] payload) throws IOException {
        Protocol.SpellMaterialPurchaseRequest request =
                Protocol.spellMaterialPurchaseRequest(payload);
        PendingSpellMaterialShop context = validSpellMaterialShopContext();
        LinkedHashSet<Integer> requestedWireIds =
                new LinkedHashSet<>(request.wireSkillIds());
        List<Integer> currentAvailable = SpellMaterialCatalog.availableWireSkillIds(
                selectedCharacterSummary(), learnedSkills);
        boolean valid = context != null
                && requestedWireIds.size() == request.wireSkillIds().size()
                && context.offeredWireSkillIds().containsAll(requestedWireIds)
                && currentAvailable.containsAll(requestedWireIds);
        if (!valid) {
            pendingSpellMaterialShop = null;
            System.out.println("[LiTo] C_EXCHANGE_SPELL rejected stale/forged rows="
                    + request.wireSkillIds() + " player=" + playerName());
            return;
        }

        RuntimeInventory nextInventory = inventory.copy();
        Integer shortageWireSkillId = null;
        for (int wireSkillId : request.wireSkillIds()) {
            for (SpellMaterialCatalog.Requirement requirement
                    : SpellMaterialCatalog.requirementsForWireSkillId(wireSkillId)) {
                if (!nextInventory.removeCatalog(
                        requirement.catalogId(), requirement.quantity())) {
                    shortageWireSkillId = wireSkillId;
                    break;
                }
            }
            if (shortageWireSkillId != null) break;
        }
        if (shortageWireSkillId != null) {
            pendingSpellMaterialShop = null;
            sendEncrypted(Protocol.notEnoughForSpell(shortageWireSkillId),
                    "S_NOT_ENOUGH_FOR_SPELL wire-skill=" + shortageWireSkillId);
            return;
        }

        LinkedHashSet<Integer> newlyLearned = new LinkedHashSet<>();
        for (int wireSkillId : request.wireSkillIds()) newlyLearned.add(wireSkillId + 1);
        LinkedHashSet<Integer> nextPurchased = new LinkedHashSet<>(purchasedSkills);
        nextPurchased.addAll(newlyLearned);
        LinkedHashSet<Integer> nextLearned = new LinkedHashSet<>(learnedSkills);
        nextLearned.addAll(newlyLearned);

        RuntimeInventory previousInventory = inventory;
        state.saveSpellPurchase(stateCharacter(), shopPoints,
                nextInventory.catalogCounts(), nextPurchased);
        NativeDeItemApplication.replace(this, nextInventory, 0);
        purchasedSkills = Set.copyOf(nextPurchased);
        learnedSkills = Set.copyOf(nextLearned);
        pendingSpellMaterialShop = null;
        sendInventoryDelta(previousInventory, inventory);
        sendEncrypted(Protocol.addSpells(Set.copyOf(newlyLearned)),
                "S_ADD_SPELL material-learned-count=" + newlyLearned.size());
        byte[] effect = Protocol.effectObject(playerObjectId(), 224);
        List<ClientSession> recipients = phase == Phase.WORLD
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (phase == Phase.WORLD && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            member.sendEncrypted(effect, "S_EFFECT material-learned-spell object="
                    + playerObjectId() + " gfx=224");
        }
        System.out.println("[LiTo] C_EXCHANGE_SPELL accepted player=" + playerName()
                + " rows=" + request.wireSkillIds()
                + " learned-total=" + learnedSkills.size());
    }

    private PendingSpellMaterialShop validSpellMaterialShopContext() {
        PendingSpellMaterialShop context = pendingSpellMaterialShop;
        ArenaMapCatalog.Point npc = context == null ? null
                : activeSpellMaterialNpcPoint(context.npcObjectId());
        boolean valid = context != null
                && (phase == Phase.BATTLE || phase == Phase.WORLD)
                && !observer && playerHp > 0 && activeInteractionContext() != 0
                && context.phase() == phase
                && context.interactionContext() == activeInteractionContext()
                && System.nanoTime() <= context.expiresAtNanos()
                && npc != null && spellMaterialNpcDistance(npc) <= 5;
        if (!valid) pendingSpellMaterialShop = null;
        return valid ? context : null;
    }

    private PendingSpellShop validSpellShopContext() {
        PendingSpellShop context = pendingSpellShop;
        ArenaMapCatalog.Point npc = context == null ? null
                : activeSpellShopNpcPoint(context.npcObjectId());
        boolean valid = context != null
                && (phase == Phase.BATTLE || phase == Phase.WORLD) && !observer
                && playerHp > 0 && activeInteractionContext() != 0
                && context.phase() == phase
                && context.interactionContext() == activeInteractionContext()
                && System.nanoTime() <= context.expiresAtNanos()
                && npc != null && spellShopNpcDistance(npc) <= 5;
        if (!valid) pendingSpellShop = null;
        return valid ? context : null;
    }

    private void createClan(byte[] payload) throws IOException {
        String clanName = readClanNamePacket(payload, Protocol.C_LITO_CLAN_CREATE);
        int encodedLength = clanName.getBytes(Protocol.LEGACY_TEXT).length;
        // sub_40BA50 calls the same sub_401680 validator as classic clan
        // creation before it can emit C_EF.  Keep forged/non-producer input
        // fail-closed instead of widening the native name domain.
        if (!Protocol.validClanName(clanName)) {
            System.out.println("[LiTo] C_LITO_CLAN_CREATE rejected non-producer name owner="
                    + playerName() + " bytes=" + encodedLength);
            return;
        }
        RepositoryClanMutation repositoryCreated;
        try {
            CharacterSummary owner = selectedCharacterSummary();
            repositoryCreated = owner == null
                    ? RepositoryClanMutation.unavailable()
                    : selectedSourceAccounts().createClan(owner.objectId(), clanName);
        } catch (Exception databaseError) {
            System.out.println("[LiTo] C_LITO_CLAN_CREATE SQL failed owner="
                    + playerName() + " clan=" + clanName + ": "
                    + databaseError.getClass().getSimpleName() + ": "
                    + databaseError.getMessage());
            return;
        }
        GameHub.ClassicClanCreateStatus status;
        if (repositoryCreated.status() == RepositoryClanMutationStatus.SUCCESS) {
            hub.reconcileSqlClan(sourceCharacterIdentity(), repositoryCreated.snapshot());
            status = GameHub.ClassicClanCreateStatus.CREATED;
        } else if (repositoryCreated.status() == RepositoryClanMutationStatus.UNAVAILABLE) {
            status = hub.createClassicClan(sourceCharacterIdentity(), clanName);
        } else if (repositoryCreated.status()
                == RepositoryClanMutationStatus.OWNER_ALREADY_MEMBER) {
            status = GameHub.ClassicClanCreateStatus.OWNER_ALREADY_MEMBER;
        } else if (repositoryCreated.status()
                == RepositoryClanMutationStatus.DUPLICATE_NAME) {
            status = GameHub.ClassicClanCreateStatus.DUPLICATE_NAME;
        } else {
            System.out.println("[LiTo] C_LITO_CLAN_CREATE SQL rejected owner="
                    + playerName() + " clan=" + clanName
                    + " status=" + repositoryCreated.status());
            return;
        }
        if (status != GameHub.ClassicClanCreateStatus.CREATED) {
            if (status == GameHub.ClassicClanCreateStatus.OWNER_ALREADY_MEMBER
                    || status == GameHub.ClassicClanCreateStatus.DUPLICATE_NAME) {
                sendEncrypted(Protocol.litoClanCreateFailure(status),
                        "S_MESSAGE_CODE lito-clan-create-rejected="
                                + (status == GameHub.ClassicClanCreateStatus.OWNER_ALREADY_MEMBER
                                ? 86 : 99)
                                + " status=" + status + " clan=" + clanName);
            } else {
                System.out.println("[LiTo] C_LITO_CLAN_CREATE rejected invalid authority owner="
                        + playerName() + " clan=" + clanName);
            }
            return;
        }
        updateLocalClanRosterState(
                Protocol.LitoClanActivity.fromBuddy(buddyActivityState()));
        sendClanInfo();
    }

    private void setClanDestroyPending(byte[] payload, boolean pending) {
        Protocol.Reader in = new Protocol.Reader(payload);
        in.c();
        if (in.remaining() != 0) throw new IllegalArgumentException("invalid clan destroy payload");
        GameHub.ClanData before = hub.clanData(sourceCharacterIdentity());
        RepositoryClanMutation repositoryChanged;
        try {
            CharacterSummary owner = selectedCharacterSummary();
            repositoryChanged = owner == null
                    ? RepositoryClanMutation.unavailable()
                    : selectedSourceAccounts().setClanDestroyPending(
                            owner.objectId(), before.destroyPending(), pending);
        } catch (Exception databaseError) {
            System.out.println("[LiTo] clan destroy-pending SQL failed owner="
                    + playerName() + ": " + databaseError.getClass().getSimpleName()
                    + ": " + databaseError.getMessage());
            return;
        }
        boolean changed;
        if (repositoryChanged.status() == RepositoryClanMutationStatus.SUCCESS) {
            hub.reconcileSqlClan(sourceCharacterIdentity(), repositoryChanged.snapshot());
            changed = before.destroyPending() != pending;
        } else if (repositoryChanged.status() == RepositoryClanMutationStatus.UNAVAILABLE) {
            changed = hub.setClanDestroyPending(sourceCharacterIdentity(), pending);
        } else {
            System.out.println("[LiTo] clan destroy-pending SQL rejected owner="
                    + playerName() + " status=" + repositoryChanged.status());
            return;
        }
        System.out.println("[LiTo] clan destroy-pending owner=" + playerName()
                + " value=" + pending + " changed=" + changed
                + "; native command has no observed immediate S response");
    }

    private void addClanCandidate(byte[] payload) throws IOException {
        String candidateName = readClanNamePacket(payload, Protocol.C_LITO_CLAN_ADD);
        GameHub.ClanMemberSnapshot candidate = hub.addClanCandidate(
                sourceCharacterIdentity(), candidateName);
        if (candidate == null) {
            System.out.println("[LiTo] clan candidate rejected owner=" + playerName()
                    + " candidate=" + candidateName);
            return;
        }
        byte[] added = Protocol.clanMemberAdded(candidate);
        List<ClientSession> recipients = hub.clanSessions(sourceCharacterIdentity());
        if (recipients.isEmpty()) recipients = List.of(this);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(added, "S_LITO_CLAN_ADD candidate=" + candidateName + " role=3");
        }
    }

    private void admitClanCandidate(byte[] payload) throws IOException {
        String candidateName = readClanNamePacket(payload, Protocol.C_LITO_CLAN_ADMIT);
        RepositoryClanMutation repositoryJoined;
        try {
            CharacterSummary owner = selectedCharacterSummary();
            repositoryJoined = owner == null
                    ? RepositoryClanMutation.unavailable()
                    : selectedSourceAccounts().joinClan(
                            owner.objectId(), candidateName, classicClanCapacity());
        } catch (Exception databaseError) {
            System.out.println("[LiTo] clan admit SQL failed owner=" + playerName()
                    + " candidate=" + candidateName + ": "
                    + databaseError.getClass().getSimpleName() + ": "
                    + databaseError.getMessage());
            return;
        }
        GameHub.ClanData clan;
        if (repositoryJoined.status() == RepositoryClanMutationStatus.SUCCESS) {
            clan = hub.reconcileSqlClan(
                    sourceCharacterIdentity(), repositoryJoined.snapshot());
        } else if (repositoryJoined.status() == RepositoryClanMutationStatus.UNAVAILABLE) {
            clan = hub.admitClanCandidate(sourceCharacterIdentity(), candidateName);
        } else {
            System.out.println("[LiTo] clan admit SQL rejected owner=" + playerName()
                    + " candidate=" + candidateName
                    + " status=" + repositoryJoined.status());
            return;
        }
        if (clan == null) {
            System.out.println("[LiTo] clan admit rejected owner=" + playerName()
                    + " candidate=" + candidateName);
            return;
        }
        byte[] refreshed = Protocol.clanInfo(clan);
        List<ClientSession> recipients = hub.clanSessions(sourceCharacterIdentity());
        if (recipients.isEmpty()) recipients = List.of(this);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(refreshed, "S_LITO_CLAN_INFO admitted=" + candidateName + " role=2");
        }
    }

    private void deleteClanMember(byte[] payload) throws IOException {
        String memberName = readClanNamePacket(payload, Protocol.C_LITO_CLAN_DELETE);
        List<ClientSession> recipients = hub.clanSessions(sourceCharacterIdentity());
        GameHub.ClanMemberSnapshot expectedMember = hub.clanData(sourceCharacterIdentity())
                .members().stream()
                .filter(member -> member.name().equalsIgnoreCase(memberName))
                .findFirst().orElse(null);
        RepositoryClanMutation repositoryRemoved;
        try {
            CharacterSummary owner = selectedCharacterSummary();
            repositoryRemoved = owner == null || expectedMember == null
                    ? RepositoryClanMutation.unavailable()
                    : selectedSourceAccounts().changeClanMember(owner.objectId(),
                            memberName, expectedMember.role().wireValue(), 0);
        } catch (Exception databaseError) {
            System.out.println("[LiTo] clan delete SQL failed owner=" + playerName()
                    + " member=" + memberName + ": "
                    + databaseError.getClass().getSimpleName() + ": "
                    + databaseError.getMessage());
            return;
        }
        GameHub.ClanMemberSnapshot removed;
        if (repositoryRemoved.status() == RepositoryClanMutationStatus.SUCCESS) {
            hub.reconcileSqlClan(sourceCharacterIdentity(), repositoryRemoved.snapshot());
            removed = expectedMember;
        } else if (repositoryRemoved.status() == RepositoryClanMutationStatus.UNAVAILABLE) {
            removed = hub.removeClanMember(sourceCharacterIdentity(), memberName);
        } else {
            System.out.println("[LiTo] clan delete SQL rejected owner=" + playerName()
                    + " member=" + memberName
                    + " status=" + repositoryRemoved.status());
            return;
        }
        if (removed == null) {
            System.out.println("[LiTo] clan delete rejected owner=" + playerName()
                    + " member=" + memberName);
            return;
        }
        byte[] deleted = Protocol.clanMemberDeleted(removed.name());
        if (recipients.isEmpty()) recipients = List.of(this);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(deleted, "S_LITO_CLAN_DELETE member=" + removed.name());
        }
    }

    private void changeClanRole(byte[] payload) throws IOException {
        Protocol.ClanRankControlRequest request = Protocol.clanRankControlRequest(payload);
        if (request.command() == 0) {
            System.out.println("[LiTo] C_RANK_CONTROL native clan-list close player="
                    + playerName());
            return;
        }
        List<ClientSession> recipients = new ArrayList<>(
                hub.clanSessions(sourceCharacterIdentity()));
        GameHub.ClanMemberSnapshot expectedMember = hub.clanData(sourceCharacterIdentity())
                .members().stream()
                .filter(member -> member.name().equalsIgnoreCase(request.characterName()))
                .findFirst().orElse(null);
        RepositoryClanMutation repositoryChanged;
        try {
            CharacterSummary owner = selectedCharacterSummary();
            repositoryChanged = owner == null || expectedMember == null
                    ? RepositoryClanMutation.unavailable()
                    : selectedSourceAccounts().changeClanMember(owner.objectId(),
                            request.characterName(), expectedMember.role().wireValue(),
                            request.role());
        } catch (Exception databaseError) {
            System.out.println("[LiTo] C_RANK_CONTROL SQL failed owner=" + playerName()
                    + " target=" + request.characterName() + ": "
                    + databaseError.getClass().getSimpleName() + ": "
                    + databaseError.getMessage());
            return;
        }
        GameHub.ClanData clan;
        if (repositoryChanged.status() == RepositoryClanMutationStatus.SUCCESS) {
            clan = hub.reconcileSqlClan(
                    sourceCharacterIdentity(), repositoryChanged.snapshot());
        } else if (repositoryChanged.status() == RepositoryClanMutationStatus.UNAVAILABLE) {
            clan = hub.changeClanRole(sourceCharacterIdentity(),
                    request.characterName(), request.role());
        } else {
            System.out.println("[LiTo] C_RANK_CONTROL SQL rejected owner=" + playerName()
                    + " target=" + request.characterName()
                    + " status=" + repositoryChanged.status());
            return;
        }
        if (clan == null) {
            System.out.println("[LiTo] C_RANK_CONTROL rejected owner=" + playerName()
                    + " target=" + request.characterName() + " role=" + request.role());
            return;
        }
        for (ClientSession recipient : hub.clanSessions(sourceCharacterIdentity())) {
            if (!recipients.contains(recipient)) recipients.add(recipient);
        }
        byte[] refreshed = Protocol.clanInfo(clan);
        if (recipients.isEmpty()) recipients = List.of(this);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(refreshed,
                    "S_LITO_CLAN_INFO rank target=" + request.characterName()
                            + " role=" + request.role());
        }
    }

    private static String readClanNamePacket(byte[] payload, int expectedOpcode) {
        Protocol.Reader in = new Protocol.Reader(payload);
        if (in.c() != expectedOpcode) throw new IllegalArgumentException("wrong clan opcode");
        String name = in.s().trim();
        if (in.remaining() != 0) throw new IllegalArgumentException("invalid clan name payload");
        return name;
    }

    private void sendClassicBuyList() throws IOException {
        clearPendingClassicList();
        long npcObjectId = classicMerchantNpcObjectId();
        List<ClassicMerchantCatalog.Offer> offers = ClassicMerchantCatalog.offers();
        Map<Long, Long> prices = new LinkedHashMap<>();
        Map<Long, InventoryCatalog.Definition> definitions = new LinkedHashMap<>();
        List<Protocol.ClassicBuyListRow> rows = new ArrayList<>();
        for (ClassicMerchantCatalog.Offer offer : offers) {
            prices.put(offer.orderId(), offer.unitPrice());
            definitions.put(offer.orderId(), offer.definition());
            rows.add(offer.wireRow());
        }
        pendingClassicList = new PendingClassicList(
                npcObjectId, Phase.BATTLE, currentRoomId, 0, prices,
                definitions, Map.of(), Map.of(),
                System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.classicBuyList(npcObjectId, rows),
                "S_BUY_LIST classic-merchant=" + npcObjectId + " rows=" + rows.size());
    }

    /**
     * Opens the exact selected-source Duran offer after the client-local
     * {@code duran2} page emits {@code C_HACTION action=buy}.  The capability
     * pins both the displayed unit price and the item definition, so the
     * later native {@code C_BUY_SELL} row cannot substitute Pandora's order 0.
     */
    private void sendClassicWorldBuyList(
            ClassicWorldMerchantCatalog.Merchant merchant) throws IOException {
        clearPendingClassicList();
        Map<Long, Long> prices = new LinkedHashMap<>();
        Map<Long, InventoryCatalog.Definition> definitions = new LinkedHashMap<>();
        Map<Long, Long> packCounts = new LinkedHashMap<>();
        List<Protocol.ClassicBuyListRow> rows = new ArrayList<>();
        for (ClassicWorldMerchantCatalog.Offer offer : merchant.offers()) {
            prices.put(offer.orderId(), offer.unitPrice());
            definitions.put(offer.orderId(), offer.definition());
            packCounts.put(offer.orderId(), offer.packCount());
            rows.add(offer.wireRow());
        }
        pendingClassicList = new PendingClassicList(
                merchant.objectId(), Phase.WORLD, activeInteractionContext(), 0,
                prices, definitions, packCounts, Map.of(),
                System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.classicBuyList(merchant.objectId(), rows),
                "S_BUY_LIST classic-world-merchant=" + merchant.objectId()
                        + " spawn=" + merchant.spawnId() + " rows=" + rows.size());
    }

