    private void sendClassicSellList() throws IOException {
        clearPendingClassicList();
        long npcObjectId = classicMerchantNpcObjectId();
        Map<Long, Long> prices = new LinkedHashMap<>();
        List<Protocol.ClassicSellListRow> rows = new ArrayList<>();
        for (RuntimeInventory.Item item : inventory.items()) {
            long price = ClassicMerchantCatalog.sellPrice(item.definition());
            if (price <= 0 || item.equipped() || item.durability() != 0) continue;
            prices.put(item.objectId(), price);
            rows.add(new Protocol.ClassicSellListRow(item.objectId(), price));
        }
        pendingClassicList = new PendingClassicList(
                npcObjectId, Phase.BATTLE, currentRoomId, 1, prices,
                Map.of(), Map.of(), Map.of(),
                System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS);
        sendEncrypted(Protocol.classicSellList(npcObjectId, rows),
                "S_SELL_LIST classic-merchant=" + npcObjectId + " rows=" + rows.size());
    }

    private void refreshPersonalWarehouse() throws IOException {
        GameStateStore.Warehouse warehouse = this.state.personalWarehouse(this.stateAccount(), this.accountCharacterIdentities());
        NativeDeItemApplication.replace(this, RuntimeInventory.fromDurableState(warehouse.inventory(), warehouse.itemStates()), 3);
    }

    private List<String> accountCharacterIdentities() {
        List<String> identities = characters.stream().map(CharacterSummary::name)
                .map(this::stateCharacter).toList();
        return identities.isEmpty() ? List.of(stateCharacter()) : identities;
    }

    private boolean isElfCharacter() {
        CharacterSummary character = selectedCharacterSummary();
        return character != null && character.type() == 2;
    }

    private PendingWarehouse loadWarehouse(GameStateStore.WarehouseScope warehouseScope, String string, String string2) throws IOException {
        GameStateStore.Warehouse warehouse;
        RuntimeInventory runtimeInventory;
        RepositoryWarehouseSnapshot repositoryWarehouseSnapshot;
        try {
            repositoryWarehouseSnapshot = this.selectedSourceAccounts().warehouse(warehouseScope, string2);
        }
        catch (Exception exception) {
            throw new IOException("cannot load SQL warehouse scope=" + String.valueOf((Object)warehouseScope), exception);
        }
        if (repositoryWarehouseSnapshot.authoritative()) {
            runtimeInventory = repositoryWarehouseSnapshot.runtimeInventory();
            warehouse = this.state.reconcileSqlWarehouse(warehouseScope, string, runtimeInventory);
        } else {
            warehouse = switch (warehouseScope) {
                default -> throw new IncompatibleClassChangeError();
                case PERSONAL -> this.state.personalWarehouse(this.stateAccount(), this.accountCharacterIdentities());
                case CLAN -> this.state.clanWarehouse(string);
                case ELF -> this.state.elfWarehouse(string);
            };
            runtimeInventory = RuntimeInventory.fromDurableState(warehouse.inventory(), warehouse.itemStates());
        }
        if (warehouseScope == GameStateStore.WarehouseScope.PERSONAL) {
            NativeDeItemApplication.replace(this, runtimeInventory.copy(), 3);
        }
        return new PendingWarehouse(warehouseScope, string, string2, repositoryWarehouseSnapshot.authoritative(), warehouse, runtimeInventory);
    }

    private int warehousePassword() throws IOException {
        try {
            RepositoryWarehousePassword sql =
                    selectedSourceAccounts().warehousePassword(accountName());
            return sql.authoritative() ? sql.password()
                    : state.warehousePassword(stateAccount());
        } catch (Exception failure) {
            throw new IOException("cannot load warehouse password", failure);
        }
    }

    private GameStateStore.WarehousePasswordStatus changeWarehousePassword(
            int expectedOld, int replacement) throws IOException {
        try {
            RepositoryWarehousePasswordChange sql = selectedSourceAccounts()
                    .changeWarehousePassword(accountName(), expectedOld, replacement);
            return sql.authoritative() ? sql.status()
                    : state.changeWarehousePassword(
                            stateAccount(), expectedOld, replacement);
        } catch (Exception failure) {
            throw new IOException("cannot change warehouse password", failure);
        }
    }

    /** Arms every locally rendered deposit controller available on storage HTML. */
    private void armWarehouseDeposits(long npcObjectId) throws IOException {
        pendingWarehousePassword = null;
        clearPendingClassicList();
        if (activeWarehouseNpcPoint(npcObjectId) == null) {
            throw new IOException("warehouse deposit actor is not active in this scene");
        }
        Map<Long, Long> offered = new LinkedHashMap<>();
        for (RuntimeInventory.Item item : inventory.items()) {
            if (item.transferable() && !item.equipped() && item.durability() == 0) {
                offered.put(item.objectId(), 0L);
            }
        }
        Map<Integer, PendingWarehouse> modes = new LinkedHashMap<>();
        modes.put(2, loadWarehouse(GameStateStore.WarehouseScope.PERSONAL,
                stateAccount(), accountName()));
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        if (!clan.name().isBlank()) {
            modes.put(4, loadWarehouse(GameStateStore.WarehouseScope.CLAN,
                    stateClan(clan.name()), clan.name()));
        }
        if (isElfCharacter()) {
            modes.put(8, loadWarehouse(GameStateStore.WarehouseScope.ELF,
                    stateAccount(), accountName()));
        }
        pendingClassicList = new PendingClassicList(
                npcObjectId, phase, activeInteractionContext(), -1, offered,
                Map.of(), Map.of(), modes,
                System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS);
        System.out.println("[LiTo] native warehouse deposits armed npc="
                + npcObjectId + " modes=" + modes.keySet() + " objects=" + offered.size());
    }

    /**
     * The original retrieve action caches its native mode/NPC in the client.
     * Message 834 asks the client to open the password UI, whose eventual
     * C_WAREHOUSE_CONTROL packet contains only mode, password and NPC id.
     * Preserve the original requested scope in a one-shot server capability
     * so native mode 1 can still distinguish personal from elven storage.
     */
    private void requestWarehouseRetrieve(int nativeMode, int retrieveMode, long npcObjectId)
            throws IOException {
        pendingWarehousePassword = null;
        clearPendingClassicList();
        if (warehousePassword() == 0) {
            sendWarehouseRetrieveList(retrieveMode, npcObjectId);
            return;
        }
        sendWarehouseRetrieveList(retrieveMode, npcObjectId, nativeMode);
    }

    private void warehouseControl(byte[] payload) throws IOException {
        Protocol.WarehouseControlRequest request = Protocol.warehouseControlRequest(payload);
        if ((phase != Phase.BATTLE && phase != Phase.WORLD) || observer || playerHp <= 0
                || rejectWhileParalyzed("C_WAREHOUSE_CONTROL")) {
            pendingWarehousePassword = null;
            System.out.println("[LiTo] C_WAREHOUSE_CONTROL rejected invalid-state phase="
                    + phase + " mode=" + request.mode());
            return;
        }
        ArenaMapCatalog.Point npc = request.mode() == 0
                ? nearestActiveWarehouseNpcPoint()
                : activeWarehouseNpcPoint(request.second());
        if (npc == null || classicNpcDistance(npc) > 5) {
            pendingWarehousePassword = null;
            System.out.println("[LiTo] C_WAREHOUSE_CONTROL rejected warehouse-distance mode="
                    + request.mode());
            return;
        }

        if (request.mode() == 0) {
            pendingWarehousePassword = null;
            int oldPassword = (int) request.first();
            int newPassword = (int) request.second();
            if (oldPassword == 0 && newPassword == 0
                    && warehousePassword() == 0) {
                sendEncrypted(Protocol.messageCode(79),
                        "S_MESSAGE_CODE warehouse-password-empty=79");
                return;
            }
            GameStateStore.WarehousePasswordStatus result =
                    changeWarehousePassword(oldPassword, newPassword);
            if (result == GameStateStore.WarehousePasswordStatus.WRONG_OLD) {
                sendEncrypted(Protocol.messageCode(835),
                        "S_MESSAGE_CODE warehouse-password-wrong=835 operation=change");
            } else if (result == GameStateStore.WarehousePasswordStatus.UNCHANGED) {
                sendEncrypted(Protocol.messageCode(342),
                        "S_MESSAGE_CODE warehouse-password-unchanged=342");
            } else {
                System.out.println("[LiTo] C_WAREHOUSE_CONTROL changed account="
                        + mask(accountName()) + " enabled=" + (newPassword != 0));
            }
            return;
        }

        PendingWarehousePassword pending = pendingWarehousePassword;
        // A native password answer is one-shot even when it is wrong, stale,
        // or forged.  The client must issue a fresh C_HACTION to obtain 834.
        pendingWarehousePassword = null;
        long now = System.nanoTime();
        boolean valid = pending != null
                && pending.nativeMode() == request.mode()
                && pending.npcObjectId() == request.second()
                && pending.phase() == phase
                && pending.roomId() == activeInteractionContext()
                && activeInteractionContext() != 0
                && now <= pending.expiresAtNanos();
        if (!valid) {
            System.out.println("[LiTo] C_WAREHOUSE_CONTROL rejected missing-or-stale-capability mode="
                    + request.mode());
            return;
        }
        int configuredPassword = warehousePassword();
        if (configuredPassword == 0 || request.first() != configuredPassword) {
            sendEncrypted(Protocol.messageCode(835),
                    "S_MESSAGE_CODE warehouse-password-wrong=835 operation=retrieve");
            return;
        }
        sendWarehouseRetrieveList(pending.retrieveMode(), pending.npcObjectId());
    }

    private void sendWarehouseRetrieveList(int mode, long npcObjectId) throws IOException {
        sendWarehouseRetrieveList(mode, npcObjectId, 0);
    }

    /**
     * Resolves the native warehouse scope and proves that it contains at least
     * one retrievable row before opening the password UI.  The retained
     * C_NPCAction performs this empty check before message 834; nativeMode is
     * non-zero only for that pre-password pass.  A correct password answer
     * calls this method again with nativeMode zero so current durable contents,
     * permissions and actor distance are revalidated before a list is issued.
     */
    private void sendWarehouseRetrieveList(int mode, long npcObjectId, int nativeMode)
            throws IOException {
        pendingWarehousePassword = null;
        clearPendingClassicList();
        GameStateStore.WarehouseScope scope;
        String owner;
        if (mode == 3) {
            scope = GameStateStore.WarehouseScope.PERSONAL;
            owner = stateAccount();
        } else if (mode == 5) {
            GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
            int role = hub.clanRole(sourceCharacterIdentity());
            if (clan.name().isBlank()) {
                clearPendingClassicList();
                sendEncrypted(Protocol.messageCode(208),
                        "S_MESSAGE_CODE pledge-warehouse-no-clan=208");
                return;
            }
            if (role != GameHub.CLAN_ROLE_OWNER && role != GameHub.CLAN_ROLE_OFFICER
                    && (role != GameHub.CLAN_ROLE_MEMBER || classicTitle.isBlank())) {
                clearPendingClassicList();
                sendEncrypted(Protocol.messageCode(728),
                        "S_MESSAGE_CODE pledge-warehouse-title-required=728");
                return;
            }
            scope = GameStateStore.WarehouseScope.CLAN;
            owner = stateClan(clan.name());
        } else if (mode == 9) {
            if (!isElfCharacter()) {
                clearPendingClassicList();
                sendEncrypted(Protocol.messageCode(166,
                                "僅精靈角色可使用精靈倉庫。"),
                        "S_MESSAGE_CODE elf-warehouse-class-required=166");
                return;
            }
            scope = GameStateStore.WarehouseScope.ELF;
            owner = stateAccount();
        } else {
            throw new IllegalArgumentException("invalid native warehouse retrieve mode");
        }
        String sqlOwner = scope == GameStateStore.WarehouseScope.CLAN
                ? hub.clanData(sourceCharacterIdentity()).name() : accountName();
        PendingWarehouse pendingWarehouse = loadWarehouse(scope, owner, sqlOwner);
        RuntimeInventory contents = pendingWarehouse.contents();
        if (activeWarehouseNpcPoint(npcObjectId) == null) {
            throw new IOException("warehouse retrieve actor is not active in this scene");
        }
        Map<Long, Long> offered = new LinkedHashMap<>();
        List<Protocol.RetrieveListRow> rows = new ArrayList<>();
        for (RuntimeInventory.Item item : contents.items()) {
            InventoryCatalog.Definition definition = item.definition();
            offered.put(item.objectId(), 0L);
            rows.add(new Protocol.RetrieveListRow(
                    item.objectId(), definition.useType(), definition.icon(),
                    item.blessing(), item.quantity(),
                    item.identified() ? 1 : 0, item.nativeViewName()));
        }
        if (rows.isEmpty()) {
            clearPendingClassicList();
            sendEncrypted(Protocol.hypertext(npcObjectId, "noitemret", "", List.of()),
                    "S_HYPERTEXT html=noitemret warehouse=" + npcObjectId + " mode=" + mode);
            return;
        }
        if (nativeMode != 0) {
            pendingWarehousePassword = new PendingWarehousePassword(
                    nativeMode, mode, npcObjectId, phase, activeInteractionContext(),
                    System.nanoTime() + WAREHOUSE_PASSWORD_TIMEOUT_NANOS);
            sendEncrypted(Protocol.messageCode(834),
                    "S_MESSAGE_CODE warehouse-password-required=834 mode=" + nativeMode
                            + " retrieve-mode=" + mode + " expires-seconds=30");
            return;
        }
        long expiresAt = System.nanoTime() + CLASSIC_LIST_CONTEXT_TIMEOUT_NANOS;
        if (mode == 5 && !hub.claimClanWarehouse(
                sourceCharacterIdentity(), this, expiresAt)) {
            clearPendingClassicList();
            sendEncrypted(Protocol.messageCode(209),
                    "S_MESSAGE_CODE pledge-warehouse-in-use=209");
            return;
        }
        pendingClassicList = new PendingClassicList(
                npcObjectId, phase, activeInteractionContext(), mode, offered,
                Map.of(), Map.of(), Map.of(mode, pendingWarehouse), expiresAt);
        sendEncrypted(Protocol.retrieveList(npcObjectId, mode, rows),
                "S_RETRIEVE_LIST warehouse=" + npcObjectId + " mode=" + mode
                        + " rows=" + rows.size());
    }

    private void clearPendingClassicList() {
        pendingClassicList = null;
        pendingClassicCraft = null;
        pendingHotelRental = null;
        hub.releaseClanWarehouse(this);
    }

    private PendingClassicList validClassicList(Protocol.ClassicShopTransaction classicShopTransaction) {
        PendingClassicList pendingClassicList = this.pendingClassicList;
        boolean bl = pendingClassicList != null && classicShopTransaction != null && (this.phase == Phase.BATTLE || this.phase == Phase.WORLD) && !this.observer && this.playerHp > 0 && pendingClassicList.phase() == this.phase && this.activeInteractionContext() != 0L && pendingClassicList.roomId() == this.activeInteractionContext() && pendingClassicList.npcObjectId() == classicShopTransaction.npcObjectId() && (pendingClassicList.mode() == classicShopTransaction.mode() || pendingClassicList.mode() == -1 && pendingClassicList.warehouseModes().containsKey(classicShopTransaction.mode())) && System.nanoTime() <= pendingClassicList.expiresAtNanos();
        ArenaMapCatalog.Point point = null;
        int n = 5;
        if (pendingClassicList != null && !pendingClassicList.warehouseModes().isEmpty()) {
            point = this.activeWarehouseNpcPoint(classicShopTransaction.npcObjectId());
        } else if (this.phase == Phase.BATTLE) {
            point = this.classicMerchantNpcPoint();
        } else if (this.phase == Phase.WORLD) {
            ClassicWorldNpcCatalog.StaticNpc staticNpc = ClassicWorldNpcCatalog.npc(this.classicWorldMapId, classicShopTransaction.npcObjectId());
            ClassicWorldMerchantCatalog.Merchant merchant = ClassicWorldMerchantCatalog.find(staticNpc);
            if (merchant != null) {
                point = new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this));
                n = merchant.maximumDistance();
            } else if (ClassicWorldKentCastleCatalog.isNiki(staticNpc)) {
                point = new ArenaMapCatalog.Point(NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this));
            }
        }
        boolean bl2 = bl = bl && point != null && this.classicNpcDistance(point) <= n;
        if (!bl) {
            this.clearPendingClassicList();
        }
        return bl ? pendingClassicList : null;
    }

    private void classicBuySell(byte[] payload) throws IOException {
        if (rentalTownRoomState && phase == Phase.BATTLE) {
            rentalTownBuySell(payload);
            return;
        }
        Protocol.ClassicShopTransaction transaction =
                Protocol.classicShopTransaction(payload);
        if (rejectWhileParalyzed("C_BUY_SELL")) {
            clearPendingClassicList();
            return;
        }
        PendingClassicList context = validClassicList(transaction);
        if (context == null) {
            System.out.println("[LiTo] C_BUY_SELL rejected stale-context npc="
                    + transaction.npcObjectId() + " mode=" + transaction.mode()
                    + " rows=" + transaction.lines().size());
            return;
        }
        if (transaction.lines().isEmpty()) {
            clearPendingClassicList();
            System.out.println("[LiTo] C_BUY_SELL cancel npc=" + transaction.npcObjectId()
                    + " mode=" + transaction.mode());
            return;
        }

        Map<Long, Long> requested = new LinkedHashMap<>();
        boolean accepted = true;
        String reason = "accepted";
        try {
            for (Protocol.ShopLine line : transaction.lines()) {
                requested.merge(line.itemId(), line.quantity(), Math::addExact);
            }
        } catch (ArithmeticException overflow) {
            accepted = false;
            reason = "quantity-overflow";
        }
        RuntimeInventory nextInventory = inventory.copy();
        RuntimeInventory nextWarehouse = warehouse.copy();
        PendingWarehouse warehouseCapability =
                context.warehouseModes().get(transaction.mode());

        if (accepted && transaction.mode() == 0) {
            long totalAdena = 0;
            long totalItemUnitWeight = 0;
            try {
                for (Map.Entry<Long, Long> entry : requested.entrySet()) {
                    InventoryCatalog.Definition definition =
                            context.offeredDefinitions().get(entry.getKey());
                    Long offeredPrice = context.offeredUnitPrices().get(entry.getKey());
                    long packCount = context.offeredPackCounts()
                            .getOrDefault(entry.getKey(), 1L);
                    if (definition == null || offeredPrice == null
                            || offeredPrice <= 0 || packCount <= 0) {
                        accepted = false;
                        reason = "unoffered-buy-row";
                        break;
                    }
                    totalAdena = Math.addExact(totalAdena,
                            Math.multiplyExact(offeredPrice, entry.getValue()));
                    totalItemUnitWeight = Math.addExact(totalItemUnitWeight,
                            Math.multiplyExact(
                                    (long) definition.unitWeight(),
                                    Math.multiplyExact(entry.getValue(), packCount)));
                    RuntimeInventory admitted = nextInventory.copy();
                    if (!admitted.add(definition,
                            Math.multiplyExact(entry.getValue(), packCount))) {
                        accepted = false;
                        reason = "inventory-capacity";
                        break;
                    }
                    nextInventory = admitted;
                }
            } catch (ArithmeticException overflow) {
                accepted = false;
                reason = "price-overflow";
            }
            if (accepted && !nextInventory.removeCatalog(InventoryCatalog.ADENA, totalAdena)) {
                accepted = false;
                reason = "insufficient-adena";
            }
            if (accepted && !BattleInventoryWeight.permitsShopOrder(
                    weightProfile(inventory, System.nanoTime()), totalItemUnitWeight)) {
                accepted = false;
                reason = "inventory-weight";
            }
        } else if (accepted && transaction.mode() == 1) {
            long totalAdena = 0;
            try {
                for (Map.Entry<Long, Long> entry : requested.entrySet()) {
                    RuntimeInventory.Item item = nextInventory.item(entry.getKey());
                    long price = item == null ? 0
                            : ClassicMerchantCatalog.sellPrice(item.definition());
                    Long offeredPrice = context.offeredUnitPrices().get(entry.getKey());
                    if (item == null || offeredPrice == null
                            || offeredPrice.longValue() != price || price <= 0
                            || item.equipped() || item.durability() != 0
                            || !nextInventory.remove(item.objectId(), entry.getValue())) {
                        accepted = false;
                        reason = "invalid-sell-row";
                        break;
                    }
                    totalAdena = Math.addExact(totalAdena,
                            Math.multiplyExact(price, entry.getValue()));
                }
                if (accepted && !nextInventory.add(
                        InventoryCatalog.require(InventoryCatalog.ADENA), totalAdena)) {
                    accepted = false;
                    reason = "inventory-capacity";
                }
            } catch (ArithmeticException overflow) {
                accepted = false;
                reason = "price-overflow";
            }
        } else if (accepted && warehouseCapability != null
                && warehouseAuthorityValid(warehouseCapability, transaction.mode())) {
            ClassicWarehouseTransaction.Outcome outcome = ClassicWarehouseTransaction.apply(
                    transaction.mode(), requested, transaction.lines().size(),
                    context.offeredUnitPrices().keySet(), inventory,
                    warehouseCapability.contents(), this::permitsInventoryAddition);
            accepted = outcome.accepted();
            reason = outcome.reason();
            nextInventory = outcome.inventory();
            nextWarehouse = outcome.warehouse();
        } else if (accepted && warehouseCapability != null) {
            accepted = false;
            reason = "warehouse-authority-changed";
        } else if (accepted) {
            accepted = false;
            reason = "unsupported-mode";
        }

        if (!accepted) {
            clearPendingClassicList();
            if (reason.equals("insufficient-adena")) {
                sendEncrypted(Protocol.messageCode(189),
                        "S_MESSAGE_CODE classic-shop-insufficient-adena=189");
            } else if (reason.equals("insufficient-mithril")) {
                sendEncrypted(Protocol.messageCode(337, "$767"),
                        "S_MESSAGE_CODE elf-warehouse-mithril-insufficient=337");
            } else if (reason.equals("warehouse-capacity")) {
                sendEncrypted(Protocol.messageCode(75),
                        "S_MESSAGE_CODE personal-warehouse-full=75");
            } else if (reason.equals("inventory-capacity")) {
                sendEncrypted(Protocol.messageCode(263),
                        "S_MESSAGE_CODE classic-shop-inventory-full=263");
            } else if (reason.equals("inventory-weight")) {
                sendInventoryWeightOver("classic-shop-or-warehouse");
            }
            System.out.println("[LiTo] C_BUY_SELL rejected npc="
                    + transaction.npcObjectId() + " mode=" + transaction.mode()
                    + " rows=" + transaction.lines().size() + " reason=" + reason);
            return;
        }

        RuntimeInventory previousInventory = inventory;
        if (warehouseCapability != null) {
            Map<Long, Long> localToSource = state.sourceInventoryBindings(
                    stateCharacter()).stream().collect(java.util.stream.Collectors.toMap(
                            GameStateStore.SourceInventoryBinding::localObjectId,
                            GameStateStore.SourceInventoryBinding::sourceObjectId,
                            (left, right) -> left, LinkedHashMap::new));
            RepositoryWarehouseTransferResult sqlResult =
                    RepositoryWarehouseTransferResult.READ_ONLY;
            if (warehouseCapability.sqlAuthoritative()) {
                CharacterSummary selected = selectedCharacterSummary();
                if (selected == null) {
                    clearPendingClassicList();
                    throw new IOException("selected character vanished during warehouse transfer");
                }
                try {
                    sqlResult = selectedSourceAccounts().persistWarehouseTransfer(
                            selected.objectId(), warehouseCapability.scope(),
                            warehouseCapability.sqlOwner(), inventory,
                            warehouseCapability.contents(), nextInventory, nextWarehouse,
                            localToSource);
                } catch (Exception failure) {
                    throw new IOException("cannot persist SQL warehouse transfer", failure);
                }
            }
            boolean committed = !warehouseCapability.sqlAuthoritative()
                    || sqlResult == RepositoryWarehouseTransferResult.SUCCESS;
            if (committed) committed = switch (warehouseCapability.scope()) {
                case PERSONAL -> state.saveInventoryAndPersonalWarehouse(
                        stateCharacter(), warehouseCapability.owner(),
                        nextInventory.catalogCounts(), nextInventory.catalogItemStates(),
                        warehouseCapability.snapshot(), nextWarehouse.catalogCounts(),
                        nextWarehouse.catalogItemStates());
                case CLAN -> state.saveInventoryAndClanWarehouse(
                        stateCharacter(), warehouseCapability.owner(),
                        nextInventory.catalogCounts(), nextInventory.catalogItemStates(),
                        warehouseCapability.snapshot(), nextWarehouse.catalogCounts(),
                        nextWarehouse.catalogItemStates());
                case ELF -> state.saveInventoryAndElfWarehouse(
                        stateCharacter(), warehouseCapability.owner(),
                        nextInventory.catalogCounts(), nextInventory.catalogItemStates(),
                        warehouseCapability.snapshot(), nextWarehouse.catalogCounts(),
                        nextWarehouse.catalogItemStates());
            };
            if (committed && warehouseCapability.sqlAuthoritative()) {
                state.reconcileWarehouseSourceBindings(
                        stateCharacter(), inventory, warehouseCapability.contents(),
                        nextInventory, nextWarehouse, localToSource);
                CharacterSummary selected = selectedCharacterSummary();
                if (selected != null) {
                    try {
                        state.importSourcePets(stateCharacter(),
                                selectedSourceAccounts().pets(selected.objectId()));
                    } catch (Exception failure) {
                        throw new IOException(
                                "cannot reconcile pets after SQL warehouse transfer", failure);
                    }
                }
            }
            if (!committed) {
                clearPendingClassicList();
                sendEncrypted(Protocol.messageCode(209),
                        "S_MESSAGE_CODE warehouse-stale=209");
                System.out.println("[LiTo] C_BUY_SELL rejected npc="
                        + transaction.npcObjectId() + " mode=" + transaction.mode()
                        + " rows=" + transaction.lines().size()
                        + " reason=warehouse-conflict sql=" + sqlResult);
                return;
            }
            if (warehouseCapability.scope() == GameStateStore.WarehouseScope.PERSONAL) {
                NativeDeItemApplication.replace(this, nextWarehouse, 3);
            }
        } else {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    nextInventory.catalogCounts(), nextInventory.catalogItemStates());
        }
        // Keep the native pledge-warehouse lease until the atomic durable
        // commit has completed. Releasing it before save() would allow a
        // second member to open a stale list during the filesystem write.
        clearPendingClassicList();
        NativeDeItemApplication.replace(this, nextInventory, 0);
        sendInventoryDelta(previousInventory, inventory);
        System.out.println("[LiTo] C_BUY_SELL accepted npc="
                + transaction.npcObjectId() + " mode=" + transaction.mode()
                + " rows=" + transaction.lines().size()
                + " inventory=" + inventory.size()
                + " warehouse=" + (warehouseCapability == null ? 0 : nextWarehouse.size()));
    }

    private boolean warehouseAuthorityValid(PendingWarehouse capability, int mode) {
        if (capability.scope() == GameStateStore.WarehouseScope.PERSONAL) {
            return capability.owner().equalsIgnoreCase(stateAccount())
                    && (mode == 2 || mode == 3);
        }
        if (capability.scope() == GameStateStore.WarehouseScope.ELF) {
            return capability.owner().equalsIgnoreCase(stateAccount())
                    && isElfCharacter() && (mode == 8 || mode == 9);
        }
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        if (!stateClan(clan.name()).equalsIgnoreCase(capability.owner())
                || (mode != 4 && mode != 5)) return false;
        int role = hub.clanRole(sourceCharacterIdentity());
        return mode == 4 ? role == GameHub.CLAN_ROLE_OWNER
                        || role == GameHub.CLAN_ROLE_OFFICER
                        || role == GameHub.CLAN_ROLE_MEMBER
                : role == GameHub.CLAN_ROLE_OWNER || role == GameHub.CLAN_ROLE_OFFICER
                        || (role == GameHub.CLAN_ROLE_MEMBER && !classicTitle.isBlank());
    }

    private void changePersonalShop(byte[] payload) throws IOException {
        Protocol.PersonalShopRequest request = Protocol.personalShopRequest(payload);
        GameHub.PrivateShopActionOutcome outcome = hub.changePrivateShop(
                currentRoomId, this, request);
        byte[] action = outcome.status() == GameHub.PrivateShopActionStatus.OPENED
                ? Protocol.personalShopAction(playerObjectId(), outcome.announcement())
                : Protocol.objectAction(playerObjectId(), BattleActionCodes.IDLE);
        for (ClientSession recipient : outcome.recipients()) {
            recipient.sendEncrypted(action, "S_ACTION personal-shop owner=" + playerName()
                    + " state=" + outcome.status());
        }
        System.out.printf("[LiTo] C_PERSONAL_SHOP owner=%s type=%d sell=%d buy=%d accepted=%s plain=%s%n",
                playerName(), request.type(), request.sellOffers().size(),
                request.buyOffers().size(),
                outcome.status() != GameHub.PrivateShopActionStatus.INVALID,
                Protocol.hex(payload));
    }

    private void queryPersonalShop(byte[] payload) throws IOException {
        Protocol.PersonalShopQuery query = Protocol.personalShopQuery(payload);
        GameHub.PrivateShopViewOutcome view = hub.queryPrivateShop(
                currentRoomId, this, query);
        byte[] list = query.type() == 0
                ? Protocol.personalShopSellList(query.targetObjectId(), view.sellRows())
                : Protocol.personalShopBuyList(query.targetObjectId(), view.buyRows());
        sendEncrypted(list, "S_PERSONAL_SHOP_LIST type=" + query.type()
                + " target=" + Long.toUnsignedString(query.targetObjectId())
                + " rows=" + (query.type() == 0 ? view.sellRows().size() : view.buyRows().size())
                + " accepted=" + view.accepted());
    }

    private void closePersonalShopIfOpen(String reason) throws IOException {
        if (!hub.hasPrivateShop(this)) return;
        GameHub.PrivateShopActionOutcome outcome = hub.closePrivateShop(this);
        byte[] idle = Protocol.objectAction(playerObjectId(), BattleActionCodes.IDLE);
        for (ClientSession recipient : outcome.recipients()) {
            recipient.sendEncrypted(idle, "S_ACTION personal-shop close owner="
                    + playerName() + " reason=" + reason);
        }
    }

    private void sendBuyList() throws IOException {
        List<TournamentShopCatalog.Offer> offers = loadTournamentShopOffers();
        if (!openTournamentShop(TournamentShopMode.BUY, offers)) return;
        Protocol.Writer packet = new Protocol.Writer().c(Protocol.S_LITO_BUY_LIST)
                .h(offers.size());
        for (TournamentShopCatalog.Offer offer : offers) addShopItem(packet, offer);
        sendEncrypted(packet.bytes(), "S_LITO_BUY_LIST items=" + offers.size()
                + " native-economy=" + config.nativeTournamentEconomyEnabled());
    }

    private void addShopItem(Protocol.Writer packet, TournamentShopCatalog.Offer offer) {
        InventoryCatalog.Definition item = offer.definition();
        byte[] details = new RuntimeInventory.Item(1, item, 1, false).nativeStatusDetail();
        packet.d(item.catalogId()).h(item.icon()).d(offer.buyPrice())
                .s(item.name()).c(details.length).raw(details);
    }

    private void sendSellList() throws IOException {
        List<TournamentShopCatalog.Offer> offers = loadTournamentShopOffers();
        if (!openTournamentShop(TournamentShopMode.SELL, offers)) return;
        List<RuntimeInventory.Item> sellable = inventory.items().stream()
                .filter(item -> tournamentSellPrice(item, offers) > 0)
                .toList();
        Protocol.Writer packet = new Protocol.Writer().c(Protocol.S_LITO_SELL_LIST)
                .h(sellable.size());
        for (RuntimeInventory.Item item : sellable) {
            // S_E0/C_DB sell rows use the runtime inventory object id. The
            // durable catalog id is never exposed in this native list.
            packet.d(item.objectId()).d(tournamentSellPrice(item, offers));
        }
        sendEncrypted(packet.bytes(), "S_LITO_SELL_LIST objects=" + sellable.size());
    }

    private void buySell(byte[] payload) throws IOException {
        Protocol.ShopTransaction transaction;
        try {
            transaction = Protocol.shopTransaction(payload);
        } catch (IllegalArgumentException malformed) {
            pendingTournamentShop = null;
            if (tournamentShopPhaseAllowed()) {
                sendPointStats();
                sendTournamentShopNotice("交易資料或數量無效，金幣與物品未變更。請重新開啟商店。");
            }
            return;
        }
        // Native mode-13/14 personal-shop confirmation is the contextual C_DB
        // form.  Never fall it through to the Tournament point shop: a stale
        // or replayed visitor capability must not become a catalog transaction.
        if (transaction.hasContext() || hub.hasPendingPrivateShopQuery(this)) {
            buySellPersonal(transaction, payload);
            return;
        }
        PendingTournamentShop shop = pendingTournamentShop;
        pendingTournamentShop = null;
        if (!validTournamentShopConfirmation(shop, transaction.operation())) {
            System.out.printf("[LiTo] C_LITO_BUY_SELL rejected phase=%s operation=%d"
                            + " reason=missing-or-stale-LTshop-context plain=%s%n",
                    phase, transaction.operation(), Protocol.hex(payload));
            if (tournamentShopPhaseAllowed()) {
                sendPointStats();
                sendTournamentShopNotice("交易已失效，請重新開啟商店後再試。金幣與物品未變更。");
            }
            return;
        }
        Map<Long, Long> requested = new LinkedHashMap<>();
        boolean accepted = !transaction.lines().isEmpty();
        try {
            for (Protocol.ShopLine line : transaction.lines()) {
                requested.merge(line.itemId(), line.quantity(), Math::addExact);
            }
        } catch (ArithmeticException overflow) {
            accepted = false;
        }

        long nextPoints = shopPoints;
        String rejectionReason = "交易資料或數量無效，金幣與物品未變更。";
        RuntimeInventory nextInventory = inventory.copy();
        if (accepted) {
            try {
                for (Map.Entry<Long, Long> entry : requested.entrySet()) {
                    long rowId = entry.getKey();
                    long quantity = entry.getValue();
                    if (quantity <= 0 || quantity > Integer.MAX_VALUE) {
                        accepted = false;
                        break;
                    }
                    InventoryCatalog.Definition definition;
                    long price;
                    if (transaction.operation() == 0) {
                        TournamentShopCatalog.Offer offer = TournamentShopCatalog.find(
                                shop.offers(), rowId);
                        definition = offer == null ? null : offer.definition();
                        price = offer == null ? 0 : offer.buyPrice();
                    } else {
                        RuntimeInventory.Item object = nextInventory.item(rowId);
                        definition = object == null ? null : object.definition();
                        price = object == null ? 0
                                : tournamentSellPrice(object, shop.offers());
                    }
                    if (price <= 0) {
                        accepted = false;
                        rejectionReason = "此物品無法交易，請重新開啟商店。金幣與物品未變更。";
                        break;
                    }
                    long total = Math.multiplyExact(price, quantity);
                    if (transaction.operation() == 0) {
                        if (nextPoints < total) {
                            rejectionReason = "金幣不足，目前持有 " + shopPoints
                                    + "，本次至少需要 " + Math.addExact(shopPoints - nextPoints, total)
                                    + "。整筆交易取消，物品未變更。";
                            accepted = false;
                            break;
                        }
                        RuntimeInventory admitted = nextInventory.copy();
                        if (!admitted.add(definition, quantity)) {
                            accepted = false;
                            rejectionReason = "背包空間不足，整筆交易取消，金幣與物品未變更。";
                            break;
                        }
                        if (!permitsInventoryAddition(nextInventory, definition, quantity)) {
                            accepted = false;
                            rejectionReason = "負重不足，整筆交易取消，金幣與物品未變更。";
                            break;
                        }
                        nextInventory = admitted;
                        nextPoints -= total;
                    } else {
                        if (!nextInventory.remove(rowId, quantity)) {
                            accepted = false;
                            break;
                        }
                        nextPoints = Math.addExact(nextPoints, total);
                        if (nextPoints > 0xFFFF_FFFFL) {
                            accepted = false;
                            rejectionReason = "金幣超過上限，整筆交易取消，物品未變更。";
                            break;
                        }
                    }
                }
            } catch (ArithmeticException overflow) {
                accepted = false;
            }
        }
        long previousPoints = shopPoints;
        if (accepted) {
            try {
                // Commit before publishing either half of the transaction.
                state.saveEconomyState(stateCharacter(), nextPoints,
                        nextInventory.catalogCounts(), nextInventory.catalogItemStates());
            } catch (IOException failure) {
                accepted = false;
                rejectionReason = "交易儲存失敗，金幣與物品未變更。請稍後重新交易。";
                System.out.println("[LiTo] shop commit failed: " + failure.getMessage());
            }
        }
        if (accepted) {
            RuntimeInventory previousInventory = inventory;
            shopPoints = nextPoints;
            NativeDeItemApplication.replace(this, nextInventory, 0);
            // The lobby already owns the same 648EBC item receiver used by
            // selection S_7C. Publish committed object deltas immediately.
            // A later bootstrap clears the retained native model before repopulating it.
            inventoryBootstrapSent = false;
            sendInventoryDelta(previousInventory, inventory, false);
        }
        System.out.printf("[LiTo] C_LITO_BUY_SELL operation=%d rows=%d context=%s accepted=%s points=%d plain=%s%n",
                transaction.operation(), transaction.lines().size(),
                transaction.hasContext() ? Long.toUnsignedString(transaction.contextId()) : "none",
                accepted, shopPoints, Protocol.hex(payload));
        // The native confirmation callback closes the list immediately after
        // C_DB.  S_DB synchronizes points; sending S_DF/S_E0 here would reopen
        // the window that the user just confirmed.
        sendPointStats();
        sendTournamentShopNotice(accepted
                ? (transaction.operation() == 0 ? "購買成功，物品已放入背包，花費 " : "出售成功，獲得 ")
                    + Math.abs(shopPoints - previousPoints) + " 金幣，剩餘 " + shopPoints + "。"
                : rejectionReason);
    }

    private void sendTournamentShopNotice(String message) throws IOException {
        // Both native dispatch tables accept S_0F. Type 9 selects the lobby
        // chat renderer in phases 1/2/3/6 and the world renderer otherwise.
        sendEncrypted(Protocol.systemMessage(9, message), "S_MESSAGE shop-result");
    }

    private List<TournamentShopCatalog.Offer> loadTournamentShopOffers()
            throws IOException {
        if (!config.nativeTournamentEconomyEnabled()) {
            return TournamentShopCatalog.offers(false);
        }
        // Reflection-level packet tests intentionally allocate a session without
        // its repository graph. Production constructors always supply accounts.
        if (accounts == null) return TournamentShopCatalog.offers(true);
        try {
            List<TournamentShopCatalog.Offer> offers = TournamentShopCatalog.fromDatabase(
                    selectedSourceAccounts().tournamentShopOffers());
            tournamentShopOffers = offers;
            return offers;
        } catch (Exception failure) {
            pendingTournamentShop = null;
            throw new IOException("cannot load selected-source Tournament shop", failure);
        }
    }

    private boolean openTournamentShop(TournamentShopMode mode,
                                       List<TournamentShopCatalog.Offer> offers) {
        if (!tournamentShopPhaseAllowed()) {
            pendingTournamentShop = null;
            System.out.println("[LiTo] C_LITO_" + mode + "_LIST rejected phase="
                    + phase + " reason=LTshop-non-gameplay-only");
            return false;
        }
        pendingTournamentShop = new PendingTournamentShop(
                mode, phase, currentChannelId, currentRoomId,
                List.copyOf(offers),
                System.nanoTime() + 60_000_000_000L);
        return true;
    }

    private boolean tournamentShopPhaseAllowed() {
        return endpoint == Endpoint.GAME
                && !selectedCharacter.isBlank()
                && (phase == Phase.LOBBY || phase == Phase.CHANNEL || phase == Phase.ROOM);
    }

    private boolean validTournamentShopConfirmation(
            PendingTournamentShop shop, int operation) {
        return shop != null
                && tournamentShopPhaseAllowed()
                && shop.mode().operation == operation
                && shop.phase() == phase
                && shop.channelId() == currentChannelId
                && shop.roomId() == currentRoomId
                && System.nanoTime() <= shop.expiresAtNanos();
    }

    private long tournamentSellPrice(RuntimeInventory.Item item) {
        List<TournamentShopCatalog.Offer> offers = tournamentShopOffers;
        if (offers == null) offers = TournamentShopCatalog.offers(
                config.nativeTournamentEconomyEnabled());
        return tournamentSellPrice(item, offers);
    }

    private long tournamentSellPrice(RuntimeInventory.Item item,
                                     List<TournamentShopCatalog.Offer> offers) {
        if (item == null) return 0;
        if (!config.nativeTournamentEconomyEnabled()) {
            return item.definition().sellPrice();
        }
        if (item.sourceBound()) return 0;
        TournamentShopCatalog.Offer offer = TournamentShopCatalog.find(
                offers, item.definition().catalogId());
        return offer == null ? 0 : offer.sellPrice();
    }

    private void buySellPersonal(Protocol.ShopTransaction transaction, byte[] payload)
            throws IOException {
        GameHub.PrivateShopTransactionOutcome outcome = hub.transactPrivateShop(
                currentRoomId, this, transaction);
        if (outcome.accepted()) {
            sendInventoryDelta(outcome.visitorBefore(), outcome.visitorAfter());
            outcome.owner().sendInventoryDelta(outcome.ownerBefore(), outcome.ownerAfter());
            if (outcome.shopClosed()) {
                byte[] idle = Protocol.objectAction(outcome.owner().playerObjectId(),
                        BattleActionCodes.IDLE);
                for (ClientSession recipient : outcome.closeRecipients()) {
                    recipient.sendEncrypted(idle, "S_ACTION personal-shop exhausted owner="
                            + outcome.owner().playerName());
                }
            }
        }
        System.out.printf("[LiTo] C_LITO_BUY_SELL personal-shop visitor=%s operation=%d rows=%d context=%s trailer=%d accepted=%s plain=%s%n",
                playerName(), transaction.operation(), transaction.lines().size(),
                transaction.hasContext() ? Long.toUnsignedString(transaction.contextId()) : "none",
                transaction.nativeTrailer().length, outcome.accepted(), Protocol.hex(payload));
    }

    private void sendPointStats() throws IOException {
        sendEncrypted(new Protocol.Writer().c(Protocol.S_LITO_POINT)
                        .s(litoDisplayName()).d(shopPoints).d(0).d(0).d(0).c(0).c(0).bytes(),
                "S_LITO_POINT player=" + playerName() + " points=" + shopPoints);
    }

    private boolean activatePendingRentalBattleHandoff(String string) throws IOException {
        if (this.rentalBattleLoadoutActive || this.accountName().isBlank() || this.selectedCharacter.isBlank()) {
            return false;
        }
        GameHub gameHub = this.hub;
        String string3 = this.accountName();
        String string2 = this.stateCharacter();
        GameHub.RentalBattleHandoff rentalBattleHandoff = gameHub.consumeRentalBattleHandoff(SourceLogin.account(this, string3), string2);
        if (rentalBattleHandoff == null) {
            return false;
        }
        NativeDeItemApplication.replace(this, this.inventory.copy(), 2);
        this.rentalBattleSourceFireResistance = this.sourceEquippedFireResistance;
        this.rentalBattleSourceMagicStats = this.sourceEquipmentMagicStats;
        this.rentalBattleSourceVitalStats = this.sourceEquipmentVitalStats;
        this.rentalBattleSourceInitialArmorClassModifier = this.sourceInitialArmorClassModifier;
        this.rentalBattleSourceWeaponSuppressed = this.sourceWeaponSuppressed;
        NativeDeItemApplication.replace(this, rentalBattleHandoff.inventory(), 0);
        this.sourceEquippedFireResistance = new SourceEquippedFireResistance(0, 0);
        this.sourceEquipmentMagicStats = SourceEquipmentMagicStats.none();
        this.sourceEquipmentVitalStats = SourceEquipmentVitalStats.none();
        this.sourceInitialArmorClassModifier = 0;
        this.sourceWeaponSuppressed = true;
        this.retainedSourceInventoryWeight = 0;
        this.inventoryBootstrapSent = false;
        this.rentalBattleLoadoutActive = true;
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, this.inventory.catalogCounts(), this.inventory.catalogItemStates());
        System.out.println("[LiTo] activated rental battle handoff player=" + this.playerName() + " trigger=" + string + " inventory-objects=" + this.inventory.size());
        return true;
    }

    private void resetNativeTournamentEconomy(String string) {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$resetNativeTournamentEconomy(string, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    private void sendInventoryDelta(RuntimeInventory before, RuntimeInventory after) throws IOException {
        sendInventoryDelta(before, after, true);
    }

    private void sendInventoryDelta(RuntimeInventory before, RuntimeInventory after,
                                    boolean refreshBattleStatus) throws IOException {
        Map<Long, RuntimeInventory.Item> oldItems = new LinkedHashMap<>();
        for (RuntimeInventory.Item item : before.items()) oldItems.put(item.objectId(), item);
        Map<Long, RuntimeInventory.Item> newItems = new LinkedHashMap<>();
        for (RuntimeInventory.Item item : after.items()) newItems.put(item.objectId(), item);

        for (RuntimeInventory.Item item : oldItems.values()) {
            if (newItems.containsKey(item.objectId())) continue;
            sendEncrypted(Protocol.removeInventory(item.objectId()),
                    "S_REMOVE_INVENTORY object=" + item.objectId()
                            + " catalog=" + item.definition().catalogId());
        }
        for (RuntimeInventory.Item item : newItems.values()) {
            RuntimeInventory.Item old = oldItems.get(item.objectId());
            if (old == null) {
                sendEncrypted(Protocol.addInventory(item.wireItem()),
                        "S_ADD_INVENTORY object=" + item.objectId()
                                + " catalog=" + item.definition().catalogId()
                                + " count=" + item.quantity());
            } else if (old.quantity() != item.quantity()) {
                sendEncrypted(Protocol.changeInventoryCount(item.objectId(), item.quantity()),
                        "S_CHANGE_COUNT object=" + item.objectId() + " count=" + item.quantity());
            }
        }
        if (refreshBattleStatus && (phase == Phase.BATTLE || phase == Phase.WORLD) && !observer
                && sourceInventoryWeightStats != null
                && sourceEquipmentMagicStats != null) {
            sendNativeBattleStatus(System.nanoTime(), "inventory-delta");
        }
    }

    private void sendGroundItems(String reason) throws IOException {
        for (BattleGroundItems.Item item : hub.groundItems(currentRoomId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    positionX, positionY, item.x(), item.y())) continue;
            sendEncrypted(Protocol.groundItem(
                            item.objectId(), item.x(), item.y(),
                            item.definition().groundGfx(), item.quantity(), item.displayName()),
                    "S_PUT_OBJECT ground-item=" + item.objectId()
                            + " catalog=" + item.definition().catalogId()
                            + " quantity=" + item.quantity() + " reason=" + reason);
        }
    }

