    private void updateClassicWorldStaticNpcVisibility(int n, int n2, int n3, int n4) throws IOException {
        List<ClassicWorldNpcCatalog.StaticNpc> list = NativeStaticNpcMotion.inScreen(this.classicWorldMapId, n, n2, this).stream().filter(staticNpc -> !ClassicWorldCastleWarField.isStaticTower(staticNpc)).filter(staticNpc -> !ClassicWorldBowCatalog.isBow(staticNpc)).toList();
        List<ClassicWorldNpcCatalog.StaticNpc> list2 = NativeStaticNpcMotion.inScreen(this.classicWorldMapId, n3, n4, this).stream().filter(staticNpc -> !ClassicWorldCastleWarField.isStaticTower(staticNpc)).filter(staticNpc -> !ClassicWorldBowCatalog.isBow(staticNpc)).toList();
        for (ClassicWorldNpcCatalog.StaticNpc staticNpc3 : list) {
            if (!list2.stream().noneMatch(staticNpc2 -> staticNpc2.objectId() == staticNpc3.objectId())) continue;
            this.sendEncrypted(Protocol.removeObject(staticNpc3.objectId()), "S_REMOVE_OBJECT classic-world-static-npc=" + staticNpc3.objectId() + " spawn=" + staticNpc3.spawnId());
        }
        for (ClassicWorldNpcCatalog.StaticNpc staticNpc3 : list2) {
            if (!list.stream().noneMatch(staticNpc2 -> staticNpc2.objectId() == staticNpc3.objectId())) continue;
            this.sendClassicWorldStaticNpc(staticNpc3, "screen-enter");
        }
    }

