    private List<ClassicWorldWaterDragonCatalog.Door>
            waterDragonDoorsInScreen(int x, int y) {
        if (classicWorldMapId != ClassicWorldWaterDragonCatalog.MAP_ID
                || classicWorldInstanceId <= 0) return List.of();
        return ClassicWorldWaterDragonCatalog.doors().stream()
                .filter(door -> BattleSpellCatalog.isInNativeScreen(
                        x, y, door.x(), door.y())).toList();
    }

    private void sendWaterDragonDoors(String reason) throws IOException {
        ClassicWorldWaterDragonInstances.Snapshot snapshot =
                hub.classicWorldWaterDragonInstances().snapshot(
                        classicWorldInstanceId);
        if (snapshot == null || !snapshot.active()) return;
        for (ClassicWorldWaterDragonCatalog.Door door
                : waterDragonDoorsInScreen(positionX, positionY)) {
            sendWaterDragonDoor(door,
                    Boolean.TRUE.equals(snapshot.openDoors().get(door.doorId())),
                    reason);
        }
    }

    private void sendWaterDragonDoor(
            ClassicWorldWaterDragonCatalog.Door door,
            boolean open, String reason) throws IOException {
        int action = open ? BattleDoor.ACTION_OPEN : BattleDoor.ACTION_CLOSED;
        int passable = open ? BattleDoor.PASSABLE : BattleDoor.NOT_PASSABLE;
        sendEncrypted(Protocol.classicCastleDoor(
                        door.objectId(classicWorldInstanceId), door.x(), door.y(),
                        door.gfxId(), action),
                "S_PUT_OBJECT Water-Dragon-door=" + door.doorId()
                        + " show=" + classicWorldInstanceId
                        + " gfx=" + door.gfxId() + " action=" + action
                        + " hp=0/0 reason=" + reason);
        sendWaterDragonDoorAttributes(door, passable, reason);
    }

    private void sendWaterDragonDoorAttributes(
            ClassicWorldWaterDragonCatalog.Door door,
            int passable, String reason) throws IOException {
        for (int edge = door.edgeLow(); edge <= door.edgeHigh(); edge++) {
            int x = door.heading() == 0 ? edge : door.entranceX();
            int y = door.heading() == 0 ? door.entranceY() : edge;
            sendEncrypted(Protocol.doorAttribute(
                            x, y, door.heading(), passable),
                    "S_CHANGE_ATTR Water-Dragon-door=" + door.doorId()
                            + " show=" + classicWorldInstanceId
                            + " x=" + x + " y=" + y
                            + " direction=" + door.heading()
                            + " passable=" + passable + " reason=" + reason);
        }
    }

    private void broadcastWaterDragonDoorOpen(
            ClassicWorldWaterDragonCatalog.Door door,
            int showId, String reason) throws IOException {
        byte[] action = Protocol.objectAction(
                door.objectId(showId), BattleDoor.ACTION_OPEN);
        for (ClientSession member : hub.classicWorldMembers(
                ClassicWorldWaterDragonCatalog.MAP_ID, showId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, door.x(), door.y())) {
                continue;
            }
            member.sendEncrypted(action,
                    "S_ACTION Water-Dragon-door=" + door.doorId()
                            + " show=" + showId + " action="
                            + BattleDoor.ACTION_OPEN + " reason=" + reason);
            member.sendWaterDragonDoorAttributes(
                    door, BattleDoor.PASSABLE, reason);
        }
    }

