    private void sendClassicWorldCompanionObject(ClientSession clientSession, BattleCompanion.Snapshot snapshot, String string) throws IOException {
        if (clientSession == null || snapshot == null || !snapshot.active() || !snapshot.kind().classicWorldEligible()) {
            return;
        }
        if (snapshot.kind() == BattleCompanion.Kind.PET) {
            this.sendEncrypted(Protocol.classicPet(snapshot, clientSession.playerName(), this == clientSession), "S_PUT_OBJECT persistent-pet=" + snapshot.objectId() + " owner=" + clientSession.playerName() + " exp=" + snapshot.experience() + " lawful=" + snapshot.lawful() + " hp-tail=" + (this == clientSession ? NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()) : 255) + " reason=" + string);
        } else {
            this.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(), snapshot.x(), snapshot.y(), snapshot.gfx(), 0, 0, snapshot.moveSpeed(), 0, snapshot.level(), 0, clientSession.playerName(), this == clientSession ? NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()) : 255);
            this.sendEncrypted(Protocol.master(snapshot.objectId(), clientSession.playerName()), "S_MASTER classic-world-companion=" + snapshot.objectId() + " owner=" + clientSession.playerName() + " reason=" + string);
            this.sendEncrypted(Protocol.speed(snapshot.objectId(), Protocol.SpeedMode.fromWire(snapshot.moveSpeed()), 0), "S_SPEED classic-world-companion=" + snapshot.objectId() + " mode=" + snapshot.moveSpeed() + " reason=" + string);
        }
        if (snapshot.hp() == 0) {
            this.sendEncrypted(Protocol.objectAction(snapshot.objectId(), 8), "S_ACTION classic-world-pet-corpse=" + snapshot.objectId() + " reason=" + string);
        }
    }

    private void sendClassicWorldMonster(
            ClassicWorldMonsterPopulation.Snapshot monster, String reason)
            throws IOException {
        if (monster.hiddenStatus()
                == ClassicWorldMonsterPopulation.HIDDEN_STATUS_SINK) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.HIDE),
                    "S_ACTION classic-world-monster hidden-sink="
                            + monster.objectId() + " action="
                            + BattleActionCodes.HIDE + " reason=" + reason);
        } else if (monster.hiddenStatus()
                == ClassicWorldMonsterPopulation.HIDDEN_STATUS_ICE) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.HIDE),
                    "S_ACTION classic-world-monster hidden-ice="
                            + monster.objectId() + " action="
                            + BattleActionCodes.HIDE + " reason=" + reason);
        } else if (monster.hiddenStatus()
                == ClassicWorldMonsterPopulation.HIDDEN_STATUS_FLY) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.MOVE_UP),
                    "S_ACTION classic-world-monster hidden-fly="
                            + monster.objectId() + " action="
                            + BattleActionCodes.MOVE_UP + " reason=" + reason);
        }
        int moveSpeed = phase == Phase.WORLD
                && classicWorldMapId == monster.mapId()
                ? hub.classicWorldMonsterMoveSpeed(
                        monster.mapId(), classicWorldInstanceId,
                        monster.objectId(), System.nanoTime())
                : BattleTimedStatus.NORMAL;
        sendEncrypted(Protocol.classicWorldMonster(monster, moveSpeed),
                "S_PUT_OBJECT classic-world-monster=" + monster.objectId()
                        + " spawn=" + monster.spawnId()
                        + " slot=" + monster.spawnNumber()
                        + " npc=" + monster.npcId()
                        + " gfx=" + monster.gfxId()
                        + " name=" + monster.nameId()
                        + " title=" + monster.title()
                        + " lawful=" + monster.lawful()
                        + " move-speed=" + moveSpeed
                        + " hp=" + monster.currentHp() + "/" + monster.maximumHp()
                        + " x=" + monster.x() + " y=" + monster.y()
                        + " heading=" + monster.heading()
                        + " hidden=" + monster.hiddenStatus()
                        + " actor-status=" + monster.actorStatus()
                        + " reason=" + reason);
        if (!monster.alive()) {
            sendEncrypted(Protocol.objectAction(
                            monster.objectId(), BattleActionCodes.DIE),
                    "S_ACTION classic-world-monster corpse=" + monster.objectId());
        } else if (phase == Phase.WORLD
                && classicWorldMapId == monster.mapId()) {
            int palette = hub.classicWorldMonsterPoisonPalette(
                    monster.mapId(), classicWorldInstanceId,
                    monster.objectId(), System.nanoTime());
            if (palette != 0) {
                sendEncrypted(Protocol.poison(monster.objectId(), palette),
                        "S_POISON classic-world-monster=" + monster.objectId()
                                + " type=" + palette + " reason=" + reason
                                + "-bootstrap");
            }
        }
    }

