    private void useLightSpell(byte[] byArray, BattleSpellCatalog.LightSpell lightSpell) throws IOException {
        boolean bl;
        Protocol.SpellSelector spellSelector = Protocol.selectorOnlySpellRequest(byArray);
        Phase phase = this.phase;
        boolean bl2 = bl = phase == Phase.WORLD;
        if (spellSelector.skillId() != lightSpell.skillId() || !BattleAnimationCatalog.get().supportsTimedAction(this.battleGfx(), lightSpell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL light rejected selector/action player=" + this.playerName() + " skill=" + spellSelector.skillId());
            return;
        }
        if (bl && !this.admitClassicWorldSpellFamily(lightSpell.skillId(), lightSpell.actionId(), "Light")) {
            return;
        }
        long l = System.nanoTime();
        NativeLightAction.commit(this, lightSpell, (Object)phase, bl, l);
    }

