    private void useAdvanceSpiritSpell(
            byte[] payload, BattleSpellCatalog.AdvanceSpiritSpell spell) throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        boolean classicWorld = phase == Phase.WORLD;
        List<ClientSession> targetPool = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomCombatants(currentRoomId);
        ClientSession target = targetPool.stream()
                .filter(candidate -> candidate.playerObjectId()
                        == request.targetObjectId())
                .findFirst().orElse(null);
        boolean sameMap = target != null
                && (classicWorld ? sameClassicWorldMap(target)
                    : hub.battleMapId(currentRoomId, this)
                        == hub.battleMapId(currentRoomId, target));
        boolean livingTarget = target != null && target.phase == phase
                && !target.observer && target.playerHp > 0
                && (!target.invisible || target == this);
        boolean nativeScreen = target != null
                && BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, target.positionX, target.positionY);
        if (request.skillId() != spell.skillId() || !sameMap || !livingTarget
                || !nativeScreen
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Advance Spirit rejected"
                    + " selector/target/range player=" + playerName()
                    + " skill=" + request.skillId()
                    + " target=" + request.targetObjectId()
                    + " same-map=" + sameMap + " living=" + livingTarget
                    + " native-screen=" + nativeScreen);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        ClientSession firstLock = playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingMp;
        int targetHp;
        int targetMp;
        int targetMaxHp;
        int targetMaxMp;
        boolean newlyActivated;
        long now = System.nanoTime();
        synchronized (firstLock) {
            synchronized (secondLock) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean battleContext = phase == Phase.BATTLE
                        && currentRoomId != 0
                        && target.phase == Phase.BATTLE
                        && target.currentRoomId == currentRoomId;
                boolean worldContext = phase == Phase.WORLD
                        && target.phase == Phase.WORLD
                        && sameClassicWorldMap(target);
                if (now < readyAt || playerMp < mpCost
                        || (phase != Phase.BATTLE && phase != Phase.WORLD)
                        || (!battleContext && !worldContext)
                        || target.phase != phase
                        || observer || playerHp <= 0 || target.observer
                        || target.playerHp <= 0
                        || (target.invisible && target != this)) {
                    System.out.println("[LiTo] C_USE_SPELL Advance Spirit rejected state"
                            + " skill=" + spell.skillId() + " mp=" + playerMp
                            + " cost=" + mpCost + " cooldownNanos="
                            + Math.max(0L, readyAt - now));
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                newlyActivated = target.timedStatus.activateAdvanceSpirit(
                        now, spell.durationSeconds());
                target.rebuildMaximumVitals(now);
                targetHp = target.playerHp;
                targetMp = target.playerMp;
                targetMaxHp = target.playerMaxHp;
                targetMaxMp = target.playerMaxMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            boolean seesCaster = !classicWorld || (sameClassicWorldMap(member)
                    && BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY));
            boolean seesTarget = !classicWorld || (sameClassicWorldMap(member)
                    && BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            target.positionX, target.positionY));
            if (seesCaster && (!invisible || member == this)) {
                member.sendEncrypted(action,
                        "S_ACTION advance-spirit-cast object=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            if (seesTarget) {
                member.sendEncrypted(effect,
                        "S_EFFECT advance-spirit target=" + target.playerObjectId()
                                + " gfx=" + spell.effectGfx());
            }
        }
        target.sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(targetHp).h(targetMaxHp).bytes(),
                "S_HIT_POINT advance-spirit=" + targetHp + "/" + targetMaxHp);
        target.broadcastOwnHitRatio("advance-spirit-max-hp");
        target.sendEncrypted(Protocol.manaPoint(targetMp, targetMaxMp),
                "S_MANA_POINT advance-spirit=" + targetMp + "/" + targetMaxMp);
        target.sendNativeBattleStatus(now, "advance-spirit-active");
        if (target != this) {
            sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                    "S_MANA_POINT advance-spirit-caster=" + remainingMp
                            + "/" + playerMaxMp);
        }
        System.out.println("[LiTo] C_USE_SPELL Advance Spirit caster=" + playerName()
                + " target=" + target.playerName() + " selector=" + request.row()
                + "/" + request.column() + " action=" + spell.actionId()
                + " gfx=" + spell.effectGfx() + " duration="
                + spell.durationSeconds() + " newly-active=" + newlyActivated
                + " max-hp=" + targetMaxHp + " max-mp=" + targetMaxMp
                + " effective-int=" + effectiveIntelligence + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + phase
                + " cancellation-immune=true selected-client-icon=unavailable");
    }

    private void useArmorBreakSpell(byte[] byArray, BattleSpellCatalog.ArmorBreakSpell armorBreakSpell) throws IOException {
        NativeArmorMaterialAction.cast(this, byArray, armorBreakSpell);
    }

    private ArmorBreakTarget resolveArmorBreakTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int sourceX, int sourceY) {
        Map<Long, ArmorBreakTarget> eligible = new LinkedHashMap<>();
        if (originPhase == Phase.WORLD) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            for (ClientSession candidate : classicWorldMembers(originMapId)) {
                if (candidate != this && candidate.phase == Phase.WORLD
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                        && !map.isSafetyZone(sourceX, sourceY)
                        && !map.isSafetyZone(
                                candidate.positionX, candidate.positionY)
                        && map.attackPosition(sourceX, sourceY,
                                candidate.positionX, candidate.positionY, 1)) {
                    eligible.put(candidate.playerObjectId(), new ArmorBreakTarget(
                            candidate.playerObjectId(), candidate.positionX,
                            candidate.positionY, candidate.battleLevel(),
                            candidate, null, null, null, false));
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, sourceX, sourceY)) {
                if (candidate.present() && candidate.alive()
                        && candidate.mapId() == originMapId
                        && !map.isSafetyZone(sourceX, sourceY)
                        && !map.isSafetyZone(candidate.x(), candidate.y())
                        && map.attackPosition(sourceX, sourceY,
                                candidate.x(), candidate.y(), 1)) {
                    eligible.put(candidate.objectId(), new ArmorBreakTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            Math.max(1, candidate.template().level()), null,
                            candidate, null, null, false));
                }
            }
        } else {
            for (ClientSession candidate : hub.roomCombatants(originRoomId)) {
                if (candidate != this && candidate.phase == Phase.BATTLE
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && candidate.currentRoomId == originRoomId
                        && hub.canAttack(originRoomId, this, candidate)) {
                    eligible.put(candidate.playerObjectId(), new ArmorBreakTarget(
                            candidate.playerObjectId(), candidate.positionX,
                            candidate.positionY, candidate.battleLevel(),
                            candidate, null, null, null, false));
                }
            }
            for (BattleQuestEncounter.Snapshot candidate
                    : hub.visibleQuestMonsters(originRoomId, this)) {
                if (candidate.alive() && hub.canAttackQuestMonster(
                        originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new ArmorBreakTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            Math.max(1, candidate.level()), null, null,
                            candidate, null, false));
                }
            }
            for (BattleTimeAttackEncounter.Snapshot candidate
                    : hub.visibleTimeAttackActors(originRoomId, this)) {
                if (candidate.alive() && hub.canAttackTimeAttackActor(
                        originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new ArmorBreakTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            Math.max(1, candidate.level()), null, null, null,
                            candidate, false));
                }
            }
            BattleRules.Mode mode = hub.roomRules(originRoomId).mode();
            ArenaMapCatalog.Point bot = hub.botPosition(originRoomId);
            if (mode != BattleRules.Mode.QUEST_BATTLE
                    && mode != BattleRules.Mode.TIME_ATTACK
                    && bot != null && hub.botHp(originRoomId) > 0) {
                eligible.put(2L, new ArmorBreakTarget(
                        2L, bot.x(), bot.y(), 1,
                        null, null, null, null, true));
            }
        }

        List<BattleArmorBreak.Candidate> candidates = eligible.values().stream()
                .map(candidate -> new BattleArmorBreak.Candidate(
                        candidate.objectId(), candidate.x(), candidate.y()))
                .toList();
        long resolved = BattleArmorBreak.resolveTarget(
                lastCombatTargetObjectId, sourceX, sourceY, candidates);
        if (resolved == 0) {
            long adjacent = candidates.stream().filter(candidate ->
                    Math.max(Math.abs(sourceX - candidate.x()),
                            Math.abs(sourceY - candidate.y())) <= 1).count();
            System.out.println("[LiTo] C_USE_SPELL Armor Break rejected unresolved"
                    + " selector-only target player=" + playerName()
                    + " last-explicit=" + lastCombatTargetObjectId
                    + " adjacent-candidates=" + adjacent);
            return null;
        }
        return eligible.get(resolved);
    }

    private boolean armorBreakTargetStillEligible(
            ArmorBreakTarget target, Phase originPhase, long originRoomId,
            int originMapId, int originInstanceId, int sourceX, int sourceY) {
        int targetX;
        int targetY;
        boolean eligible;
        if (originPhase == Phase.WORLD && target.player() != null) {
            targetX = target.player().positionX;
            targetY = target.player().positionY;
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && target.player().phase == Phase.WORLD
                    && !target.player().observer && target.player().playerHp > 0
                    && !target.player().invisible
                    && target.player().classicWorldMapId == originMapId
                    && target.player().classicWorldInstanceId == originInstanceId
                    && !map.isSafetyZone(sourceX, sourceY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(sourceX, sourceY, targetX, targetY, 1);
        } else if (originPhase == Phase.WORLD) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && current != null && current.present() && current.alive()
                    && !ClassicWorldMapCatalog.forMap(originMapId)
                            .isSafetyZone(sourceX, sourceY)
                    && !ClassicWorldMapCatalog.forMap(originMapId)
                            .isSafetyZone(targetX, targetY)
                    && ClassicWorldMapCatalog.forMap(originMapId)
                            .attackPosition(
                                    sourceX, sourceY, targetX, targetY, 1);
        } else if (target.player() != null) {
            targetX = target.player().positionX;
            targetY = target.player().positionY;
            eligible = phase == Phase.BATTLE && currentRoomId == originRoomId
                    && target.player().phase == Phase.BATTLE
                    && !target.player().observer && target.player().playerHp > 0
                    && !target.player().invisible
                    && target.player().currentRoomId == originRoomId
                    && hub.canAttack(originRoomId, this, target.player());
        } else if (target.quest() != null) {
            BattleQuestEncounter.Snapshot current = hub.questMonster(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && current.alive()
                    && hub.canAttackQuestMonster(
                            originRoomId, this, target.objectId());
        } else if (target.time() != null) {
            BattleTimeAttackEncounter.Snapshot current = hub.timeAttackActor(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && current.alive()
                    && hub.canAttackTimeAttackActor(
                            originRoomId, this, target.objectId());
        } else {
            ArenaMapCatalog.Point current = hub.botPosition(originRoomId);
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = target.bot() && current != null && hub.botHp(originRoomId) > 0;
        }
        return eligible && Math.max(Math.abs(sourceX - targetX),
                Math.abs(sourceY - targetY)) <= 1;
    }

    private void useGuardBrakeSpell(
            byte[] payload, BattleSpellCatalog.GuardBrakeSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        String nativeName = spell.horrorOfDeath()
                ? "Horror of Death" : "Guard Brake";
        String wireName = spell.horrorOfDeath()
                ? "Horror-of-Death" : "Guard-Brake";
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && !classicWorld)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL " + nativeName
                    + " rejected selector/action"
                    + " player=" + playerName() + " skill=" + request.skillId());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), wireName)) return;

        long originRoomId = currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        ArmorBreakTarget target = resolveGuardBrakeTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, spell.maximumRange());
        if (target == null) return;
        long gateNow = System.nanoTime();
        if (target.player() != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        target.player().timedStatus.absoluteBarrierActive(gateNow),
                        spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL " + nativeName
                    + " rejected Absolute Barrier"
                    + " target=" + target.objectId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        BattleCompanion.Snapshot guardCompanion = target.companion() == null
                ? null : target.companion().snapshot();
        int npcId = guardCompanion != null ? guardCompanion.npcId()
                : target.world() != null ? target.world().npcId()
                : target.quest() != null ? target.quest().npcId()
                : target.time() != null ? target.time().npcId() : 0;
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] " + nativeName
                        + " source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] " + nativeName
                        + " source NPC row missing"
                        + " player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int targetLevel = Math.max(1, target.level());
        long targetMrNow = System.nanoTime();
        int targetMr = target.player() != null
                ? target.player().effectiveBaseMagicResistance(targetMrNow)
                : target.companion() != null
                    ? target.companion().effectiveMagicResistance(
                            npcStats.magicResistance(), targetMrNow)
                : target.bot() ? 0
                : effectiveNpcMagicResistance(
                        target.world(), target.quest(), target.time(),
                        npcStats.magicResistance(), targetMrNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(targetMrNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        boolean bossImmune = npcStats != null && npcStats.boss()
                || target.world() != null && target.world().template().boss()
                || target.time() != null && target.time().finalBoss();
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence,
                totalMagicHit, targetMr, bossImmune);
        int configuredRoll = spell.horrorOfDeath()
                ? config.horrorOfDeathFixtureD100()
                : config.guardBrakeFixtureD100();
        int percentileRoll = configuredRoll == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredRoll;

        int remainingHp;
        int remainingMp;
        int rejectionMessage = 0;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (castNow < readyAt || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL " + nativeName
                        + " rejected state"
                        + " target=" + target.objectId() + " hp=" + playerHp
                        + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + phase + " origin-phase=" + originPhase);
                return;
            }
            if (playerHp <= spell.hpCost()) rejectionMessage = 279;
            else if (playerMp < mpCost) rejectionMessage = 278;
            if (rejectionMessage == 0) {
                cancelMeditation("spell-" + spell.skillId());
                playerHp -= spell.hpCost();
                playerMp -= mpCost;
                commitSpellReady(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            remainingHp = playerHp;
            remainingMp = playerMp;
        }

        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE " + wireName + "-rejected=" + rejectionMessage);
            System.out.println("[LiTo] C_USE_SPELL " + nativeName
                    + " rejected resource"
                    + " message=" + rejectionMessage + " hp=" + remainingHp
                    + " mp=" + remainingMp + " hp-cost=" + spell.hpCost()
                    + " mp-cost=" + mpCost);
            return;
        }

        if (classicWorld) {
            cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
            revealInvisibility("classic-world-spell-" + spell.skillId());
        }
        boolean probabilityBlocked = target.player() != null
                && BattleEarthBindRules.blocksProbabilityMagic(
                        target.player().timedStatus.earthBindActive(castNow),
                        spell.skillId());
        if (!classicWorld) {
            probabilityBlocked = earthBindBlocksProbabilityMagic(
                    target.player(), target.quest(), target.time(),
                    castNow, spell.skillId());
        }
        boolean probabilitySuccess = !probabilityBlocked
                && BattleGuardBrake.succeeds(probability, percentileRoll);
        if (classicWorld) {
            consumeEraseMagicAfterProbability(
                    target.player(), target.world(), null, null,
                    castNow, spell.skillId());
        } else {
            consumeEraseMagicAfterProbability(
                    target.player(), target.quest(), target.time(),
                    castNow, spell.skillId());
        }
        breakSleepForStatusSpell(target.player(), target.quest(), target.time(),
                (classicWorld ? "classic-world-" : "")
                        + "probability-spell-" + spell.skillId());

        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(originMapId).stream()
                    .filter(member -> member.phase == Phase.WORLD
                            && member.classicWorldMapId == originMapId
                            && member.classicWorldInstanceId == originInstanceId
                            && (BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    originX, originY)
                                || BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    target.x(), target.y())))
                    .toList()
                : target.quest() != null
                    ? hub.battleRecipients(originRoomId, target.quest().force())
                    : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION " + nativeName + " caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean targetStillEligible = guardBrakeTargetStillEligible(
                target, originPhase, originRoomId, originMapId,
                originInstanceId, originX, originY, spell.maximumRange());
        boolean countered = targetStillEligible && probabilitySuccess
                && target.player() != null
                && target.player().timedStatus.consumeCounterMagic(castNow);
        if (countered) publishCounterMagicConsumption(target.player(), spell.skillId());
        boolean refreshed = false;
        boolean applied = targetStillEligible && probabilitySuccess && !countered;
        if (applied && target.player() != null) {
            if (spell.horrorOfDeath()) {
                refreshed = target.player().timedStatus.activateHorrorOfDeath(
                        castNow, spell.durationSeconds());
            } else {
                refreshed = target.player().guardBrakeStatus.activate(
                        castNow, spell.durationSeconds(), spell.armorClassModifier());
            }
        }
        if (applied && spell.horrorOfDeath()) {
            if (target.companion() != null) {
                refreshed = target.companion().activateHorrorOfDeath(
                        castNow, spell.durationSeconds());
            } else if (classicWorld && target.world() != null) {
                refreshed = hub.horrorOfDeathClassicWorldMonster(
                        originMapId, originInstanceId, target.objectId(),
                        castNow, spell.durationSeconds());
            } else if (target.quest() != null) {
                refreshed = hub.horrorOfDeathQuestMonster(
                        originRoomId, this, target.objectId(),
                        castNow, spell.durationSeconds());
            } else if (target.time() != null) {
                refreshed = hub.horrorOfDeathTimeAttackActor(
                        originRoomId, this, target.objectId(),
                        castNow, spell.durationSeconds());
            }
        }
        if (applied && classicWorld && target.world() != null) {
            hub.provokeClassicWorldMonster(
                    originMapId, originInstanceId,
                    target.objectId(), playerObjectId());
        }
        if (applied) {
            byte[] effect = Protocol.effectObject(target.objectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT " + nativeName + " target=" + target.objectId()
                                + " gfx=" + spell.effectGfx());
            }
            if (target.player() != null) {
                if (spell.horrorOfDeath()) {
                    target.player().sendWisdomStatusRefresh(
                            castNow, "Horror-of-Death-active");
                } else {
                    target.player().sendEncrypted(
                            target.player().ownCharacterAttrDef(),
                            "S_AC Guard-Brake current="
                                    + target.player().battleArmorClass());
                    target.player().sendNativeBattleStatus(
                            castNow, "Guard-Brake-active");
                }
            }
        } else {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE " + wireName + "-failure="
                            + spell.failureMessage());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT " + wireName + "=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio(wireName + "-hp-cost");
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT " + wireName + "=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL " + nativeName
                + " skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + target.objectId()
                + " resolution=" + (target.objectId() == lastCombatTargetObjectId
                    ? "last-explicit-target" : "unique-range-target")
                + " npc=" + npcId + " caster-level=" + casterLevel
                + " target-level=" + targetLevel
                + " effective-int=" + effectiveIntelligence
                + " probability=" + probability + " roll=" + percentileRoll
                + " mr=" + targetMr + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " probability-blocked=" + probabilityBlocked
                + " target-still-eligible=" + targetStillEligible
                + " applied=" + applied + " refreshed=" + refreshed
                + " boss-immune=" + bossImmune + " countered=" + countered
                + " duration=" + spell.durationSeconds()
                + " player-ac=" + (target.player() == null
                    ? 0 : spell.armorClassModifier())
                + " npc-mechanical-ac=0 hp-cost=" + spell.hpCost()
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " selected-client-icon=unavailable");
    }

    private ArmorBreakTarget resolveGuardBrakeTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int sourceX, int sourceY, int maximumRange) {
        return resolveDragonKnightNegativeTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                sourceX, sourceY, maximumRange, false);
    }

    private ArmorBreakTarget resolveResistFearTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int sourceX, int sourceY, int maximumRange) {
        return resolveDragonKnightNegativeTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                sourceX, sourceY, maximumRange, true);
    }

    private ArmorBreakTarget resolveDragonKnightNegativeTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int sourceX, int sourceY, int maximumRange,
            boolean resistFear) {
        Map<Long, ArmorBreakTarget> eligible = new LinkedHashMap<>();
        if (originPhase == Phase.WORLD) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            for (ClientSession candidate : classicWorldMembers(originMapId)) {
                if (candidate != this && candidate.phase == Phase.WORLD
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                        && !map.isSafetyZone(sourceX, sourceY)
                        && !map.isSafetyZone(candidate.positionX, candidate.positionY)
                        && map.attackPosition(sourceX, sourceY,
                                candidate.positionX, candidate.positionY,
                                maximumRange)) {
                    eligible.put(candidate.playerObjectId(), new ArmorBreakTarget(
                            candidate.playerObjectId(), candidate.positionX,
                            candidate.positionY, candidate.battleLevel(),
                            candidate, null, null, null, false));
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, sourceX, sourceY)) {
                if (candidate.present() && candidate.alive()
                        && candidate.mapId() == originMapId
                        && !map.isSafetyZone(sourceX, sourceY)
                        && !map.isSafetyZone(candidate.x(), candidate.y())
                        && map.attackPosition(sourceX, sourceY,
                                candidate.x(), candidate.y(), maximumRange)) {
                    eligible.put(candidate.objectId(), new ArmorBreakTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            Math.max(1, candidate.template().level()), null,
                            candidate, null, null, false));
                }
            }
            for (ClientSession owner : classicWorldMembers(originMapId)) {
                if (owner.phase != Phase.WORLD
                        || owner.classicWorldMapId != originMapId
                        || owner.classicWorldInstanceId != originInstanceId) continue;
                for (BattleCompanion.Snapshot candidate
                        : owner.classicWorldCompanionSnapshots()) {
                    BattleCompanion controlled = owner.ownedCompanion(
                            candidate.objectId());
                    if (controlled != null && candidate.active() && candidate.hp() > 0
                            && !map.isSafetyZone(sourceX, sourceY)
                            && !map.isSafetyZone(candidate.x(), candidate.y())
                            && map.attackPosition(sourceX, sourceY,
                                    candidate.x(), candidate.y(), maximumRange)) {
                        eligible.put(candidate.objectId(), new ArmorBreakTarget(
                                candidate.objectId(), candidate.x(), candidate.y(),
                                Math.max(1, candidate.level()), null, null,
                                null, null, false, owner, controlled));
                    }
                }
            }
        } else {
            for (ClientSession candidate : hub.roomCombatants(originRoomId)) {
                if (candidate != this && candidate.phase == Phase.BATTLE
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && candidate.currentRoomId == originRoomId
                        && hub.canAttack(originRoomId, this, candidate)) {
                    eligible.put(candidate.playerObjectId(), new ArmorBreakTarget(
                            candidate.playerObjectId(), candidate.positionX,
                            candidate.positionY, candidate.battleLevel(),
                            candidate, null, null, null, false));
                }
            }
            for (ClientSession owner : hub.roomCombatants(originRoomId)) {
                if (owner != this
                        && !hub.canAttack(originRoomId, this, owner)) continue;
                for (BattleCompanion.Snapshot candidate
                        : owner.controlledCompanionSnapshots()) {
                    BattleCompanion controlled = owner.ownedCompanion(
                            candidate.objectId());
                    if (controlled != null && candidate.active() && candidate.hp() > 0) {
                        eligible.put(candidate.objectId(), new ArmorBreakTarget(
                                candidate.objectId(), candidate.x(), candidate.y(),
                                Math.max(1, candidate.level()), null, null,
                                null, null, false, owner, controlled));
                    }
                }
            }
            for (BattleQuestEncounter.Snapshot candidate
                    : hub.visibleQuestMonsters(originRoomId, this)) {
                if (candidate.alive() && hub.canAttackQuestMonster(
                        originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new ArmorBreakTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            Math.max(1, candidate.level()), null, null,
                            candidate, null, false));
                }
            }
            for (BattleTimeAttackEncounter.Snapshot candidate
                    : hub.visibleTimeAttackActors(originRoomId, this)) {
                if (candidate.alive() && hub.canAttackTimeAttackActor(
                        originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new ArmorBreakTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            Math.max(1, candidate.level()), null, null, null,
                            candidate, false));
                }
            }
            BattleRules.Mode mode = hub.roomRules(originRoomId).mode();
            ArenaMapCatalog.Point bot = hub.botPosition(originRoomId);
            if (mode != BattleRules.Mode.QUEST_BATTLE
                    && mode != BattleRules.Mode.TIME_ATTACK
                    && bot != null && hub.botHp(originRoomId) > 0) {
                eligible.put(2L, new ArmorBreakTarget(
                        2L, bot.x(), bot.y(), 1,
                        null, null, null, null, true));
            }
        }

        List<BattleGuardBrake.Candidate> guardBrakeCandidates =
                eligible.values().stream()
                    .map(candidate -> new BattleGuardBrake.Candidate(
                            candidate.objectId(), candidate.x(), candidate.y()))
                    .toList();
        List<BattleResistFear.Candidate> resistFearCandidates =
                eligible.values().stream()
                    .map(candidate -> new BattleResistFear.Candidate(
                            candidate.objectId(), candidate.x(), candidate.y()))
                    .toList();
        long resolved = resistFear
                ? DragonSkillRequests.fearTarget(
                        lastCombatTargetObjectId, sourceX, sourceY,
                        maximumRange, resistFearCandidates)
                : DragonSkillRequests.guardTarget(
                        lastCombatTargetObjectId, sourceX, sourceY,
                        maximumRange, guardBrakeCandidates);
        if (resolved == 0) {
            long inRange = eligible.values().stream().filter(candidate ->
                    Math.max(Math.abs(sourceX - candidate.x()),
                            Math.abs(sourceY - candidate.y())) <= maximumRange).count();
            System.out.println("[LiTo] C_USE_SPELL "
                    + (resistFear ? "Resist Fear" : "Guard Brake")
                    + " rejected unresolved"
                    + " selector-only target player=" + playerName()
                    + " last-explicit=" + lastCombatTargetObjectId
                    + " range-candidates=" + inRange
                    + " maximum-range=" + maximumRange);
            return null;
        }
        return eligible.get(resolved);
    }

    private boolean guardBrakeTargetStillEligible(
            ArmorBreakTarget target, Phase originPhase, long originRoomId,
            int originMapId, int originInstanceId, int sourceX, int sourceY,
            int maximumRange) {
        int targetX;
        int targetY;
        boolean eligible;
        if (originPhase == Phase.WORLD && target.player() != null) {
            targetX = target.player().positionX;
            targetY = target.player().positionY;
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && target.player().phase == Phase.WORLD
                    && !target.player().observer && target.player().playerHp > 0
                    && !target.player().invisible
                    && target.player().classicWorldMapId == originMapId
                    && target.player().classicWorldInstanceId == originInstanceId
                    && !map.isSafetyZone(sourceX, sourceY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(
                            sourceX, sourceY, targetX, targetY, maximumRange);
        } else if (originPhase == Phase.WORLD && target.companion() != null) {
            BattleCompanion.Snapshot current = target.companion().snapshot();
            targetX = current.x();
            targetY = current.y();
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            ClientSession owner = target.companionOwner();
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && owner != null && owner.phase == Phase.WORLD
                    && owner.classicWorldMapId == originMapId
                    && owner.classicWorldInstanceId == originInstanceId
                    && current.kind().classicWorldEligible()
                    && current.active() && current.hp() > 0
                    && !map.isSafetyZone(sourceX, sourceY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(
                            sourceX, sourceY, targetX, targetY, maximumRange);
        } else if (originPhase == Phase.WORLD) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && current != null && current.present() && current.alive()
                    && !map.isSafetyZone(sourceX, sourceY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(
                            sourceX, sourceY, targetX, targetY, maximumRange);
        } else if (target.player() != null) {
            targetX = target.player().positionX;
            targetY = target.player().positionY;
            eligible = phase == Phase.BATTLE && currentRoomId == originRoomId
                    && target.player().phase == Phase.BATTLE
                    && !target.player().observer && target.player().playerHp > 0
                    && !target.player().invisible
                    && target.player().currentRoomId == originRoomId
                    && hub.canAttack(originRoomId, this, target.player());
        } else if (target.companion() != null) {
            BattleCompanion.Snapshot current = target.companion().snapshot();
            targetX = current.x();
            targetY = current.y();
            ClientSession owner = target.companionOwner();
            eligible = phase == Phase.BATTLE && currentRoomId == originRoomId
                    && owner != null && owner.phase == Phase.BATTLE
                    && owner.currentRoomId == originRoomId
                    && current.active() && current.hp() > 0
                    && (owner == this || hub.canAttack(originRoomId, this, owner));
        } else if (target.quest() != null) {
            BattleQuestEncounter.Snapshot current = hub.questMonster(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && current.alive()
                    && hub.canAttackQuestMonster(
                            originRoomId, this, target.objectId());
        } else if (target.time() != null) {
            BattleTimeAttackEncounter.Snapshot current = hub.timeAttackActor(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && current.alive()
                    && hub.canAttackTimeAttackActor(
                            originRoomId, this, target.objectId());
        } else {
            ArenaMapCatalog.Point current = hub.botPosition(originRoomId);
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = target.bot() && current != null && hub.botHp(originRoomId) > 0;
        }
        return eligible && Math.max(Math.abs(sourceX - targetX),
                Math.abs(sourceY - targetY)) <= maximumRange;
    }

    private void useResistFearSpell(
            byte[] payload, BattleSpellCatalog.ResistFearSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && !classicWorld)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Resist Fear rejected selector/action"
                    + " player=" + playerName() + " skill=" + request.skillId());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Resist-Fear")) return;

        long originRoomId = currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        ArmorBreakTarget target = resolveResistFearTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, spell.maximumRange());
        if (target == null) return;
        long gateNow = System.nanoTime();
        if (target.player() != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        target.player().timedStatus.absoluteBarrierActive(gateNow),
                        spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL Resist Fear rejected Absolute Barrier"
                    + " target=" + target.objectId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int npcId = target.world() != null ? target.world().npcId()
                : target.quest() != null ? target.quest().npcId()
                : target.time() != null ? target.time().npcId() : 0;
        npcId = DragonSkillRequests.fearNpcId(npcId, target);
        if (npcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] Resist Fear source NPC lookup failed"
                        + " player=" + playerName() + " npc=" + npcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
            if (npcStats == null) {
                System.out.println("[LiTo] Resist Fear source NPC row missing"
                        + " player=" + playerName() + " npc=" + npcId);
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int casterLevel = caster == null ? 1 : Math.max(1, caster.level());
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int targetLevel = Math.max(1, target.level());
        long targetMrNow = System.nanoTime();
        int targetMr = target.player() != null
                ? target.player().effectiveBaseMagicResistance(targetMrNow)
                : target.bot() ? 0
                : effectiveNpcMagicResistance(
                        target.world(), target.quest(), target.time(),
                        DragonSkillRequests.fearMagicResistance(npcStats, target, targetMrNow), targetMrNow);
        int equipmentMagicHit = casterEquipment.totalMagicHit();
        int buffMagicHit = dragonEyeStatus.snapshot(targetMrNow).magicHit();
        int totalMagicHit = Math.addExact(equipmentMagicHit, buffMagicHit);
        boolean bossImmune = npcStats != null && npcStats.boss()
                || target.world() != null && target.world().template().boss()
                || target.time() != null && target.time().finalBoss();
        int probability = spell.probabilityForTarget(
                casterLevel, targetLevel, effectiveIntelligence,
                totalMagicHit, targetMr, bossImmune);
        int configuredRoll = config.resistFearFixtureD100();
        int percentileRoll = configuredRoll == 0
                ? ThreadLocalRandom.current().nextInt(1, 101) : configuredRoll;

        int remainingHp;
        int remainingMp;
        int rejectionMessage = 0;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (castNow < readyAt || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL Resist Fear rejected state"
                        + " target=" + target.objectId() + " hp=" + playerHp
                        + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + phase + " origin-phase=" + originPhase);
                return;
            }
            if (playerHp <= spell.hpCost()) rejectionMessage = 279;
            else if (playerMp < mpCost) rejectionMessage = 278;
            if (rejectionMessage == 0) {
                cancelMeditation("spell-" + spell.skillId());
                playerHp -= spell.hpCost();
                playerMp -= mpCost;
                commitSpellReady(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            remainingHp = playerHp;
            remainingMp = playerMp;
        }

        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE Resist-Fear-rejected=" + rejectionMessage);
            System.out.println("[LiTo] C_USE_SPELL Resist Fear rejected resource"
                    + " message=" + rejectionMessage + " hp=" + remainingHp
                    + " mp=" + remainingMp + " hp-cost=" + spell.hpCost()
                    + " mp-cost=" + mpCost);
            return;
        }

        if (classicWorld) {
            cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
            revealInvisibility("classic-world-spell-" + spell.skillId());
        }
        boolean probabilityBlocked = target.player() != null
                && BattleEarthBindRules.blocksProbabilityMagic(
                        target.player().timedStatus.earthBindActive(castNow),
                        spell.skillId());
        if (!classicWorld) {
            probabilityBlocked = earthBindBlocksProbabilityMagic(
                    target.player(), target.quest(), target.time(),
                    castNow, spell.skillId());
        }
        boolean probabilitySuccess = !probabilityBlocked
                && BattleResistFear.succeeds(probability, percentileRoll);
        if (classicWorld) {
            consumeEraseMagicAfterProbability(
                    target.player(), target.world(), null, null,
                    castNow, spell.skillId());
        } else {
            consumeEraseMagicAfterProbability(
                    target.player(), target.quest(), target.time(),
                    castNow, spell.skillId());
        }
        breakSleepForStatusSpell(target.player(), target.quest(), target.time(),
                (classicWorld ? "classic-world-" : "")
                        + "probability-spell-" + spell.skillId());

        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(originMapId).stream()
                    .filter(member -> member.phase == Phase.WORLD
                            && member.classicWorldMapId == originMapId
                            && member.classicWorldInstanceId == originInstanceId
                            && (BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    originX, originY)
                                || BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    target.x(), target.y())))
                    .toList()
                : target.quest() != null
                    ? hub.battleRecipients(originRoomId, target.quest().force())
                    : hub.roomMembers(originRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession member : recipients) {
            if (invisible && member != this) continue;
            member.sendEncrypted(action,
                    "S_ACTION Resist Fear caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        boolean targetStillEligible = guardBrakeTargetStillEligible(
                target, originPhase, originRoomId, originMapId,
                originInstanceId, originX, originY, spell.maximumRange());
        // The selected primary skills_魔屏無效技能 row makes skill188 a
        // Counter Magic exception. Preserve an active ward without consuming it.
        boolean countered = targetStillEligible && probabilitySuccess
                && !spell.counterMagicBypass() && target.player() != null
                && target.player().timedStatus.consumeCounterMagic(castNow);
        if (countered) publishCounterMagicConsumption(target.player(), spell.skillId());
        boolean alreadyActive = false;
        boolean applied = targetStillEligible && probabilitySuccess && !countered;
        if (applied && target.player() != null) {
            alreadyActive = target.player().resistFearStatus.activate(
                    castNow, spell.durationSeconds(), spell.dodgeDownModifier());
            if (!alreadyActive) {
                target.player().state.saveTimedResistFearBuff(
                        target.player().stateCharacter(),
                        new GameStateStore.TimedResistFearBuff(
                                spell.durationSeconds()));
            }
        }
        // Retained NPC overload returns without installing a dodge-down lease.
        if (applied && classicWorld && target.world() != null) {
            hub.provokeClassicWorldMonster(
                    originMapId, originInstanceId,
                    target.objectId(), playerObjectId());
        }
        if (applied) {
            byte[] effect = Protocol.effectObject(target.objectId(), spell.effectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(effect,
                        "S_EFFECT Resist Fear target=" + target.objectId()
                                + " gfx=" + spell.effectGfx());
            }
        } else {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Resist-Fear-failure=" + spell.failureMessage());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Resist-Fear=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("Resist-Fear-hp-cost");
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Resist-Fear=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Resist Fear skill=" + spell.skillId()
                + " caster=" + playerName() + " target=" + target.objectId()
                + " resolution=" + (target.objectId() == lastCombatTargetObjectId
                    ? "last-explicit-target" : "unique-range-target")
                + " npc=" + npcId + " caster-level=" + casterLevel
                + " target-level=" + targetLevel
                + " effective-int=" + effectiveIntelligence
                + " probability=" + probability + " roll=" + percentileRoll
                + " mr=" + targetMr + " equipment-magic-hit=" + equipmentMagicHit
                + " buff-magic-hit=" + buffMagicHit
                + " probability-blocked=" + probabilityBlocked
                + " target-still-eligible=" + targetStillEligible
                + " applied=" + applied + " already-active=" + alreadyActive
                + " boss-immune=" + bossImmune + " counter-bypass="
                + spell.counterMagicBypass() + " countered=" + countered
                + " duration=" + spell.durationSeconds()
                + " player-dodge-down=" + (target.player() == null
                    ? 0 : spell.dodgeDownModifier())
                + " npc-mechanical-dodge-down=0 hp-cost=" + spell.hpCost()
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " selected-client-icon=unavailable");
    }

    private void useReductionArmorSpell(
            byte[] payload, BattleSpellCatalog.ReductionArmorSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && originPhase != Phase.WORLD)) {
            System.out.println("[LiTo] C_USE_SPELL Reduction Armor rejected"
                    + " selector/phase player=" + playerName()
                    + " skill=" + request.skillId());
            return;
        }
        if (originPhase == Phase.WORLD
                && !admitClassicWorldSpellFamily(
                        spell.skillId(), spell.actionId(), "Reduction-Armor")) {
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Reduction Armor rejected"
                    + " action player=" + playerName()
                    + " skill=" + request.skillId()
                    + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);
        int rejectionMessage = 0;
        int remainingHp;
        int remainingMp;
        long now = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterWorld = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (now < readyAt || !sameCasterWorld) {
                System.out.println("[LiTo] C_USE_SPELL Reduction Armor rejected state"
                        + " skill=" + spell.skillId() + " hp=" + playerHp
                        + " mp=" + playerMp + " cooldownNanos="
                        + Math.max(0L, readyAt - now)
                        + " phase=" + phase + " origin-phase=" + originPhase);
                return;
            }
            if (playerHp <= spell.hpCost()) {
                rejectionMessage = 279;
            } else if (playerMp < mpCost) {
                rejectionMessage = 278;
            }
            if (rejectionMessage == 0) {
                cancelMeditation("spell-" + spell.skillId());
                abilityStatus.activateReductionArmor(now, spell.durationSeconds());
                playerHp -= spell.hpCost();
                playerMp -= mpCost;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            remainingHp = playerHp;
            remainingMp = playerMp;
        }

        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE reduction-armor-insufficient="
                            + rejectionMessage);
            System.out.println("[LiTo] C_USE_SPELL Reduction Armor rejected resource"
                    + " message=" + rejectionMessage + " hp=" + remainingHp
                    + " mp=" + remainingMp + " mp-cost=" + mpCost);
            return;
        }

        // Retained normal-cast commit semantics: accepted magic ends the
        // caster's Absolute Barrier and invisibility after all gates pass.
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.phase != Phase.WORLD
                        || member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION " + (originPhase == Phase.WORLD
                                ? "classic-world-" : "")
                                + "reduction-armor-cast object=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT " + (originPhase == Phase.WORLD
                            ? "classic-world-" : "")
                            + "reduction-armor target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT reduction-armor=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("reduction-armor-hp-cost");
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT reduction-armor=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Reduction Armor caster=" + playerName()
                + " selector=" + request.row() + "/" + request.column()
                + " action=" + spell.actionId() + " gfx=" + spell.effectGfx()
                + " duration=" + spell.durationSeconds()
                + " hp-cost=" + spell.hpCost() + " hp=" + remainingHp
                + "/" + playerMaxHp + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " pvp-physical-reduction="
                + spell.reduction(battleLevel(), true)
                + " other-reduction=" + spell.reduction(battleLevel(), false)
                + " cancellation-immune=true selected-client-icon=unavailable");
    }

