                // The native UI normally suppresses this request before it
                // reaches the server. Keep forged/stale requests fail-closed
                // while still giving the local player an exact readable reason.
                sendEncrypted(Protocol.systemMessage(9, "你並未裝備盾牌"),
                        "S_MESSAGE solid-carriage-missing-shield");
