    private boolean hasSolidCarriageEquipment() {
        if (!SolidCarriageRules.runtime(this.inventory)) {
            return this.requiredEquipmentMagicStats().physical().supportsSolidCarriage();
        }
        return true;
    }

    private void removeSolidCarriageUnlessEquipped(String reason) {
        if (!hasSolidCarriageEquipment() && abilityStatus.removeSolidCarriage()) {
            System.out.println("[LiTo] native Solid Carriage removed player="
                    + playerName() + " reason=" + reason
                    + " er=0 icon=omitted-no-selected-LiTo-packetbox-receiver");
        }
    }

