    /** Resolve skill219's selector-only PC target without inventing an id. */
    private ClientSession resolveSelectorOnlyIllusionAvatarTarget(
            BattleSpellCatalog.IllusionAvatarSpell spell, Phase originPhase,
            long originRoomId, int originMapId, int originInstanceId,
            int originX, int originY, long nowNanos) {
        List<ClientSession> candidates = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(originRoomId);
        ArrayList<ClientSession> eligibleExternal = new ArrayList<>();
        ClientSession lastExplicit = null;
        ClassicWorldMapCatalog.ClassicMap worldMap = originPhase == Phase.WORLD
                ? ClassicWorldMapCatalog.forMap(originMapId) : null;
        ArenaMapCatalog.Arena arena = originPhase == Phase.BATTLE
                ? ArenaMapCatalog.forMap(originMapId) : null;
        for (ClientSession candidate : candidates) {
            if (candidate == null || candidate == this || candidate.observer
                    || candidate.playerHp <= 0 || candidate.invisible
                    || candidate.timedStatus.absoluteBarrierActive(nowNanos)) {
                continue;
            }
            boolean sameContext = originPhase == Phase.BATTLE
                    ? candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == originMapId
                    : candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId;
            int range = targetRange(originX, originY,
                    candidate.positionX, candidate.positionY);
            boolean lineOfSight = originPhase == Phase.WORLD
                    ? worldMap.attackPosition(
                        originX, originY,
                        candidate.positionX, candidate.positionY,
                        spell.maximumRange())
                    : BattleSpellCatalog.hasNativeLineOfSight(
                        arena, originX, originY,
                        candidate.positionX, candidate.positionY);
            if (!sameContext || range > spell.maximumRange() || !lineOfSight) {
                continue;
            }
            eligibleExternal.add(candidate);
            if (candidate.playerObjectId() == lastCombatTargetObjectId) {
                lastExplicit = candidate;
            }
        }
        if (IllusionSkillRequests.current() != null) return IllusionSkillRequests.selectPc(this, eligibleExternal);
        if (lastExplicit != null) return lastExplicit;
        if (eligibleExternal.size() == 1) return eligibleExternal.get(0);
        if (eligibleExternal.isEmpty()) return this;
        System.out.println("[LiTo] C_USE_SPELL Illusion: Avatar rejected"
                + " ambiguous selector-only PC target player=" + playerName()
                + " last-explicit=" + lastCombatTargetObjectId
                + " eligible-external=" + eligibleExternal.size()
                + " phase=" + originPhase);
        return null;
    }

    private void useIllusionAvatarSpell(
            byte[] payload, BattleSpellCatalog.IllusionAvatarSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Illusion: Avatar rejected"
                    + " learned/action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        ClientSession target = resolveSelectorOnlyIllusionAvatarTarget(
                spell, originPhase, originRoomId, originMapId,
                originInstanceId, originX, originY, targetNow);
        if (target == null) return;

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        ClientSession firstLock = playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingMp;
        boolean refreshed;
        long castNow = System.nanoTime();
        synchronized (firstLock) {
            synchronized (secondLock) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean contextStillValid = originPhase == Phase.BATTLE
                        ? phase == Phase.BATTLE && currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId
                            && target.phase == Phase.BATTLE
                            && target.currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, target) == originMapId
                        : phase == Phase.WORLD
                            && classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                            && target.phase == Phase.WORLD
                            && target.classicWorldMapId == originMapId
                            && target.classicWorldInstanceId == originInstanceId;
                boolean lineOfSight = target == this
                        || (originPhase == Phase.WORLD
                            ? ClassicWorldMapCatalog.forMap(originMapId)
                                .attackPosition(originX, originY,
                                    target.positionX, target.positionY,
                                    spell.maximumRange())
                            : BattleSpellCatalog.hasNativeLineOfSight(
                                ArenaMapCatalog.forMap(originMapId),
                                originX, originY,
                                target.positionX, target.positionY));
                boolean targetStillAllowed = target == this
                        || !target.observer && target.playerHp > 0
                            && !target.invisible
                            && !target.timedStatus.absoluteBarrierActive(castNow)
                            && targetRange(originX, originY,
                                target.positionX, target.positionY)
                                <= spell.maximumRange()
                            && lineOfSight;
                if (castNow < readyAt || !contextStillValid
                        || observer || playerHp <= 0 || !targetStillAllowed) {
                    System.out.println("[LiTo] C_USE_SPELL Illusion: Avatar"
                            + " rejected state caster=" + playerName()
                            + " target=" + target.playerName()
                            + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow)
                            + " phase=" + originPhase);
                    return;
                }
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Illusion-Avatar-insufficient-mp=278");
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                refreshed = target.abilityStatus.activateIllusionAvatar(
                        castNow, spell.durationSeconds(),
                        spell.meleeDamage(), spell.rangedDamage(),
                        spell.spellPower(), spell.incomingDamageRate());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.positionX, target.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Illusion-Avatar caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT Illusion-Avatar target=" + target.playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        if (!refreshed) {
            target.sendMagicStatus(castNow, "illusion-avatar-start");
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Illusion-Avatar=" + remainingMp
                        + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Illusion: Avatar caster="
                + playerName() + " target=" + target.playerName()
                + " melee-damage=" + spell.meleeDamage()
                + " ranged-damage=" + spell.rangedDamage()
                + " sp=" + spell.spellPower()
                + " incoming-rate=" + spell.incomingDamageRate()
                + " duration=" + spell.durationSeconds()
                + " refreshed=" + refreshed + " stacked=false"
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " mp-cost=" + mpCost
                + " original-reduction=" + originalReduction
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " persisted=" + spell.persisted() + " client-clock-ms="
                + spell.clientCastClockMillis() + " phase=" + originPhase);
    }

    private void useAbilityBuffSpell(byte[] payload,
                                     BattleSpellCatalog.AbilityBuffSpell spell)
            throws IOException {
        Phase originPhase = phase;
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        int requestSkillId;
        long requestTargetObjectId;
        ClientSession target;
        if (spell.requestShape() == BattleSpellCatalog.RequestShape.SELECTOR_ONLY) {
            Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
            requestSkillId = request.skillId();
            requestTargetObjectId = playerObjectId();
            target = this;
        } else if (spell.requestShape() == BattleSpellCatalog.RequestShape.OBJECT_TARGET) {
            Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
            requestSkillId = request.skillId();
            requestTargetObjectId = request.targetObjectId();
            List<ClientSession> candidates = originPhase == Phase.WORLD
                    ? classicWorldMembers(originMapId)
                    : hub.roomCombatants(originRoomId);
            target = candidates.stream()
                    .filter(candidate -> candidate.playerObjectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
        } else {
            throw new IllegalStateException(
                    "unsupported native ability-buff request shape "
                            + spell.requestShape());
        }
        boolean sameContext = target != null
                && (originPhase == Phase.BATTLE
                    && target.phase == Phase.BATTLE
                    && target.currentRoomId == originRoomId
                    || originPhase == Phase.WORLD
                        && target.phase == Phase.WORLD
                        && target.classicWorldMapId == originMapId
                        && target.classicWorldInstanceId == originInstanceId);
        boolean targetAllowed = target != null
                && sameContext
                && (spell.requestShape() == BattleSpellCatalog.RequestShape.SELECTOR_ONLY
                        || sameNonemptyClan(target)
                            && (originPhase != Phase.WORLD
                                || BattleSpellCatalog.isInNativeScreen(
                                    originX, originY,
                                    target.positionX, target.positionY)));
        if (requestSkillId != spell.skillId() || !targetAllowed
                || !learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL ability buff rejected skill="
                    + requestSkillId + " target=" + requestTargetObjectId
                    + " same-clan=" + (target != null && sameNonemptyClan(target))
                    + " same-context=" + sameContext + " phase=" + originPhase);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        boolean matchingMagicHelmEquipped =
                spell.skillId() == BattleSpellCatalog.PHYSICAL_ENCHANT_DEX
                    && inventory.hasEquippedCatalog(
                            InventoryCatalog.DEXTERITY_MAGIC_HELM)
                || spell.skillId() == BattleSpellCatalog.PHYSICAL_ENCHANT_STR
                    && inventory.hasEquippedCatalog(
                            InventoryCatalog.STRENGTH_MAGIC_HELM);
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction,
                matchingMagicHelmEquipped);

        ClientSession firstLock = playerObjectId() <= target.playerObjectId() ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingMp;
        int replacedSkillId;
        long now = System.nanoTime();
        synchronized (firstLock) {
            synchronized (secondLock) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean contextStillValid = originPhase == Phase.BATTLE
                        ? phase == Phase.BATTLE && currentRoomId == originRoomId
                            && target.phase == Phase.BATTLE
                            && target.currentRoomId == originRoomId
                        : originPhase == Phase.WORLD
                            && phase == Phase.WORLD
                            && classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                            && target.phase == Phase.WORLD
                            && target.classicWorldMapId == originMapId
                            && target.classicWorldInstanceId == originInstanceId;
                if (now < readyAt || !contextStillValid
                        || observer || target.observer
                        || playerHp <= 0 || target.playerHp <= 0) {
                    System.out.println("[LiTo] C_USE_SPELL ability buff rejected state skill="
                            + spell.skillId() + " mp=" + playerMp
                            + " cooldownNanos=" + Math.max(0L, readyAt - now)
                            + " phase=" + originPhase);
                    return;
                }
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE ability-buff-insufficient-mp=278 skill="
                                    + spell.skillId());
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                if (spell.ability() == BattleSpellCatalog.Ability.STRENGTH) {
                    replacedSkillId = target.abilityStatus.activateStrength(
                            spell.skillId(), now, spell.durationSeconds(), spell.modifier());
                } else {
                    replacedSkillId = target.abilityStatus.activateDexterity(
                            spell.skillId(), now, spell.durationSeconds(), spell.modifier());
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        byte[] effect = Protocol.effectObject(target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY, originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.positionX, target.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION ability-buff-cast object=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT ability-buff target=" + target.playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT ability-buff=" + remainingMp + "/" + playerMaxMp);
        if (replacedSkillId != 0) {
            BattleSpellCatalog.AbilityBuffSpell replaced =
                    BattleSpellCatalog.abilityBuffSpell(replacedSkillId);
            if (replaced == null) {
                throw new IllegalStateException(
                        "unknown replaced ability-buff skill " + replacedSkillId);
            }
            target.sendAbilityBuffStop(
                    replaced, now, "replaced-by-" + spell.skillId(), true);
        }
        if (spell.ability() == BattleSpellCatalog.Ability.STRENGTH) {
            target.sendEncrypted(Protocol.mageStrength(spell.durationSeconds(),
                            target.battleStrength(),
                            target.currentWeight240(now), spell.activeType()),
                    "S_MAGE_STRENGTH duration=" + spell.durationSeconds()
                            + " value=" + target.battleStrength()
                            + " weight240=" + target.currentWeight240(now)
                            + " type=" + spell.activeType());
        } else {
            target.sendEncrypted(Protocol.mageDexterity(spell.durationSeconds(),
                            target.battleDexterity(), spell.activeType()),
                    "S_MAGE_DEXTERITY duration=" + spell.durationSeconds()
                            + " value=" + target.battleDexterity()
                            + " type=" + spell.activeType());
        }
        target.sendSchema2AbilityScoresStatus(now,
                "ability-buff-" + spell.skillId());
        if (spell.happenMessage() > 0) {
            target.sendEncrypted(Protocol.messageCode(spell.happenMessage()),
                    "S_MESSAGE_CODE ability-buff-happen=" + spell.happenMessage()
                            + " skill=" + spell.skillId());
        }
        System.out.println("[LiTo] C_USE_SPELL ability buff=" + spell.key()
                + " caster=" + playerName() + " target=" + target.playerName()
                + " duration=" + spell.durationSeconds() + " mp="
                + remainingMp + "/" + playerMaxMp + " mp-cost=" + mpCost
                + " effective-int=" + effectiveIntelligence
                + " original-reduction=" + originalReduction
                + " matching-magic-helm=" + matchingMagicHelmEquipped
                + " phase=" + originPhase);
    }

    private void sendAbilityBuffStop(
            BattleSpellCatalog.AbilityBuffSpell spell, long nowNanos,
            String reason, boolean replacementInProgress) throws IOException {
        if (spell.ability() == BattleSpellCatalog.Ability.STRENGTH) {
            int currentStrength = replacementInProgress
                    ? battleStrengthWithoutAbility() : battleStrength(nowNanos);
            int weight240 = replacementInProgress
                    ? currentWeight240(nowNanos, currentStrength)
                    : currentWeight240(nowNanos);
            sendEncrypted(Protocol.mageStrength(
                            0, currentStrength, weight240, spell.stopType()),
                    "S_MAGE_STRENGTH duration=0 value=" + currentStrength
                            + " weight240=" + weight240
                            + " type=" + spell.stopType()
                            + " skill=" + spell.skillId() + " reason=" + reason);
        } else {
            int currentDexterity = replacementInProgress
                    ? battleDexterityWithoutAbility() : battleDexterity(nowNanos);
            sendEncrypted(Protocol.mageDexterity(
                            0, currentDexterity, spell.stopType()),
                    "S_MAGE_DEXTERITY duration=0 value=" + currentDexterity
                            + " type=" + spell.stopType()
                            + " skill=" + spell.skillId() + " reason=" + reason);
        }
        sendSchema2AbilityScoresStatus(nowNanos,
                "ability-buff-stop-" + spell.skillId() + "-" + reason);
        if (spell.stopMessage() > 0) {
            sendEncrypted(Protocol.messageCode(spell.stopMessage()),
                    "S_MESSAGE_CODE ability-buff-stop=" + spell.stopMessage()
                            + " skill=" + spell.skillId() + " reason=" + reason);
        }
    }

    private void useWeaponBuffSpell(byte[] payload,
                                    BattleSpellCatalog.WeaponBuffSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        long originRoomId = currentRoomId;
        int originMapId = classicWorld ? classicWorldMapId : 0;
        int originInstanceId = classicWorld ? classicWorldInstanceId : -1;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> phaseMembers = classicWorld
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(originRoomId);
        ClientSession playerTarget = phaseMembers.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .filter(candidate -> !classicWorld
                        || candidate.phase == Phase.WORLD
                            && candidate.classicWorldMapId == originMapId
                            && candidate.classicWorldInstanceId == originInstanceId)
                .findFirst().orElse(null);
        ClientSession companionOwner = null;
        BattleCompanion controlledCompanion = null;
        BattleCompanion.Snapshot companionTarget = null;
        if (classicWorld) {
            for (ClientSession owner : phaseMembers) {
                if (owner.phase != Phase.WORLD
                        || owner.classicWorldMapId != originMapId
                        || owner.classicWorldInstanceId != originInstanceId) continue;
                BattleCompanion.Snapshot match = owner.classicWorldCompanionSnapshots()
                        .stream()
                        .filter(candidate -> candidate.objectId()
                                == request.targetObjectId())
                        .findFirst().orElse(null);
                if (match == null) continue;
                BattleCompanion controlled = owner.ownedCompanion(match.objectId());
                if (controlled == null) continue;
                companionOwner = owner;
                controlledCompanion = controlled;
                companionTarget = match;
                break;
            }
        }
        ClassicWorldMonsterPopulation.Snapshot worldMonster = classicWorld
                ? hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId()) : null;
        BattleQuestEncounter.Snapshot questTarget = classicWorld ? null
                : hub.visibleQuestMonsters(originRoomId, this).stream()
                .filter(candidate -> candidate.objectId() == request.targetObjectId())
                .findFirst().orElse(null);
        BattleTimeAttackEncounter.Snapshot timeTarget = classicWorld ? null
                : hub.visibleTimeAttackActors(originRoomId, this).stream()
                .filter(candidate -> candidate.objectId() == request.targetObjectId())
                .findFirst().orElse(null);

        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionTarget == null ? 0 : 1)
                + (worldMonster == null ? 0 : 1)
                + (questTarget == null ? 0 : 1)
                + (timeTarget == null ? 0 : 1);
        int targetX = playerTarget != null ? playerTarget.positionX
                : companionTarget != null ? companionTarget.x()
                : worldMonster != null ? worldMonster.x()
                : questTarget != null ? questTarget.x()
                : timeTarget != null ? timeTarget.x() : Integer.MIN_VALUE;
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionTarget != null ? companionTarget.y()
                : worldMonster != null ? worldMonster.y()
                : questTarget != null ? questTarget.y()
                : timeTarget != null ? timeTarget.y() : Integer.MIN_VALUE;
        boolean livingTarget = playerTarget != null
                ? playerTarget.phase == originPhase && !playerTarget.observer
                    && playerTarget.playerHp > 0
                    && (!playerTarget.invisible || playerTarget == this)
                    && (!classicWorld
                        || playerTarget.classicWorldMapId == originMapId
                            && playerTarget.classicWorldInstanceId == originInstanceId)
                : companionTarget != null
                    ? companionOwner.phase == Phase.WORLD
                        && companionOwner.classicWorldMapId == originMapId
                        && companionOwner.classicWorldInstanceId == originInstanceId
                        && companionTarget.active() && companionTarget.hp() > 0
                : worldMonster != null
                    ? worldMonster.mapId() == originMapId
                        && worldMonster.present() && worldMonster.alive()
                : questTarget != null ? questTarget.alive()
                : timeTarget != null && timeTarget.alive();
        if (request.skillId() != spell.skillId() || targetCount != 1 || !livingTarget
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL weapon buff rejected selector/target/range"
                    + " player=" + playerName() + " skill=" + request.skillId()
                    + " target=" + request.targetObjectId()
                    + " candidates=" + targetCount + " phase=" + originPhase);
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "weapon-buff")) return;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        long now = System.nanoTime();
        int remainingMp;
        boolean playerWeaponPresent = false;
        int replacedSkill = 0;
        int replacedItemWeaponSkill = 0;
        String weaponLogName = "";

        if (playerTarget != null) {
            ClientSession firstLock = playerObjectId() <= playerTarget.playerObjectId()
                    ? this : playerTarget;
            ClientSession secondLock = firstLock == this ? playerTarget : this;
            synchronized (firstLock) {
                synchronized (secondLock) {
                    long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                    if (now < readyAt || playerMp < mpCost
                            || phase != originPhase || observer || playerHp <= 0
                            || positionX != originX || positionY != originY
                            || playerTarget.phase != originPhase
                            || playerTarget.observer || playerTarget.playerHp <= 0) {
                        System.out.println("[LiTo] C_USE_SPELL weapon buff rejected state skill="
                                + spell.skillId() + " mp=" + playerMp
                                + " cost=" + mpCost + " cooldownNanos="
                                + Math.max(0L, readyAt - now));
                        return;
                    }
                    if (classicWorld
                            && (classicWorldMapId != originMapId
                                || classicWorldInstanceId != originInstanceId
                                || playerTarget.classicWorldMapId != originMapId
                                || playerTarget.classicWorldInstanceId
                                    != originInstanceId
                                || playerTarget.positionX != targetX
                                || playerTarget.positionY != targetY
                                || playerTarget.invisible && playerTarget != this
                                || !BattleSpellCatalog.isInNativeScreen(
                                        positionX, positionY,
                                        playerTarget.positionX,
                                        playerTarget.positionY))) {
                        System.out.println("[LiTo] C_USE_SPELL weapon buff rejected "
                                + "WORLD revalidation skill=" + spell.skillId());
                        return;
                    }
                    SourceWeaponPhysicalStats targetWeapon =
                            playerTarget.activePhysicalWeapon();
                    playerWeaponPresent = targetWeapon.present();
                    if (playerWeaponPresent) {
                        weaponLogName = playerTarget.activeWeaponLogName(targetWeapon);
                        RuntimeInventory.Item equippedWeapon =
                                playerTarget.inventory.equippedWeaponItem();
                        if (equippedWeapon != null) {
                            replacedItemWeaponSkill =
                                    playerTarget.itemWeaponEnchantStatus.remove(
                                            equippedWeapon.objectId());
                        }
                        replacedSkill = playerTarget.weaponBuffStatus.activate(
                                now, spell.durationSeconds(), spell.skillId(),
                                spell.meleeHit(), spell.meleeDamage(),
                                spell.rangedHit(), spell.rangedDamage());
                    }
                    playerMp -= mpCost;
                    remainingMp = playerMp;
                    spellReadyNanos.put(spell.skillId(), now
                            + spell.reuseDelayMillis() * 1_000_000L);
                }
            }
        } else if (companionTarget != null) {
            synchronized (this) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                BattleCompanion.Snapshot locked = controlledCompanion.snapshot();
                if (now < readyAt || playerMp < mpCost
                        || phase != Phase.WORLD || observer || playerHp <= 0
                        || classicWorldMapId != originMapId
                        || classicWorldInstanceId != originInstanceId
                        || positionX != originX || positionY != originY
                        || companionOwner.phase != Phase.WORLD
                        || companionOwner.classicWorldMapId != originMapId
                        || companionOwner.classicWorldInstanceId != originInstanceId
                        || !locked.active() || locked.hp() <= 0
                        || locked.x() != targetX || locked.y() != targetY
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY, locked.x(), locked.y())) {
                    System.out.println("[LiTo] C_USE_SPELL weapon buff rejected "
                            + "WORLD companion state skill=" + spell.skillId());
                    return;
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        } else if (worldMonster != null) {
            synchronized (this) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                ClassicWorldMonsterPopulation.Snapshot locked =
                        hub.classicWorldMonster(originMapId, originInstanceId,
                                worldMonster.objectId());
                if (now < readyAt || playerMp < mpCost
                        || phase != Phase.WORLD || observer || playerHp <= 0
                        || classicWorldMapId != originMapId
                        || classicWorldInstanceId != originInstanceId
                        || positionX != originX || positionY != originY
                        || locked == null || !locked.present() || !locked.alive()
                        || locked.x() != targetX || locked.y() != targetY
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY, locked.x(), locked.y())) {
                    System.out.println("[LiTo] C_USE_SPELL weapon buff rejected "
                            + "WORLD monster state skill=" + spell.skillId());
                    return;
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        } else {
            synchronized (this) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                if (now < readyAt || playerMp < mpCost
                        || phase != Phase.BATTLE || observer || playerHp <= 0) {
                    System.out.println("[LiTo] C_USE_SPELL weapon buff rejected state skill="
                            + spell.skillId() + " mp=" + playerMp
                            + " cost=" + mpCost + " cooldownNanos="
                            + Math.max(0L, readyAt - now));
                    return;
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(originMapId)
                : questTarget != null
                ? hub.battleRecipients(currentRoomId, questTarget.force())
                : timeTarget != null
                    ? hub.roomMembers(currentRoomId)
                    : playerTarget != null
                        && hub.roomRules(currentRoomId).mode()
                                == BattleRules.Mode.QUEST_BATTLE
                            ? hub.battleRecipients(currentRoomId,
                                    hub.forceOf(currentRoomId, playerTarget))
                            : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        for (ClientSession recipient : recipients) {
            if (classicWorld
                    && (recipient.phase != Phase.WORLD
                        || recipient.classicWorldMapId != originMapId
                        || recipient.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                recipient.positionX, recipient.positionY,
                                originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                recipient.positionX, recipient.positionY,
                                targetX, targetY))) continue;
            if (invisible && recipient != this) continue;
            recipient.sendEncrypted(action,
                    "S_ACTION weapon-buff caster=" + playerObjectId()
                            + " action=" + spell.actionId()
                            + " skill=" + spell.skillId());
        }

        // Retained L1SkillUse sends this target-local message from runSkill.
        // A legal no-weapon cast still consumes MP and continues to cast gfx.
        if (playerTarget != null) {
            if (playerWeaponPresent) {
                playerTarget.sendEncrypted(Protocol.messageCode(
                                spell.successMessage(), weaponLogName, "$245", "$247"),
                        "S_MESSAGE_CODE weapon-buff-success=" + spell.successMessage()
                                + " weapon=" + weaponLogName);
            } else {
                playerTarget.sendEncrypted(Protocol.messageCode(spell.missingWeaponMessage()),
                        "S_MESSAGE_CODE weapon-buff-missing="
                                + spell.missingWeaponMessage());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT weapon-buff=" + remainingMp + "/" + playerMaxMp);

        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        for (ClientSession recipient : recipients) {
            if (classicWorld
                    && (recipient.phase != Phase.WORLD
                        || recipient.classicWorldMapId != originMapId
                        || recipient.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                recipient.positionX, recipient.positionY,
                                targetX, targetY))) continue;
            recipient.sendEncrypted(effect,
                    "S_EFFECT weapon-buff target=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx()
                            + " skill=" + spell.skillId());
        }
        System.out.println("[LiTo] C_USE_SPELL weapon buff=" + spell.key()
                + " caster=" + playerName() + " target=" + request.targetObjectId()
                + " player-target=" + (playerTarget != null)
                + " companion-target=" + (companionTarget != null)
                + " world-monster-target=" + (worldMonster != null)
                + " weapon=" + playerWeaponPresent
                + " replaced-skill=" + replacedSkill
                + " replaced-item-weapon-skill=" + replacedItemWeaponSkill
                + " melee-hit=" + (playerWeaponPresent ? spell.meleeHit() : 0)
                + " melee-damage=" + (playerWeaponPresent ? spell.meleeDamage() : 0)
                + " ranged-hit=" + (playerWeaponPresent ? spell.rangedHit() : 0)
                + " ranged-damage=" + (playerWeaponPresent ? spell.rangedDamage() : 0)
                + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " map=" + (classicWorld ? originMapId : 0)
                + " instance=" + (classicWorld ? originInstanceId : -1)
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

    private void useHasteSpell(byte[] payload, BattleSpellCatalog.HasteSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        int originMapId = classicWorld ? classicWorldMapId : 0;
        int originInstanceId = classicWorld ? classicWorldInstanceId : -1;
        List<ClientSession> phaseMembers = classicWorld
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(currentRoomId);
        ClientSession playerTarget = phaseMembers.stream()
                .filter(candidate -> candidate.playerObjectId()
                        == request.targetObjectId())
                .filter(candidate -> !classicWorld || sameClassicWorldMap(candidate))
                .findFirst().orElse(null);
        ClientSession companionOwner = null;
        BattleCompanion controlledCompanion = null;
        BattleCompanion.Snapshot companionTarget = null;
        for (ClientSession owner : phaseMembers) {
            List<BattleCompanion.Snapshot> snapshots = classicWorld
                    ? owner.classicWorldCompanionSnapshots()
                    : owner.controlledCompanionSnapshots();
            BattleCompanion.Snapshot match = snapshots.stream()
                    .filter(candidate -> candidate.objectId()
                            == request.targetObjectId())
                    .findFirst().orElse(null);
            if (match == null) continue;
            BattleCompanion controlled = owner.ownedCompanion(match.objectId());
            if (controlled == null) continue;
            companionOwner = owner;
            controlledCompanion = controlled;
            companionTarget = match;
            break;
        }
        ClassicWorldMonsterPopulation.Snapshot worldMonster = classicWorld
                ? hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId()) : null;
        BattleQuestEncounter.Snapshot questTarget = classicWorld ? null
                : hub.visibleQuestMonsters(currentRoomId, this).stream()
                        .filter(candidate -> candidate.objectId()
                                == request.targetObjectId())
                        .findFirst().orElse(null);
        BattleTimeAttackEncounter.Snapshot timeTarget = classicWorld ? null
                : hub.visibleTimeAttackActors(currentRoomId, this).stream()
                        .filter(candidate -> candidate.objectId()
                                == request.targetObjectId())
                        .findFirst().orElse(null);

        ArenaMapCatalog.Point botTarget = !classicWorld && request.targetObjectId() == 2
                && hub.botHp(currentRoomId) > 0 ? hub.botPosition(currentRoomId) : null;
        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionTarget == null ? 0 : 1)
                + (worldMonster == null ? 0 : 1)
                + (questTarget == null ? 0 : 1)
                + (timeTarget == null ? 0 : 1) + (botTarget == null ? 0 : 1);
        int targetX = playerTarget != null ? playerTarget.positionX
                : companionTarget != null ? companionTarget.x()
                : worldMonster != null ? worldMonster.x()
                : questTarget != null ? questTarget.x()
                : timeTarget != null ? timeTarget.x() : botTarget != null ? botTarget.x() : Integer.MIN_VALUE;
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionTarget != null ? companionTarget.y()
                : worldMonster != null ? worldMonster.y()
                : questTarget != null ? questTarget.y()
                : timeTarget != null ? timeTarget.y() : botTarget != null ? botTarget.y() : Integer.MIN_VALUE;
        boolean livingTarget = playerTarget != null
                ? playerTarget.phase == originPhase && playerTarget.playerHp > 0
                    && (!playerTarget.invisible || playerTarget == this)
                    && (!classicWorld || sameClassicWorldMap(playerTarget))
                : companionTarget != null
                    ? companionOwner.phase == originPhase
                        && companionTarget.active() && companionTarget.hp() > 0
                        && (!classicWorld || sameClassicWorldMap(companionOwner))
                : worldMonster != null
                    ? worldMonster.mapId() == originMapId
                        && worldMonster.present() && worldMonster.alive()
                : questTarget != null ? questTarget.alive()
                : timeTarget != null ? timeTarget.alive() : botTarget != null;
        if (request.skillId() != spell.skillId() || targetCount != 1 || !livingTarget
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, targetX, targetY)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Haste rejected selector/target/range"
                    + " player=" + playerName() + " skill=" + request.skillId()
                    + " target=" + request.targetObjectId()
                    + " candidates=" + targetCount);
            sendEncrypted(Protocol.messageCode(spell.failureMessage()), "S_MESSAGE_CODE Haste invalid target");
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Haste")) return;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction,
                equipment.hasteCostHalvingHelmEquipped());
        long now = System.nanoTime();
        int remainingMp;
        BattleTimedStatus.SpeedChange playerSpeedChange = null;
        boolean appliedNpc = false;

        if (playerTarget != null) {
            ClientSession firstLock = playerObjectId() <= playerTarget.playerObjectId()
                    ? this : playerTarget;
            ClientSession secondLock = firstLock == this ? playerTarget : this;
            synchronized (firstLock) {
                synchronized (secondLock) {
                    long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                    if (now < readyAt || playerMp < mpCost
                            || phase != originPhase || observer || playerHp <= 0
                            || playerTarget.phase != originPhase
                            || playerTarget.playerHp <= 0
                            || (playerTarget.invisible && playerTarget != this)
                            || classicWorld && !sameClassicWorldMap(playerTarget)
                            || !BattleSpellCatalog.isInNativeScreen(
                                    positionX, positionY,
                                    playerTarget.positionX, playerTarget.positionY)) {
                        System.out.println("[LiTo] C_USE_SPELL Haste rejected state skill="
                                + spell.skillId() + " mp=" + playerMp
                                + " cost=" + mpCost + " cooldownNanos="
                                + Math.max(0L, readyAt - now));
                        return;
                    }
                    cancelMeditation("spell-" + spell.skillId());
                    playerTarget.timedStatus.clearDrunken();
                    playerSpeedChange = playerTarget.timedStatus.activateHaste(
                            now, spell.durationSeconds(), spell.skillId());
                    playerMp -= mpCost;
                    remainingMp = playerMp;
                    commitSpellReady(spell.skillId(), now
                            + spell.reuseDelayMillis() * 1_000_000L);
                }
            }
        } else if (companionTarget != null) {
            synchronized (this) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                if (now < readyAt || playerMp < mpCost
                        || phase != originPhase || observer || playerHp <= 0
                        || companionOwner.phase != originPhase
                        || classicWorld && !sameClassicWorldMap(companionOwner)) {
                    System.out.println("[LiTo] C_USE_SPELL Haste rejected state skill="
                            + spell.skillId() + " mp=" + playerMp
                            + " cost=" + mpCost + " cooldownNanos="
                            + Math.max(0L, readyAt - now));
                    return;
                }
                BattleCompanion.Snapshot locked = controlledCompanion.snapshot();
                if (!locked.active() || locked.hp() <= 0
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY, locked.x(), locked.y())
                        || !controlledCompanion.activateHaste(
                                now, spell.durationSeconds(), spell.skillId())) return;
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            appliedNpc = true;
        } else if (worldMonster != null) {
            synchronized (this) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                ClassicWorldMonsterPopulation.Snapshot locked =
                        hub.classicWorldMonster(originMapId, originInstanceId,
                                worldMonster.objectId());
                if (now < readyAt || playerMp < mpCost
                        || phase != Phase.WORLD || observer || playerHp <= 0
                        || classicWorldMapId != originMapId
                        || classicWorldInstanceId != originInstanceId
                        || locked == null || !locked.present() || !locked.alive()
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY, locked.x(), locked.y())
                        || !hub.hasteClassicWorldMonster(
                                originMapId, originInstanceId, locked.objectId(),
                                now, spell.durationSeconds())) return;
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            appliedNpc = true;
        } else if (botTarget != null) {
            synchronized (this) {
                if (now < spellReadyNanos.getOrDefault(spell.skillId(), 0L)
                        || playerMp < mpCost || phase != Phase.BATTLE || observer
                        || playerHp <= 0 || !hub.hasteArenaBot(currentRoomId,
                            positionX, positionY, now, spell.durationSeconds())) {
                    sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                            "S_MESSAGE_CODE Haste unavailable");
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now + spell.reuseDelayMillis() * 1_000_000L);
                appliedNpc = true;
            }
        } else {
            synchronized (this) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                if (now < readyAt || playerMp < mpCost
                        || phase != Phase.BATTLE || observer || playerHp <= 0) {
                    System.out.println("[LiTo] C_USE_SPELL Haste rejected state skill="
                            + spell.skillId() + " mp=" + playerMp
                            + " cost=" + mpCost + " cooldownNanos="
                            + Math.max(0L, readyAt - now));
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            appliedNpc = questTarget != null
                    ? hub.hasteQuestMonster(currentRoomId, this,
                            questTarget.objectId(), now, spell.durationSeconds())
                    : hub.hasteTimeAttackActor(currentRoomId, this,
                            timeTarget.objectId(), now, spell.durationSeconds());
            if (!appliedNpc) {
                cancelAbsoluteBarrier("spell-" + spell.skillId());
                sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                        "S_MESSAGE_CODE Haste-stale=" + spell.failureMessage());
                sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                        "S_MANA_POINT Haste-stale=" + remainingMp
                                + "/" + playerMaxMp);
                System.out.println("[LiTo] C_USE_SPELL Haste target became stale target="
                        + request.targetObjectId());
                return;
            }
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());

        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(originMapId)
                : questTarget != null
                ? hub.battleRecipients(currentRoomId, questTarget.force())
                : playerTarget != null
                        && hub.roomRules(currentRoomId).mode()
                                == BattleRules.Mode.QUEST_BATTLE
                    ? hub.battleRecipients(currentRoomId,
                            hub.forceOf(currentRoomId, playerTarget))
                    : hub.roomMembers(currentRoomId);
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        int resultingSpeed = playerTarget != null
                ? playerSpeedChange.type()
                : companionTarget != null
                    ? controlledCompanion.snapshot().moveSpeed()
                : worldMonster != null
                    ? (hub.classicWorldMonsterHasteActive(
                            originMapId, originInstanceId,
                            worldMonster.objectId(), now)
                        ? BattleTimedStatus.HASTE : BattleTimedStatus.NORMAL)
                : botTarget != null ? BattleTimedStatus.HASTE
                : questTarget != null
                    ? (hub.questMonsterHasteActive(currentRoomId,
                            questTarget.objectId(), now)
                        ? BattleTimedStatus.HASTE : BattleTimedStatus.NORMAL)
                    : (hub.timeAttackActorHasteActive(currentRoomId,
                            timeTarget.objectId(), now)
                        ? BattleTimedStatus.HASTE : BattleTimedStatus.NORMAL);
        for (ClientSession recipient : recipients) {
            boolean seesCaster = !classicWorld
                    || BattleSpellCatalog.isInNativeScreen(
                            recipient.positionX, recipient.positionY,
                            positionX, positionY);
            boolean seesTarget = !classicWorld
                    || recipient.phase == Phase.WORLD
                        && recipient.classicWorldMapId == originMapId
                        && recipient.classicWorldInstanceId == originInstanceId
                        && BattleSpellCatalog.isInNativeScreen(
                                recipient.positionX, recipient.positionY,
                                targetX, targetY);
            if (seesCaster && (!invisible || recipient == this)) {
                recipient.sendEncrypted(action,
                        "S_ACTION Haste caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            if (seesTarget) {
                recipient.sendEncrypted(effect,
                        "S_EFFECT Haste target=" + request.targetObjectId()
                                + " gfx=" + spell.effectGfx());
                int duration = resultingSpeed == BattleTimedStatus.HASTE
                        && recipient == playerTarget ? spell.durationSeconds() : 0;
                recipient.sendEncrypted(Protocol.speed(
                                request.targetObjectId(),
                                Protocol.SpeedMode.fromWire(resultingSpeed), duration),
                        "S_SPEED Haste target=" + request.targetObjectId()
                                + " type=" + resultingSpeed
                                + " duration=" + duration);
            }
        }
        if (playerTarget != null && spell.happenMessage() > 0) {
            playerTarget.sendEncrypted(Protocol.messageCode(spell.happenMessage()),
                    "S_MESSAGE_CODE Haste-applied=" + spell.happenMessage()
                            + " skill=" + spell.skillId());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Haste=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Haste caster=" + playerName()
                + " phase=" + originPhase
                + " target=" + request.targetObjectId()
                + " player-target=" + (playerTarget != null)
                + " companion-target=" + (companionTarget != null)
                + " world-monster-target=" + (worldMonster != null)
                + " npc-applied=" + appliedNpc
                + " resulting-speed=" + resultingSpeed
                + " duration=" + spell.durationSeconds()
                + " mp-cost=" + mpCost
                + " haste-helm=" + equipment.hasteCostHalvingHelmEquipped()
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useSelfHasteSpell(
            byte[] payload, BattleSpellCatalog.SelfHasteSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (request.skillId() != spell.skillId()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL self Haste rejected selector/action"
                    + " player=" + playerName() + " skill=" + request.skillId());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Greater-Haste")) return;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction,
                equipment.greaterHasteCostHalvingHelmEquipped());
        int remainingMp;
        long now = System.nanoTime();
        BattleTimedStatus.SpeedChange speedChange;
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (now < readyAt || playerMp < mpCost
                    || phase != originPhase
                    || (originPhase != Phase.BATTLE && originPhase != Phase.WORLD)
                    || observer || playerHp <= 0) {
                System.out.println("[LiTo] C_USE_SPELL self Haste rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            playerMp -= mpCost;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
            speedChange = timedStatus.activateHaste(
                    now, spell.durationSeconds(), spell.skillId());
            // Retained GREATER_HASTE clears the drink flag only when it
            // actually enters Haste.  Its Slow branch merely removes the
            // opposing lease and remains at normal speed.
            if (speedChange.type() == BattleTimedStatus.HASTE) {
                timedStatus.clearDrunken();
            }
        }

        // Commit MP/reuse and the speed transition before breaking states
        // interrupted by this accepted normal cast.  The common commit helper
        // reveals invisibility too early for this retained ordering.
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(classicWorldMapId)
                : hub.roomMembers(currentRoomId);
        for (ClientSession member : recipients) {
            if (classicWorld && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION self-Haste caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT self-Haste target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        if (speedChange.type() == BattleTimedStatus.HASTE) {
            sendEncrypted(Protocol.messageCode(spell.happenMessage()),
                    "S_MESSAGE_CODE self-Haste-applied=" + spell.happenMessage());
        }
        broadcastMovementSpeed(speedChange.type(),
                speedChange.durationSeconds(), spell.key());
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT self-Haste=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL self Haste=" + spell.key()
                + " phase=" + originPhase
                + " caster=" + playerName() + " selector=" + request.row()
                + "/" + request.column() + " action=" + spell.actionId()
                + " gfx=" + spell.effectGfx() + " duration="
                + spell.durationSeconds() + " resulting-speed="
                + speedChange.type() + " effective-int="
                + effectiveIntelligence + " mp-cost=" + mpCost
                + " greater-haste-helm="
                + equipment.greaterHasteCostHalvingHelmEquipped()
                + " mp=" + remainingMp + "/" + playerMaxMp);
    }

    private void useCombatBuffSpell(
            byte[] payload, BattleSpellCatalog.CombatBuffSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        Phase originPhase = phase;
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> phaseMembers = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(originRoomId);
        ClientSession target = phaseMembers.stream()
                .filter(candidate -> candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        int targetX = target == null ? Integer.MIN_VALUE : target.positionX;
        int targetY = target == null ? Integer.MIN_VALUE : target.positionY;
        boolean sameContext = target != null
                && (originPhase == Phase.BATTLE
                    && target.phase == Phase.BATTLE
                    && target.currentRoomId == originRoomId
                    || originPhase == Phase.WORLD
                        && target.phase == Phase.WORLD
                        && target.classicWorldMapId == originMapId
                        && target.classicWorldInstanceId == originInstanceId);
        boolean qualifiedTarget = target != null
                && (sameNonemptyClan(target) || sameClassicParty(target));
        if (request.skillId() != spell.skillId() || !qualifiedTarget
                || !sameContext || target.observer || target.playerHp <= 0
                || (target.invisible && target != this)
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL combat buff rejected skill="
                    + request.skillId() + " target=" + request.targetObjectId()
                    + " clan-or-party=" + qualifiedTarget
                    + " same-context=" + sameContext
                    + " phase=" + originPhase);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);
        ClientSession firstLock = playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingMp;
        long now = System.nanoTime();
        synchronized (firstLock) {
            synchronized (secondLock) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean contextStillValid = originPhase == Phase.BATTLE
                        ? phase == Phase.BATTLE && currentRoomId == originRoomId
                            && target.phase == Phase.BATTLE
                            && target.currentRoomId == originRoomId
                        : originPhase == Phase.WORLD
                            && phase == Phase.WORLD
                            && classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                            && target.phase == Phase.WORLD
                            && target.classicWorldMapId == originMapId
                            && target.classicWorldInstanceId == originInstanceId;
                if (now < readyAt || playerMp < mpCost
                        || !contextStillValid || observer || playerHp <= 0
                        || target.observer || target.playerHp <= 0
                        || positionX != originX || positionY != originY
                        || target.positionX != targetX || target.positionY != targetY
                        || target.invisible && target != this
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                target.positionX, target.positionY)) {
                    System.out.println("[LiTo] C_USE_SPELL combat buff rejected state skill="
                            + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                            + " cooldownNanos=" + Math.max(0L, readyAt - now)
                            + " phase=" + originPhase);
                    return;
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
                target.abilityStatus.activateBerserk(now, spell.durationSeconds(),
                        spell.armorClass(), spell.meleeHit(), spell.meleeDamage());
            }
        }

        // The accepted cast commits its cost, reuse clock and target lease
        // before breaking states interrupted on the caster.  Avoid the common
        // commit helper because it reveals invisibility before Meditation and
        // Absolute Barrier have been ended.
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                targetX, targetY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION combat-buff caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT combat-buff target=" + target.playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        target.sendNativeBattleStatus(now, spell.key() + "-start");
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT combat-buff=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL combat buff=" + spell.key()
                + " caster=" + playerName() + " target=" + target.playerName()
                + " duration=" + spell.durationSeconds()
                + " ac=" + spell.armorClass() + " melee-hit=" + spell.meleeHit()
                + " melee-damage=" + spell.meleeDamage()
                + " effective-int=" + effectiveIntelligence + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " map=" + (originPhase == Phase.WORLD ? originMapId : 0)
                + " instance=" + (originPhase == Phase.WORLD
                    ? originInstanceId : -1)
                + " icon=omitted-selected-LiTo-FA-is-tournament-clan");
    }

