    private void useExoticVitalizeSpell(byte[] byArray, BattleSpellCatalog.ExoticVitalizeSpell exoticVitalizeSpell) throws IOException {
        NativeSelfCastAction.exoticVitalize(this, byArray, exoticVitalizeSpell);
    }

    private void useAdditionalFireSpell(byte[] byArray, BattleSpellCatalog.AdditionalFireSpell additionalFireSpell) throws IOException {
        NativeSelfCastAction.additionalFire(this, byArray, additionalFireSpell);
    }

    private void useWeightSpell(byte[] byArray, BattleSpellCatalog.WeightSpell weightSpell) throws IOException {
        NativeSelfCastAction.weight(this, byArray, weightSpell);
    }

    /**
     * Skill206 has PC/range3 semantics in the selected database, but its exact
     * LiTo producer is selector-only. Reuse the last admitted combat target,
     * otherwise the sole eligible external PC, and finally the caster. More
     * than one unresolved external candidate fails closed.
     */
    private ClientSession resolveSelectorOnlyConcentrationTarget(
            BattleSpellCatalog.RegenSpell spell, Phase originPhase,
            long originRoomId, int originMapId, int originInstanceId,
            int originX, int originY, long nowNanos) {
        if (spell.targeting() == BattleSpellCatalog.Targeting.SELF_SELECTOR) {
            return this;
        }
        List<ClientSession> candidates = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomCombatants(originRoomId);
        ArrayList<ClientSession> eligibleExternal = new ArrayList<>();
        ClientSession lastExplicit = null;
        ClassicWorldMapCatalog.ClassicMap map = originPhase == Phase.WORLD
                ? ClassicWorldMapCatalog.forMap(originMapId) : null;
        for (ClientSession candidate : candidates) {
            if (candidate == null || candidate == this || candidate.observer
                    || candidate.playerHp <= 0 || candidate.invisible
                    || candidate.timedStatus.absoluteBarrierActive(nowNanos)) {
                continue;
            }
            boolean sameContext = originPhase == Phase.BATTLE
                    ? candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                    : candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId;
            if (!sameContext || targetRange(originX, originY,
                    candidate.positionX, candidate.positionY)
                    > spell.maximumRange()) continue;
            if (map != null && !map.attackPosition(
                    originX, originY, candidate.positionX, candidate.positionY,
                    spell.maximumRange())) continue;
            eligibleExternal.add(candidate);
            if (candidate.playerObjectId() == lastCombatTargetObjectId) {
                lastExplicit = candidate;
            }
        }
        if (lastExplicit != null) return lastExplicit;
        if (eligibleExternal.size() == 1) return eligibleExternal.get(0);
        if (eligibleExternal.isEmpty()) return this;
        System.out.println("[LiTo] C_USE_SPELL Concentration rejected"
                + " ambiguous selector-only PC target player=" + playerName()
                + " last-explicit=" + lastCombatTargetObjectId
                + " eligible-external=" + eligibleExternal.size()
                + " phase=" + originPhase);
        return null;
    }

    private void useRegenSpell(byte[] payload, BattleSpellCatalog.RegenSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL regen buff rejected learned/action"
                    + " skill=" + spell.skillId() + " caster=" + playerName());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long targetNow = System.nanoTime();
        ClientSession target = resolveSelectorOnlyConcentrationTarget(
                spell, originPhase, originRoomId, originMapId,
                originInstanceId, originX, originY, targetNow);
        if (target == null) return;

        ClientSession firstLock = playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingHp;
        int remainingMp;
        int rejectionMessage = 0;
        long castNow = System.nanoTime();
        synchronized (firstLock) {
            synchronized (secondLock) {
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean contextStillValid = originPhase == Phase.BATTLE
                        ? phase == Phase.BATTLE && currentRoomId == originRoomId
                            && target.phase == Phase.BATTLE
                            && target.currentRoomId == originRoomId
                        : phase == Phase.WORLD
                            && classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                            && target.phase == Phase.WORLD
                            && target.classicWorldMapId == originMapId
                            && target.classicWorldInstanceId == originInstanceId;
                boolean targetStillAllowed = target == this
                        || !target.observer && target.playerHp > 0
                            && !target.invisible
                            && !target.timedStatus.absoluteBarrierActive(castNow)
                            && targetRange(originX, originY,
                                target.positionX, target.positionY)
                                <= spell.maximumRange()
                            && (originPhase != Phase.WORLD
                                || ClassicWorldMapCatalog.forMap(originMapId)
                                    .attackPosition(originX, originY,
                                        target.positionX, target.positionY,
                                        spell.maximumRange()));
                if (castNow < readyAt || !contextStillValid || observer
                        || playerHp <= 0 || !targetStillAllowed) {
                    System.out.println("[LiTo] C_USE_SPELL regen buff rejected state skill="
                            + spell.skillId() + " hp=" + playerHp + " mp=" + playerMp
                            + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                            + " phase=" + originPhase);
                    return;
                }
                if (playerHp < spell.hpCost() + 1) {
                    rejectionMessage = 279;
                } else if (playerMp < mpCost) {
                    rejectionMessage = 278;
                }
                if (rejectionMessage == 0) {
                    cancelMeditation("spell-" + spell.skillId());
                    if (spell.effect() == BattleSpellCatalog.RegenEffect.MEDITATION) {
                        target.timedStatus.activateMeditation(
                                castNow, spell.durationSeconds());
                    } else {
                        target.timedStatus.activateConcentration(
                                castNow, spell.durationSeconds());
                    }
                    playerHp -= spell.hpCost();
                    playerMp -= mpCost;
                    commitSpellReady(spell.skillId(), castNow
                            + spell.reuseDelayMillis() * 1_000_000L);
                }
                remainingHp = playerHp;
                remainingMp = playerMp;
            }
        }
        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE regen-spell-insufficient=" + rejectionMessage
                            + " skill=" + spell.skillId());
            System.out.println("[LiTo] C_USE_SPELL regen buff rejected resource skill="
                    + spell.skillId() + " message=" + rejectionMessage
                    + " hp=" + remainingHp + " mp=" + remainingMp);
            return;
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.positionX, target.positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION regen-spell-cast object=" + playerObjectId()
                            + " action=" + spell.actionId()
                            + " skill=" + spell.skillId());
            member.sendEncrypted(effect,
                    "S_EFFECT regen-spell target=" + target.playerObjectId()
                            + " gfx=" + spell.effectGfx()
                            + " skill=" + spell.skillId());
        }
        if (spell.hpCost() != 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT regen-spell=" + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("regen-spell-hp-cost");
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT regen-spell=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL regen buff=" + spell.key()
                + " caster=" + playerName() + " target=" + target.playerName()
                + " duration=" + spell.durationSeconds() + " mpr=" + spell.mprBonus()
                + " client-clock-ms=" + spell.clientCastClockMillis()
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase);
    }

    private boolean sameNonemptyClan(ClientSession target) {
        return hub.sameClan(sourceCharacterIdentity(), target.sourceCharacterIdentity());
    }

    private boolean sameClassicParty(ClientSession target) {
        GameHub.ClassicPartyData party = hub.classicPartyData(sourceCharacterIdentity());
        return party.inParty() && party.memberIdentities().stream()
                .anyMatch(name -> name.equalsIgnoreCase(target.sourceCharacterIdentity()));
    }

    /**
     * Builds the retained L1Character-style world lookup for skill 113.  The
     * selected client supplies an object id plus advisory coordinates; every
     * accepted coordinate and identity below comes from current server state.
     */
    private BattleTrueTarget.Candidate resolveTrueTargetCandidate(
            long requestedObjectId, Phase originPhase, long originRoomId,
            int originMapId, int originInstanceId,
            int sourceX, int sourceY, long nowNanos) {
        List<BattleTrueTarget.Candidate> candidates = new ArrayList<>();
        if (originPhase == Phase.WORLD) {
            List<ClientSession> members = classicWorldMembers(originMapId);
            for (ClientSession candidate : members) {
                boolean sameWorld = candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId;
                boolean alive = !candidate.observer && candidate.playerHp > 0;
                boolean visible = (candidate == this || !candidate.invisible)
                        && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                candidate.timedStatus.absoluteBarrierActive(nowNanos),
                                BattleSpellCatalog.TRUE_TARGET);
                candidates.add(new BattleTrueTarget.Candidate(
                        candidate.playerObjectId(), candidate.positionX,
                        candidate.positionY, BattleTrueTarget.Kind.PLAYER,
                        alive, visible, sameWorld));
            }
            for (ClientSession owner : members) {
                boolean sameWorld = owner.phase == Phase.WORLD
                        && owner.classicWorldMapId == originMapId
                        && owner.classicWorldInstanceId == originInstanceId;
                for (BattleCompanion.Snapshot companion
                        : owner.classicWorldCompanionSnapshots()) {
                    candidates.add(new BattleTrueTarget.Candidate(
                            companion.objectId(), companion.x(), companion.y(),
                            BattleTrueTarget.Kind.COMPANION,
                            companion.active() && companion.hp() > 0,
                            companion.active(), sameWorld));
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot monster
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, sourceX, sourceY)) {
                candidates.add(new BattleTrueTarget.Candidate(
                        monster.objectId(), monster.x(), monster.y(),
                        BattleTrueTarget.Kind.WORLD_MONSTER,
                        monster.present() && monster.alive(), monster.present(),
                        monster.mapId() == originMapId));
            }
            return BattleTrueTarget.resolve(requestedObjectId, candidates);
        }

        BattleRules.Mode mode = hub.roomRules(originRoomId).mode();
        int casterMap = hub.battleMapId(originRoomId, this);
        List<ClientSession> combatants = hub.roomCombatants(originRoomId);
        List<ClientSession> visibleCombatants = hub.visibleBattleCombatants(
                originRoomId, this);

        for (ClientSession candidate : combatants) {
            boolean sameWorld = visibleCombatants.contains(candidate)
                    && hub.battleMapId(originRoomId, candidate) == casterMap;
            boolean alive = candidate.phase == Phase.BATTLE
                    && !candidate.observer && candidate.playerHp > 0;
            boolean visible = (candidate == this || !candidate.invisible)
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            candidate.timedStatus.absoluteBarrierActive(nowNanos),
                            BattleSpellCatalog.TRUE_TARGET);
            candidates.add(new BattleTrueTarget.Candidate(
                    candidate.playerObjectId(), candidate.positionX,
                    candidate.positionY, BattleTrueTarget.Kind.PLAYER,
                    alive, visible, sameWorld));
        }

        for (ClientSession owner : visibleCombatants) {
            boolean sameWorld = hub.battleMapId(originRoomId, owner) == casterMap;
            for (BattleCompanion.Snapshot companion
                    : owner.controlledCompanionSnapshots()) {
                candidates.add(new BattleTrueTarget.Candidate(
                        companion.objectId(), companion.x(), companion.y(),
                        BattleTrueTarget.Kind.COMPANION,
                        companion.active() && companion.hp() > 0,
                        companion.active(), sameWorld));
            }
        }

        for (BattleGuardianTower.Snapshot tower
                : hub.visibleGuardianTowers(originRoomId, this)) {
            candidates.add(new BattleTrueTarget.Candidate(
                    tower.objectId(), tower.x(), tower.y(),
                    BattleTrueTarget.Kind.GUARDIAN_TOWER,
                    !tower.destroyed() && tower.hp() > 0,
                    !tower.destroyed(), true));
        }
        for (BattleQuestEncounter.Snapshot monster
                : hub.visibleQuestMonsters(originRoomId, this)) {
            candidates.add(new BattleTrueTarget.Candidate(
                    monster.objectId(), monster.x(), monster.y(),
                    BattleTrueTarget.Kind.QUEST_MONSTER,
                    monster.alive() && monster.hp() > 0,
                    monster.alive(), true));
        }
        for (BattleTimeAttackEncounter.Snapshot actor
                : hub.visibleTimeAttackActors(originRoomId, this)) {
            candidates.add(new BattleTrueTarget.Candidate(
                    actor.objectId(), actor.x(), actor.y(),
                    BattleTrueTarget.Kind.TIME_ATTACK_ACTOR,
                    actor.alive() && actor.hp() > 0,
                    actor.alive(), true));
        }

        if (mode != BattleRules.Mode.QUEST_BATTLE
                && mode != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(originRoomId) < 2
                && hub.botHp(originRoomId) > 0) {
            ArenaMapCatalog.Point bot = hub.botPosition(originRoomId);
            if (bot == null) bot = ArenaMapCatalog.forMap(casterMap).botSpawn();
            if (bot != null) {
                candidates.add(new BattleTrueTarget.Candidate(
                        2, bot.x(), bot.y(), BattleTrueTarget.Kind.ARENA_BOT,
                        true, true, true));
            }
        }
        return BattleTrueTarget.resolve(requestedObjectId, candidates);
    }

    private void useTrueTargetSpell(byte[] payload,
                                    BattleSpellCatalog.TrueTargetSpell spell)
            throws IOException {
        Protocol.TrueTargetRequest request = Protocol.trueTargetRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (originPhase != Phase.BATTLE && !classicWorld) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected phase="
                    + originPhase + " player=" + playerName());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "True-Target")) return;

        long originRoomId = currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        long now = System.nanoTime();
        BattleTrueTarget.Candidate target = resolveTrueTargetCandidate(
                request.targetObjectId(), originPhase, originRoomId,
                originMapId, originInstanceId, originX, originY, now);
        if (target == null || !BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected target="
                    + request.targetObjectId() + " player=" + playerName());
            return;
        }

        boolean lineOfSight = classicWorld
                ? ClassicWorldMapCatalog.forMap(originMapId).hasLineOfSight(
                        originX, originY, target.x(), target.y())
                : BattleSpellCatalog.hasNativeLineOfSight(
                        ArenaMapCatalog.forMap(originMapId),
                        originX, originY, target.x(), target.y());
        if (!BattleSpellCatalog.isInNativeScreen(
                    originX, originY, target.x(), target.y())
                || !lineOfSight) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected outside-screen target="
                    + request.targetObjectId() + " source=" + originX + "," + originY
                    + " target-position=" + target.x() + "," + target.y());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp = -1;
        boolean insufficientMp = false;
        BattleTrueTarget.Candidate commitTarget = resolveTrueTargetCandidate(
                request.targetObjectId(), originPhase, originRoomId,
                originMapId, originInstanceId, originX, originY,
                System.nanoTime());
        if (!target.equals(commitTarget)) {
            System.out.println("[LiTo] C_USE_SPELL True Target rejected moved target="
                    + request.targetObjectId() + " player=" + playerName());
            return;
        }
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (now < readyAt || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL True Target rejected state skill="
                        + spell.skillId() + " mp=" + playerMp
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            if (playerMp < mpCost) {
                insufficientMp = true;
            } else {
                cancelMeditation("spell-" + spell.skillId());
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), now
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }
        if (insufficientMp) {
            sendEncrypted(Protocol.messageCode(278),
                    "S_MESSAGE_CODE True-Target-insufficient-mp=278");
            System.out.println("[LiTo] C_USE_SPELL True Target rejected insufficient-mp"
                    + " player=" + playerName() + " mp=" + playerMp
                    + " mp-cost=" + mpCost);
            return;
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(playerObjectId()).c(spell.actionId()).bytes();
        List<ClientSession> actionRecipients = classicWorld
                ? classicWorldMembers(originMapId).stream()
                    .filter(member -> member.phase == Phase.WORLD
                            && member.classicWorldMapId == originMapId
                            && member.classicWorldInstanceId == originInstanceId
                            && BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    originX, originY))
                    .toList()
                : hub.battleRecipients(
                        originRoomId, hub.forceOf(originRoomId, this));
        for (ClientSession member : actionRecipients) {
            member.sendEncrypted(action,
                    "S_ACTION True Target caster=" + playerObjectId()
                            + " action=" + spell.actionId());
        }

        LinkedHashSet<ClientSession> recipients = new LinkedHashSet<>();
        recipients.add(this);
        if (!hub.clanData(sourceCharacterIdentity()).name().isBlank()) {
            List<ClientSession> audience = classicWorld
                    ? classicWorldMembers(originMapId)
                    : hub.visibleBattleCombatants(originRoomId, this);
            for (ClientSession candidate : audience) {
                boolean sameWorld = classicWorld
                        ? candidate.phase == Phase.WORLD
                            && candidate.classicWorldMapId == originMapId
                            && candidate.classicWorldInstanceId == originInstanceId
                        : candidate.phase == Phase.BATTLE
                            && hub.battleMapId(originRoomId, candidate) == originMapId;
                if (sameWorld && !candidate.observer
                        && hub.sameClan(sourceCharacterIdentity(),
                                candidate.sourceCharacterIdentity())
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.positionX, candidate.positionY)) {
                    recipients.add(candidate);
                }
            }
        }
        byte[] marker = Protocol.commandTarget(
                target.objectId(), target.x(), target.y(), request.text());
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(marker,
                    "S_COMMAND_TARGET skill=" + spell.skillId()
                            + " target=" + target.objectId()
                            + " x=" + target.x() + " y=" + target.y()
                            + " caster=" + playerName());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT True Target=" + remainingMp + "/" + playerMaxMp);
        if (request.x() != target.x() || request.y() != target.y()) {
            System.out.println("[LiTo] C_USE_SPELL True Target ignored stale coordinates client="
                    + request.x() + "," + request.y() + " server="
                    + target.x() + "," + target.y());
        }
        System.out.println("[LiTo] C_USE_SPELL True Target accepted caster=" + playerName()
                + " target=" + target.objectId() + " kind=" + target.kind()
                + " recipients=" + recipients.size() + " mp-cost=" + mpCost
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " counter-magic-bypass=" + spell.counterMagicBypass());
    }

    private void useRoyalAuraSpell(
            byte[] payload, BattleSpellCatalog.RoyalAuraSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && !classicWorld)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL royal aura rejected selector/action"
                    + " player=" + playerName() + " skill=" + request.skillId());
            return;
        }
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Royal-Aura")) return;

        long now = System.nanoTime();
        long originRoomId = currentRoomId;
        int casterMap = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        LinkedHashSet<ClientSession> targets = new LinkedHashSet<>();
        targets.add(this);
        List<ClientSession> targetPool = classicWorld
                ? classicWorldMembers(casterMap)
                : hub.roomCombatants(originRoomId);
        for (ClientSession candidate : targetPool) {
            boolean partyTarget = (spell.targetTo() & 8) != 0
                    && sameClassicParty(candidate);
            boolean clanTarget = (spell.targetTo() & 4) != 0
                    && sameNonemptyClan(candidate);
            boolean sameWorld = classicWorld
                    ? candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == casterMap
                        && candidate.classicWorldInstanceId == originInstanceId
                    : candidate.phase == Phase.BATTLE
                        && candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == casterMap;
            if (candidate == this || !sameWorld
                    || candidate.observer || candidate.playerHp <= 0
                    || (!partyTarget && !clanTarget)
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            candidate.positionX, candidate.positionY)) {
                continue;
            }
            targets.add(candidate);
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == casterMap
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == casterMap);
            if (now < readyAt || playerMp < mpCost || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL royal aura rejected state skill="
                        + spell.skillId() + " mp=" + playerMp + " cost=" + mpCost
                        + " cooldownNanos=" + Math.max(0L, readyAt - now));
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        targets.removeIf(target -> target != this && (target.phase != originPhase
                || target.observer || target.playerHp <= 0
                || (classicWorld
                    ? target.classicWorldMapId != casterMap
                        || target.classicWorldInstanceId != originInstanceId
                    : target.currentRoomId != originRoomId
                        || hub.battleMapId(originRoomId, target) != casterMap)
                || !(((spell.targetTo() & 8) != 0
                            && sameClassicParty(target))
                        || ((spell.targetTo() & 4) != 0
                            && sameNonemptyClan(target)))
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, target.positionX, target.positionY)));
        Map<ClientSession, Integer> replaced = new LinkedHashMap<>();
        boolean braveAura = spell.skillId() == BattleSpellCatalog.BRAVE_AURA;
        for (ClientSession target : targets) {
            synchronized (target) {
                if (braveAura) {
                    target.abilityStatus.activateBraveAura(
                            now, spell.durationSeconds(), spell.meleeDamage());
                    replaced.put(target, 0);
                } else {
                    replaced.put(target, target.abilityStatus.activateRoyalAura(
                            spell.skillId(), now, spell.durationSeconds(),
                            spell.armorClass(), spell.meleeHit(), spell.rangedHit(),
                            spell.magicResistance()));
                }
            }
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(casterMap)
                : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            boolean seesCaster = !classicWorld || (member.phase == Phase.WORLD
                    && member.classicWorldMapId == casterMap
                    && member.classicWorldInstanceId == originInstanceId
                    && BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            originX, originY));
            if (seesCaster) {
                member.sendEncrypted(action,
                        "S_ACTION royal-aura caster=" + playerObjectId()
                                + " action=" + spell.actionId()
                                + " skill=" + spell.skillId());
            }
            for (ClientSession target : targets) {
                if (classicWorld && (member.phase != Phase.WORLD
                        || member.classicWorldMapId != casterMap
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                target.positionX, target.positionY))) continue;
                member.sendEncrypted(
                        Protocol.effectObject(target.playerObjectId(), spell.effectGfx()),
                        "S_EFFECT royal-aura target=" + target.playerObjectId()
                                + " gfx=" + spell.effectGfx()
                                + " skill=" + spell.skillId());
            }
        }
        for (ClientSession target : targets) {
            BattleSpellCatalog.RoyalAuraSpell previous =
                    BattleSpellCatalog.royalAuraSpell(replaced.get(target));
            if (spell.armorClass() != 0
                    || (previous != null && previous.armorClass() != 0)) {
                target.sendArmorClassStatus(
                        "royal-aura-start-" + spell.skillId());
            }
            if (spell.magicResistance() != 0
                    || (previous != null && previous.magicResistance() != 0)) {
                target.sendMagicStatus(
                        now, "royal-aura-start-" + spell.skillId());
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT royal-aura=" + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL royal aura=" + spell.key()
                + " caster=" + playerName() + " targets="
                + targets.stream().map(ClientSession::playerName).toList()
                + " duration=" + spell.durationSeconds()
                + " ac=" + spell.armorClass()
                + " melee-hit=" + spell.meleeHit()
                + " ranged-hit=" + spell.rangedHit()
                + " mr=" + spell.magicResistance()
                + " melee-damage=" + spell.meleeDamage()
                + " effective-original-reduction=" + originalReduction
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " icon=omitted-selected-LiTo-FA-is-tournament-clan");
    }

    private void useCallClanSpell(
            byte[] payload, BattleSpellCatalog.CallClanSpell spell)
            throws IOException {
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Call-Clan")) return;
        Protocol.CallClanSpellRequest request = Protocol.callClanSpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            rejectCallClan(spell, "selector-or-action", spell.failureMessage(), null);
            return;
        }

        ClientSession target = classicWorld
                ? hub.onlineMemberByName(this, request.targetName())
                : hub.activeMemberByName(this, request.targetName());
        if (target == null) {
            rejectCallClan(spell, "target-offline-or-ambiguous", 73,
                    request.targetName());
            return;
        }
        if (!sameNonemptyClan(target)) {
            rejectCallClan(spell, "target-not-same-nonempty-clan", 414, null);
            return;
        }
        if (!callClanSharedContext(target)) {
            // Tournament rooms are separate authoritative worlds.  The
            // classic skill cannot import a lobby actor or another match.
            rejectCallClan(spell, "target-outside-caster-world", 629, null);
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        PendingCallClan invitation;
        long now = System.nanoTime();
        long originRoomId = classicWorld ? 0 : currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(currentRoomId, this);
        int originInstanceId = classicWorld ? classicWorldInstanceId : -1;
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean originStillValid = classicWorld
                    ? phase == Phase.WORLD && classicWorldMapId == originMapId
                        && classicWorldInstanceId == originInstanceId
                    : phase == Phase.BATTLE && currentRoomId == originRoomId
                        && currentRoomId != 0;
            if (now < readyAt || playerMp < mpCost || !originStillValid
                    || observer || playerHp <= 0
                    || pendingPortal != null || hub.hasPrivateShop(this)) {
                rejectCallClan(spell, "mp-cooldown-or-caster-state",
                        spell.failureMessage(), null);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
            invitation = new PendingCallClan(
                    this, originPhase, originRoomId, originMapId, originInstanceId,
                    positionX, positionY, Math.floorMod(playerHeading, 8),
                    now + CALL_CLAN_INVITE_TIMEOUT_NANOS);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        boolean published = callClanSharedContext(target)
                && sameNonemptyClan(target)
                && publishCallClanPrompt(target, invitation, now);

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> actionRecipients = classicWorld
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : actionRecipients) {
            if (classicWorld && (member.classicWorldInstanceId != originInstanceId
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            invitation.casterX(), invitation.casterY()))) continue;
            member.sendEncrypted(action, "S_ACTION Call Clan caster="
                    + playerObjectId() + " action=" + spell.actionId()
                    + " phase=" + originPhase);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Call Clan=" + remainingMp + "/" + playerMaxMp);
        if (published) {
            target.sendEncrypted(Protocol.callClanAsk(),
                    "S_ASK question=" + spell.questionId()
                            + " Call Clan caster=" + playerName());
        }
        System.out.println("[LiTo] C_USE_SPELL Call Clan caster=" + playerName()
                + " target=" + target.playerName() + " selector="
                + request.row() + "/" + request.column()
                + " snapshot=" + invitation.mapId() + ":"
                + invitation.casterX() + "," + invitation.casterY()
                + " heading=" + invitation.casterHeading()
                + " prompt-published=" + published
                + " effective-original-reduction=" + originalReduction
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " counter-magic-bypass=" + spell.counterMagicBypass());
    }

    private boolean callClanSharedContext(ClientSession target) {
        return phase == Phase.BATTLE
                ? callClanSharedBattle(target)
                : callClanSharedClassicWorld(target);
    }

    private boolean callClanSharedClassicWorld(ClientSession target) {
        GameHub.ClassicWorldLocation casterLocation = hub.classicWorldLocation(this);
        GameHub.ClassicWorldLocation targetLocation =
                target == null ? null : hub.classicWorldLocation(target);
        return target != null && phase == Phase.WORLD && target.phase == Phase.WORLD
                && !observer && !target.observer && playerHp > 0 && target.playerHp > 0
                && pendingPortal == null && target.pendingPortal == null
                && !hub.hasPrivateShop(this) && !hub.hasPrivateShop(target)
                && casterLocation != null && targetLocation != null
                && ClassicWorldMapCatalog.supports(casterLocation.mapId())
                && ClassicWorldMapCatalog.supports(targetLocation.mapId());
    }

    private void rejectCallClan(BattleSpellCatalog.CallClanSpell spell,
                                String reason, int messageId, String argument)
            throws IOException {
        if (messageId > 0) {
            byte[] message = argument == null
                    ? Protocol.messageCode(messageId)
                    : Protocol.messageCode(messageId, argument);
            sendEncrypted(message,
                    "S_MESSAGE_CODE Call Clan rejected=" + messageId
                            + " reason=" + reason
                            + (argument == null ? "" : " argument=" + argument));
        }
        System.out.println("[LiTo] C_USE_SPELL " + spell.key()
                + " rejected player=" + playerName() + " reason=" + reason);
    }

    private boolean callClanSharedBattle(ClientSession target) {
        if (target == null || currentRoomId == 0
                || phase != Phase.BATTLE || target.phase != Phase.BATTLE
                || observer || target.observer || playerHp <= 0 || target.playerHp <= 0
                || target.currentRoomId != currentRoomId
                || pendingPortal != null || target.pendingPortal != null
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(target)
                || !hub.battleStarted(currentRoomId)) {
            return false;
        }
        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        return combatants.contains(this) && combatants.contains(target)
                && hub.battleMapId(currentRoomId, this)
                        == hub.battleMapId(currentRoomId, target);
    }

    private boolean publishCallClanPrompt(ClientSession target,
                                          PendingCallClan invitation,
                                          long nowNanos) {
        synchronized (target) {
            PendingCallClan current = target.pendingCallClan;
            if (current != null && nowNanos - current.expiresAtNanos() < 0) {
                // Question 729 carries no generation or caller id.  Keep the
                // first unanswered prompt as the only acceptable capability.
                return false;
            }
        }
        hub.cancelPendingPlayerTradePrompt(target);
        synchronized (target) {
            PendingCallClan current = target.pendingCallClan;
            if (current != null && nowNanos - current.expiresAtNanos() < 0) {
                return false;
            }
            target.clearPendingAskCallbacks();
            target.pendingCallClan = invitation;
            return true;
        }
    }

    private void answerCallClan(Protocol.AskAnswer answer) throws IOException {
        PendingCallClan invitation = pendingCallClan;
        // One-shot capability: consume before id/text/answer/state validation.
        pendingCallClan = null;
        if (invitation == null || answer.questionId() != BattleCallClan.QUESTION_ID
                || !answer.text().isEmpty()) {
            System.out.println("[LiTo] C_ANSWER Call Clan rejected player="
                    + playerName() + " question=" + answer.questionId()
                    + " result=pending-unavailable-or-malformed");
            return;
        }
        if (answer.answer() == 0) {
            System.out.println("[LiTo] C_ANSWER Call Clan declined player="
                    + playerName() + " caster=" + invitation.caster().playerName());
            return;
        }

        long now = System.nanoTime();
        if (invitation.originPhase() == Phase.WORLD) {
            if (!ClassicWorldMapCatalog.supports(classicWorldMapId)
                    || !ClassicWorldMapCatalog.forMap(classicWorldMapId)
                            .allowsEscape()) {
                sendEncrypted(Protocol.messageCode(647),
                        "S_MESSAGE_CODE Call Clan source-not-escapable=647");
                return;
            }
            if (!callClanClassicWorldDestinationAllowed(invitation)) {
                sendEncrypted(Protocol.messageCode(629),
                        "S_MESSAGE_CODE Call Clan destination-too-far=629");
                return;
            }
        }
        if (timedStatus.actionLocked(now)
                || !callClanInvitationValid(invitation, now)) {
            System.out.println("[LiTo] C_ANSWER Call Clan rejected state player="
                    + playerName() + " caster="
                    + (invitation.caster() == null
                            ? "none" : invitation.caster().playerName()));
            return;
        }
        BattleCallClan.Destination destination =
                resolveCallClanDestination(invitation, now);
        if (destination == null) {
            sendEncrypted(Protocol.messageCode(627),
                    "S_MESSAGE_CODE Call Clan occupied-or-blocked=627");
            System.out.println("[LiTo] C_ANSWER Call Clan rejected destination player="
                    + playerName());
            return;
        }

        beginCallClanPortal(invitation, destination);
        System.out.println("[LiTo] C_ANSWER Call Clan accepted player=" + playerName()
                + " caster=" + invitation.caster().playerName()
                + " destination=" + destination.mapId() + ":"
                + destination.x() + "," + destination.y()
                + " heading=" + destination.heading());
    }

    private boolean callClanInvitationValid(PendingCallClan invitation,
                                             long nowNanos) {
        ClientSession caster = invitation == null ? null : invitation.caster();
        if (caster == null || nowNanos - invitation.expiresAtNanos() >= 0
                || observer || caster.observer || playerHp <= 0 || caster.playerHp <= 0
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(caster)
                || caster.positionX != invitation.casterX()
                || caster.positionY != invitation.casterY()
                || !sameNonemptyClan(caster)) {
            return false;
        }
        if (pendingPortal != null && pendingCallClanPortal == null) return false;
        if (invitation.originPhase() == Phase.WORLD) {
            GameHub.ClassicWorldLocation inviteeLocation =
                    hub.classicWorldLocation(this);
            GameHub.ClassicWorldLocation casterLocation =
                    hub.classicWorldLocation(caster);
            return invitation.roomId() == 0
                    && phase == Phase.WORLD && caster.phase == Phase.WORLD
                    && inviteeLocation != null && casterLocation != null
                    && caster.classicWorldMapId == invitation.mapId()
                    && caster.classicWorldInstanceId == invitation.instanceId()
                    && casterLocation.mapId() == invitation.mapId();
        }
        return invitation.originPhase() == Phase.BATTLE
                && invitation.roomId() == currentRoomId
                && caster.currentRoomId == currentRoomId
                && phase == Phase.BATTLE && caster.phase == Phase.BATTLE
                && currentRoomId != 0 && hub.battleStarted(currentRoomId)
                && hub.roomCombatants(currentRoomId).contains(this)
                && hub.roomCombatants(currentRoomId).contains(caster)
                && hub.battleMapId(currentRoomId, this) == invitation.mapId()
                && hub.battleMapId(currentRoomId, caster) == invitation.mapId();
    }

    private boolean callClanClassicWorldDestinationAllowed(
            PendingCallClan invitation) {
        if (invitation == null || invitation.originPhase() != Phase.WORLD
                || invitation.instanceId() != -1
                || (invitation.mapId() != 0 && invitation.mapId() != 4
                    && invitation.mapId() != 304)) return false;
        if (invitation.mapId() != 4) return true;
        int castleId = callClanClassicWorldCastleId(
                invitation.casterX(), invitation.casterY());
        return castleId == 0 || hub.classicCastleWarActive(
                selectedClassicServerName, castleId);
    }

    private static int callClanClassicWorldCastleId(int x, int y) {
        if (inRectangle(x, y, 33089, 32717, 33219, 32827)) return 1;
        if (inRectangle(x, y, 32750, 32250, 32850, 32350)) return 2;
        if (inRectangle(x, y, 32571, 33350, 32721, 33460)) return 3;
        if (inRectangle(x, y, 33559, 32615, 33686, 32755)) return 4;
        if (inRectangle(x, y, 33458, 33315, 33583, 33490)) return 5;
        if (inRectangle(x, y, 34007, 33172, 34162, 33332)) return 7;
        return 0;
    }

    private static boolean inRectangle(int x, int y, int minX, int minY,
                                       int maxX, int maxY) {
        return x >= minX && x <= maxX && y >= minY && y <= maxY;
    }

    private BattleCallClan.Destination resolveCallClanDestination(
            PendingCallClan invitation, long nowNanos) {
        BattleCallClan.TileProbe passable;
        if (invitation.originPhase() == Phase.WORLD) {
            if (!ClassicWorldMapCatalog.supports(invitation.mapId())) return null;
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(invitation.mapId());
            passable = map::standingPassable;
        } else {
            ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(invitation.mapId());
            passable = arena::nativeStandingFloor;
        }
        return BattleCallClan.adjacentDestination(
                invitation.mapId(), invitation.casterX(), invitation.casterY(),
                invitation.casterHeading(), passable,
                (x, y) -> callClanDestinationOccupied(
                        invitation, x, y, nowNanos));
    }

    private boolean callClanDestinationOccupied(
            PendingCallClan invitation, int x, int y, long nowNanos) {
        if (invitation.originPhase() == Phase.WORLD) {
            int mapId = invitation.mapId();
            int instanceId = invitation.instanceId();
            for (ClientSession member : hub.classicWorldMembers(mapId, instanceId)) {
                if (member.playerHp > 0 && member.positionX == x
                        && member.positionY == y) return true;
                for (BattleCompanion.Snapshot companion
                        : member.controlledCompanionSnapshots()) {
                    if (companion.active() && companion.x() == x
                            && companion.y() == y) return true;
                }
            }
            if (hub.classicWorldMonsterOccupies(mapId, instanceId, x, y)) return true;
            return ClassicWorldNpcCatalog.all(mapId).stream()
                    .anyMatch(npc -> npc.x() == x && npc.y() == y);
        }
        int mapId = hub.battleMapId(currentRoomId, this);
        if (occupies(repairNpcPoint(), x, y)
                || occupies(spellShopNpcPoint(), x, y)
                || occupies(spellMaterialNpcPoint(), x, y)
                || occupies(classicMerchantNpcPoint(), x, y)
                || occupies(warehouseNpcPoint(), x, y)
                || occupies(castleStewardNpcPoint(), x, y)
                || occupies(houseAuctionBoardPoint(), x, y)
                || occupies(mercenaryCommanderNpcPoint(), x, y)) {
            return true;
        }
        List<ClientSession> combatants = hub.roomCombatants(currentRoomId);
        for (ClientSession combatant : combatants) {
            if (combatant.currentRoomId == currentRoomId
                    && hub.battleMapId(currentRoomId, combatant) == mapId
                    && combatant.positionX == x && combatant.positionY == y) {
                return true;
            }
            if (hub.battleMapId(currentRoomId, combatant) != mapId) continue;
            for (BattleCompanion.Snapshot companion
                    : combatant.controlledCompanionSnapshots()) {
                if (companion.active() && companion.x() == x && companion.y() == y) {
                    return true;
                }
            }
        }
        BattleRules.Mode mode = hub.roomRules(currentRoomId).mode();
        ArenaMapCatalog.Point bot = hub.botPosition(currentRoomId);
        if (mode != BattleRules.Mode.QUEST_BATTLE
                && mode != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(currentRoomId) < 2
                && bot != null && hub.botHp(currentRoomId) > 0
                && bot.x() == x && bot.y() == y) {
            return true;
        }
        if (hub.visibleGuardianTowers(currentRoomId, this).stream()
                .anyMatch(tower -> !tower.destroyed()
                        && tower.x() == x && tower.y() == y)) return true;
        if (hub.visibleQuestMonsters(currentRoomId, this).stream()
                .anyMatch(actor -> actor.alive() && actor.x() == x && actor.y() == y)) {
            return true;
        }
        if (hub.visibleTimeAttackActors(currentRoomId, this).stream()
                .anyMatch(actor -> actor.alive() && actor.x() == x && actor.y() == y)) {
            return true;
        }
        if (hub.battleDoorBlocks(currentRoomId, x, y)
                || hub.siegeGateBlocks(currentRoomId, x, y)) return true;
        if (hub.cookingFires(currentRoomId, nowNanos).stream()
                .anyMatch(fire -> fire.x() == x && fire.y() == y)) return true;
        return hub.shockStunEffects(currentRoomId, nowNanos).stream()
                .anyMatch(effect -> effect.x() == x && effect.y() == y);
    }

    private static boolean occupies(ArenaMapCatalog.Point point, int x, int y) {
        return point != null && point.x() == x && point.y() == y;
    }

    private void beginCallClanPortal(PendingCallClan invitation,
                                     BattleCallClan.Destination destination)
            throws IOException {
        if (pendingPortal != null) {
            throw new IllegalStateException("Call Clan portal already pending");
        }
        clearPendingAskCallbacks();
        pendingPortal = new Protocol.PortalDestination(
                destination.mapId(), destination.x(), destination.y(), true);
        pendingPortalReady = false;
        pendingRunClanPortal = null;
        pendingCallClanPortal = new PendingCallClanPortal(invitation, destination);
        pendingClassicWorldPortal = invitation.originPhase() == Phase.WORLD
                ? new PendingClassicWorldPortal(
                        pendingPortal, destination.heading(), 0,
                        "Call-Clan-116", invitation.instanceId())
                : null;
        sendEncrypted(Protocol.requestSummon(playerObjectId()),
                "S_REQUEST_SUMMON Call Clan player=" + playerName()
                        + " object=" + playerObjectId());
    }

    private boolean callClanPortalStillValid(PendingCallClanPortal portal,
                                               long nowNanos) {
        if (portal == null || portal != pendingCallClanPortal
                || !callClanInvitationValid(portal.invitation(), nowNanos)) {
            return false;
        }
        BattleCallClan.Destination current =
                resolveCallClanDestination(portal.invitation(), nowNanos);
        return portal.destination().equals(current);
    }

    private void useRunClanSpell(
            byte[] payload, BattleSpellCatalog.RunClanSpell spell)
            throws IOException {
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Run-Clan")) return;
        Protocol.RunClanSpellRequest request = Protocol.runClanSpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            rejectRunClan(spell, "selector-or-action", spell.failureMessage(), null);
            return;
        }

        ClientSession target = classicWorld
                ? hub.onlineMemberByName(this, request.targetName())
                : hub.activeMemberByName(this, request.targetName());
        if (target == null) {
            rejectRunClan(spell, "target-offline-or-ambiguous", 73,
                    request.targetName());
            return;
        }
        if (!sameNonemptyClan(target)) {
            rejectRunClan(spell, "target-not-same-nonempty-clan", 414, null);
            return;
        }
        if (!callClanSharedContext(target)) {
            rejectRunClan(spell, "target-outside-caster-world", 629, null);
            return;
        }
        if (classicWorld && !ClassicWorldMapCatalog.forMap(classicWorldMapId)
                .allowsEscape()) {
            rejectRunClan(spell, "source-not-escapable", 647, null);
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Run-Clan-source-not-escapable");
            return;
        }
        if (classicWorld && !runClanClassicWorldDestinationAllowed(target)) {
            rejectRunClan(spell, "destination-map-instance-or-war-area", 1192, null);
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Run-Clan-destination-rejected");
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        long now = System.nanoTime();
        long originRoomId = classicWorld ? 0 : currentRoomId;
        int sourceMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(currentRoomId, this);
        int sourceInstanceId = classicWorld ? classicWorldInstanceId : -1;
        int targetMapId = classicWorld
                ? target.classicWorldMapId : hub.battleMapId(currentRoomId, target);
        int targetInstanceId = classicWorld ? target.classicWorldInstanceId : -1;
        BattleRunClan.Destination destination = BattleRunClan.exactDestination(
                targetMapId, target.positionX, target.positionY);
        PendingRunClanPortal portal = new PendingRunClanPortal(
                target, originPhase, originRoomId, sourceMapId, sourceInstanceId,
                targetMapId, targetInstanceId, target.positionX, target.positionY,
                now + BattleRunClan.PORTAL_TIMEOUT_SECONDS * 1_000_000_000L,
                destination);
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean originStillValid = classicWorld
                    ? phase == Phase.WORLD && classicWorldMapId == sourceMapId
                        && classicWorldInstanceId == sourceInstanceId
                    : phase == Phase.BATTLE && currentRoomId == originRoomId
                        && currentRoomId != 0;
            if (now < readyAt || playerMp < mpCost || !originStillValid
                    || observer || playerHp <= 0
                    || pendingPortal != null || hub.hasPrivateShop(this)) {
                rejectRunClan(spell, "mp-cooldown-or-caster-state",
                        spell.failureMessage(), null);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), now
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        boolean started = runClanPortalContextValid(portal, now);

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        List<ClientSession> actionRecipients = classicWorld
                ? classicWorldMembers(sourceMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : actionRecipients) {
            if (classicWorld && (member.classicWorldInstanceId != sourceInstanceId
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            positionX, positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION Run Clan caster=" + playerObjectId()
                            + " action=" + spell.actionId()
                            + " phase=" + originPhase);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Run Clan=" + remainingMp + "/" + playerMaxMp);
        if (started) {
            beginRunClanPortal(portal);
        } else {
            sendEncrypted(Protocol.messageCode(629),
                    "S_MESSAGE_CODE Run Clan stale-target=629");
        }
        System.out.println("[LiTo] C_USE_SPELL Run Clan caster=" + playerName()
                + " target=" + target.playerName() + " selector="
                + request.row() + "/" + request.column()
                + " destination=" + destination.mapId() + ":"
                + destination.x() + "," + destination.y()
                + " heading=" + destination.heading()
                + " portal-started=" + started
                + " effective-original-reduction=" + originalReduction
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " phase=" + originPhase
                + " source=" + sourceMapId + "/" + sourceInstanceId
                + " target-instance=" + targetInstanceId
                + " counter-magic-bypass=" + spell.counterMagicBypass());
    }

    private void rejectRunClan(BattleSpellCatalog.RunClanSpell spell,
                               String reason, int messageId, String argument)
            throws IOException {
        if (messageId > 0) {
            byte[] message = argument == null
                    ? Protocol.messageCode(messageId)
                    : Protocol.messageCode(messageId, argument);
            sendEncrypted(message,
                    "S_MESSAGE_CODE Run Clan rejected=" + messageId
                            + " reason=" + reason
                            + (argument == null ? "" : " argument=" + argument));
        }
        System.out.println("[LiTo] C_USE_SPELL " + spell.key()
                + " rejected player=" + playerName() + " reason=" + reason);
    }

    private void beginRunClanPortal(PendingRunClanPortal portal)
            throws IOException {
        if (pendingPortal != null || portal == null) {
            throw new IllegalStateException("Run Clan portal already pending");
        }
        clearPendingAskCallbacks();
        pendingPortal = new Protocol.PortalDestination(
                portal.destination().mapId(), portal.destination().x(),
                portal.destination().y(), true);
        pendingPortalReady = false;
        pendingCallClanPortal = null;
        pendingRunClanPortal = portal;
        pendingClassicWorldPortal = portal.originPhase() == Phase.WORLD
                ? new PendingClassicWorldPortal(
                        pendingPortal, portal.destination().heading(), 0,
                        "Run-Clan-118", portal.targetInstanceId())
                : null;
        sendEncrypted(Protocol.requestSummon(playerObjectId()),
                "S_REQUEST_SUMMON Run Clan player=" + playerName()
                        + " object=" + playerObjectId());
    }

    private boolean runClanPortalStillValid(PendingRunClanPortal portal,
                                             long nowNanos) {
        return portal != null && portal == pendingRunClanPortal
                && runClanPortalContextValid(portal, nowNanos);
    }

    private boolean runClanPortalContextValid(PendingRunClanPortal portal,
                                               long nowNanos) {
        ClientSession target = portal == null ? null : portal.target();
        if (portal == null || target == null
                || nowNanos - portal.expiresAtNanos() >= 0
                || observer || target.observer || playerHp <= 0 || target.playerHp <= 0
                || hub.hasPrivateShop(this) || hub.hasPrivateShop(target)
                || target.positionX != portal.targetX()
                || target.positionY != portal.targetY()
                || !sameNonemptyClan(target)
                || (target != this && target.pendingPortal != null)) {
            return false;
        }
        if (portal.originPhase() == Phase.WORLD) {
            if (portal.roomId() != 0 || phase != Phase.WORLD
                    || target.phase != Phase.WORLD
                    || classicWorldMapId != portal.sourceMapId()
                    || classicWorldInstanceId != portal.sourceInstanceId()
                    || target.classicWorldMapId != portal.targetMapId()
                    || target.classicWorldInstanceId != portal.targetInstanceId()
                    || !ClassicWorldMapCatalog.supports(portal.sourceMapId())
                    || !ClassicWorldMapCatalog.forMap(portal.sourceMapId()).allowsEscape()
                    || !runClanClassicWorldDestinationAllowed(target)) {
                return false;
            }
        } else if (portal.originPhase() == Phase.BATTLE) {
            if (portal.roomId() != currentRoomId
                    || target.currentRoomId != currentRoomId
                    || phase != Phase.BATTLE || target.phase != Phase.BATTLE
                    || currentRoomId == 0 || !hub.battleStarted(currentRoomId)
                    || !hub.roomCombatants(currentRoomId).contains(this)
                    || !hub.roomCombatants(currentRoomId).contains(target)
                    || hub.battleMapId(currentRoomId, this) != portal.sourceMapId()
                    || hub.battleMapId(currentRoomId, target) != portal.targetMapId()
                    || portal.sourceMapId() != portal.targetMapId()) {
                return false;
            }
        } else {
            return false;
        }
        BattleRunClan.Destination current = BattleRunClan.exactDestination(
                portal.targetMapId(), target.positionX, target.positionY);
        return portal.destination().equals(current);
    }

    private static boolean runClanClassicWorldDestinationAllowed(
            ClientSession target) {
        if (target == null || target.phase != Phase.WORLD
                || target.classicWorldInstanceId != -1
                || (target.classicWorldMapId != 0
                    && target.classicWorldMapId != 4
                    && target.classicWorldMapId != 304)) return false;
        if (target.classicWorldMapId != 4) return true;
        int castleId = callClanClassicWorldCastleId(
                target.positionX, target.positionY);
        return castleId == 0 || target.hub.classicCastleWarActive(
                target.selectedClassicServerName, castleId);
    }

