    /** Exact selected/retained object-target self buff for skill166 Storm Shot. */
    private void useStormShotSpell(
            byte[] payload, BattleSpellCatalog.StormShotSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        if (phase != Phase.BATTLE && phase != Phase.WORLD) return;
        // Exact row166 attr=0 bypasses retained isAttrAgrees(); ordinary skill
        // acquisition still grants it only to wind elves.
        if (spell.attribute() != BattleSpellCatalog.ATTRIBUTE_UNSPECIFIED
                && (elfAttribute & spell.attribute()) == 0
                && !isAdministrator()) {
            System.out.println("[LiTo] C_USE_SPELL Storm Shot rejected attribute"
                    + " player=" + playerName() + " required=" + spell.attribute()
                    + " elf-attr=" + elfAttribute + " phase=" + phase);
            return;
        }
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Storm-Shot-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Storm-Shot-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Storm-Shot-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Storm-Shot-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Storm-Shot-overweight=316");
            return;
        }
        if (request.targetObjectId() != playerObjectId()) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Storm-Shot-invalid-target="
                            + spell.failureMessage());
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned"
                    + " Storm Shot player=" + playerName());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Storm Shot rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        int remainingMp;
        boolean refreshed;
        long castNow;
        Phase originPhase;
        long originRoomId;
        int originMapId;
        int originInstanceId;
        int originX;
        int originY;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || observer
                    || playerHp <= 0
                    || request.targetObjectId() != playerObjectId()
                    || (phase != Phase.BATTLE && phase != Phase.WORLD)) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Storm-Shot-insufficient-mp=278");
                } else if (request.targetObjectId() != playerObjectId()) {
                    sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                            "S_MESSAGE_CODE Storm-Shot-state-failure="
                                    + spell.failureMessage());
                }
                System.out.println("[LiTo] C_USE_SPELL Storm Shot rejected state"
                        + " player=" + playerName() + " mp=" + playerMp
                        + " cost=" + mpCost + " target="
                        + request.targetObjectId() + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow) + " phase=" + phase);
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            refreshed = stormShotStatus.activate(
                    castNow, spell.durationSeconds(),
                    spell.rangedHitModifier(), spell.rangedDamageModifier());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
            originPhase = phase;
            originRoomId = currentRoomId;
            originMapId = classicWorldMapId;
            originInstanceId = classicWorldInstanceId;
            originX = positionX;
            originY = positionY;
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) continue;
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Storm-Shot caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT Storm-Shot target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Storm-Shot="
                        + remainingMp + "/" + playerMaxMp);
        state.saveTimedStormShotBuff(stateCharacter(),
                new GameStateStore.TimedStormShotBuff(spell.durationSeconds()));
        sendEncrypted(Protocol.messageCode(spell.happenMessage()),
                "S_MESSAGE_CODE Storm-Shot-happen=" + spell.happenMessage());
        System.out.println("[LiTo] C_USE_SPELL Storm Shot caster="
                + playerName() + " selector=" + request.row() + "/"
                + request.column() + " target=" + request.targetObjectId()
                + " duration=" + spell.durationSeconds()
                + " refreshed=" + refreshed + " attribute-gate=none"
                + " ranged-hit=" + spell.rangedHitModifier()
                + " ranged-damage=" + spell.rangedDamageModifier()
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " phase=" + originPhase
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

