    /** Exact selected/retained selector-only three-strike skill187. */
    private void useFoeSlayerSpell(
            byte[] payload, BattleSpellCatalog.FoeSlayerSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        boolean classicWorld = originPhase == Phase.WORLD;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && !classicWorld)) return;
        if (classicWorld && !admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Foe-Slayer")) return;
        if (!classicWorld && (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId()))) {
            System.out.println("[LiTo] C_USE_SPELL Foe Slayer rejected learned/action"
                    + " player=" + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = classicWorld
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        FoeSlayerTarget target = resolveFoeSlayerTarget(
                originPhase, originRoomId, originMapId, originInstanceId,
                originX, originY, spell.maximumRange());
        if (target == null) return;

        int remainingHp;
        int remainingMp;
        int rejectionMessage = 0;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (classicWorld
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (castNow < readyAt || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL Foe Slayer rejected state"
                        + " player=" + playerName() + " target="
                        + target.objectId() + " hp=" + playerHp + " mp="
                        + playerMp + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            if (playerHp <= spell.hpCost()) rejectionMessage = 279;
            else if (playerMp < spell.mpCost()) rejectionMessage = 278;
            if (rejectionMessage == 0) {
                cancelMeditation("spell-" + spell.skillId());
                playerHp -= spell.hpCost();
                playerMp -= spell.mpCost();
                commitSpellReady(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            remainingHp = playerHp;
            remainingMp = playerMp;
        }
        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE Foe-Slayer-rejected=" + rejectionMessage);
            System.out.println("[LiTo] C_USE_SPELL Foe Slayer rejected resource"
                    + " message=" + rejectionMessage + " hp=" + remainingHp
                    + " mp=" + remainingMp);
            return;
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        BattleRules.Mode battleMode = classicWorld ? null
                : hub.roomRules(originRoomId).mode();
        List<ClientSession> recipients = classicWorld
                ? classicWorldMembers(originMapId).stream()
                    .filter(member -> member.phase == Phase.WORLD
                            && member.classicWorldMapId == originMapId
                            && member.classicWorldInstanceId == originInstanceId
                            && (BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    originX, originY)
                                || BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    target.x(), target.y())))
                    .toList()
                : target.quest() != null
                        || target.tower() != null
                            && battleMode == BattleRules.Mode.QUEST_BATTLE
                    ? hub.battleRecipients(originRoomId,
                            target.quest() != null ? target.quest().force()
                                    : target.tower().force())
                    : hub.roomMembers(originRoomId);
        // The reference sends the physical strikes then caster effect7020.
        // An extra casting action would queue a full slow animation first.

        boolean targetStillEligible = foeSlayerTargetStillEligible(
                target, originPhase, originRoomId, originMapId,
                originInstanceId, originX, originY, spell.maximumRange());
        BattleChainswordWeakness.ConsumeOutcome consumed =
                new BattleChainswordWeakness.ConsumeOutcome(
                        0, 0, false, false, false);
        if (targetStillEligible) {
            consumed = chainswordWeakness.consumeFoeSlayer(
                    battleCharacterType(), target.objectId(), castNow);
            int sourceDamageBonus = spell.damageForExposureLevel(
                    consumed.consumedLevel());
            if (sourceDamageBonus != consumed.damageBonus()) {
                throw new IllegalStateException(
                        "Foe Slayer exposure/catalog damage mismatch");
            }
            foeSlayerSequence.begin(target.objectId(),
                    consumed.consumedLevel(), sourceDamageBonus,
                    spell.hitCount());
            Protocol.AttackRequest physical = new Protocol.AttackRequest(
                    target.objectId(), target.x(), target.y());
            try {
                for (int strike = 0; strike < spell.hitCount(); strike++) {
                    attack(physical, AttackEnvelope.DIRECT);
                }
            } finally {
                foeSlayerSequence.clear();
            }

            byte[] attackerEffect = Protocol.effectObject(
                    playerObjectId(), spell.attackerEffectGfx());
            byte[] targetEffect = Protocol.effectObject(
                    target.objectId(), spell.targetEffectGfx());
            for (ClientSession member : recipients) {
                member.sendEncrypted(attackerEffect,
                        "S_EFFECT Foe Slayer caster=" + playerObjectId()
                                + " gfx=" + spell.attackerEffectGfx());
                member.sendEncrypted(targetEffect,
                        "S_EFFECT Foe Slayer target=" + target.objectId()
                                + " gfx=" + spell.targetEffectGfx());
            }
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Foe-Slayer=" + remainingHp + "/" + playerMaxHp);
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Foe-Slayer=" + remainingMp + "/" + playerMaxMp);
        broadcastOwnHitRatio("foe-slayer-hp-cost");
        System.out.println("[LiTo] C_USE_SPELL Foe Slayer caster=" + playerName()
                + " selector=" + request.row() + "/" + request.column()
                + " target=" + target.objectId() + " target-still-eligible="
                + targetStillEligible + " hits=" + spell.hitCount()
                + " exposure-level=" + consumed.consumedLevel()
                + " per-hit-exposure-bonus=" + consumed.damageBonus()
                + " exposure-consumed=" + consumed.consumed()
                + " target-mismatch=" + consumed.targetMismatch()
                + " hp-cost=" + spell.hpCost() + " hp=" + remainingHp
                + "/" + playerMaxHp + " mp-cost=" + spell.mpCost()
                + " mp=" + remainingMp + "/" + playerMaxMp
                + " reuse-ms=" + spell.reuseDelayMillis()
                + " counter-magic-bypass=" + spell.counterMagicBypass()
                + " selected-client-weakness-icon=unavailable"
                + " phase=" + originPhase);
    }

    private FoeSlayerTarget resolveFoeSlayerTarget(
            Phase originPhase, long originRoomId, int originMapId,
            int originInstanceId, int sourceX, int sourceY, int maximumRange) {
        FoeSlayerTarget companion = (FoeSlayerTarget) DragonCombat.foeCompanion(this);
        if (companion != null) return companion;
        Map<Long, FoeSlayerTarget> eligible = new LinkedHashMap<>();
        if (originPhase == Phase.WORLD) {
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            for (ClientSession candidate : classicWorldMembers(originMapId)) {
                if (candidate != this && candidate.phase == Phase.WORLD
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                        && !map.isSafetyZone(sourceX, sourceY)
                        && !map.isSafetyZone(candidate.positionX, candidate.positionY)
                        && map.attackPosition(sourceX, sourceY,
                                candidate.positionX, candidate.positionY,
                                maximumRange)) {
                    eligible.put(candidate.playerObjectId(), new FoeSlayerTarget(
                            candidate.playerObjectId(), candidate.positionX,
                            candidate.positionY, candidate,
                            null, null, null, null, false));
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, sourceX, sourceY)) {
                if (candidate.present() && candidate.alive()
                        && candidate.mapId() == originMapId
                        && !map.isSafetyZone(sourceX, sourceY)
                        && !map.isSafetyZone(candidate.x(), candidate.y())
                        && map.attackPosition(sourceX, sourceY,
                                candidate.x(), candidate.y(), maximumRange)) {
                    eligible.put(candidate.objectId(), new FoeSlayerTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            null, candidate, null, null, null, false));
                }
            }
        } else {
            for (ClientSession candidate : hub.roomCombatants(originRoomId)) {
                if (candidate != this && candidate.phase == Phase.BATTLE
                        && !candidate.observer && candidate.playerHp > 0
                        && !candidate.invisible
                        && candidate.currentRoomId == originRoomId
                        && hub.canAttack(originRoomId, this, candidate)) {
                    eligible.put(candidate.playerObjectId(), new FoeSlayerTarget(
                            candidate.playerObjectId(), candidate.positionX,
                            candidate.positionY, candidate,
                            null, null, null, null, false));
                }
            }
            for (BattleGuardianTower.Snapshot candidate
                    : hub.visibleGuardianTowers(originRoomId, this)) {
                if (!candidate.destroyed() && candidate.hp() > 0
                        && hub.canAttackGuardianTower(
                                originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new FoeSlayerTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            null, null, candidate, null, null, false));
                }
            }
            for (BattleQuestEncounter.Snapshot candidate
                    : hub.visibleQuestMonsters(originRoomId, this)) {
                if (candidate.alive() && hub.canAttackQuestMonster(
                        originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new FoeSlayerTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            null, null, null, candidate, null, false));
                }
            }
            for (BattleTimeAttackEncounter.Snapshot candidate
                    : hub.visibleTimeAttackActors(originRoomId, this)) {
                if (candidate.alive() && hub.canAttackTimeAttackActor(
                        originRoomId, this, candidate.objectId())) {
                    eligible.put(candidate.objectId(), new FoeSlayerTarget(
                            candidate.objectId(), candidate.x(), candidate.y(),
                            null, null, null, null, candidate, false));
                }
            }
            List<ClientSession> combatants = hub.roomCombatants(originRoomId);
            BattleRules.Mode mode = hub.roomRules(originRoomId).mode();
            ArenaMapCatalog.Point bot = hub.botPosition(originRoomId);
            if (mode != BattleRules.Mode.QUEST_BATTLE
                    && mode != BattleRules.Mode.TIME_ATTACK
                    && hub.roomCombatantCount(originRoomId) < 2 && bot != null
                    && hub.botHp(originRoomId) > 0) {
                eligible.put(2L, new FoeSlayerTarget(
                        2L, bot.x(), bot.y(), null,
                        null, null, null, null, true));
            }
        }
        List<BattleGuardBrake.Candidate> candidates = eligible.values().stream()
                .map(candidate -> new BattleGuardBrake.Candidate(
                        candidate.objectId(), candidate.x(), candidate.y()))
                .toList();
        long resolved = DragonSkillRequests.guardTarget(
                lastCombatTargetObjectId, sourceX, sourceY,
                maximumRange, candidates);
        if (resolved == 0) {
            System.out.println("[LiTo] C_USE_SPELL Foe Slayer rejected unresolved"
                    + " selector-only target player=" + playerName()
                    + " last-explicit=" + lastCombatTargetObjectId
                    + " maximum-range=" + maximumRange);
            return null;
        }
        return eligible.get(resolved);
    }

    private boolean foeSlayerTargetStillEligible(
            FoeSlayerTarget target, Phase originPhase, long originRoomId,
            int originMapId, int originInstanceId, int sourceX, int sourceY,
            int maximumRange) {
        if (DragonCombat.foeCompanionStillEligible(this, target.objectId(), originPhase,
                originRoomId, originMapId, originInstanceId, sourceX, sourceY, maximumRange)) return true;
        int targetX;
        int targetY;
        boolean eligible;
        if (originPhase == Phase.WORLD && target.player() != null) {
            targetX = target.player().positionX;
            targetY = target.player().positionY;
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && target.player().phase == Phase.WORLD
                    && !target.player().observer && target.player().playerHp > 0
                    && !target.player().invisible
                    && sameClassicWorldMap(target.player())
                    && !map.isSafetyZone(sourceX, sourceY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(
                            sourceX, sourceY, targetX, targetY, maximumRange);
        } else if (originPhase == Phase.WORLD) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            ClassicWorldMapCatalog.ClassicMap map =
                    ClassicWorldMapCatalog.forMap(originMapId);
            eligible = phase == Phase.WORLD
                    && classicWorldMapId == originMapId
                    && classicWorldInstanceId == originInstanceId
                    && positionX == sourceX && positionY == sourceY
                    && current != null && current.present() && current.alive()
                    && !map.isSafetyZone(sourceX, sourceY)
                    && !map.isSafetyZone(targetX, targetY)
                    && map.attackPosition(
                            sourceX, sourceY, targetX, targetY, maximumRange);
        } else if (target.player() != null) {
            targetX = target.player().positionX;
            targetY = target.player().positionY;
            eligible = phase == Phase.BATTLE && currentRoomId == originRoomId
                    && target.player().phase == Phase.BATTLE
                    && !target.player().observer && target.player().playerHp > 0
                    && !target.player().invisible
                    && target.player().currentRoomId == originRoomId
                    && hub.canAttack(originRoomId, this, target.player());
        } else if (target.tower() != null) {
            BattleGuardianTower.Snapshot current = hub.guardianTower(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && !current.destroyed() && current.hp() > 0
                    && hub.canAttackGuardianTower(
                            originRoomId, this, target.objectId());
        } else if (target.quest() != null) {
            BattleQuestEncounter.Snapshot current = hub.questMonster(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && current.alive()
                    && hub.canAttackQuestMonster(
                            originRoomId, this, target.objectId());
        } else if (target.time() != null) {
            BattleTimeAttackEncounter.Snapshot current = hub.timeAttackActor(
                    originRoomId, target.objectId());
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = current != null && current.alive()
                    && hub.canAttackTimeAttackActor(
                            originRoomId, this, target.objectId());
        } else {
            ArenaMapCatalog.Point current = hub.botPosition(originRoomId);
            targetX = current == null ? Integer.MAX_VALUE : current.x();
            targetY = current == null ? Integer.MAX_VALUE : current.y();
            eligible = target.bot() && current != null
                    && hub.botHp(originRoomId) > 0;
        }
        return eligible && Math.max(Math.abs(sourceX - targetX),
                Math.abs(sourceY - targetY)) <= maximumRange;
    }

    /** Exact selected/retained selector-only next-melee-hit skill182. */
    private void useBurningSlashSpell(
            byte[] payload, BattleSpellCatalog.BurningSlashSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        Phase originPhase = phase;
        if (request.skillId() != spell.skillId()
                || (originPhase != Phase.BATTLE && originPhase != Phase.WORLD)) {
            return;
        }
        if (originPhase == Phase.WORLD
                && !admitClassicWorldSpellFamily(
                        spell.skillId(), spell.actionId(), "Burning-Slash")) {
            return;
        }
        if (originPhase == Phase.BATTLE
                && (!learnedSkills.contains(spell.skillId())
                    || !BattleAnimationCatalog.get().supportsTimedAction(
                            battleGfx(), spell.actionId()))) {
            System.out.println("[LiTo] C_USE_SPELL Burning Slash rejected"
                    + " learned/action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = originPhase == Phase.WORLD
                ? classicWorldMapId : hub.battleMapId(originRoomId, this);
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        int remainingHp;
        boolean refreshed;
        int rejectionMessage = 0;
        long castNow = System.nanoTime();
        synchronized (this) {
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean sameCasterContext = phase == originPhase && !observer
                    && playerHp > 0 && positionX == originX && positionY == originY
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, this) == originMapId);
            if (castNow < readyAt || !sameCasterContext) {
                System.out.println("[LiTo] C_USE_SPELL Burning Slash rejected state"
                        + " player=" + playerName() + " hp=" + playerHp
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow)
                        + " phase=" + phase + " origin-phase=" + originPhase);
                return;
            }
            if (playerHp <= spell.hpCost()) {
                rejectionMessage = 279;
                refreshed = false;
            } else {
                cancelMeditation("spell-" + spell.skillId());
                refreshed = burningSlashStatus.activate(
                        castNow, spell.durationSeconds());
                playerHp -= spell.hpCost();
                commitSpellReady(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
            remainingHp = playerHp;
        }
        if (rejectionMessage != 0) {
            sendEncrypted(Protocol.messageCode(rejectionMessage),
                    "S_MESSAGE_CODE Burning-Slash-insufficient-hp="
                            + rejectionMessage);
            return;
        }

        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.phase != Phase.WORLD
                        || member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION Burning-Slash caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT Burning-Slash target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(remainingHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT Burning-Slash=" + remainingHp + "/" + playerMaxHp);
        broadcastOwnHitRatio("burning-slash-hp-cost");
        System.out.println("[LiTo] C_USE_SPELL Burning Slash caster="
                + playerName() + " selector=" + request.row() + "/"
                + request.column() + " duration=" + spell.durationSeconds()
                + " refreshed=" + refreshed + " hp-cost=" + spell.hpCost()
                + " hp=" + remainingHp + "/" + playerMaxHp
                + " next-melee-damage=" + spell.nextMeleeDamage()
                + " impact-gfx=" + spell.impactGfx()
                + " counter-magic-effective-bypass="
                + spell.counterMagicBypass() + " phase=" + originPhase
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

    /** Exact selected/retained object-target HPR buff for skill158. */
    private void useNaturesTouchSpell(
            byte[] payload, BattleSpellCatalog.NaturesTouchSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Natures-Touch-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Natures-Touch-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Natures-Touch-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Natures-Touch-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Natures-Touch-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())) {
            System.out.println("[LiTo] C_USE_SPELL rejected unlearned"
                    + " Nature's Touch player=" + playerName());
            return;
        }
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Nature's Touch rejected"
                    + " unavailable action player=" + playerName()
                    + " gfx=" + battleGfx() + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int casterBattleMap = originPhase == Phase.BATTLE
                ? hub.battleMapId(originRoomId, this) : 0;
        List<ClientSession> population = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.visibleBattleCombatants(originRoomId, this);
        ClientSession target = population.stream()
                .filter(candidate -> candidate.playerObjectId()
                        == request.targetObjectId())
                .findFirst().orElse(request.targetObjectId() == playerObjectId()
                        ? this : null);
        boolean validTarget = target != null && target.playerHp > 0
                && !target.observer
                && (!target.invisible || target == this)
                && BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, target.positionX, target.positionY)
                && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                        target.timedStatus.absoluteBarrierActive(requestNow),
                        spell.skillId())
                && (originPhase == Phase.WORLD
                    ? target.phase == Phase.WORLD
                        && target.classicWorldMapId == originMapId
                        && target.classicWorldInstanceId == originInstanceId
                    : target.phase == Phase.BATTLE
                        && target.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, target) == casterBattleMap);
        if (!validTarget) {
            sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                    "S_MESSAGE_CODE Natures-Touch-invalid-target="
                            + spell.failureMessage());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(), caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(originalReduction);
        ClientSession firstLock = playerObjectId() <= target.playerObjectId()
                ? this : target;
        ClientSession secondLock = firstLock == this ? target : this;
        int remainingMp;
        boolean refreshed;
        boolean consumedWaterLife;
        long castNow;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
                boolean stillValid = phase == originPhase && playerHp > 0
                        && !observer && playerMp >= mpCost
                        && target.playerHp > 0 && !target.observer
                        && (!target.invisible || target == this)
                        && BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                target.positionX, target.positionY)
                        && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                target.timedStatus.absoluteBarrierActive(castNow),
                                spell.skillId())
                        && (originPhase == Phase.WORLD
                            ? classicWorldMapId == originMapId
                                && classicWorldInstanceId == originInstanceId
                                && target.phase == Phase.WORLD
                                && target.classicWorldMapId == originMapId
                                && target.classicWorldInstanceId == originInstanceId
                            : currentRoomId == originRoomId
                                && target.phase == Phase.BATTLE
                                && target.currentRoomId == originRoomId
                                && hub.battleMapId(originRoomId, target)
                                    == casterBattleMap);
                if (castNow < readyAt || !stillValid) {
                    if (playerMp < mpCost) {
                        sendEncrypted(Protocol.messageCode(278),
                                "S_MESSAGE_CODE Natures-Touch-insufficient-mp=278");
                    } else {
                        sendEncrypted(Protocol.messageCode(spell.failureMessage()),
                                "S_MESSAGE_CODE Natures-Touch-state-failure="
                                        + spell.failureMessage());
                    }
                    return;
                }
                cancelMeditation("spell-" + spell.skillId());
                refreshed = target.naturesTouchStatus.activate(
                        castNow, spell.durationSeconds());
                // Retained L1SkillUse lists Nature's Touch with healing skills:
                // application consumes, rather than doubles, Water Life.
                consumedWaterLife = target.waterLifeStatus.cancel();
                playerMp -= mpCost;
                remainingMp = playerMp;
                commitSpellReady(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
            }
        }

        revealInvisibility("spell-" + spell.skillId());
        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(
                target.playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId) : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || !BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                member.positionX, member.positionY))) continue;
            member.sendEncrypted(action,
                    "S_ACTION Natures-Touch caster=" + playerObjectId()
                            + " action=" + spell.actionId());
            member.sendEncrypted(effect,
                    "S_EFFECT Natures-Touch target=" + target.playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Natures-Touch="
                        + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Nature's Touch caster="
                + playerName() + " selector=" + request.row() + "/"
                + request.column() + " target=" + target.playerName()
                + " duration=" + spell.durationSeconds()
                + " refreshed=" + refreshed
                + " natural-hpr=" + spell.hpRegenModifier()
                + " water-life-consumed=" + consumedWaterLife
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp + " counter-magic-bypass="
                + spell.counterMagicBypass() + " phase=" + originPhase
                + " persisted=false"
                + " icon=omitted-no-selected-LiTo-packetbox-receiver");
    }

    private void useWaterLifeSpell(byte[] byArray, BattleSpellCatalog.WaterLifeSpell waterLifeSpell) throws IOException {
        NativeWaterLifeCastAction.cast(this, byArray, waterLifeSpell);
    }

