    /** Exact LiTo.bin cccd inventory-object path for skill21 Blessed Armor. */
    private void useItemArmorEnchantSpell(
            byte[] payload, BattleSpellCatalog.ItemArmorEnchantSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        Phase originPhase = phase;
        String spellName = spell.displayName();
        if (request.skillId() != spell.skillId()) {
            System.out.println("[LiTo] C_USE_SPELL item armor enchant rejected"
                    + " selector player=" + playerName()
                    + " skill=" + request.skillId()
                    + " expected=" + spell.skillId());
            return;
        }
        if (originPhase == Phase.WORLD
                && !admitClassicWorldSpellFamily(
                        spell.skillId(), spell.actionId(), spellName)) {
            return;
        }
        if ((originPhase != Phase.BATTLE && originPhase != Phase.WORLD)
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL item armor enchant rejected"
                    + " phase/action player=" + playerName()
                    + " phase=" + originPhase + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(effectiveIntelligence, originalReduction);

        RuntimeInventory.Item selectedItem;
        boolean validBodyArmor;
        boolean equippedBodyArmor;
        int replacedSkill = 0;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || phase != originPhase || observer
                    || originPhase == Phase.BATTLE && currentRoomId != originRoomId
                    || originPhase == Phase.WORLD
                        && (classicWorldMapId != originMapId
                            || classicWorldInstanceId != originInstanceId)) {
                System.out.println("[LiTo] C_USE_SPELL item armor enchant rejected state"
                        + " player=" + playerName() + " mp=" + playerMp
                        + " phase=" + phase + " origin-phase=" + originPhase
                        + " mp-cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            selectedItem = inventory.item(request.targetObjectId());
            InventoryCatalog.NativeArmorStatus armor = selectedItem == null
                    ? null : selectedItem.definition().sourceArmorStatus();
            validBodyArmor = selectedItem != null
                    && selectedItem.definition().sourceArmor()
                    && armor != null && armor.armorType() == 2;
            equippedBodyArmor = validBodyArmor && selectedItem.equipped();
            cancelMeditation("spell-" + spell.skillId());
            if (validBodyArmor) {
                replacedSkill = itemArmorEnchantStatus.activate(
                        castNow, spell.durationSeconds(), spell.skillId(),
                        selectedItem.objectId(), selectedItem.nativeLogName(),
                        spell.armorClass());
            }
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }

        // Retained useConsume commits MP before runSkill validates _itemobjid.
        // An invalid object therefore reports 79 while preserving any lease
        // already bound to a different armor object.
        if (!validBodyArmor) {
            sendEncrypted(Protocol.messageCode(spell.invalidItemMessage()),
                    "S_MESSAGE_CODE " + spellName + "-invalid-item="
                            + spell.invalidItemMessage());
        } else {
            sendEncrypted(Protocol.messageCode(
                            spell.successMessage(), selectedItem.nativeLogName(),
                            "$245", "$247"),
                    "S_MESSAGE_CODE " + spellName + "-success="
                            + spell.successMessage() + " armor="
                            + selectedItem.nativeLogName());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT " + spellName + "="
                        + remainingMp + "/" + playerMaxMp);
        if (equippedBodyArmor) {
            sendEncrypted(ownCharacterAttrDef(),
                    "S_AC " + spellName + " current=" + battleArmorClass());
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        List<ClientSession> recipients = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomMembers(originRoomId);
        for (ClientSession member : recipients) {
            if (originPhase == Phase.WORLD
                    && (member.phase != Phase.WORLD
                        || member.classicWorldMapId != originMapId
                        || member.classicWorldInstanceId != originInstanceId
                        || member != this && !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                member.positionX, member.positionY))) {
                continue;
            }
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION " + spellName + " caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT " + spellName + " target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        System.out.println("[LiTo] C_USE_SPELL " + spellName + " caster="
                + playerName() + " item=" + request.targetObjectId()
                + " armor=" + validBodyArmor + " equipped=" + equippedBodyArmor
                + " phase=" + originPhase + " replaced-skill=" + replacedSkill
                + " duration=" + (validBodyArmor ? spell.durationSeconds() : 0)
                + " armor-class=" + (validBodyArmor ? spell.armorClass() : 0)
                + " cancellation-immune=true"
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/" + playerMaxMp);
    }

