    /**
     * Exact retained skill23 Reveal Weakness flow for real monster actors.
     * The selected client emits target-only cccd.  The spell commits no
     * target state and does not enter Counter Magic: its TYPE_BUFF result is
     * the generic target gfx2510 followed by one weak-attribute effect per
     * low nibble bit in retained earth/fire/water/wind order.
     */
    private void useRevealWeaknessSpell(
            byte[] payload, BattleSpellCatalog.RevealWeaknessSpell spell)
            throws IOException {
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.maximumRange() != -1) return;

        Phase originPhase = phase;
        if (originPhase != Phase.BATTLE && originPhase != Phase.WORLD) return;
        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Reveal-Weakness-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Reveal-Weakness-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=Reveal-Weakness-Silence-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE Reveal-Weakness-Silence-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE Reveal-Weakness-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected"
                    + " learned/action player=" + playerName());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        long originRoomId = currentRoomId;
        ClassicWorldMonsterPopulation.Snapshot worldMonster = null;
        BattleQuestEncounter.Snapshot questMonster = null;
        BattleTimeAttackEncounter.Snapshot timeMonster = null;
        if (originPhase == Phase.WORLD) {
            worldMonster = hub.classicWorldMonster(
                    originMapId, originInstanceId, request.targetObjectId());
            if (worldMonster == null || !worldMonster.present()
                    || !worldMonster.alive()
                    || worldMonster.mapId() != originMapId) {
                System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected"
                        + " unknown/dead WORLD monster="
                        + request.targetObjectId());
                return;
            }
        } else {
            questMonster = hub.questMonster(originRoomId,
                    request.targetObjectId());
            timeMonster = hub.timeAttackActor(originRoomId,
                    request.targetObjectId());
            int matches = (questMonster != null && questMonster.alive() ? 1 : 0)
                    + (timeMonster != null && timeMonster.alive() ? 1 : 0);
            if (matches != 1) {
                System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected"
                        + " unknown/ambiguous BATTLE monster="
                        + request.targetObjectId() + " matches=" + matches);
                return;
            }
        }

        int targetX = worldMonster != null ? worldMonster.x()
                : questMonster != null ? questMonster.x() : timeMonster.x();
        int targetY = worldMonster != null ? worldMonster.y()
                : questMonster != null ? questMonster.y() : timeMonster.y();
        int npcId = worldMonster != null ? worldMonster.npcId()
                : questMonster != null ? questMonster.npcId() : timeMonster.npcId();
        if (!BattleSpellCatalog.isInNativeScreen(
                positionX, positionY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected"
                    + " native-screen target=" + request.targetObjectId());
            return;
        }

        int weakAttribute;
        if (worldMonster != null) {
            weakAttribute = worldMonster.template().weakAttribute();
        } else {
            SourceNpcPhysicalStats sourceStats;
            try {
                sourceStats = selectedSourceAccounts().npcPhysicalStats(npcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected"
                        + " source NPC lookup failed npc=" + npcId
                        + " reason=" + sourceFailure.getMessage());
                return;
            }
            if (sourceStats == null) {
                System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected"
                        + " source NPC row missing npc=" + npcId);
                return;
            }
            weakAttribute = sourceStats.weakAttribute();
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = equipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean originStable = phase == originPhase && playerHp > 0 && !observer
                    && (originPhase == Phase.WORLD
                        ? classicWorldMapId == originMapId
                            && classicWorldInstanceId == originInstanceId
                        : currentRoomId == originRoomId);
            if (!originStable || castNow < readyAt || playerMp < mpCost) {
                if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE Reveal-Weakness-insufficient-mp=278");
                }
                System.out.println("[LiTo] C_USE_SPELL Reveal Weakness rejected state"
                        + " target=" + request.targetObjectId() + " mp=" + playerMp
                        + " cost=" + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation("spell-" + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        List<ClientSession> recipients;
        if (originPhase == Phase.WORLD) {
            recipients = new ArrayList<>();
            for (ClientSession member : classicWorldMembers(originMapId)) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                positionX, positionY)
                            && !BattleSpellCatalog.isInNativeScreen(
                                    member.positionX, member.positionY,
                                    targetX, targetY)) continue;
                recipients.add(member);
            }
        } else {
            recipients = questMonster != null
                    ? hub.battleRecipients(originRoomId, questMonster.force())
                    : hub.roomMembers(originRoomId);
        }

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] castEffect = Protocol.effectObject(
                request.targetObjectId(), spell.effectGfx());
        int[] weaknessEffects = spell.weaknessEffects(weakAttribute);
        for (ClientSession member : recipients) {
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION Reveal-Weakness caster=" + playerObjectId()
                                + " action=" + spell.actionId());
            }
            member.sendEncrypted(castEffect,
                    "S_EFFECT Reveal-Weakness target=" + request.targetObjectId()
                            + " gfx=" + spell.effectGfx());
            for (int weaknessEffect : weaknessEffects) {
                member.sendEncrypted(Protocol.effectObject(
                                request.targetObjectId(), weaknessEffect),
                        "S_EFFECT Reveal-Weakness weak-attribute="
                                + weakAttribute + " target="
                                + request.targetObjectId() + " gfx="
                                + weaknessEffect);
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Reveal-Weakness="
                        + remainingMp + "/" + playerMaxMp);
        System.out.println("[LiTo] C_USE_SPELL Reveal Weakness caster="
                + playerName() + " target=" + request.targetObjectId()
                + " npc=" + npcId + " weak-attribute=" + weakAttribute
                + " weak-effects=" + weaknessEffects.length
                + " counter-magic-consumed=false damage=0"
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp + " phase=" + originPhase);
    }

    /**
     * Exact retained skill13 Detection flow in both playable phases. LiTo.bin
     * emits selector-only {@code 14 01 04}; the target=none spell attaches its
     * action19/gfx749 cast effect to the caster, then independently removes
     * invisibility from every non-GM player in the native visible screen. This
     * server has no GM-invisibility state, so all ordinary invisible players
     * qualify. Ordinary WORLD also executes the retained sink-NPC and
     * WorldTrap branches from the selected spawn populations.
     */
    private void useDetectionSpell(
            byte[] payload, BattleSpellCatalog.DetectionSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId() || spell.nativeArea() != -1) return;

        Phase originPhase = phase;
        long originRoomId = currentRoomId;
        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int battleMap = 0;
        if (originPhase == Phase.WORLD) {
            if (!admitClassicWorldSpellFamily(
                    spell.skillId(), spell.actionId(), "Detection")) return;
        } else if (originPhase == Phase.BATTLE) {
            if (!BattleAnimationCatalog.get().supportsTimedAction(
                    battleGfx(), spell.actionId())) {
                System.out.println("[LiTo] C_USE_SPELL Detection rejected action"
                        + " player=" + playerName() + " gfx=" + battleGfx()
                        + " action=" + spell.actionId());
                return;
            }
            battleMap = hub.battleMapId(originRoomId, this);
        } else {
            return;
        }

        final int originBattleMap = battleMap;
        List<ClientSession> phaseMembers = originPhase == Phase.WORLD
                ? classicWorldMembers(originMapId)
                : hub.roomMembers(originRoomId);
        List<ClientSession> recipients = phaseMembers.stream()
                .filter(member -> originPhase == Phase.WORLD
                        ? member.phase == Phase.WORLD
                            && member.classicWorldMapId == originMapId
                            && member.classicWorldInstanceId == originInstanceId
                        : member.phase == Phase.BATTLE
                            && member.currentRoomId == originRoomId
                            && hub.battleMapId(originRoomId, member) == originBattleMap)
                .filter(member -> BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, positionX, positionY))
                .toList();
        List<ClientSession> revealTargets = recipients.stream()
                .filter(candidate -> candidate != this && !candidate.observer
                        && candidate.playerHp > 0 && candidate.invisible)
                .toList();

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveIntelligence = equipment.effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                caster == null ? 0 : caster.type(),
                caster == null ? 0 : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction,
                inventory.hasEquippedCatalog(InventoryCatalog.STRENGTH_MAGIC_HELM));

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            boolean originChanged = phase != originPhase || playerHp <= 0 || observer
                    || originPhase == Phase.WORLD
                        && (classicWorldMapId != originMapId
                            || classicWorldInstanceId != originInstanceId)
                    || originPhase == Phase.BATTLE
                        && currentRoomId != originRoomId;
            if (castNow < readyAt || playerMp < mpCost || originChanged) {
                System.out.println("[LiTo] C_USE_SPELL Detection rejected state"
                        + " phase=" + phase + " mp=" + playerMp
                        + " mp-cost=" + mpCost + " hp=" + playerHp
                        + " cooldownNanos=" + Math.max(0L, readyAt - castNow));
                return;
            }
            cancelMeditation((originPhase == Phase.WORLD
                    ? "classic-world-spell-" : "spell-") + spell.skillId());
            playerMp -= mpCost;
            remainingMp = playerMp;
            commitSpellReady(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelAbsoluteBarrier((originPhase == Phase.WORLD
                ? "classic-world-spell-" : "spell-") + spell.skillId());

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(playerObjectId(), spell.effectGfx());
        for (ClientSession member : recipients) {
            member.sendEncrypted(action,
                    "S_ACTION " + (originPhase == Phase.WORLD
                            ? "classic-world " : "")
                            + "Detection caster=" + playerObjectId());
            member.sendEncrypted(effect,
                    "S_EFFECT " + (originPhase == Phase.WORLD
                            ? "classic-world " : "")
                            + "Detection target=" + playerObjectId()
                            + " gfx=" + spell.effectGfx());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT " + (originPhase == Phase.WORLD
                        ? "classic-world " : "")
                        + "Detection=" + remainingMp + "/" + playerMaxMp);

        ClassicWorldDetectionContext worldContext = originPhase == Phase.WORLD
                ? applyClassicWorldDetectionContext(
                        originMapId, originInstanceId,
                        positionX, positionY,
                        "native-detection-" + spell.skillId())
                : new ClassicWorldDetectionContext(0, 0, 0);

        int revealed = 0;
        for (ClientSession target : revealTargets) {
            boolean stillPresent = originPhase == Phase.WORLD
                    ? target.phase == Phase.WORLD
                        && target.classicWorldMapId == originMapId
                        && target.classicWorldInstanceId == originInstanceId
                    : target.phase == Phase.BATTLE
                        && target.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, target) == originBattleMap;
            if (!stillPresent || !BattleSpellCatalog.isInNativeScreen(
                    positionX, positionY, target.positionX, target.positionY)
                    || !target.cancelInvisibilityState()) continue;
            target.publishInvisibilityReveal((originPhase == Phase.WORLD
                    ? "classic-world-detection-" : "detection-") + spell.skillId());
            revealed++;
        }
        System.out.println("[LiTo] C_USE_SPELL Detection skill=" + spell.skillId()
                + " caster=" + playerName() + " phase=" + originPhase
                + " selector=" + request.row() + "/" + request.column()
                + " native-area=" + spell.nativeArea()
                + " reveal-candidates=" + revealTargets.size()
                + " explicitly-revealed=" + revealed
                + " damage-targets=0 counter-magic-exempt=true"
                + " hidden-sink-reveals=" + worldContext.hiddenReveals()
                + " trap-activations=" + worldContext.trapActivations()
                + " trap-effects=" + worldContext.trapEffects()
                + " effective-int=" + effectiveIntelligence
                + " strength-magic-helm="
                + inventory.hasEquippedCatalog(InventoryCatalog.STRENGTH_MAGIC_HELM)
                + " mp-cost=" + mpCost + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

    /**
     * Exact retained skill72 flow for the ordinary imported WORLD. LiTo.bin
     * emits selector-only {@code 14 08 07}; the spell independently reveals
     * every invisible player in the native screen, while damage is admitted
     * only for an invisible player in the ordinary combat zone. The retained
     * source gives ordinary NPCs an animation target with zero damage, reveals
     * HIDDEN_STATUS_SINK actors, and invokes the selected WorldTrap registry.
     */
    private void useClassicWorldCounterDetectionSpell(
            byte[] payload, BattleSpellCatalog.CounterDetectionSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId() || spell.nativeArea() != -1) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(), "Counter-Detection")) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        int originHeading = playerHeading & 7;
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        Map<ClientSession, ArenaMapCatalog.Point> playerCells =
                new LinkedHashMap<>();
        classicWorldMembers(originMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && !candidate.observer
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.positionX, candidate.positionY))
                .forEach(candidate -> playerCells.put(candidate,
                        new ArenaMapCatalog.Point(
                                candidate.positionX, candidate.positionY)));
        List<ClassicWorldMonsterPopulation.Snapshot> monsterTargets =
                hub.classicWorldMonstersInScreen(
                                originMapId, originInstanceId,
                                originX, originY).stream()
                        .filter(candidate -> candidate.present() && candidate.alive())
                        .toList();

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || observer || phase != Phase.WORLD
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || positionX != originX || positionY != originY
                    || !counterDetectionCasterStillAdmitted(
                            Phase.WORLD, spell, castNow)) {
                System.out.println("[LiTo] C_USE_SPELL classic-world Counter"
                        + " Detection rejected state mp=" + playerMp
                        + " mp-cost=" + mpCost + " hp=" + playerHp
                        + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            playerMp -= mpCost;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        ClassicWorldDetectionContext worldContext =
                applyClassicWorldDetectionContext(
                        originMapId, originInstanceId, originX, originY,
                        "native-counter-detection-" + spell.skillId());

        Map<ClientSession, Integer> playerDamages = new LinkedHashMap<>();
        List<ClientSession> revealTargets = new ArrayList<>();
        List<Protocol.AttackManyTarget> wireTargets = new ArrayList<>();
        for (Map.Entry<ClientSession, ArenaMapCatalog.Point> entry
                : playerCells.entrySet()) {
            ClientSession target = entry.getKey();
            ArenaMapCatalog.Point cell = entry.getValue();
            synchronized (target) {
                boolean stillVisible = target.phase == Phase.WORLD
                        && target.classicWorldMapId == originMapId
                        && target.classicWorldInstanceId == originInstanceId
                        && !target.observer
                        && target.positionX == cell.x()
                        && target.positionY == cell.y()
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY, cell.x(), cell.y());
                if (!stillVisible || !target.invisible) continue;
                revealTargets.add(target);
                if (target.playerHp <= 0
                        || !map.isNormalZone(originX, originY)
                        || !map.isNormalZone(cell.x(), cell.y())
                        || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                target.timedStatus.absoluteBarrierActive(castNow),
                                spell.skillId())) continue;
                // Retained COUNTER_DETECTION admits an invisible PC before
                // the ordinary PK/war and glanceCheck gates.
                int sourceDamage = spell.rollDamage(sides ->
                        ThreadLocalRandom.current().nextInt(1, sides + 1));
                int damage = ordinaryMagicDamage(
                        spell.skillId(), spell.attribute(), sourceDamage,
                        target.effectiveSpellElementalResistance(
                                spell.attribute()),
                        target.effectiveBaseMagicResistance(castNow),
                        target.effectiveArmorMagicReductionBase(),
                        "classic-world-player=" + target.playerName());
                damage = target.combatDamageAfterCooking(
                        damage, "classic-world-counter-detection-"
                                + spell.skillId());
                damage = target.earthBindProtectedCombatDamage(
                        damage, "classic-world-counter-detection-"
                                + spell.skillId());
                playerDamages.put(target, damage);
                wireTargets.add(new Protocol.AttackManyTarget(
                        target.playerObjectId(), true));
            }
        }
        int npcAnimationTargets = 0;
        for (ClassicWorldMonsterPopulation.Snapshot identity : monsterTargets) {
            ClassicWorldMonsterPopulation.Snapshot target =
                    hub.classicWorldMonster(
                            originMapId, originInstanceId, identity.objectId());
            if (target == null || !target.present() || !target.alive()
                    || target.x() != identity.x() || target.y() != identity.y()
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, target.x(), target.y())
                    || !map.attackPosition(originX, originY,
                            target.x(), target.y(), 19)) continue;
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.objectId(), true));
            npcAnimationTargets++;
        }

        List<ClientSession> recipients = hub.classicWorldMembers(
                        originMapId, originInstanceId).stream()
                .filter(member -> member.phase == Phase.WORLD
                        && member.classicWorldMapId == originMapId
                        && member.classicWorldInstanceId == originInstanceId
                        && BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY))
                .toList();
        long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
        if (wireTargets.isEmpty()) {
            byte[] action = Protocol.objectAction(
                    playerObjectId(), spell.actionId());
            for (ClientSession member : recipients) {
                if (invisible && member != this) continue;
                member.sendEncrypted(action,
                        "S_ACTION classic-world Counter-Detection-empty caster="
                                + playerObjectId());
            }
        } else {
            byte[] attack = Protocol.attackMany(
                    spell.actionId(), playerObjectId(), originX, originY,
                    originHeading, sequence, spell.effectGfx(), 0,
                    wireTargets);
            for (ClientSession member : recipients) {
                member.sendEncrypted(attack,
                        "S_ATTACK_MANY classic-world Counter-Detection caster="
                                + playerObjectId() + " targets="
                                + wireTargets.size() + " gfx="
                                + spell.effectGfx() + " type=0 sequence="
                                + sequence + " counter-magic-exempt=true");
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world Counter-Detection="
                        + remainingMp + "/" + playerMaxMp);

        for (Map.Entry<ClientSession, Integer> entry : playerDamages.entrySet()) {
            entry.getKey().takeClassicWorldPlayerDamage(
                    entry.getValue(), this, false);
        }
        int revealed = 0;
        for (ClientSession target : revealTargets) {
            if (!sameClassicWorldMap(target)
                    || !target.cancelInvisibilityState()) continue;
            target.publishInvisibilityReveal(
                    "classic-world-counter-detection-" + spell.skillId());
            revealed++;
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world Counter Detection"
                + " skill=" + spell.skillId() + " caster=" + playerName()
                + " selector=" + request.row() + "/" + request.column()
                + " native-area=" + spell.nativeArea()
                + " damage-targets=" + playerDamages.size()
                + " npc-animation-targets=" + npcAnimationTargets
                + " counter-magic-exempt=true"
                + " reveal-candidates=" + revealTargets.size()
                + " explicitly-revealed=" + revealed
                + " hidden-sink-reveals=" + worldContext.hiddenReveals()
                + " trap-activations=" + worldContext.trapActivations()
                + " trap-effects=" + worldContext.trapEffects()
                + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

    /**
     * Exact retained COUNTER_DETECTION flow. LiTo.bin sends only ccc
     * (14 08 07); area=-1 is the classic visible screen. Every visible
     * invisible player is revealed. Retained EXCEPT_COUNTER_MAGIC explicitly
     * includes skill 72, and an invisible PC in a non-safe combat zone bypasses
     * the ordinary PK/war target gate. Ordinary visible NPCs remain animation
     * targets with no damage, as in retained L1SkillUse.
     */
    private void useCounterDetectionSpell(
            byte[] payload, BattleSpellCatalog.CounterDetectionSpell spell)
            throws IOException {
        Protocol.SpellSelector request = Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId() || spell.nativeArea() != -1) return;
        if (!BattleAnimationCatalog.get().supportsTimedAction(
                battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL Counter Detection rejected action"
                    + " player=" + playerName() + " gfx=" + battleGfx()
                    + " action=" + spell.actionId());
            return;
        }

        long originRoomId = currentRoomId;
        int originMapId = hub.battleMapId(originRoomId, this);
        int originX = positionX;
        int originY = positionY;
        int originHeading = playerHeading & 7;
        ArenaMapCatalog.Arena arena = ArenaMapCatalog.forMap(originMapId);
        Map<ClientSession, ArenaMapCatalog.Point> playerCells =
                new LinkedHashMap<>();
        List<ClientSession> combatants = hub.roomCombatants(originRoomId);
        combatants.stream()
                .filter(candidate -> candidate != this
                        && candidate.phase == Phase.BATTLE && !candidate.observer
                        && candidate.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, candidate) == originMapId
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.positionX, candidate.positionY))
                .forEach(candidate -> playerCells.put(candidate,
                        new ArenaMapCatalog.Point(
                                candidate.positionX, candidate.positionY)));

        // Retained non-SINK NPCs stay in the range animation with zero damage.
        // Tournament actors have no sourced HIDDEN_STATUS_SINK/trap state, so
        // this method deliberately does not invent an appear-on-ground model.
        List<BattleGuardianTower.Snapshot> towerTargets =
                hub.visibleGuardianTowers(originRoomId, this).stream()
                        .filter(candidate -> hub.canAttackGuardianTower(
                                originRoomId, this, candidate.objectId())
                                && BattleSpellCatalog.isInNativeScreen(
                                        originX, originY,
                                        candidate.x(), candidate.y()))
                        .toList();
        List<BattleQuestEncounter.Snapshot> questTargets =
                hub.visibleQuestMonsters(originRoomId, this).stream()
                        .filter(candidate -> hub.canAttackQuestMonster(
                                originRoomId, this, candidate.objectId())
                                && BattleSpellCatalog.isInNativeScreen(
                                        originX, originY,
                                        candidate.x(), candidate.y()))
                        .toList();
        List<BattleTimeAttackEncounter.Snapshot> timeTargets =
                hub.visibleTimeAttackActors(originRoomId, this).stream()
                        .filter(candidate -> hub.canAttackTimeAttackActor(
                                originRoomId, this, candidate.objectId())
                                && BattleSpellCatalog.isInNativeScreen(
                                        originX, originY,
                                        candidate.x(), candidate.y()))
                        .toList();
        boolean botTarget = hub.roomRules(originRoomId).mode()
                != BattleRules.Mode.QUEST_BATTLE
                && hub.roomRules(originRoomId).mode()
                    != BattleRules.Mode.TIME_ATTACK
                && hub.roomCombatantCount(originRoomId) < 2;
        ArenaMapCatalog.Point bot = botTarget
                ? hub.botPosition(originRoomId) : null;
        if (bot == null && botTarget) {
            bot = arena.botSpawn();
        }
        botTarget = botTarget && bot != null
                && BattleSpellCatalog.isInNativeScreen(
                        originX, originY, bot.x(), bot.y());
        ArenaMapCatalog.Point botIdentity = bot;

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment = requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment.effectiveIntelligence(
                baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || playerMp < mpCost || playerHp <= 0
                    || phase != Phase.BATTLE || observer
                    || currentRoomId != originRoomId
                    || hub.battleMapId(originRoomId, this) != originMapId
                    || positionX != originX || positionY != originY
                    || !counterDetectionCasterStillAdmitted(
                            Phase.BATTLE, spell, castNow)) {
                System.out.println("[LiTo] C_USE_SPELL Counter Detection rejected state"
                        + " mp=" + playerMp + " mp-cost=" + mpCost
                        + " hp=" + playerHp + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            playerMp -= mpCost;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("spell-" + spell.skillId());
        cancelAbsoluteBarrier("spell-" + spell.skillId());
        revealInvisibility("spell-" + spell.skillId());

        Map<ClientSession, Integer> playerDamages = new LinkedHashMap<>();
        List<ClientSession> revealTargets = new ArrayList<>();
        List<Protocol.AttackManyTarget> wireTargets = new ArrayList<>();
        for (Map.Entry<ClientSession, ArenaMapCatalog.Point> entry
                : playerCells.entrySet()) {
            ClientSession target = entry.getKey();
            ArenaMapCatalog.Point cell = entry.getValue();
            synchronized (target) {
                boolean stillVisible = target.phase == Phase.BATTLE
                        && target.currentRoomId == originRoomId
                        && !target.observer
                        && hub.battleMapId(originRoomId, target) == originMapId
                        && target.positionX == cell.x()
                        && target.positionY == cell.y()
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY, cell.x(), cell.y());
                if (!stillVisible) continue;
                boolean hidden = target.invisible;
                if (hidden) revealTargets.add(target);
                boolean lineOfSight = hidden
                        || BattleSpellCatalog.hasNativeLineOfSight(
                                arena, originX, originY, cell.x(), cell.y());
                if (target.playerHp <= 0 || !lineOfSight
                        || (!hidden
                            && !hub.canAttack(originRoomId, this, target))
                        || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                target.timedStatus.absoluteBarrierActive(castNow),
                                spell.skillId())) continue;
                int sourceDamage = spell.rollDamage(sides ->
                        ThreadLocalRandom.current().nextInt(1, sides + 1));
                int damage = ordinaryMagicDamage(
                        spell.skillId(), spell.attribute(), sourceDamage,
                        target.effectiveSpellElementalResistance(
                                spell.attribute()),
                        target.effectiveBaseMagicResistance(castNow),
                        target.effectiveArmorMagicReductionBase(),
                        "player=" + target.playerName());
                damage = target.combatDamageAfterCooking(
                        damage, "counter-detection-" + spell.skillId());
                damage = target.earthBindProtectedCombatDamage(
                        damage, "counter-detection-" + spell.skillId());
                playerDamages.put(target, damage);
                wireTargets.add(new Protocol.AttackManyTarget(
                        target.playerObjectId(), true));
            }
        }
        int npcAnimationTargets = 0;
        for (BattleGuardianTower.Snapshot identity : towerTargets) {
            BattleGuardianTower.Snapshot target = hub.guardianTower(
                    originRoomId, identity.objectId());
            if (target == null || target.hp() <= 0
                    || target.x() != identity.x() || target.y() != identity.y()
                    || !hub.canAttackGuardianTower(
                            originRoomId, this, target.objectId())
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, target.x(), target.y())
                    || !BattleSpellCatalog.hasNativeLineOfSight(
                            arena, originX, originY, target.x(), target.y())) continue;
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.objectId(), true));
            npcAnimationTargets++;
        }
        for (BattleQuestEncounter.Snapshot identity : questTargets) {
            BattleQuestEncounter.Snapshot target = hub.questMonster(
                    originRoomId, identity.objectId());
            if (target == null || !target.alive()
                    || target.x() != identity.x() || target.y() != identity.y()
                    || !hub.canAttackQuestMonster(
                            originRoomId, this, target.objectId())
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, target.x(), target.y())
                    || !BattleSpellCatalog.hasNativeLineOfSight(
                            arena, originX, originY, target.x(), target.y())) continue;
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.objectId(), true));
            npcAnimationTargets++;
        }
        for (BattleTimeAttackEncounter.Snapshot identity : timeTargets) {
            BattleTimeAttackEncounter.Snapshot target = hub.timeAttackActor(
                    originRoomId, identity.objectId());
            if (target == null || !target.alive()
                    || target.x() != identity.x() || target.y() != identity.y()
                    || !hub.canAttackTimeAttackActor(
                            originRoomId, this, target.objectId())
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, target.x(), target.y())
                    || !BattleSpellCatalog.hasNativeLineOfSight(
                            arena, originX, originY, target.x(), target.y())) continue;
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.objectId(), true));
            npcAnimationTargets++;
        }
        if (botTarget) {
            ArenaMapCatalog.Point currentBot = hub.botPosition(originRoomId);
            if (currentBot == null) currentBot = arena.botSpawn();
            if (currentBot != null && botIdentity != null
                    && currentBot.equals(botIdentity)
                    && BattleSpellCatalog.hasNativeLineOfSight(
                            arena, originX, originY,
                            currentBot.x(), currentBot.y())) {
                wireTargets.add(new Protocol.AttackManyTarget(2, true));
                npcAnimationTargets++;
            }
        }

        List<ClientSession> recipients = hub.roomMembers(originRoomId).stream()
                .filter(member -> member.phase == Phase.BATTLE
                        && member.currentRoomId == originRoomId
                        && hub.battleMapId(originRoomId, member) == originMapId
                        && BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY))
                .toList();
        long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
        if (wireTargets.isEmpty()) {
            byte[] action = Protocol.objectAction(
                    playerObjectId(), spell.actionId());
            for (ClientSession member : recipients) {
                if (invisible && member != this) continue;
                member.sendEncrypted(action,
                        "S_ACTION Counter-Detection-empty caster="
                                + playerObjectId());
            }
        } else {
            byte[] attack = Protocol.attackMany(
                    spell.actionId(), playerObjectId(), originX, originY,
                    originHeading, sequence, spell.effectGfx(), 0,
                    wireTargets);
            for (ClientSession member : recipients) {
                member.sendEncrypted(attack,
                        "S_ATTACK_MANY Counter-Detection caster="
                                + playerObjectId() + " targets="
                                + wireTargets.size() + " gfx="
                                + spell.effectGfx() + " type=0 sequence="
                                + sequence
                                + " counter-magic-exempt=true");
            }
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT Counter-Detection="
                        + remainingMp + "/" + playerMaxMp);

        for (Map.Entry<ClientSession, Integer> entry : playerDamages.entrySet()) {
            entry.getKey().takePlayerDamage(entry.getValue(), this);
        }
        int revealed = 0;
        for (ClientSession target : revealTargets) {
            if (!target.cancelInvisibilityState()) continue;
            target.publishInvisibilityReveal("counter-detection-" + spell.skillId());
            revealed++;
        }
        System.out.println("[LiTo] C_USE_SPELL Counter Detection skill="
                + spell.skillId() + " caster=" + playerName()
                + " selector=" + request.row() + "/" + request.column()
                + " native-area=" + spell.nativeArea()
                + " damage-targets=" + playerDamages.size()
                + " npc-animation-targets=" + npcAnimationTargets
                + " counter-magic-exempt=true"
                + " reveal-candidates=" + revealTargets.size()
                + " explicitly-revealed=" + revealed
                + " trap-detection=context-unavailable-on-current-arena"
                + " effective-int=" + effectiveIntelligence
                + " mp-cost=" + mpCost + " mp=" + remainingMp
                + "/" + playerMaxMp);
    }

