    private List<ClassicWorldMonsterPopulation.Snapshot>
            classicCastleTrebuchetsInScreen(
                    String source, int mapId, int x, int y) {
        List<ClassicWorldMonsterPopulation.Snapshot> result = new ArrayList<>();
        for (ClassicWorldCastleWarField.WarObject object
                : hub.classicCastleWarObjectsInScreen(source, mapId, x, y)) {
            if (object.kind() != ClassicWorldCastleWarField.Kind.TREBUCHET
                    || object.currentHp() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot snapshot =
                    hub.classicCastleTrebuchetCombatSnapshot(
                            source, mapId, object.objectId());
            if (snapshot != null && snapshot.present() && snapshot.alive()
                    && snapshot.mapId() == mapId) {
                result.add(snapshot);
            }
        }
        return List.copyOf(result);
    }

    /**
     * Rebuilds every live retained {@code L1TowerInstance} in native screen
     * from the authoritative castle-war field.  Towers deliberately remain a
     * distinct receiver: they own no monster hate, reward or timed-status
     * state, but attack magic still commits through their native damage
     * lifecycle.
     */
    private List<ClassicWorldMonsterPopulation.Snapshot>
            classicCastleTowersInScreen(
                    String source, int mapId, int x, int y) {
        List<ClassicWorldMonsterPopulation.Snapshot> result = new ArrayList<>();
        for (ClassicWorldCastleWarField.WarObject object
                : hub.classicCastleWarObjectsInScreen(source, mapId, x, y)) {
            if (object.kind() != ClassicWorldCastleWarField.Kind.TOWER
                    || object.currentHp() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot snapshot =
                    hub.classicCastleTowerCombatSnapshot(
                            source, mapId, object.objectId());
            if (snapshot != null && snapshot.present() && snapshot.alive()
                    && snapshot.mapId() == mapId) {
                result.add(snapshot);
            }
        }
        return List.copyOf(result);
    }

    private ClassicWorldMonsterPopulation.Snapshot currentClassicCastleTower(
            ClassicWorldMonsterPopulation.Snapshot target) {
        if (target == null) return null;
        ClassicWorldMonsterPopulation.Snapshot current =
                hub.classicCastleTowerCombatSnapshot(
                        selectedClassicServerName, target.mapId(),
                        target.objectId());
        return current == null || !current.present() || !current.alive()
                ? null : current;
    }

    /** Exact retained L1TowerInstance.receiveDamage authorization/lifecycle. */
    private int applyClassicWorldCastleTowerMagicDamage(
            ClassicWorldMonsterPopulation.Snapshot target, int damage)
            throws IOException {
        if (target == null || damage <= 0) return 0;
        ClassicWorldCastleWarField.WarObject objective =
                hub.classicCastleWarObject(
                        selectedClassicServerName, target.mapId(),
                        target.objectId());
        if (objective == null
                || objective.kind() != ClassicWorldCastleWarField.Kind.TOWER
                || objective.currentHp() <= 0) return 0;
        CastleSummary defender;
        try {
            defender = effectiveClassicCastleById(objective.castleId());
        } catch (Exception error) {
            throw new IOException("castle defender lookup failed", error);
        }
        String attackerClan = hub.clanData(sourceCharacterIdentity()).name();
        ClassicWorldCastleWarField.TowerHit hit =
                hub.damageClassicCastleTower(
                        selectedClassicServerName, target.mapId(),
                        target.objectId(), attackerClan,
                        defender == null ? "" : defender.clanName(), damage);
        if (hit != null && hit.appliedDamage() > 0) {
            publishClassicCastleTowerHit(hit);
        }
        return hit == null ? 0 : hit.appliedDamage();
    }

    /**
     * Rebuilds every destructible retained {@code L1DoorInstance} as a magic
     * target from the authoritative door state.  The combat proxy places the
     * actor on the nearest retained entrance edge, matching the direct-spell
     * and physical routes without allowing a cast through a closed gate.
     */
    private List<ClassicWorldAreaCastleDoorTarget>
            classicCastleDoorMagicTargets(
                    int mapId, int casterX, int casterY) {
        Map<Long, ClassicWorldAreaCastleDoorTarget> result =
                new LinkedHashMap<>();
        for (ClassicWorldDwarfCastleDoorState.Snapshot door
                : hub.dwarfCastleDoors()) {
            if (door.definition().mapId() != mapId) continue;
            ClassicWorldMonsterPopulation.Snapshot combat =
                    hub.dwarfCastleDoorCombatSnapshot(
                            mapId, door.definition().objectId(),
                            casterX, casterY);
            if (combat != null) {
                result.put(combat.objectId(),
                        new ClassicWorldAreaCastleDoorTarget(
                                combat, true, null));
            }
        }
        for (ClassicWorldCastleDoorCombat.View door
                : hub.mainlandCastleDoors()) {
            if (door.definition().mapId() != mapId) continue;
            ClassicWorldCastleDoorCombat.Target target =
                    hub.mainlandCastleDoorCombatTarget(
                            mapId, door.definition().objectId(),
                            casterX, casterY);
            if (target != null) {
                result.put(target.combat().objectId(),
                        new ClassicWorldAreaCastleDoorTarget(
                                target.combat(), false,
                                target.view().definition().family()));
            }
        }
        for (ClassicWorldHeineCastleDoorState.Snapshot door
                : hub.heineCastleDoors()) {
            if (door.definition().mapId() != mapId) continue;
            ClassicWorldCastleDoorCombat.Target target =
                    hub.mainlandCastleDoorCombatTarget(
                            mapId, door.definition().objectId(),
                            casterX, casterY);
            if (target != null) {
                result.put(target.combat().objectId(),
                        new ClassicWorldAreaCastleDoorTarget(
                                target.combat(), false,
                                target.view().definition().family()));
            }
        }
        return List.copyOf(result.values());
    }

    private void applyClassicWorldAreaCastleDoorDamage(
            ClassicWorldAreaCastleDoorTarget target, int damage)
            throws IOException {
        if (target == null || damage <= 0) return;
        if (target.dwarf()) {
            ClassicWorldDwarfCastleDoorState.DoorHit hit =
                    hub.damageDwarfCastleDoor(
                            target.combat().mapId(),
                            target.combat().objectId(), damage);
            if (hit != null && hit.appliedDamage() > 0) {
                publishDwarfCastleDoorHit(hit);
            }
            return;
        }
        ClassicWorldCastleDoorCombat.Hit hit =
                hub.damageMainlandCastleDoor(
                        target.family(), target.combat().mapId(),
                        target.combat().objectId(), damage);
        if (hit != null && hit.appliedDamage() > 0) {
            publishMainlandCastleDoorHit(hit);
        }
    }

    private ClassicWorldAreaCastleDoorTarget
            currentClassicWorldAreaCastleDoorTarget(
                    ClassicWorldAreaCastleDoorTarget target,
                    int casterX, int casterY) {
        if (target == null) return null;
        if (target.dwarf()) {
            ClassicWorldMonsterPopulation.Snapshot combat =
                    hub.dwarfCastleDoorCombatSnapshot(
                            target.combat().mapId(),
                            target.combat().objectId(), casterX, casterY);
            return combat == null ? null
                    : new ClassicWorldAreaCastleDoorTarget(
                            combat, true, null);
        }
        ClassicWorldCastleDoorCombat.Target current =
                hub.mainlandCastleDoorCombatTarget(
                        target.combat().mapId(), target.combat().objectId(),
                        casterX, casterY);
        return current == null ? null
                : new ClassicWorldAreaCastleDoorTarget(
                        current.combat(), false,
                        current.view().definition().family());
    }

    /**
     * Retained selector-only, caster-centred area attack for ordinary WORLD.
     * The selected client sends no actor tail for range-zero spells, so every
     * target and coordinate is rebuilt from the authoritative map instance.
     */
    private void useClassicWorldCenteredAreaAttackSpell(
            byte[] payload, BattleSpellCatalog.AreaAttackSpell spell)
            throws IOException {
        Protocol.SpellSelector request =
                Protocol.selectorOnlySpellRequest(payload);
        if (request.skillId() != spell.skillId()
                || spell.maximumRange() != 0
                || spell.areaRadius() <= 0
                || spell.requestShape()
                    != BattleSpellCatalog.RequestShape.SELECTOR_ONLY) return;
        if (!admitClassicWorldSpellFamily(
                spell.skillId(), spell.actionId(),
                "centered-area-" + spell.key())) return;

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        int originHeading = playerHeading & 7;
        int radius = spell.areaRadius();
        long requestNow = System.nanoTime();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        List<ClientSession> worldMembers = classicWorldMembers(originMapId);

        List<ClientSession> playerTargets = worldMembers.stream()
                .filter(candidate -> candidate != this
                        && candidate.phase == Phase.WORLD
                        && candidate.classicWorldMapId == originMapId
                        && candidate.classicWorldInstanceId == originInstanceId
                        && candidate.playerHp > 0 && !candidate.observer
                        && !candidate.invisible
                        && map.isNormalZone(originX, originY)
                        && map.isNormalZone(
                                candidate.positionX, candidate.positionY)
                        && targetRange(originX, originY,
                                candidate.positionX, candidate.positionY)
                            <= radius
                        && BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.positionX, candidate.positionY)
                        && map.attackPosition(originX, originY,
                                candidate.positionX, candidate.positionY,
                                radius * 2)
                        && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                                candidate.timedStatus
                                    .absoluteBarrierActive(requestNow),
                                spell.skillId()))
                .toList();

        List<ClassicWorldAreaCompanionTarget> companionTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> monsterTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> trebuchetTargets =
                new ArrayList<>();
        List<ClassicWorldMonsterPopulation.Snapshot> castleTowerTargets =
                new ArrayList<>();
        List<ClassicWorldAreaCastleDoorTarget> castleDoorTargets =
                new ArrayList<>();
        Map<Long, SourceNpcPhysicalStats> monsterStats =
                new LinkedHashMap<>();
        try {
            if (map.isNormalZone(originX, originY)) {
                for (ClientSession owner : worldMembers) {
                    if (owner == this || owner.phase != Phase.WORLD
                            || owner.classicWorldMapId != originMapId
                            || owner.classicWorldInstanceId
                                != originInstanceId) continue;
                    for (BattleCompanion.Snapshot snapshot
                            : owner.classicWorldCompanionSnapshots()) {
                        if (!snapshot.kind().classicWorldEligible()
                                || !snapshot.active() || snapshot.hp() <= 0
                                || !map.isNormalZone(snapshot.x(), snapshot.y())
                                || targetRange(originX, originY,
                                        snapshot.x(), snapshot.y()) > radius
                                || !BattleSpellCatalog.isInNativeScreen(
                                        originX, originY,
                                        snapshot.x(), snapshot.y())
                                || !map.attackPosition(originX, originY,
                                        snapshot.x(), snapshot.y(),
                                        radius * 2)) continue;
                        BattleCompanion controlled =
                                owner.ownedCompanion(snapshot.objectId());
                        if (controlled == null) continue;
                        SourceNpcPhysicalStats stats = selectedSourceAccounts()
                                .npcPhysicalStats(snapshot.npcId());
                        if (stats == null) {
                            System.out.println("[LiTo] rejected classic-world"
                                    + " centered-area; companion source row"
                                    + " missing player=" + playerName()
                                    + " npc=" + snapshot.npcId());
                            return;
                        }
                        companionTargets.add(new ClassicWorldAreaCompanionTarget(
                                owner, controlled, snapshot, stats));
                    }
                }
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : hub.classicWorldMonstersInScreen(
                            originMapId, originInstanceId, originX, originY)) {
                if (!candidate.present() || !candidate.alive()
                        || candidate.mapId() != originMapId
                        || targetRange(originX, originY,
                                candidate.x(), candidate.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.x(), candidate.y())
                        || !map.attackPosition(originX, originY,
                                candidate.x(), candidate.y(),
                                radius * 2)) continue;
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(candidate.npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; monster source row missing"
                            + " player=" + playerName() + " npc="
                            + candidate.npcId());
                    return;
                }
                monsterTargets.add(candidate);
                monsterStats.put(candidate.objectId(), stats);
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : classicCastleTrebuchetsInScreen(
                            selectedClassicServerName, originMapId,
                            originX, originY)) {
                if (targetRange(originX, originY,
                            candidate.x(), candidate.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.x(), candidate.y())
                        || !map.attackPosition(originX, originY,
                                candidate.x(), candidate.y(), radius * 2)) {
                    continue;
                }
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(candidate.npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; trebuchet source row missing"
                            + " player=" + playerName() + " npc="
                            + candidate.npcId());
                    return;
                }
                trebuchetTargets.add(candidate);
                monsterStats.put(candidate.objectId(), stats);
            }
            for (ClassicWorldMonsterPopulation.Snapshot candidate
                    : classicCastleTowersInScreen(
                            selectedClassicServerName, originMapId,
                            originX, originY)) {
                if (targetRange(originX, originY,
                            candidate.x(), candidate.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY,
                                candidate.x(), candidate.y())
                        || !map.attackPosition(originX, originY,
                                candidate.x(), candidate.y(), radius * 2)) {
                    continue;
                }
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(candidate.npcId());
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; castle tower source row missing"
                            + " player=" + playerName() + " npc="
                            + candidate.npcId());
                    return;
                }
                castleTowerTargets.add(candidate);
                monsterStats.put(candidate.objectId(), stats);
            }
            for (ClassicWorldAreaCastleDoorTarget candidate
                    : classicCastleDoorMagicTargets(
                            originMapId, originX, originY)) {
                ClassicWorldMonsterPopulation.Snapshot combat =
                        candidate.combat();
                if (targetRange(originX, originY,
                            combat.x(), combat.y()) > radius
                        || !BattleSpellCatalog.isInNativeScreen(
                                originX, originY, combat.x(), combat.y())
                        || !map.attackPosition(originX, originY,
                                combat.x(), combat.y(), radius * 2)) {
                    continue;
                }
                SourceNpcPhysicalStats stats = selectedSourceAccounts()
                        .npcPhysicalStats(
                                ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID);
                if (stats == null) {
                    System.out.println("[LiTo] rejected classic-world"
                            + " centered-area; castle door source row missing"
                            + " player=" + playerName() + " npc="
                            + ClassicWorldCastleDoorCombat.NPC_TEMPLATE_ID);
                    return;
                }
                castleDoorTargets.add(candidate);
                monsterStats.put(combat.objectId(), stats);
            }
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] rejected classic-world centered-area;"
                    + " source NPC lookup failed player=" + playerName()
                    + " skill=" + spell.skillId() + " reason="
                    + sourceFailure.getMessage());
            return;
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats casterEquipment =
                requiredEquipmentMagicStats();
        int casterType = caster == null ? 0 : caster.type();
        int effectiveIntelligence = casterEquipment
                .effectiveIntelligence(baseIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                casterType, caster == null ? 0
                        : Math.max(0, caster.originalIntelligence()));
        int mpCost = spell.effectiveMpCost(
                effectiveIntelligence, originalReduction);

        int remainingHp;
        int remainingMp;
        long castNow;
        synchronized (this) {
            castNow = System.nanoTime();
            long readyAt = spellReadyNanos.getOrDefault(spell.skillId(), 0L);
            if (castNow < readyAt || phase != Phase.WORLD || observer
                    || classicWorldMapId != originMapId
                    || classicWorldInstanceId != originInstanceId
                    || positionX != originX || positionY != originY
                    || playerHp <= spell.hpCost() || playerMp < mpCost
                    || !centeredAreaCasterStillAdmitted(
                            Phase.WORLD, spell.skillId(),
                            spell.actionId(), castNow)) {
                if (playerHp <= spell.hpCost()) {
                    sendEncrypted(Protocol.messageCode(279),
                            "S_MESSAGE_CODE classic-world-centered-area"
                                    + "-insufficient-hp=279 skill="
                                    + spell.skillId());
                } else if (playerMp < mpCost) {
                    sendEncrypted(Protocol.messageCode(278),
                            "S_MESSAGE_CODE classic-world-centered-area"
                                    + "-insufficient-mp=278 skill="
                                    + spell.skillId());
                }
                System.out.println("[LiTo] C_USE_SPELL classic-world"
                        + " centered-area rejected state skill="
                        + spell.skillId() + " hp=" + playerHp + " hp-cost="
                        + spell.hpCost() + " mp=" + playerMp + " mp-cost="
                        + mpCost + " cooldownNanos="
                        + Math.max(0L, readyAt - castNow));
                return;
            }
            playerHp -= spell.hpCost();
            playerMp -= mpCost;
            remainingHp = playerHp;
            remainingMp = playerMp;
            spellReadyNanos.put(spell.skillId(), castNow
                    + spell.reuseDelayMillis() * 1_000_000L);
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        Map<ClientSession, Integer> playerDamages = new LinkedHashMap<>();
        Map<ClientSession, BattleEraseMagicStatus.Lease> playerEraseLeases =
                new LinkedHashMap<>();
        Map<ClassicWorldAreaCompanionTarget, Integer> companionDamages =
                new LinkedHashMap<>();
        Map<ClassicWorldAreaCompanionTarget, BattleEraseMagicStatus.Lease>
                companionEraseLeases = new LinkedHashMap<>();
        Map<Long, Integer> monsterDamages = new LinkedHashMap<>();
        Map<Long, BattleEraseMagicStatus.Lease> monsterEraseLeases =
                new LinkedHashMap<>();
        Map<Long, Integer> trebuchetDamages = new LinkedHashMap<>();
        Map<Long, Integer> castleTowerDamages = new LinkedHashMap<>();
        Map<ClassicWorldAreaCastleDoorTarget, Integer> castleDoorDamages =
                new LinkedHashMap<>();
        List<ClientSession> counteredTargets = new ArrayList<>();
        List<Protocol.AttackManyTarget> wireTargets = new ArrayList<>();
        int counterMirrorTriggers = 0;

        for (ClientSession target : playerTargets) {
            if (!sameClassicWorldMap(target) || target.playerHp <= 0
                    || target.observer || target.invisible
                    || !map.isNormalZone(originX, originY)
                    || !map.isNormalZone(target.positionX, target.positionY)
                    || targetRange(originX, originY,
                            target.positionX, target.positionY) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            target.positionX, target.positionY)
                    || !map.attackPosition(originX, originY,
                            target.positionX, target.positionY,
                            radius * 2)
                    || BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            target.timedStatus.absoluteBarrierActive(castNow),
                            spell.skillId())) continue;
            if (target.timedStatus.consumeCounterMagic(castNow)) {
                counteredTargets.add(target);
                continue;
            }
            BattleEraseMagicStatus.Lease eraseLease =
                    target.eraseMagicStatus.capture(castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell),
                    target.effectiveSpellElementalResistance(spell.attribute()),
                    target.effectiveBaseMagicResistance(castNow),
                    target.effectiveArmorMagicReductionBase(),
                    "classic-world-player=" + target.playerName());
            damage = target.combatDamageAfterCooking(
                    damage, "classic-world-centered-area-" + spell.skillId());
            damage = target.earthBindProtectedCombatDamage(
                    damage, "classic-world-centered-area-" + spell.skillId());
            BattleCounterMirrorStatus.Decision mirror =
                    target.counterMirrorDecision(
                            damage, true,
                            ThreadLocalRandom.current().nextInt(100), castNow);
            if (mirror.triggered()) {
                publishPlayerCounterMirrorTrigger(
                        target, mirror,
                        "classic-world-centered-area-" + spell.skillId());
                damage = 0;
                counterMirrorTriggers++;
            }
            playerDamages.put(target, damage);
            playerEraseLeases.put(target, eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    target.playerObjectId(), damage > 0));
        }

        for (ClassicWorldAreaCompanionTarget target : companionTargets) {
            BattleCompanion.Snapshot current = target.controlled().snapshot();
            if (!sameClassicWorldMap(target.owner())
                    || current.objectId() != target.snapshot().objectId()
                    || !current.kind().classicWorldEligible()
                    || !current.active() || current.hp() <= 0
                    || !map.isNormalZone(originX, originY)
                    || !map.isNormalZone(current.x(), current.y())
                    || targetRange(originX, originY,
                            current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            BattleEraseMagicStatus.Lease eraseLease =
                    target.controlled().captureEraseMagic(castNow);
            int targetMr = target.controlled().effectiveMagicResistance(
                    target.stats().magicResistance(), castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    targetMr, 0,
                    "classic-world-companion=" + current.objectId());
            if (!classicWorldCkewAttackAllowed(current.npcId(), castNow)) {
                damage = 0;
            }
            companionDamages.put(target, damage);
            companionEraseLeases.put(target, eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target : monsterTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicWorldMonster(
                            originMapId, originInstanceId, target.objectId());
            if (current == null || !current.present() || !current.alive()
                    || targetRange(originX, originY,
                            current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            SourceNpcPhysicalStats stats = monsterStats.get(current.objectId());
            if (stats == null) continue;
            BattleEraseMagicStatus.Lease eraseLease =
                    hub.captureClassicWorldMonsterEraseMagic(
                            originMapId, originInstanceId,
                            current.objectId(), castNow);
            int targetMr = hub.classicWorldMonsterEffectiveMagicResistance(
                    originMapId, originInstanceId, current.objectId(),
                    stats.magicResistance(), castNow);
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell),
                    hub.classicWorldMonsterElementalFallDownModifier(
                            originMapId, originInstanceId, current.objectId(),
                            spell.attribute(), castNow),
                    targetMr, 0,
                    "classic-world-monster=" + current.objectId());
            if (!classicWorldCkewAttackAllowed(current.npcId(), castNow)) {
                damage = 0;
            }
            monsterDamages.put(current.objectId(), damage);
            monsterEraseLeases.put(current.objectId(), eraseLease);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target : trebuchetTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            target.objectId());
            if (current == null || !current.present() || !current.alive()
                    || targetRange(originX, originY,
                            current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            SourceNpcPhysicalStats stats = monsterStats.get(current.objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-trebuchet=" + current.objectId());
            trebuchetDamages.put(current.objectId(), damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldMonsterPopulation.Snapshot target
                : castleTowerTargets) {
            ClassicWorldMonsterPopulation.Snapshot current =
                    currentClassicCastleTower(target);
            if (current == null || targetRange(originX, originY,
                        current.x(), current.y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY, current.x(), current.y())
                    || !map.attackPosition(originX, originY,
                            current.x(), current.y(), radius * 2)) continue;
            SourceNpcPhysicalStats stats = monsterStats.get(current.objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-tower=" + current.objectId());
            castleTowerDamages.put(current.objectId(), damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.objectId(), damage > 0));
        }

        for (ClassicWorldAreaCastleDoorTarget target : castleDoorTargets) {
            ClassicWorldAreaCastleDoorTarget current =
                    currentClassicWorldAreaCastleDoorTarget(
                            target, originX, originY);
            if (current == null || targetRange(originX, originY,
                        current.combat().x(), current.combat().y()) > radius
                    || !BattleSpellCatalog.isInNativeScreen(
                            originX, originY,
                            current.combat().x(), current.combat().y())
                    || !map.attackPosition(originX, originY,
                            current.combat().x(), current.combat().y(),
                            radius * 2)) {
                continue;
            }
            SourceNpcPhysicalStats stats =
                    monsterStats.get(current.combat().objectId());
            if (stats == null) continue;
            int damage = areaSpellDamage(
                    spell, rollAreaSpellSourceDamage(spell), 0,
                    stats.magicResistance(), 0,
                    "classic-world-castle-door="
                            + current.combat().objectId());
            castleDoorDamages.put(current, damage);
            wireTargets.add(new Protocol.AttackManyTarget(
                    current.combat().objectId(), damage > 0));
        }

        for (ClientSession target : counteredTargets) {
            publishCounterMagicConsumption(target, spell.skillId());
        }
        long sequence = ATTACK_SPELL_SEQUENCE.incrementAndGet();
        if (wireTargets.isEmpty()) {
            byte[] action = Protocol.objectAction(
                    playerObjectId(), spell.actionId());
            for (ClientSession member : worldMembers) {
                if (!sameClassicWorldMap(member)
                        || !BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                originX, originY)
                        || invisible && member != this) continue;
                member.sendEncrypted(action,
                        "S_ACTION classic-world centered-area-empty caster="
                                + playerObjectId() + " skill="
                                + spell.skillId());
            }
        } else {
            byte[] attack = Protocol.attackMany(
                    spell.actionId(), playerObjectId(), originX, originY,
                    originHeading, sequence, spell.effectGfx(), 0,
                    wireTargets);
            publishClassicWorldAreaAttackSpellPacket(
                    attack, originX, originY,
                    "centered=" + spell.skillId() + " key=" + spell.key()
                            + " targets=" + wireTargets.size()
                            + " gfx=" + spell.effectGfx()
                            + " type=0 sequence=" + sequence
                            + " countered=" + counteredTargets.size()
                            + " counter-mirror-triggered="
                            + counterMirrorTriggers);
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world centered-area="
                        + remainingMp + "/" + playerMaxMp);
        if (spell.hpCost() != 0) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(remainingHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT classic-world centered-area-hp-cost="
                            + remainingHp + "/" + playerMaxHp);
            broadcastOwnHitRatio("classic-world-centered-area-hp-cost");
        }
        applySpellLawfulDelta(spell.lawfulDelta(), spell.key());

        for (Map.Entry<ClientSession, Integer> entry
                : playerDamages.entrySet()) {
            if (entry.getValue() > 0) {
                entry.getKey().takeClassicWorldPlayerDamage(
                        entry.getValue(), this, false);
            }
            entry.getKey().eraseMagicStatus.consume(
                    playerEraseLeases.get(entry.getKey()));
        }
        for (Map.Entry<ClassicWorldAreaCompanionTarget, Integer> entry
                : companionDamages.entrySet()) {
            ClassicWorldAreaCompanionTarget target = entry.getKey();
            target.controlled().consumeEraseMagic(
                    companionEraseLeases.get(target));
            if (entry.getValue() > 0) {
                target.controlled().selectMasterTarget(playerObjectId());
                target.owner().applyClassicWorldMonsterCompanionDamage(
                        target.controlled(), target.snapshot(), entry.getValue(),
                        playerObjectId(),
                        "centered-area-spell-" + spell.skillId());
            }
        }
        for (Map.Entry<Long, Integer> entry : monsterDamages.entrySet()) {
            ClassicWorldMonsterPopulation.Hit transition = null;
            if (entry.getValue() > 0) {
                transition = hub.damageClassicWorldMonster(
                        originMapId, originInstanceId, entry.getKey(),
                        playerObjectId(), entry.getValue());
            }
            hub.consumeClassicWorldMonsterEraseMagic(
                    originMapId, originInstanceId, entry.getKey(),
                    monsterEraseLeases.get(entry.getKey()));
            if (transition == null) continue;
            hub.provokeClassicWorldMonster(
                    originMapId, originInstanceId,
                    entry.getKey(), playerObjectId());
            for (BattleCompanion.Snapshot companion
                    : classicWorldCompanionSnapshots()) {
                BattleCompanion controlled =
                        ownedCompanion(companion.objectId());
                if (controlled != null) {
                    controlled.selectMasterTarget(entry.getKey());
                }
            }
            publishClassicWorldSpellMonsterDamage(
                    spell.skillId(), transition);
        }
        for (Map.Entry<Long, Integer> entry : trebuchetDamages.entrySet()) {
            if (entry.getValue() <= 0) continue;
            ClassicWorldCastleWarField.TrebuchetHit hit =
                    hub.damageClassicCastleTrebuchet(
                            selectedClassicServerName, originMapId,
                            entry.getKey(), entry.getValue());
            if (hit == null || hit.appliedDamage() <= 0) continue;
            publishClassicCastleTrebuchetHit(hit);
            if (hit.diedNow()) {
                hub.scheduleClassicCastleTrebuchetCorpseRemoval(
                        selectedClassicServerName, hit.after());
            }
        }
        for (Map.Entry<Long, Integer> entry
                : castleTowerDamages.entrySet()) {
            if (entry.getValue() <= 0) continue;
            ClassicWorldMonsterPopulation.Snapshot target =
                    hub.classicCastleTowerCombatSnapshot(
                            selectedClassicServerName, originMapId,
                            entry.getKey());
            applyClassicWorldCastleTowerMagicDamage(
                    target, entry.getValue());
        }
        for (Map.Entry<ClassicWorldAreaCastleDoorTarget, Integer> entry
                : castleDoorDamages.entrySet()) {
            applyClassicWorldAreaCastleDoorDamage(
                    entry.getKey(), entry.getValue());
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world centered-area skill="
                + spell.skillId() + " key=" + spell.key() + " caster="
                + playerName() + " radius=" + radius + " players="
                + playerDamages.size() + " companions="
                + companionDamages.size() + " monsters="
                + monsterDamages.size() + " trebuchets="
                + trebuchetDamages.size() + " castle-towers="
                + castleTowerDamages.size() + " castle-doors="
                + castleDoorDamages.size() + " wire-targets="
                + wireTargets.size() + " countered="
                + counteredTargets.size() + " counter-mirror-triggered="
                + counterMirrorTriggers + " effective-int="
                + effectiveIntelligence + " mp-cost=" + mpCost
                + " hp-cost=" + spell.hpCost() + " hp=" + remainingHp
                + "/" + playerMaxHp + " lawful-delta="
                + spell.lawfulDelta() + " mp=" + remainingMp + "/"
                + playerMaxMp);
    }

