    private BoneBreakApplication applyClassicWorldBoneBreak(
            BattleSpellCatalog.BoneBreakSpell spell,
            ClientSession playerTarget,
            BattleCompanion controlledCompanion,
            ClassicWorldMonsterPopulation.Snapshot monsterTarget,
            boolean castleTrebuchetTarget,
            long targetObjectId, int targetX, int targetY,
            long nowNanos, int rollFixture,
            List<ClientSession> worldMembers) throws IOException {
        boolean eligible = playerTarget != null
                ? playerTarget.phase == Phase.WORLD
                    && playerTarget.playerHp > 0
                    && !BattleAbsoluteBarrierRules.blocksIncomingSpell(
                            playerTarget.timedStatus.absoluteBarrierActive(
                                    nowNanos), spell.skillId())
                : controlledCompanion != null
                    ? controlledCompanion.snapshot().active()
                        && controlledCompanion.snapshot().hp() > 0
                    : monsterTarget != null && monsterTarget.present()
                        && monsterTarget.alive();
        if (!eligible) return BoneBreakApplication.ineligible();

        boolean alreadyActive = playerTarget != null
                ? playerTarget.timedStatus.boneBreakActive(nowNanos)
                : controlledCompanion != null
                    ? controlledCompanion.boneBreakActive(nowNanos)
                    : castleTrebuchetTarget
                        ? hub.classicCastleTrebuchetBoneBreakActive(
                                selectedClassicServerName, classicWorldMapId,
                                monsterTarget.objectId(), nowNanos)
                        : hub.classicWorldMonsterBoneBreakActive(
                                classicWorldMapId, classicWorldInstanceId,
                                monsterTarget.objectId(), nowNanos);
        if (alreadyActive) {
            return new BoneBreakApplication(true, true, 0, false, 0);
        }
        int roll = rollFixture > 0 ? rollFixture
                : ThreadLocalRandom.current().nextInt(
                        spell.minimumRoll(), spell.maximumRoll() + 1);
        if (!spell.succeeds(roll)) {
            return new BoneBreakApplication(true, false, roll, false, 0);
        }
        boolean activated = playerTarget != null
                ? playerTarget.timedStatus.activateBoneBreak(
                        nowNanos, spell.durationSeconds())
                : controlledCompanion != null
                    ? controlledCompanion.activateBoneBreak(
                            nowNanos, spell.durationSeconds())
                    : castleTrebuchetTarget
                        ? hub.boneBreakClassicCastleTrebuchet(
                                selectedClassicServerName, classicWorldMapId,
                                monsterTarget.objectId(), nowNanos,
                                spell.durationSeconds())
                        : hub.boneBreakClassicWorldMonster(
                                classicWorldMapId, classicWorldInstanceId,
                                monsterTarget.objectId(), nowNanos,
                                spell.durationSeconds());
        if (!activated) {
            return new BoneBreakApplication(true, true, roll, false, 0);
        }
        BattleBoneBreakEffects.Effect effect =
                hub.placeClassicWorldBoneBreakEffect(
                        classicWorldMapId, classicWorldInstanceId,
                        targetObjectId, targetX, targetY,
                        nowNanos, spell.durationSeconds());
        if (effect == null) {
            throw new IllegalStateException(
                    "classic-world Bone Break status activated without effect");
        }
        byte[] put = Protocol.boneBreakEffect(effect);
        for (ClientSession member : worldMembers) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY,
                            targetX, targetY)) continue;
            member.sendEncrypted(put,
                    "S_PUT_OBJECT classic-world Bone Break effect="
                            + effect.objectId() + " target=" + targetObjectId
                            + " npc=" + spell.effectNpcId()
                            + " gfx=" + spell.effectNpcGfx()
                            + " duration=" + spell.durationSeconds());
        }
        if (playerTarget != null) {
            playerTarget.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.STUN_APPLY),
                    "S_PARALYSE mode=22 classic-world Bone Break duration="
                            + spell.durationSeconds());
        }
        return new BoneBreakApplication(
                true, false, roll, true, effect.objectId());
    }

