    private void useCurseRemovalSpell(byte[] byArray, BattleSpellCatalog.CurseRemovalSpell curseRemovalSpell) throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$useCurseRemovalSpell(byArray, curseRemovalSpell, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

