    /** Exact retained Pet_Collar withdrawal order for one persistent WORLD pet. */
    private void usePetCollar(RuntimeInventory.Item collar) throws Exception {
        if (phase != Phase.WORLD || observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) {
            System.out.println("[LiTo] C_USE_ITEM pet-collar rejected phase=" + phase
                    + " observer=" + observer + " hp=" + playerHp);
            return;
        }
        if (rejectWhileParalyzed("C_USE_ITEM pet-collar")) return;
        if (!inventory.items().stream().anyMatch(item ->
                item.definition().catalogId() == InventoryCatalog.PET_CALLING_FLUTE)) {
            sendEncrypted(Protocol.messageCode(79),
                    "S_MESSAGE_CODE pet-collar-missing-flute=79");
            return;
        }
        if (!ClassicWorldMapCatalog.forMap(classicWorldMapId).allowsPetRecall()) {
            sendEncrypted(Protocol.messageCode(563),
                    "S_MESSAGE_CODE pet-collar-map=563 map=" + classicWorldMapId);
            return;
        }
        boolean alreadyActive;
        synchronized (tamedCompanions) {
            alreadyActive = tamedCompanions.stream()
                    .map(BattleCompanion::snapshot)
                    .anyMatch(pet -> pet.active() && pet.kind() == BattleCompanion.Kind.PET
                            && pet.collarObjectId() == collar.objectId());
        }
        if (alreadyActive) return;

        GameStateStore.PetState durable = state.petForCollar(collar.objectId());
        if (durable == null || durable.collarCatalogId()
                != collar.definition().catalogId()) {
            System.out.println("[LiTo] C_USE_ITEM pet-collar has no durable pet object="
                    + collar.objectId());
            return;
        }
        SourcePetTemplate template = selectedSourceAccounts().petTemplate(durable.npcId());
        List<BattleCompanion.Snapshot> active = classicWorldCompanionSnapshots().stream()
                .filter(BattleCompanion.Snapshot::active).toList();
        int usedPetCost = active.stream().mapToInt(BattleCompanion.Snapshot::petCost).sum();
        CharacterSummary character = selectedCharacterSummary();
        int charisma = character == null ? 9 : Math.max(0, character.charisma());
        if (active.size() >= 8 || charisma + 6 - usedPetCost < template.charismaCost()) {
            sendEncrypted(Protocol.messageCode(489),
                    "S_MESSAGE_CODE pet-collar-capacity=489 charisma=" + charisma
                            + " used=" + usedPetCost + " pet-cost="
                            + template.charismaCost());
            return;
        }
        ArenaMapCatalog.Point spawn = summonSpawnPoint(null, true);
        if (spawn == null) {
            sendEncrypted(Protocol.messageCode(489),
                    "S_MESSAGE_CODE pet-collar-no-spawn=489");
            return;
        }

        RuntimeInventory previous = inventory.copy();
        if (!inventory.removeCatalog(InventoryCatalog.PET_CALLING_FLUTE, 1)) return;
        BattleCompanion pet = BattleCompanion.pet(
                durable, template, spawn.x(), spawn.y());
        synchronized (tamedCompanions) {
            tamedCompanions.add(pet);
        }
        try {
            state.saveEconomyState(stateCharacter(), shopPoints,
                    inventory.catalogCounts(), inventory.catalogItemStates());
            sendInventoryDelta(previous, inventory);
            BattleCompanion.Snapshot snapshot = pet.snapshot();
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY, snapshot.x(), snapshot.y())) continue;
                member.sendClassicWorldCompanionObject(this, snapshot, "pet-collar-recall");
                member.sendEncrypted(Protocol.effectObject(snapshot.objectId(), 755),
                        "S_EFFECT persistent-pet=" + snapshot.objectId()
                                + " gfx=755 reason=collar-recall");
            }
            System.out.println("[LiTo] C_USE_ITEM pet-collar recalled owner=" + playerName()
                    + " collar=" + collar.objectId() + " pet=" + snapshot.objectId()
                    + " npc=" + snapshot.npcId() + " level=" + snapshot.level()
                    + " hp=" + snapshot.hp() + "/" + snapshot.maxHp()
                    + " flute-consumed=1");
        } catch (Exception failure) {
            synchronized (tamedCompanions) {
                tamedCompanions.remove(pet);
            }
            NativeDeItemApplication.replace(this, previous, 0);
            throw failure;
        }
    }

    private ArenaMapCatalog.Point summonSpawnPoint(
            ArenaMapCatalog.Arena arena, boolean classicWorld) {
        for (int radius = 1; radius <= 8; radius++) {
            for (int dy = -radius; dy <= radius; dy++) {
                for (int dx = -radius; dx <= radius; dx++) {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != radius) continue;
                    int x = positionX + dx;
                    int y = positionY + dy;
                    boolean standing = classicWorld
                            ? ClassicWorldMapCatalog.forMap(
                                    classicWorldMapId).standingPassable(x, y)
                            : arena.nativeStandingFloor(x, y);
                    boolean occupied = classicWorld
                            ? classicWorldCompanionTileOccupied(x, y, 0, 0)
                            : companionTileOccupied(currentRoomId, x, y, 0, 0);
                    if (standing && !occupied) {
                        return new ArenaMapCatalog.Point(x, y);
                    }
                }
            }
        }
        return null;
    }

