        BattleCompanion.Snapshot snapshot = battleCompanion.snapshot();
        boolean bl = this.phase == Phase.WORLD;
        for (ClientSession clientSession : list) {
            if (bl && !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, snapshot.x(), snapshot.y())) continue;
            clientSession.sendBattleObject(snapshot.objectId(), snapshot.name(), snapshot.name(), snapshot.x(), snapshot.y(), snapshot.gfx(), 0, 0, snapshot.moveSpeed(), 0, snapshot.level(), 0, this.playerName(), bl && clientSession != this ? 255 : NativeBattleTamedLifecycle.visualHealthRatio(snapshot.hp(), snapshot.maxHp()));
            clientSession.sendEncrypted(Protocol.master(snapshot.objectId(), this.playerName()), "S_MASTER " + string + "-companion=" + snapshot.objectId() + " owner=" + this.playerName());
            clientSession.sendEncrypted(Protocol.speed(snapshot.objectId(), Protocol.SpeedMode.fromWire(snapshot.moveSpeed()), 0), "S_SPEED " + string + "-companion=" + snapshot.objectId() + " mode=" + snapshot.moveSpeed());
            clientSession.sendEncrypted(Protocol.effectObject(snapshot.objectId(), n), "S_EFFECT " + string + "-companion=" + snapshot.objectId() + " gfx=" + n);
        }
