    private ResurrectionCastCommit commitClassicWorldResurrectionCast(BattleSpellCatalog.ResurrectionSpell resurrectionSpell, ClientSession clientSession, int n, int n2, int n3, long l) throws IOException {
        boolean bl;
        long l2 = this.spellReadyNanos.getOrDefault(resurrectionSpell.skillId(), 0L);
        boolean bl2 = this.phase == Phase.WORLD && !this.observer && this.playerHp > 0 && this.classicWorldMapId == n && this.classicWorldInstanceId == n2;
        boolean bl3 = bl = clientSession == null || clientSession.phase == Phase.WORLD && !clientSession.observer && clientSession.playerHp == 0 && clientSession.classicWorldMapId == n && clientSession.classicWorldInstanceId == n2;
        if (l < l2 || this.playerMp < n3 || !bl2 || !bl) {
            System.out.println("[LiTo] C_USE_SPELL classic-world-resurrection rejected state skill=" + resurrectionSpell.skillId() + " hp=" + this.playerHp + " mp=" + this.playerMp + " mp-cost=" + n3 + " cooldownNanos=" + Math.max(0L, l2 - l));
            return new ResurrectionCastCommit(false, false, null, this.playerMp);
        }
        if (!NativeResurrectionMaterialAction.admit(this, clientSession, resurrectionSpell.skillId(), resurrectionSpell.actionId(), resurrectionSpell.reuseDelayMillis())) {
            return new ResurrectionCastCommit(false, false, null, this.playerMp);
        }
        l = System.nanoTime();
        RuntimeInventory runtimeInventory = NativeCastMaterial.previous(this);
        ClientSession clientSession2 = this;
        clientSession2.playerMp = NativeSkillConsumption.boundMp(clientSession2, clientSession2.playerMp - n3);
        this.spellReadyNanos.put(resurrectionSpell.skillId(), l + (long)resurrectionSpell.reuseDelayMillis() * 1000000L);
        return new ResurrectionCastCommit(true, false, runtimeInventory, this.playerMp);
    }

