        long l2 = this.spellReadyNanos.getOrDefault(resurrectionSpell.skillId(), 0L);
        if (l < l2 || this.playerMp < n || this.playerHp <= 0 || this.phase != Phase.BATTLE || this.observer || clientSession != null && (clientSession.phase != Phase.BATTLE || clientSession.observer || clientSession.playerHp != 0)) {
            System.out.println("[LiTo] C_USE_SPELL resurrection rejected state skill=" + resurrectionSpell.skillId() + " hp=" + this.playerHp + " mp=" + this.playerMp + " mp-cost=" + n + " cooldownNanos=" + Math.max(0L, l2 - l));
            return new ResurrectionCastCommit(false, false, null, this.playerMp);
        }
        if (!NativeResurrectionMaterialAction.admit(this, clientSession, resurrectionSpell.skillId(), resurrectionSpell.actionId(), resurrectionSpell.reuseDelayMillis())) {
            return new ResurrectionCastCommit(false, false, null, this.playerMp);
        }
        l = System.nanoTime();
        RuntimeInventory runtimeInventory = NativeCastMaterial.previous(this);
        ClientSession clientSession2 = this;
        clientSession2.playerMp = NativeSkillConsumption.boundMp(clientSession2, clientSession2.playerMp - n);
        this.spellReadyNanos.put(resurrectionSpell.skillId(), l + (long)resurrectionSpell.reuseDelayMillis() * 1000000L);
        return new ResurrectionCastCommit(true, false, runtimeInventory, this.playerMp);
