    private boolean admitClassicWorldSpellFamily(int n, int n2, String string) throws IOException {
        if (this.phase != Phase.WORLD) {
            return true;
        }
        long l = System.nanoTime();
        BattlePolymorphCatalog.Form form = this.polymorphStatus.active(l);
        if (form != null && !form.skillUsable() && !CombatAwaken.classicActive(this.awakenStatus.snapshot())) {
            this.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK), "S_PARALYSE mode=7 reason=classic-world-" + string + "-polymorph-rejected");
            this.sendEncrypted(Protocol.messageCode(285, new String[0]), "S_MESSAGE_CODE classic-world-" + string + "-polymorph-rejected=285");
            return false;
        }
        if (this.timedStatus.silenceActive(l)) {
            this.sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK), "S_PARALYSE mode=7 reason=classic-world-" + string + "-silenced-rejected");
            this.sendEncrypted(Protocol.messageCode(285, new String[0]), "S_MESSAGE_CODE classic-world-" + string + "-silenced-rejected=285");
            return false;
        }
        if (this.currentWeight240(l) >= 197) {
            this.sendEncrypted(Protocol.messageCode(316, new String[0]), "S_MESSAGE_CODE classic-world-" + string + "-overweight=316");
            return false;
        }
        if (!this.learnedSkills.contains(n) || !BattleAnimationCatalog.get().supportsTimedAction(this.battleGfx(), n2)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world " + string + " rejected learned/action player=" + this.playerName() + " skill=" + n + " action=" + n2);
            return false;
        }
        return true;
    }

    private boolean centeredAreaCasterStillAdmitted(Phase phase, int n, int n2, long l) {
        BattlePolymorphCatalog.Form form = this.polymorphStatus.active(l);
        boolean bl = form != null && !form.skillUsable() && (phase != Phase.WORLD || !CombatAwaken.classicActive(this.awakenStatus.snapshot()));
        return !CombatBindControl.actionLocked(this.timedStatus, l) && !this.timedStatus.silenceActive(l) && this.currentWeight240(l) < 197 && this.learnedSkills.contains(n) && !bl && BattleAnimationCatalog.get().supportsTimedAction(this.battleGfx(), n2);
    }

