    /** Test-only die fixture; zero preserves the native random healing dice. */
    private void useClassicWorldHealingSpell(
            byte[] payload, BattleSpellCatalog.HealingSpell spell,
            int dieRollFixture) throws IOException {
        if (dieRollFixture < 0 || dieRollFixture > spell.dieSides()) {
            throw new IllegalArgumentException(
                    "invalid classic-world healing die fixture");
        }
        Protocol.ObjectSpellRequest request = Protocol.objectSpellRequest(payload);
        if (request.skillId() != spell.skillId()) return;

        long requestNow = System.nanoTime();
        BattlePolymorphCatalog.Form active = polymorphStatus.active(requestNow);
        if (active != null && !active.skillUsable()) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-healing-polymorph-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-healing-polymorph-rejected=285");
            return;
        }
        if (timedStatus.silenceActive(requestNow)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.TELEPORT_UNLOCK),
                    "S_PARALYSE mode=7 reason=classic-world-healing-silenced-rejected");
            sendEncrypted(Protocol.messageCode(285),
                    "S_MESSAGE_CODE classic-world-healing-silenced-rejected=285");
            return;
        }
        if (currentWeight240(requestNow)
                >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(316),
                    "S_MESSAGE_CODE classic-world-healing-overweight=316");
            return;
        }
        if (!learnedSkills.contains(spell.skillId())
                || !BattleAnimationCatalog.get().supportsTimedAction(
                        battleGfx(), spell.actionId())) {
            System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                    + " learned/action player=" + playerName()
                    + " skill=" + spell.skillId());
            return;
        }

        int originMapId = classicWorldMapId;
        int originInstanceId = classicWorldInstanceId;
        int originX = positionX;
        int originY = positionY;
        List<ClientSession> worldMembers = classicWorldMembers(originMapId);
        ClientSession playerTarget = worldMembers.stream()
                .filter(candidate -> sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        ClientSession companionOwner = worldMembers.stream()
                .filter(this::sameClassicWorldMap)
                .filter(candidate -> candidate.classicWorldCompanionSnapshot(
                        request.targetObjectId()) != null)
                .findFirst().orElse(null);
        BattleCompanion.Snapshot companionTarget = companionOwner == null ? null
                : companionOwner.classicWorldCompanionSnapshot(
                        request.targetObjectId());
        ClassicWorldMonsterPopulation.Snapshot monsterTarget =
                hub.classicWorldMonster(originMapId, originInstanceId,
                        request.targetObjectId());
        boolean validMonster = monsterTarget != null && monsterTarget.present()
                && monsterTarget.alive() && monsterTarget.mapId() == originMapId;
        int targetCount = (playerTarget == null ? 0 : 1)
                + (companionTarget == null ? 0 : 1)
                + (validMonster ? 1 : 0);
        if (targetCount != 1) {
            System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                    + " unknown/dead/ambiguous target=" + request.targetObjectId()
                    + " matches=" + targetCount
                    + " skill=" + spell.skillId());
            return;
        }

        int targetX = playerTarget != null ? playerTarget.positionX
                : companionTarget != null ? companionTarget.x()
                : monsterTarget.x();
        int targetY = playerTarget != null ? playerTarget.positionY
                : companionTarget != null ? companionTarget.y()
                : monsterTarget.y();
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(originMapId);
        boolean livingPlayer = playerTarget == null
                || playerTarget.phase == Phase.WORLD
                    && !playerTarget.observer && playerTarget.playerHp > 0
                    && (playerTarget == this || !playerTarget.invisible)
                    && sameClassicWorldMap(playerTarget);
        boolean livingCompanion = companionTarget == null
                || companionTarget.active() && companionTarget.hp() > 0;
        boolean absoluteBarrierBlocked = playerTarget != null
                && BattleAbsoluteBarrierRules.blocksIncomingSpell(
                    playerTarget.timedStatus.absoluteBarrierActive(requestNow),
                    spell.skillId());
        if (!livingPlayer || !livingCompanion
                || absoluteBarrierBlocked
                || !BattleSpellCatalog.isInNativeScreen(
                        originX, originY, targetX, targetY)
                || !map.hasLineOfSight(originX, originY, targetX, targetY)) {
            System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                    + " gate/screen target=" + request.targetObjectId()
                    + " absolute-barrier=" + absoluteBarrierBlocked
                    + " skill=" + spell.skillId());
            return;
        }

        SourceNpcPhysicalStats npcStats = null;
        int targetNpcId = companionTarget != null ? companionTarget.npcId()
                : monsterTarget != null ? monsterTarget.npcId() : 0;
        if (targetNpcId != 0) {
            try {
                npcStats = selectedSourceAccounts().npcPhysicalStats(targetNpcId);
            } catch (Exception sourceFailure) {
                System.out.println("[LiTo] classic-world healing source NPC lookup"
                        + " failed player=" + playerName() + " npc=" + targetNpcId
                        + " reason=" + sourceFailure.getClass().getSimpleName()
                        + ": " + sourceFailure.getMessage());
                return;
            }
        }

        CharacterSummary caster = selectedCharacterSummary();
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int intelligence = equipment.effectiveIntelligence(
                caster == null ? 8 : caster.intelligence());
        int characterType = caster == null ? 0 : caster.type();
        int originalIntelligence = caster == null
                ? 0 : Math.max(0, caster.originalIntelligence());
        int originalReduction = BattleSpellCatalog.originalMagicConsumeReduction(
                characterType, originalIntelligence);
        int mpCost = spell.effectiveMpCost(
                intelligence, originalReduction, equipment.healingHelmEquipped());
        int rolled = 0;
        for (int index = 0; index < spell.diceCount(intelligence); index++) {
            rolled += dieRollFixture == 0
                    ? ThreadLocalRandom.current().nextInt(1, spell.dieSides() + 1)
                    : dieRollFixture;
        }
        int lawfulHealing = spell.applyLawfulRevision(
                rolled, caster == null ? 0 : characterLawful());

        int adjustedHealing = lawfulHealing;
        boolean targetWaterLife = false;
        boolean consumedWaterLife = false;
        boolean targetPolluteWater = false;
        int hpAfter = -1;
        int remainingMp;
        long castNow;
        ClientSession targetLock = playerTarget != null
                ? playerTarget : companionOwner;
        ClientSession firstLock = targetLock == null
                || playerObjectId() <= targetLock.playerObjectId()
                ? this : targetLock;
        ClientSession secondLock = targetLock == null
                ? this : firstLock == this ? targetLock : this;
        synchronized (firstLock) {
            synchronized (secondLock) {
                castNow = System.nanoTime();
                long readyAt = spellReadyNanos.getOrDefault(
                        spell.skillId(), 0L);
                BattleCompanion.Snapshot lockedCompanion = null;
                if (companionTarget != null && companionOwner != null) {
                    BattleCompanion controlled = companionOwner.ownedCompanion(
                            companionTarget.objectId());
                    lockedCompanion = controlled == null
                            ? null : controlled.snapshot();
                }
                ClassicWorldMonsterPopulation.Snapshot lockedMonster =
                        monsterTarget == null ? null : hub.classicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId());
                boolean targetStillAvailable = playerTarget != null
                        ? playerTarget.phase == Phase.WORLD
                            && !playerTarget.observer
                            && playerTarget.playerHp > 0
                            && (playerTarget == this
                                || !playerTarget.invisible)
                            && playerTarget.classicWorldMapId == originMapId
                            && playerTarget.classicWorldInstanceId
                                == originInstanceId
                            && playerTarget.positionX == targetX
                            && playerTarget.positionY == targetY
                            && !BattleAbsoluteBarrierRules
                                .blocksIncomingSpell(
                                    playerTarget.timedStatus
                                        .absoluteBarrierActive(castNow),
                                    spell.skillId())
                        : companionTarget != null
                            ? lockedCompanion != null
                                && lockedCompanion.active()
                                && lockedCompanion.hp() > 0
                                && lockedCompanion.x() == targetX
                                && lockedCompanion.y() == targetY
                            : lockedMonster != null
                                && lockedMonster.present()
                                && lockedMonster.alive()
                                && lockedMonster.mapId() == originMapId
                                && lockedMonster.x() == targetX
                                && lockedMonster.y() == targetY;
                boolean endpointStillAllowed = phase == Phase.WORLD
                        && !observer && playerHp > 0
                        && classicWorldMapId == originMapId
                        && classicWorldInstanceId == originInstanceId
                        && positionX == originX && positionY == originY
                        && BattleSpellCatalog.isInNativeScreen(
                            originX, originY, targetX, targetY)
                        && map.hasLineOfSight(
                            originX, originY, targetX, targetY);
                if (!targetStillAvailable || !endpointStillAllowed
                        || castNow < readyAt || playerMp < mpCost) {
                    if (playerMp < mpCost) {
                        sendEncrypted(Protocol.messageCode(278),
                                "S_MESSAGE_CODE classic-world-healing-insufficient-mp=278");
                    }
                    System.out.println("[LiTo] C_USE_SPELL classic-world healing rejected"
                            + " state player=" + playerName() + " skill="
                            + spell.skillId() + " mp=" + playerMp
                            + " cost=" + mpCost + " target-available="
                            + targetStillAvailable + " endpoint="
                            + endpointStillAllowed + " cooldownNanos="
                            + Math.max(0L, readyAt - castNow));
                    return;
                }
                if (lockedCompanion != null) companionTarget = lockedCompanion;
                if (lockedMonster != null) monsterTarget = lockedMonster;
                if (monsterTarget != null) {
                    targetPolluteWater =
                            hub.classicWorldMonsterPolluteWaterActive(
                                originMapId, originInstanceId,
                                monsterTarget.objectId(), castNow);
                    adjustedHealing =
                            BattleHealingRecovery.adjustedSingleTargetAmount(
                                lawfulHealing, false, targetPolluteWater,
                                false, false);
                } else if (playerTarget != null) {
                    targetWaterLife =
                            playerTarget.waterLifeStatus.active(castNow);
                    targetPolluteWater = playerTarget.timedStatus
                            .polluteWaterActive(castNow);
                    adjustedHealing =
                            BattleHealingRecovery.adjustedSingleTargetAmount(
                                lawfulHealing, targetWaterLife,
                                targetPolluteWater,
                                playerTarget.timedStatus
                                    .waterDragonDirtyCurrentActive(castNow),
                                playerTarget.timedStatus
                                    .waterDragonHealingErosionActive(castNow));
                }
                playerMp -= mpCost;
                remainingMp = playerMp;
                spellReadyNanos.put(spell.skillId(), castNow
                        + spell.reuseDelayMillis() * 1_000_000L);
                if (playerTarget != null) {
                    consumedWaterLife = playerTarget.waterLifeStatus.cancel();
                    if (adjustedHealing >= 0) {
                        playerTarget.playerHp = Math.min(
                                playerTarget.playerMaxHp,
                                Math.addExact(playerTarget.playerHp,
                                    adjustedHealing));
                    }
                    hpAfter = playerTarget.playerHp;
                }
            }
        }
        cancelMeditation("classic-world-spell-" + spell.skillId());
        cancelAbsoluteBarrier("classic-world-spell-" + spell.skillId());
        revealInvisibility("classic-world-spell-" + spell.skillId());

        byte[] action = Protocol.objectAction(playerObjectId(), spell.actionId());
        byte[] effect = Protocol.effectObject(request.targetObjectId(), spell.effectGfx());
        for (ClientSession member : worldMembers) {
            if (!sameClassicWorldMap(member)
                    || !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, originX, originY)
                        && !BattleSpellCatalog.isInNativeScreen(
                            member.positionX, member.positionY, targetX, targetY)) {
                continue;
            }
            if (!invisible || member == this) {
                member.sendEncrypted(action,
                        "S_ACTION classic-world healing caster=" + playerObjectId()
                                + " action=" + spell.actionId()
                                + " skill=" + spell.skillId());
            }
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world healing target="
                            + request.targetObjectId() + " gfx="
                            + spell.effectGfx() + " skill=" + spell.skillId());
        }
        sendEncrypted(Protocol.manaPoint(remainingMp, playerMaxMp),
                "S_MANA_POINT classic-world healing="
                        + remainingMp + "/" + playerMaxMp);

        int npcHpDelta = npcStats == null ? 0
                : spell.npcHpDelta(npcStats.undead(), adjustedHealing);
        if (playerTarget != null) {
            if (hpAfter >= 0) {
                if (adjustedHealing < 0) {
                    playerTarget.takeClassicWorldPlayerDamage(
                            -adjustedHealing, this, false);
                    hpAfter = playerTarget.playerHp;
                } else {
                    playerTarget.sendEncrypted(
                            new Protocol.Writer().c(Protocol.S_HIT_POINT)
                                    .h(hpAfter).h(playerTarget.playerMaxHp).bytes(),
                            "S_HIT_POINT classic-world healing=" + hpAfter
                                    + "/" + playerTarget.playerMaxHp);
                    playerTarget.broadcastHitRatio(
                            playerTarget.playerObjectId(), hpAfter,
                            playerTarget.playerMaxHp,
                            "classic-world-healing-" + spell.skillId());
                }
                if (spell.happenMessage() > 0) {
                    playerTarget.sendEncrypted(
                            Protocol.messageCode(spell.happenMessage()),
                            "S_MESSAGE_CODE classic-world healing-applied="
                                    + spell.happenMessage()
                                    + " skill=" + spell.skillId());
                }
            }
        } else if (companionTarget != null && companionOwner != null) {
            BattleCompanion companion = companionOwner.ownedCompanion(
                    companionTarget.objectId());
            if (companion != null && npcHpDelta < 0) {
                companionOwner.applyClassicWorldMonsterCompanionDamage(
                        companion, companionTarget, -npcHpDelta,
                        playerObjectId(), "healing-spell-undead");
                hpAfter = companion.snapshot().hp();
            } else if (companion != null && npcHpDelta > 0) {
                companion.heal(npcHpDelta);
                BattleCompanion.Snapshot after = companion.snapshot();
                hpAfter = after.hp();
                byte[] ratio = Protocol.hitRatio(
                        after.objectId(), after.hp(), after.maxHp());
                for (ClientSession member : worldMembers) {
                    if (sameClassicWorldMap(member)
                            && BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                after.x(), after.y())) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO classic-world companion-healing="
                                        + after.objectId() + " hp=" + after.hp()
                                        + "/" + after.maxHp()
                                        + " skill=" + spell.skillId());
                    }
                }
            }
        } else if (monsterTarget != null && npcHpDelta < 0) {
            ClassicWorldMonsterPopulation.Hit transition =
                    hub.damageClassicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId(), playerObjectId(),
                            -npcHpDelta);
            if (transition != null) {
                hub.provokeClassicWorldMonster(
                        originMapId, originInstanceId,
                        monsterTarget.objectId(), playerObjectId());
                publishClassicWorldSpellMonsterDamage(
                        spell.skillId(), transition);
                hpAfter = transition.after().currentHp();
            }
        } else if (monsterTarget != null && npcHpDelta > 0) {
            ClassicWorldMonsterPopulation.Healing healing =
                    hub.healClassicWorldMonster(
                            originMapId, originInstanceId,
                            monsterTarget.objectId(), npcHpDelta);
            if (healing != null) {
                ClassicWorldMonsterPopulation.Snapshot after = healing.after();
                hpAfter = after.currentHp();
                byte[] ratio = Protocol.hitRatio(
                        after.objectId(), after.currentHp(), after.maximumHp());
                for (ClientSession member : worldMembers) {
                    if (sameClassicWorldMap(member)
                            && BattleSpellCatalog.isInNativeScreen(
                                member.positionX, member.positionY,
                                after.x(), after.y())) {
                        member.sendEncrypted(ratio,
                                "S_HIT_RATIO classic-world monster-healing="
                                        + after.objectId() + " hp="
                                        + after.currentHp() + "/"
                                        + after.maximumHp() + " skill="
                                        + spell.skillId());
                    }
                }
            }
        }
        System.out.println("[LiTo] C_USE_SPELL classic-world healing skill="
                + spell.skillId() + " caster=" + playerName() + " target="
                + request.targetObjectId() + " player-target="
                + (playerTarget != null) + " companion-target="
                + (companionTarget != null) + " npc=" + targetNpcId
                + " undead=" + (npcStats == null ? 0 : npcStats.undead())
                + " rolled=" + rolled + " lawful-healing=" + lawfulHealing
                + " adjusted-healing=" + adjustedHealing
                + " water-life=" + targetWaterLife
                + " water-life-consumed=" + consumedWaterLife
                + " pollute-water=" + targetPolluteWater
                + " npc-hp-delta=" + npcHpDelta + " hp-after=" + hpAfter
                + " mp-cost=" + mpCost + " mp=" + remainingMp + "/"
                + playerMaxMp);
    }


    /** Resolve only active actors in this room/map; never substitute the caster for a missing target. */
    private MassSlowCompanionTarget resolveBattleSpellCompanion(long objectId) {
        if (phase != Phase.BATTLE || observer || objectId == 0) return null;
        int map = hub.battleMapId(currentRoomId, this);
        for (ClientSession owner : hub.roomCombatants(currentRoomId)) {
            if (owner.phase != Phase.BATTLE || owner.observer || owner.currentRoomId != currentRoomId
                    || hub.battleMapId(currentRoomId, owner) != map) continue;
            BattleCompanion controlled = owner.ownedCompanion(objectId);
            if (controlled == null) continue;
            BattleCompanion.Snapshot actor = controlled.snapshot();
            if (!actor.active() || actor.hp() <= 0) return null;
            try {
                SourceNpcPhysicalStats stats = selectedSourceAccounts().npcPhysicalStats(actor.npcId());
                return new MassSlowCompanionTarget(owner, controlled, actor, stats);
            } catch (Exception failure) {
                System.out.println("[LiTo] battle companion spell target lookup failed npc=" + actor.npcId()
                        + " reason=" + failure.getClass().getSimpleName());
                return null;
            }
        }
        return null;
    }

    private boolean battleSpellCompanionStillAvailable(MassSlowCompanionTarget target) {
        ClientSession owner = target.owner();
        BattleCompanion.Snapshot actor = target.controlled().snapshot();
        return phase == Phase.BATTLE && !observer && playerHp > 0
                && owner.phase == Phase.BATTLE && !owner.observer
                && owner.currentRoomId == currentRoomId
                && hub.battleMapId(currentRoomId, owner) == hub.battleMapId(currentRoomId, this)
                && owner.ownedCompanion(actor.objectId()) == target.controlled()
                && actor.active() && actor.hp() > 0
                && actor.objectId() == target.snapshot().objectId()
                && actor.x() == target.snapshot().x() && actor.y() == target.snapshot().y();
    }

    private int applyBattleSpellCompanionDamage(MassSlowCompanionTarget target, int damage, int skillId)
            throws IOException {
        if (damage <= 0 || !battleSpellCompanionStillAvailable(target)) return 0;
        BattleCompanion.Damage hit = applyBattleCompanionFeedbackDamage(target.controlled(), damage,
                hub.roomMembers(currentRoomId), "targeted-spell-" + skillId);
        if (hit == null || hit.appliedDamage() <= 0) return 0;
        markBattleCombatWith(target.owner());
        return hit.appliedDamage();
    }

    private void useHealingSpell(byte[] byArray, BattleSpellCatalog.HealingSpell healingSpell) throws IOException {
        NativeSourceHealingCast.run(this, new Object[]{byArray, healingSpell}, 0);
    }

    private void notifyPeersOfDisconnect() throws IOException {
        if (phase == Phase.WORLD) {
            notifyClassicWorldPeersOfRemoval("disconnect");
            return;
        }
        if (rentalTownRoomState && phase == Phase.BATTLE) {
            prepareRentalHotelDeparture("disconnect");
            notifyRentalTownDeparture("disconnect");
            return;
        }
        if (phase != Phase.ROOM && phase != Phase.BATTLE && phase != Phase.RESULT) return;
        boolean battleCombatantDisconnect = phase == Phase.BATTLE
                && hub.registerBattleDisconnect(currentRoomId, this);
        byte[] roomExit = new Protocol.Writer().c(Protocol.S_LITO_EXIT_ROOM)
                .d(currentRoomId).s(litoDisplayName()).bytes();
        byte[] removed = Protocol.removeObject(playerObjectId());
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            if (member == this) continue;
            try {
                if (phase == Phase.BATTLE && !observer) {
                    member.sendEncrypted(removed, "S_REMOVE_OBJECT disconnected=" + playerName());
                }
                member.sendEncrypted(roomExit, "S_LITO_EXIT_ROOM disconnected=" + playerName());
            } catch (IOException error) {
                // Near-simultaneous closes legitimately make the peer socket
                // unavailable. The authoritative resolver still observes both
                // sessions and must not be cancelled by this best-effort UI hint.
                System.out.println("[LiTo] disconnect peer notification skipped recipient="
                        + member.playerName() + " reason=" + error.getMessage());
            }
        }
        if (battleCombatantDisconnect) {
            System.out.println("[LiTo] battle disconnect pending room=" + currentRoomId
                    + " player=" + playerName() + " graceMs="
                    + GameHub.BATTLE_DISCONNECT_GRACE_MS);
        }
    }

    private void attack(byte[] byArray, AttackEnvelope attackEnvelope) throws IOException {
        int n = switch (attackEnvelope) {
            default -> throw new IncompatibleClassChangeError();
            case DIRECT -> 23;
            case FAR -> 24;
            case ALTERNATE -> 122;
        };
        Protocol.AttackRequest attackRequest = Protocol.attackRequest(byArray, n);
        int n2 = BattleActionCodes.attackForWalk(this.battleWalkAction());
        if (!this.admitWindShackleAction(n2, "C_" + attackEnvelope.name() + "_ATTACK")) {
            return;
        }
        this.attack(attackRequest, attackEnvelope);
    }

    private boolean admitWindShackleAction(int actionId, String operation) {
        long nowNanos = System.nanoTime();
        BattleWindShackleStatus.Snapshot status =
                windShackleStatus.snapshot(nowNanos);
        if (!status.active()) return true;
        BattleAnimationCatalog.Animation animation = BattleAnimationCatalog.get()
                .requireTimedAction(battleGfx(), actionId);
        boolean admitted = windShackleStatus.tryAction(
                nowNanos, animation.durationMillis());
        if (!admitted) {
            System.out.println("[LiTo] Wind Shackle action throttled player="
                    + playerName() + " operation=" + operation
                    + " gfx=" + battleGfx() + " action=" + actionId
                    + " native-ms=" + animation.durationMillis()
                    + " multiplier=" + BattleWindShackleStatus.ACTION_MULTIPLIER
                    + " remaining=" + status.remainingSeconds());
        }
        return admitted;
    }

    /**
     * One retained weapon-buff authority shared by BATTLE, WORLD-player and
     * WORLD-monster physical attack consumers.
     */
    private NativeWeaponBuffModifiers nativeWeaponBuffModifiers(
            boolean ranged, long nowNanos) {
        int hit = Math.addExact(
                Math.addExact(
                        Math.addExact(
                                windShotStatus.physicalHit(ranged, nowNanos),
                                stormEyeStatus.physicalHit(ranged, nowNanos)),
                        stormShotStatus.physicalHit(ranged, nowNanos)),
                burningWeaponStatus.physicalHit(ranged, nowNanos));
        int damage = Math.addExact(
                Math.addExact(
                        Math.addExact(
                                Math.addExact(
                                        fireWeaponStatus.physicalDamage(ranged, nowNanos),
                                        fireBlessStatus.physicalDamage(ranged, nowNanos)),
                                stormEyeStatus.physicalDamage(ranged, nowNanos)),
                        stormShotStatus.physicalDamage(ranged, nowNanos)),
                burningWeaponStatus.physicalDamage(ranged, nowNanos));
        return new NativeWeaponBuffModifiers(hit, damage);
    }

    /**
     * Consumes native skill182 only for an admitted ordinary melee hit and
     * publishes its retained location effect to the relevant visibility set.
     */
    private boolean consumeBurningSlash(
            boolean eligible, long nowNanos, long targetObjectId,
            int targetX, int targetY, List<ClientSession> recipients,
            String source) throws IOException {
        if (!eligible || !burningSlashStatus.consume(nowNanos)) return false;
        BattleSpellCatalog.BurningSlashSpell spell =
                BattleSpellCatalog.burningSlashSpell(
                        BattleSpellCatalog.BURNING_SLASH);
        byte[] impact = Protocol.effectLocation(
                targetX, targetY, spell.impactGfx());
        for (ClientSession recipient : recipients) {
            if (phase == Phase.WORLD
                    && (recipient.phase != Phase.WORLD
                        || !sameClassicWorldMap(recipient)
                        || !BattleSpellCatalog.isInNativeScreen(
                                recipient.positionX, recipient.positionY,
                                targetX, targetY))) continue;
            recipient.sendEncrypted(impact,
                    "S_EFFECT_LOCATION Burning-Slash target=" + targetObjectId
                            + " x=" + targetX + " y=" + targetY
                            + " gfx=" + spell.impactGfx()
                            + " source=" + source);
        }
        System.out.println("[LiTo] Burning Slash consumed attacker="
                + playerName() + " target=" + targetObjectId
                + " x=" + targetX + " y=" + targetY
                + " source-damage-bonus=" + spell.nextMeleeDamage()
                + " impact-gfx=" + spell.impactGfx()
                + " source=" + source);
        return true;
    }

    /**
     * Retained ordinary-WORLD physical multiplier family. Burning Spirit and
     * Elemental Fire share one inclusive 1..100 roll; weapon double damage,
     * Double Brake and Soul of Flame contribute candidates, and only the
     * greatest multiplier is applied.
     */
    private ClassicWorldPhysicalProc classicWorldPhysicalProc(
            SourceWeaponPhysicalStats weapon, boolean physicalHit,
            boolean ranged, boolean soulOfFlameActive, long nowNanos) {
        boolean kiringkuAttack = weapon.present()
                && weapon.weaponType() == BattleKiringkuDamage.WEAPON_TYPE;
        boolean meleeProcEligible = physicalHit && !ranged && !kiringkuAttack;
        boolean burningSpiritActive = timedStatus.burningSpiritActive(nowNanos);
        boolean elementalFireActive = timedStatus.elementalFireActive(nowNanos);
        boolean sharedRollRequired = burningSpiritActive && meleeProcEligible
                || elementalFireActive && meleeProcEligible;
        int configuredSharedRoll = config.elementalFireProcFixtureRoll() > 0
                ? config.elementalFireProcFixtureRoll()
                : config.burningSpiritProcFixtureRoll();
        int sharedRoll = !sharedRollRequired ? 0
                : configuredSharedRoll > 0 ? configuredSharedRoll
                    : ThreadLocalRandom.current().nextInt(1, 101);
        BattlePhysicalProcBuff.Outcome burningSpirit =
                BattlePhysicalProcBuff.burningSpirit(
                        burningSpiritActive, meleeProcEligible,
                        burningSpiritActive && meleeProcEligible
                                ? sharedRoll : 0);
        BattlePhysicalProcBuff.Outcome elementalFire =
                BattlePhysicalProcBuff.elementalFire(
                        elementalFireActive, meleeProcEligible,
                        elementalFireActive && meleeProcEligible
                                ? sharedRoll : 0);
        boolean doubleBrakeActive = timedStatus.doubleBrakeActive(nowNanos);
        boolean doubleBrakeEligible = physicalHit && !ranged && weapon.present()
                && (weapon.weaponType() == 11 || weapon.weaponType() == 12);
        int doubleBrakeRoll = !doubleBrakeActive || !doubleBrakeEligible
                ? 0 : config.doubleBrakeProcFixtureRoll() > 0
                    ? config.doubleBrakeProcFixtureRoll()
                    : ThreadLocalRandom.current().nextInt(1, 101);
        BattlePhysicalProcBuff.Outcome doubleBrake =
                BattlePhysicalProcBuff.doubleBrake(
                        doubleBrakeActive, weapon.weaponType(), physicalHit,
                        doubleBrakeRoll);
        double multiplier = Math.max(
                Math.max(
                        Math.max(burningSpirit.multiplier(),
                                elementalFire.multiplier()),
                        doubleBrake.multiplier()),
                BattlePhysicalProcBuff.soulOfFlameMultiplier(
                        soulOfFlameActive));
        return new ClassicWorldPhysicalProc(
                burningSpirit, elementalFire, doubleBrake, multiplier);
    }

    private int chainswordWeaknessRoll(long nowNanos) {
        if (!config.chainswordWeaknessAdvanceFixtureEnabled()) {
            return ThreadLocalRandom.current().nextInt(100);
        }
        // Isolated TCP evidence needs a reproducible 0->1->2->3 transition.
        // The values are still exact members of the retained native windows:
        // 19 enters level1, while 39 advances levels1/2 through the 20..39 arm.
        int level = chainswordWeakness.snapshot(nowNanos).level();
        return level == 0 ? 19 : level < 3 ? 39 : 0;
    }

    private void attack(Protocol.AttackRequest attackRequest, AttackEnvelope attackEnvelope) throws IOException {
        NativeSourceDollAction.enter(this, new Object[]{attackRequest, attackEnvelope}, "nativeSourceControlledOriginal_attack", "(Llocal/lito381/server/Protocol$AttackRequest;Llocal/lito381/server/ClientSession$AttackEnvelope;)V", true);
    }

    private void attackClassicWorld(
            Protocol.AttackRequest request, AttackEnvelope envelope) throws IOException {
        if (observer || playerHp <= 0
                || !ClassicWorldMapCatalog.supports(classicWorldMapId)) return;
        if (rejectWhileParalyzed("C_" + envelope.name() + "_ATTACK")) return;
        closePersonalShopIfOpen("classic-world-attack");
        ClassicWorldCastleWarField.WarObject castleObjective =
                hub.classicCastleWarObject(selectedClassicServerName,
                        classicWorldMapId, request.targetObjectId());
        if (castleObjective != null
                && castleObjective.kind() == ClassicWorldCastleWarField.Kind.CROWN) {
            claimClassicCastleCrown(castleObjective);
            return;
        }
        ClassicWorldDwarfCastleDoorState.Snapshot dwarfCastleDoor =
                hub.dwarfCastleDoor(
                        classicWorldMapId, request.targetObjectId());
        ClassicWorldCastleDoorCombat.Target mainlandCastleDoor =
                hub.mainlandCastleDoorCombatTarget(
                        classicWorldMapId, request.targetObjectId(),
                        positionX, positionY);
        int weight240 = currentWeight240(System.nanoTime());
        if (weight240 >= BattleInventoryWeight.BUFFED_REGEN_LIMIT) {
            sendEncrypted(Protocol.messageCode(110),
                    "S_MESSAGE_CODE classic-world-attack-overweight=110 weight240="
                            + weight240);
            return;
        }

        ClientSession playerTarget = classicWorldMembers(classicWorldMapId).stream()
                .filter(candidate -> candidate != this
                        && sameClassicWorldMap(candidate)
                        && candidate.playerObjectId() == request.targetObjectId())
                .findFirst().orElse(null);
        if (playerTarget != null) {
            attackClassicWorldPlayer(request, envelope, playerTarget);
            return;
        }

        boolean castleTowerTarget = castleObjective != null
                && castleObjective.kind() == ClassicWorldCastleWarField.Kind.TOWER;
        boolean castleTrebuchetTarget = castleObjective != null
                && castleObjective.kind() == ClassicWorldCastleWarField.Kind.TREBUCHET;
        boolean dwarfCastleDoorTarget = dwarfCastleDoor != null;
        boolean mainlandCastleDoorTarget = mainlandCastleDoor != null;
        ClassicWorldDspyEscorts.Snapshot targetDspy =
                hub.classicWorldDspyEscorts().find(request.targetObjectId());
        boolean dspyTarget = targetDspy != null && targetDspy.alive()
                && targetDspy.mapId() == classicWorldMapId;
        ClassicWorldNpcCatalog.StaticNpc targetScarecrow =
                ClassicWorldScarecrowCatalog.target(
                        classicWorldMapId, request.targetObjectId());
        boolean scarecrowTarget = targetScarecrow != null;
        ClassicWorldNpcCatalog.StaticNpc targetMonsterGuard =
                ClassicWorldMonsterGuardCatalog.target(
                        classicWorldMapId, request.targetObjectId());
        boolean monsterGuardTarget = targetMonsterGuard != null;
        ClassicWorldMonsterPopulation.Snapshot target = dspyTarget
                ? ClassicWorldDspyCatalog.combatProjection(targetDspy)
                : monsterGuardTarget
                ? ClassicWorldMonsterGuardCatalog.combatProjection(
                        targetMonsterGuard,
                        hub.classicWorldNpcHeading(targetMonsterGuard))
                : scarecrowTarget
                ? ClassicWorldScarecrowCatalog.combatProjection(
                        targetScarecrow,
                        hub.classicWorldNpcHeading(targetScarecrow))
                : castleTowerTarget
                ? hub.classicCastleTowerCombatSnapshot(
                        selectedClassicServerName, classicWorldMapId,
                        request.targetObjectId())
                : castleTrebuchetTarget
                    ? hub.classicCastleTrebuchetCombatSnapshot(
                            selectedClassicServerName, classicWorldMapId,
                            request.targetObjectId())
                : dwarfCastleDoorTarget
                    ? hub.dwarfCastleDoorCombatSnapshot(
                            classicWorldMapId, request.targetObjectId(),
                            positionX, positionY)
                : mainlandCastleDoorTarget
                    ? mainlandCastleDoor.combat()
                : hub.classicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        request.targetObjectId());
        if (target == null && !dspyTarget && !monsterGuardTarget
                && !scarecrowTarget && !castleTowerTarget
                && !castleTrebuchetTarget && !dwarfCastleDoorTarget
                && !mainlandCastleDoorTarget) {
            ClassicWorldMonsterPopulation.Snapshot hiddenTarget =
                    hub.classicWorldMonsterIncludingHidden(
                            classicWorldMapId, classicWorldInstanceId,
                            request.targetObjectId());
            if (hiddenTarget != null
                    && (hiddenTarget.hiddenStatus()
                        == ClassicWorldMonsterPopulation.HIDDEN_STATUS_SINK
                    || hiddenTarget.hiddenStatus()
                        == ClassicWorldMonsterPopulation.HIDDEN_STATUS_FLY)) {
                System.out.println("[LiTo] rejected classic-world attack player="
                        + playerName() + " target=" + request.targetObjectId()
                        + " reason=hidden-status-"
                        + hiddenTarget.hiddenStatus());
                return;
            }
        }
        if (target == null || !target.present() || !target.alive()
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, target.x(), target.y())) {
            System.out.println("[LiTo] rejected classic-world attack player="
                    + playerName() + " target=" + request.targetObjectId()
                    + " reason=missing/dead/out-of-screen");
            return;
        }

        SourceEquipmentPhysicalStats equipment =
                requiredEquipmentMagicStats().physical();
        boolean sourceWeaponActive = !inventory.hasEquippedWeapon()
                && !sourceWeaponSuppressed;
        RuntimeInventory.Item runtimeWeapon = sourceWeaponActive
                ? null : inventory.equippedWeaponItem();
        long runtimeWeaponObjectId = runtimeWeapon == null
                ? 0 : runtimeWeapon.objectId();
        SourceWeaponPhysicalStats weapon = activePhysicalWeapon();
        boolean sourceWeaponBonusesActive = sourceWeaponActive
                || runtimeWeapon != null && runtimeWeapon.sourceBound()
                    && weapon.present();
        boolean ranged = envelope == AttackEnvelope.FAR
                || (envelope == AttackEnvelope.ALTERNATE && weapon.ranged());
        int maximumRange = BattlePhysicalAttack.maximumRange(weapon);
        int range = Math.max(Math.abs(positionX - target.x()),
                Math.abs(positionY - target.y()));
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        boolean targetAttackPosition = monsterGuardTarget
                ? ClassicWorldMonsterGuardCatalog.attackPosition(
                        map, positionX, positionY,
                        target.x(), target.y(), maximumRange)
                : map.attackPosition(
                        positionX, positionY,
                        target.x(), target.y(), maximumRange);
        if ((weapon.present() && weapon.ranged() != ranged)
                || range > maximumRange || !targetAttackPosition) {
            System.out.println("[LiTo] rejected classic-world attack player="
                    + playerName() + " target=" + target.objectId()
                    + " envelope=" + envelope + " weapon=" + weapon.weaponType()
                    + " range=" + range + " max=" + maximumRange
                    + " reason=weapon-envelope/range/los");
            return;
        }
        lastCombatTargetObjectId = target.objectId();

        ClassicWorldProjectileDebit projectileDebit = null;
        SourceProjectilePhysicalStats projectile = weapon.projectile();
        if (ranged) {
            projectileDebit = debitClassicWorldProjectile(weapon);
            if (projectileDebit == null) return;
            weapon = projectileDebit.weapon();
            projectile = projectileDebit.projectile();
        }

        naturalHpRegen.noteAttack();
        naturalMpRegen.noteAttack();
        cancelMeditation("classic-world-attack");
        revealInvisibility("classic-world-physical-attack");
        long physicalAttackNowNanos = System.nanoTime();
        boolean soulOfFlameActive = timedStatus.soulOfFlameActive(
                physicalAttackNowNanos);
        BattleWeaponBuffStatus.Modifier weaponBuff =
                weaponBuffStatus.modifier(physicalAttackNowNanos);
        NativeWeaponBuffModifiers nativeWeaponBuffs =
                nativeWeaponBuffModifiers(ranged, physicalAttackNowNanos);
        BattleItemWeaponEnchantStatus.Modifier itemWeaponEnchant =
                itemWeaponEnchantStatus.modifier(
                        physicalAttackNowNanos, runtimeWeaponObjectId);
        BattleAbilityStatus.Berserk berserk =
                abilityStatus.berserk(physicalAttackNowNanos);
        BattleAbilityStatus.BraveAura braveAura =
                abilityStatus.braveAura(physicalAttackNowNanos);
        BattleAbilityStatus.IllusionOgre illusionOgre =
                abilityStatus.illusionOgre(physicalAttackNowNanos);
        BattleAbilityStatus.IllusionAvatar illusionAvatar =
                abilityStatus.illusionAvatar(physicalAttackNowNanos);
        BattleAnimationCatalog.Animation animation = BattleAnimationCatalog.get()
                .requireTimedAction(battleGfx(),
                        BattleActionCodes.attackForWalk(battleWalkAction()));
        CharacterSummary character = selectedCharacterSummary();
        int characterType = character == null ? 0 : character.type();
        int level = effectiveClassicLevel(character);
        int attackStat = ranged ? battleDexterity() : battleStrength();
        int statHit = requiredPhysicalGrowthStats().hit(ranged, attackStat);
        int equipmentHit = equipment.totalHit(ranged, sourceWeaponBonusesActive);
        equipmentHit = Math.addExact(equipmentHit, weaponBuff.hit(ranged));
        equipmentHit = Math.addExact(equipmentHit, nativeWeaponBuffs.hit());
        equipmentHit = Math.addExact(
                equipmentHit, ranged ? 0 : berserk.meleeHit());
        equipmentHit = Math.addExact(
                equipmentHit, ranged ? 0 : illusionOgre.meleeHit());
        int d20 = 1;
        int d100 = 1;
        int negativeAcRoll = 0;
        int hitChance = 100;
        boolean hit = true;
        if (config.battlePhysicalHitEnabled()) {
            d20 = config.uncannyDodgeHitFixtureD20() > 0
                    ? config.uncannyDodgeHitFixtureD20()
                    : ThreadLocalRandom.current().nextInt(1, 21);
            if (target.template().armorClass() < 0) {
                negativeAcRoll = ThreadLocalRandom.current().nextInt(1,
                        BattlePhysicalAttack.negativeAcRollMaximum(
                                target.template().armorClass()) + 1);
            }
            hitChance = BattlePhysicalAttack.hitChanceWithStatBonus(
                    characterType, level, statHit, target.template().armorClass(),
                    equipmentHit, 0, d20, negativeAcRoll);
            d100 = config.uncannyDodgeHitFixtureD100() > 0
                    ? config.uncannyDodgeHitFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            hit = BattlePhysicalAttack.hits(hitChance, d100);
        }

        boolean targetLarge = target.template().large();
        int weaponRoll = 0;
        int projectileRoll = 0;
        int unarmedRoll = 0;
        if (weapon.present() && ranged) {
            projectileRoll = ThreadLocalRandom.current().nextInt(
                    1, projectile.damageMaximum(targetLarge) + 1);
        } else if (weapon.present()) {
            int maximum = BattlePhysicalDamage.weaponDieMaximum(
                    weapon, targetLarge);
            int fixedWeaponRoll = config.shadowFangDamageFixtureWeaponRoll();
            int ordinaryRoll = fixedWeaponRoll > 0
                    ? Math.min(fixedWeaponRoll, maximum)
                    : ThreadLocalRandom.current().nextInt(1, maximum + 1);
            weaponRoll = BattleSoulOfFlame.meleeWeaponRoll(
                    soulOfFlameActive, ordinaryRoll, maximum);
        } else {
            unarmedRoll = BattlePhysicalDamage.unarmedDamage(
                    ThreadLocalRandom.current().nextInt(4, 9));
        }
        int statDamage = requiredPhysicalGrowthStats().damage(ranged, attackStat);
        int equipmentDamage = equipment.totalDamageBonus(
                ranged, sourceWeaponBonusesActive);
        equipmentDamage = Math.addExact(
                equipmentDamage, weaponBuff.damage(ranged));
        equipmentDamage = Math.addExact(
                equipmentDamage, nativeWeaponBuffs.damage());
        equipmentDamage = Math.addExact(
                equipmentDamage, itemWeaponEnchant.damage(ranged));
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : berserk.meleeDamage());
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : braveAura.meleeDamage());
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : illusionOgre.meleeDamage());
        equipmentDamage = Math.addExact(equipmentDamage,
                ranged ? illusionAvatar.rangedDamage()
                        : illusionAvatar.meleeDamage());
        int sourceDamage = BattlePhysicalDamage.sourceDamage(
                weapon, ranged, targetLarge, weaponRoll,
                projectileRoll, unarmedRoll,
                statDamage, equipmentDamage, 0);
        int soulOfFlameRangedWeaponBase = BattleSoulOfFlame.rangedWeaponBase(
                soulOfFlameActive, weapon, targetLarge);
        sourceDamage = Math.addExact(
                sourceDamage, soulOfFlameRangedWeaponBase);
        SourceNpcPhysicalStats targetPhysical = new SourceNpcPhysicalStats(
                target.npcId(), target.template().armorClass(),
                target.template().large(), target.template().damageReduction(),
                target.template().hard(), target.template().undead(),
                target.template().weakAttribute(), target.template().magicResistance(),
                false, target.lawful(), false, target.template().boss(),
                target.template().mp(), target.template().strength(),
                target.template().dexterity());
        int materialMaximum = BattlePhysicalOffense.materialMaximum(
                weapon, targetPhysical);
        int materialRoll = materialMaximum == 0 ? 0
                : ThreadLocalRandom.current().nextInt(1, materialMaximum + 1);
        int blessingMaximum = BattlePhysicalOffense.blessingMaximum(
                weapon, targetPhysical);
        int blessingRoll = blessingMaximum == 0 ? 0
                : ThreadLocalRandom.current().nextInt(1, blessingMaximum + 1);
        BattlePhysicalOffense.NpcOutcome offense =
                BattlePhysicalOffense.againstNpc(
                        weapon, targetPhysical, materialRoll, blessingRoll);
        boolean chainswordAttack = characterType
                == BattleChainswordWeakness.DRAGON_KNIGHT_TYPE
                && weapon.weaponType() == BattleChainswordWeakness.WEAPON_TYPE;
        BattleFoeSlayerSequence.Strike foeSlayerStrike =
                foeSlayerSequence.next(target.objectId());
        BattleChainswordWeakness.AttackOutcome chainswordWeaknessOutcome =
                BattleChainswordWeakness.AttackOutcome.none();
        if (!foeSlayerStrike.active() && chainswordAttack && hit) {
            chainswordWeaknessOutcome = chainswordWeakness.attack(
                    characterType, weapon.weaponType(), target.objectId(),
                    physicalAttackNowNanos,
                    chainswordWeaknessRoll(physicalAttackNowNanos));
        } else {
            chainswordWeakness.snapshot(physicalAttackNowNanos);
        }
        int preCritical = Math.max(0, Math.addExact(
                Math.addExact(sourceDamage, offense.totalBonus()),
                Math.addExact(
                        Math.addExact(chainswordWeaknessOutcome.damageBonus(),
                                foeSlayerStrike.active()
                                    ? foeSlayerStrike.damageBonus() : 0),
                        ranged ? 0
                            : armBreakerStatus.meleeDamageModifier(
                                    physicalAttackNowNanos))));
        ClassicWorldPhysicalProc physicalProc = classicWorldPhysicalProc(
                weapon, hit, ranged, soulOfFlameActive,
                physicalAttackNowNanos);
        int doubleDamageChance = weapon.present()
                ? weapon.combatTraits().doubleDamageChance() : 0;
        BattleWeaponCritical.DamageOutcome critical = BattleWeaponCritical.apply(
                weapon, preCritical,
                doubleDamageChance == 0 ? 0
                    : ThreadLocalRandom.current().nextInt(1, 101),
                physicalProc.multiplier());
        boolean altarAttackAllowed = classicWorldCkewAttackAllowed(
                target.npcId(), System.nanoTime());
        if (!altarAttackAllowed) hit = false;
        boolean kiringkuAttack = weapon.present()
                && weapon.weaponType() == BattleKiringkuDamage.WEAPON_TYPE;
        boolean burningSlashConsumed = consumeBurningSlash(
                hit && !ranged && !kiringkuAttack,
                physicalAttackNowNanos, target.objectId(), target.x(), target.y(),
                classicWorldMembers(classicWorldMapId),
                "classic-world-monster-physical");
        int beforeDefense = burningSlashConsumed
                ? Math.addExact(critical.damage(),
                    BattleSpellCatalog.burningSlashSpell(
                            BattleSpellCatalog.BURNING_SLASH).nextMeleeDamage())
                : critical.damage();
        int acMaximum = BattlePhysicalDefense.npcAcMaximum(targetPhysical);
        int acRoll = acMaximum == 0 ? 0
                : config.shadowFangDamageFixtureWeaponRoll() > 0 ? 0
                    : ThreadLocalRandom.current().nextInt(acMaximum);
        BattlePhysicalDefense.NpcOutcome defense =
                BattlePhysicalDefense.againstNpc(
                        beforeDefense, targetPhysical, acRoll, ranged,
                        equipment.totalPierce() > 0);
        int damage = hit ? defense.damage() : 0;
        boolean armorBreakDamageActive =
                hub.classicWorldMonsterArmorBreakActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), physicalAttackNowNanos);
        damage = BattleArmorBreak.damageAfterBreak(
                damage, armorBreakDamageActive, weapon.weaponType());
        long strikerGaleNowNanos = System.nanoTime();
        damage = BattleStrikerGale.damageAfterStatus(
                damage,
                hub.classicWorldMonsterStrikerGaleActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), strikerGaleNowNanos),
                BattleStrikerGale.playerWeaponEligible(weapon.weaponType()));
        damage = BattleEarthBindRules.protectedCombatDamage(
                hub.classicWorldMonsterEarthBindActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), physicalAttackNowNanos),
                damage);
        NativeMagicDollEffects.AttackProc magicDollAttackProc = hit
                ? NativeMagicDollEffects.attack(activeMagicDollPowers(),
                    () -> ThreadLocalRandom.current().nextInt(1000))
                : NativeMagicDollEffects.AttackProc.empty();
        boolean guardianHarvest = ClassicWorldGuardianCatalog.isGuardian(target)
                && characterType == 2 && !weapon.present();
        if (guardianHarvest && hit && !harvestClassicWorldGuardian(
                target, ThreadLocalRandom.current().nextInt(1, 101))) {
            return;
        }
        int attackHeading = heading(positionX, positionY, target.x(), target.y());
        playerHeading = attackHeading;
        long projectileSequence = ranged
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        byte[] attack = ranged
                ? Protocol.rangedPhysicalAttack(
                        animation.actionId(), playerObjectId(),
                        damage > 0 ? target.objectId() : 0,
                        Math.min(0xFF, Math.max(0, damage)), attackHeading,
                        projectileSequence, projectile.effectGfx(),
                        positionX, positionY, target.x(), target.y())
                : new Protocol.Writer().c(Protocol.S_ATTACK)
                        .c(animation.actionId()).d(playerObjectId()).d(target.objectId())
                        .c(Math.min(0xFF, damage)).c(0).d(0).bytes();
        if (scarecrowTarget && hit) {
            resolveClassicWorldScarecrowHit(
                    targetScarecrow, target.template(), level);
        }
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, target.x(), target.y())) {
                continue;
            }
            member.sendEncrypted(attack,
                    "S_ATTACK classic-world attacker=" + playerObjectId()
                            + " target=" + target.objectId()
                            + " npc=" + target.npcId() + " damage=" + damage
                            + " ranged=" + ranged
                            + " projectile=" + projectile.itemId()
                            + " projectile-remaining="
                            + (projectileDebit == null ? 0
                                : projectileDebit.reservation().balance()
                                        .remainingCount())
                            + " hit=" + hit + " hit-chance=" + hitChance
                            + " d20=" + d20 + " d100=" + d100
                            + " source-damage=" + sourceDamage
                            + " soul-of-flame-active=" + soulOfFlameActive
                            + " soul-of-flame-ranged-weapon-base="
                            + soulOfFlameRangedWeaponBase
                            + " weapon-buff-skill=" + weaponBuff.skillId()
                            + " weapon-buff-hit=" + weaponBuff.hit(ranged)
                            + " weapon-buff-damage=" + weaponBuff.damage(ranged)
                            + " item-weapon-enchant-active="
                            + itemWeaponEnchant.active()
                            + " item-weapon-enchant-damage="
                            + itemWeaponEnchant.damage(ranged)
                            + " berserkers-hit="
                            + (ranged ? 0 : berserk.meleeHit())
                            + " berserkers-damage="
                            + (ranged ? 0 : berserk.meleeDamage())
                            + " brave-aura-damage="
                            + (ranged ? 0 : braveAura.meleeDamage())
                            + " burning-spirit-active="
                            + physicalProc.burningSpirit().active()
                            + " burning-spirit-eligible="
                            + physicalProc.burningSpirit().eligible()
                            + " burning-spirit-chance="
                            + physicalProc.burningSpirit().chance()
                            + " burning-spirit-roll="
                            + physicalProc.burningSpirit().roll()
                            + " burning-spirit-triggered="
                            + physicalProc.burningSpirit().triggered()
                            + " burning-spirit-multiplier="
                            + physicalProc.burningSpirit().multiplier()
                            + " elemental-fire-active="
                            + physicalProc.elementalFire().active()
                            + " elemental-fire-triggered="
                            + physicalProc.elementalFire().triggered()
                            + " double-brake-active="
                            + physicalProc.doubleBrake().active()
                            + " double-brake-triggered="
                            + physicalProc.doubleBrake().triggered()
                            + " physical-proc-multiplier="
                            + physicalProc.multiplier()
                            + " double-damage-chance=" + critical.chance()
                            + " double-damage-roll=" + critical.chanceRoll()
                            + " double-damage-triggered=" + critical.triggered()
                            + " double-damage-multiplier=" + critical.multiplier()
                            + " burning-slash-consumed=" + burningSlashConsumed
                            + " chainsword=" + chainswordAttack
                            + " chainsword-weakness-roll="
                            + chainswordWeaknessOutcome.chanceRoll()
                            + " chainsword-weakness-before="
                            + chainswordWeaknessOutcome.beforeLevel()
                            + " chainsword-weakness-after="
                            + chainswordWeaknessOutcome.afterLevel()
                            + " chainsword-weakness-triggered="
                            + chainswordWeaknessOutcome.triggered()
                            + " chainsword-weakness-bonus="
                            + chainswordWeaknessOutcome.damageBonus()
                            + " chainsword-weakness-ui=unavailable-in-selected-LiTo-bin"
                            + " foe-slayer-strike=" + foeSlayerStrike.active()
                            + " foe-slayer-strike-index="
                            + foeSlayerStrike.strikeIndex()
                            + " foe-slayer-strike-total="
                            + foeSlayerStrike.totalStrikes()
                            + " foe-slayer-exposure-level="
                            + foeSlayerStrike.exposureLevel()
                            + " foe-slayer-damage-bonus="
                            + (foeSlayerStrike.active()
                                ? foeSlayerStrike.damageBonus() : 0)
                            + " foe-slayer-final-strike="
                            + foeSlayerStrike.finalStrike()
                            + " before-defense=" + beforeDefense
                            + " npc-reduction=" + defense.totalReduction()
                            + " armor-break-active=" + armorBreakDamageActive
                            + " action=" + animation.actionId());
        }
        // Retained L1GuardianInstance.receiveDamage discards every unarmed
        // elf hit after the normal attack action has been published.
        if (guardianHarvest) return;
        // Retained L1ScarecrowInstance and L1MonsterGuardInstance both ignore
        // committed HP damage. The attack animation remains visible, but the
        // static receiver cannot gain hate, lose HP, die, drop or respawn.
        if (scarecrowTarget || monsterGuardTarget) return;
        if (!dspyTarget && !castleTowerTarget && !castleTrebuchetTarget
                && !dwarfCastleDoorTarget && !mainlandCastleDoorTarget) {
            attemptEnchantVenomPoison(
                    null, null, null, target,
                    weapon.present(), hit, target.objectId());
        }
        if (damage <= 0) return;

        if (castleTowerTarget) {
            CastleSummary defender;
            try {
                defender = effectiveClassicCastleById(
                        castleObjective.castleId());
            } catch (Exception error) {
                throw new IOException("castle defender lookup failed", error);
            }
            String attackerClan = hub.clanData(
                    sourceCharacterIdentity()).name();
            ClassicWorldCastleWarField.TowerHit towerHit =
                    hub.damageClassicCastleTower(
                            selectedClassicServerName, classicWorldMapId,
                            target.objectId(), attackerClan,
                            defender == null ? "" : defender.clanName(), damage);
            if (towerHit == null || towerHit.appliedDamage() <= 0) {
                System.out.println("[LiTo] classic castle tower damage rejected player="
                        + playerName() + " object=" + target.objectId()
                        + " castle=" + castleObjective.castleId()
                        + " clan=" + attackerClan);
                return;
            }
            publishClassicCastleTowerHit(towerHit);
            return;
        }

        if (dwarfCastleDoorTarget) {
            ClassicWorldDwarfCastleDoorState.DoorHit doorHit =
                    hub.damageDwarfCastleDoor(
                            classicWorldMapId, target.objectId(), damage);
            if (doorHit == null || doorHit.appliedDamage() <= 0) return;
            publishDwarfCastleDoorHit(doorHit);
            return;
        }

        if (mainlandCastleDoorTarget) {
            ClassicWorldCastleDoorCombat.Hit doorHit =
                    hub.damageMainlandCastleDoor(
                            mainlandCastleDoor.view().definition().family(),
                            classicWorldMapId, target.objectId(), damage);
            if (doorHit == null || doorHit.appliedDamage() <= 0) return;
            publishMainlandCastleDoorHit(doorHit);
            return;
        }

        if (castleTrebuchetTarget) {
            ClassicWorldCastleWarField.TrebuchetHit trebuchetHit =
                    hub.damageClassicCastleTrebuchet(
                            selectedClassicServerName, classicWorldMapId,
                            target.objectId(), damage);
            if (trebuchetHit == null || trebuchetHit.appliedDamage() <= 0) return;
            publishClassicCastleTrebuchetHit(trebuchetHit);
            if (trebuchetHit.diedNow()) {
                hub.scheduleClassicCastleTrebuchetCorpseRemoval(
                        selectedClassicServerName, trebuchetHit.after());
            }
            return;
        }

        if (dspyTarget) {
            ClassicWorldDspyEscorts.Damage transition =
                    hub.classicWorldDspyEscorts().damage(
                            target.objectId(), damage, System.nanoTime());
            if (transition == null || transition.appliedDamage() <= 0) return;
            byte[] ratio = Protocol.hitRatio(
                    target.objectId(), transition.after().currentHp(),
                    transition.after().maximumHp());
            for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
                if (!BattleSpellCatalog.isInNativeScreen(
                        member.positionX, member.positionY,
                        target.x(), target.y())) continue;
                member.sendEncrypted(ratio,
                        "S_HIT_RATIO Dspy-follower=" + target.objectId()
                                + " hp=" + transition.after().currentHp() + "/"
                                + transition.after().maximumHp()
                                + " source=player-physical");
                if (transition.diedNow()) {
                    member.sendEncrypted(Protocol.objectAction(
                                    target.objectId(), BattleActionCodes.DIE),
                            "S_ACTION Dspy-follower-death=" + target.objectId()
                                    + " attacker=" + playerObjectId()
                                    + " delete-delay-ms="
                                    + ClassicWorldDspyEscorts.CORPSE_MILLIS);
                }
            }
            if (transition.diedNow()) {
                hub.clearClassicWorldMonsterTargets(target.objectId());
            }
            System.out.println("[LiTo] Dspy follower damaged player="
                    + playerName() + " follower=" + target.objectId()
                    + " applied=" + transition.appliedDamage()
                    + " hp=" + transition.after().currentHp() + "/"
                    + transition.after().maximumHp()
                    + " died=" + transition.diedNow());
            return;
        }

        boolean sleepActiveBeforeDamage =
                hub.classicWorldMonsterSleepActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), System.nanoTime());
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), playerObjectId(), damage);
        if (transition == null) return;
        boolean sleepActiveAfterDamage =
                hub.classicWorldMonsterSleepActive(
                        classicWorldMapId, classicWorldInstanceId,
                        target.objectId(), System.nanoTime());
        hub.provokeClassicWorldMonster(
                classicWorldMapId, classicWorldInstanceId,
                target.objectId(), playerObjectId());
        for (BattleCompanion.Snapshot companion : classicWorldCompanionSnapshots()) {
            BattleCompanion controlled = ownedCompanion(companion.objectId());
            if (controlled != null) controlled.selectMasterTarget(target.objectId());
        }
        ClassicWorldMonsterPopulation.Snapshot after = transition.after();
        byte[] ratio = Protocol.hitRatio(
                after.objectId(), after.currentHp(), after.maximumHp());
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, after.x(), after.y())) continue;
            member.sendEncrypted(ratio,
                    "S_HIT_RATIO classic-world-monster=" + after.objectId()
                            + " hp=" + after.currentHp() + "/" + after.maximumHp());
            if (transition.diedNow()) {
                member.sendEncrypted(Protocol.objectAction(
                                after.objectId(), BattleActionCodes.DIE),
                        "S_ACTION classic-world-monster=" + after.objectId()
                                + " action=" + BattleActionCodes.DIE);
            }
        }
        System.out.println("[LiTo] classic-world monster damaged player="
                + playerName() + " object=" + after.objectId()
                + " spawn=" + after.spawnId() + " npc=" + after.npcId()
                + " damage=" + transition.appliedDamage()
                + " hp=" + after.currentHp() + "/" + after.maximumHp()
                + " died=" + transition.diedNow()
                + " sleep-before=" + sleepActiveBeforeDamage
                + " sleep-after=" + sleepActiveAfterDamage);
        if (transition.diedNow()) {
            handleClassicWorldWaterDragonDeath(
                    after, transition.contributions());
            distributeClassicWorldMonsterRewards(
                    after, transition.contributions());
            hub.scheduleClassicWorldMonsterLifecycle(
                    classicWorldInstanceId, after);
        }
        applyNativeMagicDollClassicWorldAttackProcs(
                magicDollAttackProc, target, targetPhysical);
    }

    /**
     * Retained L1GuardianInstance harvest happens before attack.action().
     * False means storeItem failed and the source returns without publishing
     * the attack; a no-reward roll remains a successful no-op.
     */
    private boolean harvestClassicWorldGuardian(
            ClassicWorldMonsterPopulation.Snapshot guardian,
            int oneBasedRoll) throws IOException {
        if (!ClassicWorldGuardianCatalog.isGuardian(guardian)) {
            throw new IllegalArgumentException("harvest target is not L1Guardian");
        }
        ClassicWorldGuardianCatalog.Harvest harvest =
                ClassicWorldGuardianCatalog.harvest(
                        guardian.npcId(), oneBasedRoll);
        if (harvest == null) {
            System.out.println("[LiTo] L1Guardian harvest no-drop player="
                    + playerName() + " npc=" + guardian.npcId()
                    + " roll=" + oneBasedRoll);
            return true;
        }
        InventoryCatalog.Definition reward =
                InventoryCatalog.require(harvest.itemId());
        RuntimeInventory next = inventory.copy();
        boolean weightAllowed = permitsInventoryAddition(
                next, reward, harvest.quantity());
        boolean added = weightAllowed && next.add(reward, harvest.quantity());
        if (!added) {
            if (!weightAllowed) sendInventoryWeightOver("L1Guardian-harvest");
            else sendInventoryCapacityOver("L1Guardian-harvest");
            System.out.println("[LiTo] L1Guardian harvest storeItem failed player="
                    + playerName() + " npc=" + guardian.npcId()
                    + " item=" + harvest.itemId() + " count="
                    + harvest.quantity() + " roll=" + oneBasedRoll);
            return false;
        }
        state.saveEconomyState(stateCharacter(), shopPoints,
                next.catalogCounts(), next.catalogItemStates());
        RuntimeInventory previous = inventory;
        NativeDeItemApplication.replace(this, next, 0);
        sendInventoryDelta(previous, inventory);
        sendEncrypted(Protocol.messageCode(
                        ClassicWorldGuardianCatalog.HARVEST_MESSAGE,
                        harvest.giverNameId(), harvest.itemMessageArgument()),
                "S_MESSAGE_CODE L1Guardian-harvest=143 npc="
                        + guardian.npcId() + " item=" + harvest.itemId()
                        + " count=" + harvest.quantity());
        System.out.println("[LiTo] L1Guardian harvest player=" + playerName()
                + " npc=" + guardian.npcId() + " roll=" + oneBasedRoll
                + " item=" + harvest.itemId() + " count="
                + harvest.quantity());
        return true;
    }

    private void resolveClassicWorldScarecrowHit(ClassicWorldNpcCatalog.StaticNpc staticNpc, ClassicWorldMonsterCatalog.MonsterTemplate monsterTemplate, int n) throws IOException {
        int n2;
        int n3;
        if (staticNpc == null || monsterTemplate == null || !ClassicWorldScarecrowCatalog.isScarecrow(staticNpc)) {
            throw new IllegalArgumentException("invalid classic scarecrow hit");
        }
        if (n < this.config.classicWorldScarecrowMaxLevel()) {
            this.applyClassicWorldNpcReward(monsterTemplate, staticNpc.experience(), 0, 1L, 1L);
        }
        if (!NativeStaticNpcScene.turn(this.hub, staticNpc, n3 = (n2 = NativeStaticNpcScene.heading(this.hub, staticNpc, this)) + 1 & 7, this)) {
            throw new IOException("canonical scarecrow heading update failed object=" + staticNpc.objectId());
        }
        byte[] byArray = new Protocol.Writer().c(28).d(staticNpc.objectId()).c(n3).bytes();
        for (ClientSession clientSession : this.classicWorldMembers(staticNpc.mapId())) {
            if (!BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, NativeStaticNpcMotion.x(staticNpc, this), NativeStaticNpcMotion.y(staticNpc, this))) continue;
            clientSession.sendEncrypted(byArray, "S_CHANGE_DIRECTION L1Scarecrow=" + staticNpc.objectId() + " npc=" + staticNpc.npcId() + " heading=" + n2 + "->" + n3);
        }
        System.out.println("[LiTo] classic-world L1Scarecrow hit player=" + this.playerName() + " object=" + staticNpc.objectId() + " npc=" + staticNpc.npcId() + " heading=" + n2 + "->" + n3 + " training-level=" + n + "/" + this.config.classicWorldScarecrowMaxLevel() + " exp=" + (n < this.config.classicWorldScarecrowMaxLevel() ? staticNpc.experience() : 0L));
    }

