    /** Exact retained L1CrownInstance.onAction ownership transition. */
    private void claimClassicCastleCrown(
            ClassicWorldCastleWarField.WarObject crown) throws IOException {
        if (crown == null || crown.kind() != ClassicWorldCastleWarField.Kind.CROWN
                || phase != Phase.WORLD || observer || playerHp <= 0
                || movementLockPending || pendingPortal != null
                || !hub.classicCastleWarActive(
                    selectedClassicServerName, crown.castleId())) return;
        CharacterSummary character = selectedCharacterSummary();
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        int gfx = battleGfx();
        if (character == null || character.type() != 0
                || (gfx != 0 && gfx != 1) || clan.name().isBlank()
                || hub.clanRole(sourceCharacterIdentity()) != GameHub.CLAN_ROLE_OWNER
                || Math.abs(positionX - crown.x()) > 1
                || Math.abs(positionY - crown.y()) > 1) return;
        if (selectedLegacyCastle() != null) {
            sendEncrypted(Protocol.messageCode(474),
                    "S_MESSAGE_CODE crown-already-owns-castle=474 player="
                            + playerName());
            return;
        }
        CastleSummary previous;
        try {
            previous = effectiveClassicCastleById(crown.castleId());
        } catch (Exception error) {
            throw new IOException("castle crown owner lookup failed", error);
        }
        if (previous != null && !hub.classicCastleSiegeParticipant(
                selectedClassicServerName, crown.castleId(), clan.name())) {
            System.out.println("[LiTo] castle crown rejected undeclared clan="
                    + clan.name() + " castle=" + crown.castleId());
            return;
        }

        GameHub.ClassicCastleClaim claim = hub.claimClassicCastleCrown(
                selectedClassicServerName, classicWorldMapId, crown.objectId(),
                clan.name(), playerName(), playerObjectId());
        if (claim == null) return;

        List<ClientSession> sourceRecipients = hub.connectedSessionsSnapshot().stream()
                .filter(session -> session.usesClassicSource(
                        selectedClassicServerName)).toList();
        GameHub.deliverClassicCastleWarNotices(
                selectedClassicServerName, claim.siege().notices(), sourceRecipients);

        List<ClientSession> mapRecipients = classicWorldMembers(classicWorldMapId);
        long previousLeaderObjectId = previous == null ? 0
                : previous.leaderObjectId();
        if (previousLeaderObjectId != 0) {
            byte[] clear = Protocol.castleOwner(0, previousLeaderObjectId);
            for (ClientSession recipient : mapRecipients) {
                recipient.sendEncrypted(clear,
                        "S_CASTLE_OWNER clear castle=" + crown.castleId()
                                + " former=" + previousLeaderObjectId);
            }
        }
        int crownSlot = castleOwnerCrownSlot(crown.castleId());
        byte[] owner = Protocol.castleOwner(crownSlot, playerObjectId());
        for (ClientSession recipient : mapRecipients) {
            recipient.sendEncrypted(owner,
                    "S_CASTLE_OWNER slot=" + crownSlot
                            + " castle=" + crown.castleId()
                            + " owner=" + playerObjectId());
        }

        ClassicWorldCastleWarField.Area area =
                ClassicWorldCastleWarField.area(crown.castleId());
        List<ClassicWorldCastleWarField.Point> returns =
                ClassicWorldCastleWarField.returnPoints(crown.castleId());
        int selector = 0;
        for (ClientSession recipient : mapRecipients) {
            GameHub.ClanData recipientClan = hub.clanData(
                    recipient.sourceCharacterIdentity());
            if (recipient == this || recipient.isAdministrator()
                    || recipientClan.name().equalsIgnoreCase(clan.name())
                    || !area.contains(recipient.classicWorldMapId,
                        recipient.positionX, recipient.positionY)) continue;
            recipient.serverClassicCastleCrownExpel(
                    crown.castleId(), returns.get(selector++ % returns.size()),
                    clan.name());
        }

        for (ClientSession member : hub.connectedClanSessions(
                sourceCharacterIdentity())) {
            if (member.phase != Phase.WORLD && member.phase != Phase.BATTLE) continue;
            if (member == this) {
                member.sendEncrypted(Protocol.castleWarOwnershipEvent(
                                Protocol.ServerEventType.CASTLE_WAR_INITIATIVE),
                        "S_EVENT castle-initiative subtype=3 castle="
                                + crown.castleId());
            }
            member.sendEncrypted(Protocol.castleWarOwnershipEvent(
                            Protocol.ServerEventType.CASTLE_WAR_OCCUPIED),
                    "S_EVENT castle-occupied subtype=4 castle=" + crown.castleId());
        }

        for (ClientSession recipient : sourceRecipients) {
            recipient.serverClassicCastleWarFieldTransition(
                    claim.field(), "crown-claim-castle-" + crown.castleId());
        }
        int repaired = hub.repairClassicCastleDoors(crown.castleId());
        for (ClientSession recipient : sourceRecipients) {
            recipient.serverClassicCastleDoorRepair(
                    crown.castleId(), repaired, "crown-claim");
        }
        System.out.println("[LiTo] castle crown claimed player=" + playerName()
                + " clan=" + clan.name() + " castle=" + crown.castleId()
                + " former=" + (previous == null ? "NPC" : previous.clanName())
                + " ownership-revision=" + (claim.ownership() == null
                    ? 0 : claim.ownership().revision())
                + " field-removed=" + claim.field().removed().size()
                + " field-spawned=" + claim.field().spawned().size()
                + " repaired-doors=" + repaired);
    }

    private void serverClassicCastleCrownExpel(
            int castleId, ClassicWorldCastleWarField.Point destination,
            String winnerClan) throws IOException {
        Protocol.PortalDestination portal = new Protocol.PortalDestination(
                destination.mapId(), destination.x(), destination.y(), true);
        pendingCallClanPortal = null;
        pendingRunClanPortal = null;
        pendingClassicWorldPortal = new PendingClassicWorldPortal(
                portal, 5, 0, "Castle-Crown-expel-castle-" + castleId, -1);
        pendingPortal = portal;
        pendingPortalReady = true;
        byte[] effect = Protocol.effectObject(
                playerObjectId(), ClassicWorldTeleportCatalog.TELEPORT_EFFECT_GFX);
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)) {
                member.sendEncrypted(effect,
                        "S_EFFECT crown-expel target=" + playerObjectId()
                                + " castle=" + castleId + " winner=" + winnerClan);
            }
        }
        sendEncrypted(Protocol.portal(portal.mapId(), portal.x(), portal.y()),
                "S_PORTAL crown-expel castle=" + castleId
                        + " winner=" + winnerClan + " destination="
                        + portal.mapId() + ":" + portal.x() + "," + portal.y());
    }

    private void serverClassicCastleDoorRepair(
            int castleId, int repairedDoors, String reason) throws IOException {
        if (phase != Phase.WORLD || repairedDoors <= 0) return;
        if (castleId == ClassicWorldDwarfCastleCatalog.CASTLE_ID) {
            sendDwarfCastleDoors(reason);
        } else if (castleId == ClassicWorldAdenToiCatalog.CASTLE_ID) {
            sendAdenCastleDoors(reason);
        } else if (castleId == ClassicWorldHeineCatalog.CASTLE_ID) {
            sendHeineCastleDoors(reason);
        }
    }

    /**
     * Retained {@code L1PcInstance.onAction -> L1AttackPc} path for an ordinary
     * classic-WORLD player target.  Tournament room authorization is
     * deliberately not consulted here: the retained world is PK-enabled, and
     * its safety/combat/normal tile bits are authoritative.
     */
    private void attackClassicWorldPlayer(
            Protocol.AttackRequest request, AttackEnvelope envelope,
            ClientSession target) throws IOException {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(classicWorldMapId);
        if (target.phase != Phase.WORLD || target.playerHp <= 0
                || target.invisible || !sameClassicWorldMap(target)
                || !BattleSpellCatalog.isInNativeScreen(
                        positionX, positionY, target.positionX, target.positionY)) {
            System.out.println("[LiTo] rejected classic-world player attack attacker="
                    + playerName() + " target=" + target.playerName()
                    + " reason=state/dead/invisible/out-of-screen");
            return;
        }

        SourceEquipmentMagicStats attackerEquipment = requiredEquipmentMagicStats();
        SourceEquipmentPhysicalStats equipment = attackerEquipment.physical();
        boolean sourceWeaponActive = !inventory.hasEquippedWeapon()
                && !sourceWeaponSuppressed;
        RuntimeInventory.Item runtimeWeapon = sourceWeaponActive
                ? null : inventory.equippedWeaponItem();
        long runtimeWeaponObjectId = runtimeWeapon == null
                ? 0 : runtimeWeapon.objectId();
        SourceWeaponPhysicalStats sourceWeapon = equipment.weapon();
        SourceWeaponPhysicalStats weapon = sourceWeaponActive
                ? sourceWeapon
                : runtimeWeapon == null ? SourceWeaponPhysicalStats.none()
                    : inventory.equippedPhysicalWeapon();
        boolean sourceWeaponBonusesActive = sourceWeaponActive
                || runtimeWeapon != null && runtimeWeapon.sourceBound()
                    && weapon.present();
        if (sourceWeaponActive && weapon.present()) {
            GameStateStore.SourceWeaponDurabilityBalance durability =
                    state.sourceWeaponDurabilityBalance(stateCharacter(), sourceWeapon);
            weapon = weapon.withDurability(durability.effectiveDurability());
        }

        boolean ranged = envelope == AttackEnvelope.FAR
                || envelope == AttackEnvelope.ALTERNATE && weapon.ranged();
        if (weapon.present() && weapon.ranged() != ranged) {
            System.out.println("[LiTo] rejected classic-world player attack attacker="
                    + playerName() + " target=" + target.playerName()
                    + " reason=weapon/envelope-mismatch weapon="
                    + weapon.weaponType() + " envelope=" + envelope);
            return;
        }
        int range = Math.max(Math.abs(positionX - target.positionX),
                Math.abs(positionY - target.positionY));
        int maximumRange = BattlePhysicalAttack.maximumRange(weapon);
        if (range > maximumRange
                || !map.attackPosition(positionX, positionY,
                        target.positionX, target.positionY, maximumRange)) {
            System.out.println("[LiTo] rejected classic-world player attack attacker="
                    + playerName() + " target=" + target.playerName()
                    + " ranged=" + ranged + " range=" + range + " max="
                    + maximumRange + " reason=range/los");
            return;
        }
        lastCombatTargetObjectId = target.playerObjectId();

        naturalHpRegen.noteAttack();
        naturalMpRegen.noteAttack();
        cancelMeditation("classic-world-player-attack");
        int attackHeading = heading(
                positionX, positionY, target.positionX, target.positionY);
        playerHeading = attackHeading;
        BattleAnimationCatalog.Animation animation = BattleAnimationCatalog.get()
                .requireTimedAction(battleGfx(),
                        BattleActionCodes.attackForWalk(battleWalkAction()));
        boolean safetyMotionOnly = map.isSafetyZone(positionX, positionY)
                || map.isSafetyZone(target.positionX, target.positionY);
        if (safetyMotionOnly) {
            revealInvisibility("classic-world-player-safe-zone-motion");
            publishClassicWorldPhysicalAttack(target, animation.actionId(), 0,
                    false, 0, 0, 0, "safety-motion-only");
            System.out.println("[LiTo] classic-world player attack motion-only attacker="
                    + playerName() + " target=" + target.playerName()
                    + " attacker-zone=" + map.zoneType(positionX, positionY)
                    + " target-zone="
                    + map.zoneType(target.positionX, target.positionY));
            return;
        }

        ClassicWorldProjectileDebit projectileDebit = null;
        SourceProjectilePhysicalStats projectile = weapon.projectile();
        if (ranged) {
            projectileDebit = debitClassicWorldProjectile(weapon);
            if (projectileDebit == null) return;
            weapon = projectileDebit.weapon();
            projectile = projectileDebit.projectile();
        }

        revealInvisibility("classic-world-player-physical-attack");
        long nowNanos = System.nanoTime();
        boolean soulOfFlameActive = timedStatus.soulOfFlameActive(nowNanos);
        BattleCookingStatus.Snapshot cooking = cookingStatus.active(nowNanos);
        BattleDragonEyeStatus.Snapshot dragonEye = dragonEyeStatus.snapshot(nowNanos);
        BattleWeaponBuffStatus.Modifier weaponBuff = weaponBuffStatus.modifier(nowNanos);
        NativeWeaponBuffModifiers nativeWeaponBuffs =
                nativeWeaponBuffModifiers(ranged, nowNanos);
        BattleItemWeaponEnchantStatus.Modifier itemEnchant =
                itemWeaponEnchantStatus.modifier(nowNanos, runtimeWeaponObjectId);
        BattleAbilityStatus.Berserk berserk = abilityStatus.berserk(nowNanos);
        BattleAbilityStatus.BounceAttack bounce = abilityStatus.bounceAttack(nowNanos);
        BattleAbilityStatus.RoyalAura royal = abilityStatus.royalAura(nowNanos);
        BattleAbilityStatus.BraveAura brave = abilityStatus.braveAura(nowNanos);
        BattleAbilityStatus.IllusionOgre illusionOgre =
                abilityStatus.illusionOgre(nowNanos);
        BattleAbilityStatus.IllusionAvatar illusionAvatar =
                abilityStatus.illusionAvatar(nowNanos);
        ClassicWorldWaterDragonCatalog.Blessing blessing =
                waterDragonBlessing(nowNanos);

        int equipmentHit = Math.addExact(
                Math.addExact(equipment.totalHit(ranged, sourceWeaponBonusesActive),
                        weaponBuff.hit(ranged)),
                Math.addExact(Math.addExact(ranged ? 0 : berserk.meleeHit(),
                                ranged ? 0 : bounce.meleeHit()),
                        ranged ? royal.rangedHit() : royal.meleeHit()));
        equipmentHit = Math.addExact(equipmentHit, nativeWeaponBuffs.hit());
        equipmentHit = Math.addExact(
                equipmentHit, ranged ? 0 : illusionOgre.meleeHit());
        int equipmentDamage = Math.addExact(
                Math.addExact(Math.addExact(
                                equipment.totalDamageBonus(
                                        ranged, sourceWeaponBonusesActive),
                                weaponBuff.damage(ranged)), itemEnchant.damage(ranged)),
                Math.addExact(ranged ? 0 : berserk.meleeDamage(),
                        Math.addExact(ranged ? 0 : brave.meleeDamage(),
                                nativeWeaponBuffs.damage())));
        equipmentDamage = Math.addExact(
                equipmentDamage, ranged ? 0 : illusionOgre.meleeDamage());
        equipmentDamage = Math.addExact(equipmentDamage,
                ranged ? illusionAvatar.rangedDamage()
                        : illusionAvatar.meleeDamage());
        int waterDragonHit = ranged && blessing != null ? blessing.bowHit() : 0;
        int waterDragonDamage = ranged && blessing != null ? blessing.bowDamage() : 0;
        equipmentHit = Math.addExact(equipmentHit, waterDragonHit);
        equipmentDamage = Math.addExact(equipmentDamage, waterDragonDamage);

        BattleSpellCatalog.WeaknessSpell weakness =
                BattleSpellCatalog.weaknessSpell(BattleSpellCatalog.WEAKNESS);
        BattleSpellCatalog.WeaknessSpell disease =
                BattleSpellCatalog.weaknessSpell(BattleSpellCatalog.DISEASE);
        boolean weaknessActive = !ranged && timedStatus.weaknessActive(nowNanos);
        boolean diseaseActive = !ranged && timedStatus.diseaseActive(nowNanos);
        int statusHit = (weaknessActive ? weakness.meleeHitModifier() : 0)
                + (diseaseActive ? disease.meleeHitModifier() : 0);
        int statusDamage = (weaknessActive ? weakness.meleeDamageModifier() : 0)
                + (diseaseActive ? disease.meleeDamageModifier() : 0)
                + (ranged ? 0
                    : armBreakerStatus.meleeDamageModifier(nowNanos));

        CharacterSummary character = selectedCharacterSummary();
        int characterType = character == null ? 0 : character.type();
        int level = character == null ? 1 : Math.max(1, character.level());
        int attackStat = Math.max(1, ranged ? battleDexterity() : battleStrength());
        int statHit = requiredPhysicalGrowthStats().hit(ranged, attackStat);
        int targetAc = target.battleArmorClass();
        int d20 = config.uncannyDodgeHitFixtureD20() > 0
                ? config.uncannyDodgeHitFixtureD20()
                : ThreadLocalRandom.current().nextInt(1, 21);
        int negativeAcRoll = targetAc < 0
                ? ThreadLocalRandom.current().nextInt(1,
                    BattlePhysicalAttack.negativeAcRollMaximum(targetAc) + 1)
                : 0;
        int targetDodgeModifier = target.effectivePhysicalDodge(nowNanos);
        int targetDodgeDown = target.effectivePhysicalDodgeDown(nowNanos);
        int hitChance = BattlePhysicalAttack.hitChanceWithStatBonus(
                characterType, level, statHit, targetAc,
                Math.addExact(equipmentHit, statusHit), cooking.physicalHit(ranged),
                targetDodgeModifier, targetDodgeDown, d20, negativeAcRoll);
        int d100 = config.uncannyDodgeHitFixtureD100() > 0
                ? config.uncannyDodgeHitFixtureD100()
                : ThreadLocalRandom.current().nextInt(1, 101);
        boolean hit = !config.battlePhysicalHitEnabled()
                || BattlePhysicalAttack.hits(hitChance, d100);
        boolean rangedEvasionChecked = false;
        int targetEvasionRate = 0;
        int rangedEvasionRoll = 0;
        if (hit && config.battlePhysicalHitEnabled()
                && weapon.bow() && hitChance > d100) {
            rangedEvasionChecked = true;
            targetEvasionRate = target.effectiveRangedEvasionRate(nowNanos);
            rangedEvasionRoll = config.rangedEvasionFixtureD100() > 0
                    ? config.rangedEvasionFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            hit = BattleRangedEvasion.hitsAfterEvasion(
                    targetEvasionRate, rangedEvasionRoll);
        }

        BattleFoeSlayerSequence.Strike foeSlayerStrike =
                foeSlayerSequence.next(target.playerObjectId());

        BattleCounterBarrier.Decision counter =
                BattleCounterBarrier.Decision.inactive();
        if (hit && !ranged) {
            counter = target.counterBarrierDecision(
                    level, effectiveBaseMagicResistance(), false,
                    counterBarrierRoll(), nowNanos);
            if (counter.triggered()) {
                commitClassicWorldPlayerCounterBarrier(target, counter);
                return;
            }
        }

        // Retained PcPhysicalAttackFlow executes L1PcInstance.setPetTarget
        // after a successful hit and after Counter Barrier has declined the
        // strike. Only aggressive companions follow this master-selected target.
        if (hit) {
            for (BattleCompanion.Snapshot companion
                    : classicWorldCompanionSnapshots()) {
                BattleCompanion controlled = ownedCompanion(companion.objectId());
                if (controlled != null) {
                    controlled.selectMasterTarget(target.playerObjectId());
                }
            }
        }

        int meleeWeaponMaximum = weapon.present() && !ranged
                ? BattlePhysicalDamage.weaponDieMaximum(weapon, false) : 0;
        int fixedWeaponRoll = config.shadowFangDamageFixtureWeaponRoll();
        int ordinaryWeaponRoll = meleeWeaponMaximum == 0 ? 0
                : fixedWeaponRoll > 0
                    ? Math.min(fixedWeaponRoll, meleeWeaponMaximum)
                    : ThreadLocalRandom.current().nextInt(1,
                            meleeWeaponMaximum + 1);
        int weaponRoll = BattleSoulOfFlame.meleeWeaponRoll(
                soulOfFlameActive, ordinaryWeaponRoll, meleeWeaponMaximum);
        int projectileRoll = weapon.present() && ranged
                ? fixedWeaponRoll > 0
                    ? Math.min(fixedWeaponRoll, projectile.damageMaximum(false))
                    : ThreadLocalRandom.current().nextInt(1,
                            projectile.damageMaximum(false) + 1)
                : 0;
        int unarmedRoll = weapon.present() ? 0
                : BattlePhysicalDamage.unarmedDamage(
                    ThreadLocalRandom.current().nextInt(4, 9));
        int statDamage = requiredPhysicalGrowthStats().damage(ranged, attackStat);
        int sourceDamage = BattlePhysicalDamage.sourceDamage(
                weapon, ranged, false, weaponRoll, projectileRoll, unarmedRoll,
                statDamage, Math.addExact(equipmentDamage,
                        ranged ? 0 : dragonEye.meleeDamage()),
                cooking.physicalDamage(ranged));
        int soulOfFlameRangedWeaponBase = BattleSoulOfFlame.rangedWeaponBase(
                soulOfFlameActive, weapon, false);
        sourceDamage = Math.addExact(
                sourceDamage, soulOfFlameRangedWeaponBase);
        BattlePhysicalOffense.PlayerOutcome offense = hit
                ? BattlePhysicalOffense.againstPlayer(weapon,
                    target.effectiveWeaponAttributeResistance(
                            weapon.combatTraits().attributeKind()))
                : BattlePhysicalOffense.PlayerOutcome.none();
        boolean chainswordAttack = characterType
                == BattleChainswordWeakness.DRAGON_KNIGHT_TYPE
                && weapon.weaponType() == BattleChainswordWeakness.WEAPON_TYPE;
        BattleChainswordWeakness.AttackOutcome chainswordWeaknessOutcome =
                BattleChainswordWeakness.AttackOutcome.none();
        if (!foeSlayerStrike.active() && chainswordAttack && hit) {
            chainswordWeaknessOutcome = chainswordWeakness.attack(
                    characterType, weapon.weaponType(), target.playerObjectId(),
                    nowNanos, chainswordWeaknessRoll(nowNanos));
        } else {
            chainswordWeakness.snapshot(nowNanos);
        }
        int preCritical = Math.max(0, Math.addExact(
                Math.addExact(
                        Math.addExact(sourceDamage, offense.attributeDamage()),
                        Math.addExact(chainswordWeaknessOutcome.damageBonus(),
                                foeSlayerStrike.active()
                                    ? foeSlayerStrike.damageBonus() : 0)),
                statusDamage));
        int doubleChance = weapon.present()
                ? weapon.combatTraits().doubleDamageChance() : 0;
        ClassicWorldPhysicalProc physicalProc = classicWorldPhysicalProc(
                weapon, hit, ranged, soulOfFlameActive, nowNanos);
        BattleWeaponCritical.DamageOutcome critical = BattleWeaponCritical.apply(
                weapon, preCritical,
                doubleChance == 0 ? 0 : ThreadLocalRandom.current().nextInt(1, 101),
                physicalProc.multiplier());
        boolean kiringkuAttack = weapon.present()
                && weapon.weaponType() == BattleKiringkuDamage.WEAPON_TYPE;
        boolean burningSlashConsumed = consumeBurningSlash(
                hit && !ranged && !kiringkuAttack,
                nowNanos, target.playerObjectId(), target.positionX,
                target.positionY, classicWorldMembers(classicWorldMapId),
                "classic-world-player-physical");
        int resolvedSourceDamage = burningSlashConsumed
                ? Math.addExact(critical.damage(),
                    BattleSpellCatalog.burningSlashSpell(
                            BattleSpellCatalog.BURNING_SLASH).nextMeleeDamage())
                : critical.damage();
        int acMaximum = BattlePhysicalDefense.playerAcMaximum(
                target.battleCharacterType(), targetAc);
        int acRoll = acMaximum == 0 ? 0
                : ThreadLocalRandom.current().nextInt(acMaximum);
        int armorBase = target.effectiveArmorMagicReductionBase();
        int armorRoll = armorBase <= 10 ? 0
                : ThreadLocalRandom.current().nextInt(armorBase - 10);
        BattlePhysicalDefense.PlayerOutcome defense =
                BattlePhysicalDefense.againstPlayer(
                        resolvedSourceDamage, target.battleCharacterType(), targetAc,
                        acRoll, armorBase, armorRoll,
                        equipment.totalIgnoreReduction(),
                        target.requiredEquipmentMagicStats().physical()
                                .directionalReduction(ranged));
        int damage = hit ? target.combatDamageAfterCooking(
                defense.damage(), "classic-world-player-physical", true,
                weapon.weaponType()) : 0;
        damage = BattleStrikerGale.damageAfterStatus(
                damage, target.timedStatus.strikerGaleActive(nowNanos),
                BattleStrikerGale.playerWeaponEligible(weapon.weaponType()));
        if (target.timedStatus.earthBindActive(nowNanos)
                || target.timedStatus.absoluteBarrierActive(nowNanos)) {
            damage = 0;
        }
        NativeMagicDollEffects.AttackProc magicDollAttackProc = hit
                ? NativeMagicDollEffects.attack(activeMagicDollPowers(),
                    () -> ThreadLocalRandom.current().nextInt(1000))
                : NativeMagicDollEffects.AttackProc.empty();

        long projectileSequence = ranged
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        byte[] resolvedPacket = ranged
                ? Protocol.rangedPhysicalAttack(
                    animation.actionId(), playerObjectId(),
                    damage > 0 ? target.playerObjectId() : 0,
                    Math.min(0xFF, Math.max(0, damage)), attackHeading,
                    projectileSequence, projectile.effectGfx(),
                    positionX, positionY, target.positionX, target.positionY)
                : classicWorldPhysicalAttackPacket(
                    target, animation.actionId(), damage);
        publishClassicWorldPhysicalAttackPacket(
                target, resolvedPacket, damage, hit, hitChance, d20, d100,
                ranged ? "resolved-ranged"
                    + " ranged-er-checked=" + rangedEvasionChecked
                    + " target-er=" + targetEvasionRate
                    + " ranged-er-roll=" + rangedEvasionRoll
                    : "resolved-melee");
        attemptEnchantVenomPoison(
                target, null, null, null,
                weapon.present(), hit, target.playerObjectId());
        if (damage > 0) {
            target.applyBounceAttackWeaponDamage(
                    this, weapon, sourceWeapon, sourceWeaponActive,
                    runtimeWeaponObjectId);
            target.takeClassicWorldPlayerDamage(damage, this);
        }
        applyNativeMagicDollAttackProcs(magicDollAttackProc,
                target.playerObjectId(), target, null, null, null);
        System.out.println("[LiTo] classic-world player physical attacker="
                + playerName() + " target=" + target.playerName()
                + " weapon=" + weapon.weaponType() + " ranged=" + ranged
                + " projectile=" + projectile.itemId() + " projectile-remaining="
                + (projectileDebit == null ? 0
                    : projectileDebit.reservation().balance().remainingCount())
                + " source="
                + resolvedSourceDamage + " damage=" + damage + " hit=" + hit
                + " soul-of-flame-active=" + soulOfFlameActive
                + " soul-of-flame-weapon-roll=" + weaponRoll
                + " soul-of-flame-ranged-weapon-base="
                + soulOfFlameRangedWeaponBase
                + " item-weapon-enchant-active=" + itemEnchant.active()
                + " item-weapon-enchant-damage=" + itemEnchant.damage(ranged)
                + " burning-spirit-active="
                + physicalProc.burningSpirit().active()
                + " burning-spirit-eligible="
                + physicalProc.burningSpirit().eligible()
                + " burning-spirit-chance="
                + physicalProc.burningSpirit().chance()
                + " burning-spirit-roll="
                + physicalProc.burningSpirit().roll()
                + " burning-spirit-triggered="
                + physicalProc.burningSpirit().triggered()
                + " burning-spirit-multiplier="
                + physicalProc.burningSpirit().multiplier()
                + " elemental-fire-active="
                + physicalProc.elementalFire().active()
                + " elemental-fire-triggered="
                + physicalProc.elementalFire().triggered()
                + " double-brake-active="
                + physicalProc.doubleBrake().active()
                + " double-brake-triggered="
                + physicalProc.doubleBrake().triggered()
                + " physical-proc-multiplier="
                + physicalProc.multiplier()
                + " double-damage-chance=" + critical.chance()
                + " double-damage-roll=" + critical.chanceRoll()
                + " double-damage-triggered=" + critical.triggered()
                + " double-damage-multiplier=" + critical.multiplier()
                + " burning-slash-consumed=" + burningSlashConsumed
                + " chainsword=" + chainswordAttack
                + " chainsword-weakness-roll="
                + chainswordWeaknessOutcome.chanceRoll()
                + " chainsword-weakness-before="
                + chainswordWeaknessOutcome.beforeLevel()
                + " chainsword-weakness-after="
                + chainswordWeaknessOutcome.afterLevel()
                + " chainsword-weakness-triggered="
                + chainswordWeaknessOutcome.triggered()
                + " chainsword-weakness-bonus="
                + chainswordWeaknessOutcome.damageBonus()
                + " chainsword-weakness-ui=unavailable-in-selected-LiTo-bin"
                + " foe-slayer-strike=" + foeSlayerStrike.active()
                + " foe-slayer-strike-index="
                + foeSlayerStrike.strikeIndex()
                + " foe-slayer-strike-total="
                + foeSlayerStrike.totalStrikes()
                + " foe-slayer-exposure-level="
                + foeSlayerStrike.exposureLevel()
                + " foe-slayer-damage-bonus="
                + (foeSlayerStrike.active()
                    ? foeSlayerStrike.damageBonus() : 0)
                + " foe-slayer-final-strike="
                + foeSlayerStrike.finalStrike()
                + " chance=" + hitChance + " d20=" + d20 + " d100=" + d100
                + " ranged-er-checked=" + rangedEvasionChecked
                + " target-er=" + targetEvasionRate
                + " ranged-er-roll=" + rangedEvasionRoll
                + " target-ac=" + targetAc
                + " target-dodge-modifier=" + targetDodgeModifier
                + " target-dodge-down=" + targetDodgeDown
                + " ac-reduction="
                + defense.acReduction() + " armor-reduction="
                + defense.armorReduction() + " criminal-eligible="
                + classicWorldPinkNameEligible(target, map));
    }

    /** Same persistent arrow/sting debit used by retained tournament combat. */
    private ClassicWorldProjectileDebit debitClassicWorldProjectile(
            SourceWeaponPhysicalStats originalWeapon) throws IOException {
        SourceWeaponPhysicalStats weapon = originalWeapon;
        SourceProjectilePhysicalStats projectile = weapon.projectile();
        RuntimeInventory.Item runtimeProjectile = projectile.present()
                ? inventory.item(projectile.objectId()) : null;
        if (runtimeProjectile != null && runtimeProjectile.sourceBound()) {
            long sourceObjectId = sourceProjectileObjects.entrySet().stream()
                    .filter(entry -> entry.getValue() == runtimeProjectile.objectId())
                    .mapToLong(Map.Entry::getKey).findFirst().orElse(0L);
            if (sourceObjectId == 0) {
                System.out.println("[LiTo] rejected classic-world ranged attack source"
                        + " projectile has no provenance player=" + playerName()
                        + " runtime-object=" + runtimeProjectile.objectId());
                return null;
            }
            projectile = projectile.withObjectId(sourceObjectId);
            weapon = weapon.withProjectile(projectile);
        }
        if (!projectile.present()) {
            System.out.println("[LiTo] rejected classic-world ranged attack missing"
                    + " qualified projectile player=" + playerName()
                    + " weapon-item=" + weapon.itemId()
                    + " weapon-type=" + weapon.weaponType());
            return null;
        }

        GameStateStore.SourceProjectileReservation reservation;
        long runtimeObjectId = 0;
        RuntimeInventory.Item before = null;
        RuntimeInventory.Item after = null;
        try {
            Long mappedRuntimeObject = sourceProjectileObjects.get(projectile.objectId());
            RuntimeInventory.Item localProjectile = mappedRuntimeObject == null
                    ? inventory.item(projectile.objectId()) : null;
            if (localProjectile != null && !localProjectile.sourceBound()
                    && localProjectile.definition().projectile()) {
                runtimeObjectId = localProjectile.objectId();
                before = localProjectile;
                RuntimeInventory candidate = inventory.copy();
                if (projectile.consumeOnAttack()
                        && !candidate.remove(runtimeObjectId, 1)) {
                    throw new IOException(
                            "runtime projectile candidate debit was rejected");
                }
                state.saveEconomyState(stateCharacter(), shopPoints,
                        candidate.catalogCounts(), candidate.catalogItemStates());
                NativeDeItemApplication.replace(this, candidate, 0);
                after = inventory.item(runtimeObjectId);
                long remaining = after == null ? 0 : after.quantity();
                reservation = new GameStateStore.SourceProjectileReservation(
                        true, new GameStateStore.SourceProjectileBalance(
                                projectile.objectId(), projectile.itemId(),
                                projectile.count(), remaining));
            } else if (mappedRuntimeObject == null) {
                reservation = state.reserveSourceProjectile(
                        stateCharacter(), projectile);
            } else {
                runtimeObjectId = mappedRuntimeObject;
                before = inventory.item(runtimeObjectId);
                RuntimeInventory candidate = inventory.copy();
                if (projectile.consumeOnAttack() && before != null
                        && candidate.consumeSourceProjectile(runtimeObjectId) == null) {
                    throw new IOException(
                            "source projectile candidate debit was rejected");
                }
                reservation = state.reserveSourceProjectile(
                        stateCharacter(), projectile, runtimeObjectId,
                        candidate.catalogCounts(), candidate.catalogItemStates());
                if (reservation.accepted() && projectile.consumeOnAttack()) {
                    NativeDeItemApplication.replace(this, candidate, 0);
                    after = inventory.item(runtimeObjectId);
                }
            }
        } catch (IOException failure) {
            System.out.println("[LiTo] rejected classic-world ranged projectile"
                    + " ledger player=" + playerName() + " projectile-object="
                    + projectile.objectId() + " reason=" + failure.getMessage());
            return null;
        }
        if (!reservation.accepted()) {
            System.out.println("[LiTo] rejected classic-world ranged projectile"
                    + " exhausted player=" + playerName() + " projectile-object="
                    + projectile.objectId() + " item=" + projectile.itemId());
            return null;
        }
        if (before != null && projectile.consumeOnAttack()) {
            if (after == null) {
                sendEncrypted(Protocol.removeInventory(runtimeObjectId),
                        "S_REMOVE_INVENTORY classic-world source-projectile object="
                                + runtimeObjectId + " remaining=0");
            } else {
                sendEncrypted(Protocol.changeInventoryCount(
                                runtimeObjectId, after.quantity()),
                        "S_CHANGE_COUNT classic-world source-projectile object="
                                + runtimeObjectId + " remaining=" + after.quantity());
            }
        }
        return new ClassicWorldProjectileDebit(
                weapon, projectile, reservation, runtimeObjectId, before, after);
    }

    private void publishClassicWorldPhysicalAttack(
            ClientSession target, int actionId, int damage, boolean hit,
            int hitChance, int d20, int d100, String reason) throws IOException {
        publishClassicWorldPhysicalAttackPacket(target,
                classicWorldPhysicalAttackPacket(target, actionId, damage),
                damage, hit, hitChance, d20, d100, reason);
    }

    private byte[] classicWorldPhysicalAttackPacket(
            ClientSession target, int actionId, int damage) {
        return new Protocol.Writer().c(Protocol.S_ATTACK)
                .c(actionId).d(playerObjectId()).d(target.playerObjectId())
                .c(Math.min(0xFF, Math.max(0, damage))).c(0).d(0).bytes();
    }

    private void publishClassicWorldPhysicalAttackPacket(
            ClientSession target, byte[] packet, int damage, boolean hit,
            int hitChance, int d20, int d100, String reason) throws IOException {
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    target.positionX, target.positionY)) continue;
            member.sendEncrypted(packet,
                    "S_ATTACK classic-world-player attacker=" + playerObjectId()
                            + " target=" + target.playerObjectId()
                            + " damage=" + damage + " hit=" + hit
                            + " chance=" + hitChance + " d20=" + d20
                            + " d100=" + d100 + " reason=" + reason);
        }
    }

    private void commitClassicWorldPlayerCounterBarrier(
            ClientSession defender, BattleCounterBarrier.Decision decision)
            throws IOException {
        BattleSpellCatalog.CounterBarrierSpell spell =
                BattleSpellCatalog.counterBarrierSpell(
                        BattleSpellCatalog.COUNTER_BARRIER);
        byte[] effect = Protocol.effectObject(
                defender.playerObjectId(), spell.triggerEffectGfx());
        byte[] reaction = Protocol.objectAction(
                playerObjectId(), BattleActionCodes.DAMAGE);
        String evidence = " defender=" + defender.playerObjectId()
                + " attacker=" + playerObjectId()
                + " probability=" + decision.probability()
                + " roll=" + decision.roll()
                + " gfx=" + spell.triggerEffectGfx()
                + " action=" + BattleActionCodes.DAMAGE
                + " source-damage=" + decision.sourceDamage()
                + " original-attack-suppressed=true"
                + " recursive-reflection-suppressed=true";
        for (ClientSession member : classicWorldMembers(classicWorldMapId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY, positionX, positionY)
                    && !BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    defender.positionX, defender.positionY)) continue;
            member.sendEncrypted(effect,
                    "S_EFFECT classic-world-player Counter-Barrier" + evidence);
            member.sendEncrypted(reaction,
                    "S_ACTION classic-world-player Counter-Barrier" + evidence);
        }
        int appliedDamage = combatDamageAfterCooking(
                decision.sourceDamage(), "classic-world-counter-barrier", true);
        takeClassicWorldPlayerDamage(appliedDamage, defender, false, true);
        System.out.println("[LiTo] classic-world player Counter Barrier triggered"
                + " defender=" + defender.playerName()
                + " attacker=" + playerName() + evidence
                + " applied-damage=" + appliedDamage);
    }

    /** Retained player portion of CalcExp, including its native party pool. */
    private void distributeClassicWorldMonsterRewards(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions)
            throws IOException {
        if (defeated == null) return;
        // Retained L1GuardInstance death only removes the guard and applies
        // its PK absolution to a player it killed.  It never enters
        // L1MonsterInstance's CalcExp/drop/lawful reward path.
        if (ClassicWorldGuardCatalog.isGuard(defeated)) return;
        if (ClassicWorldDesireCaveCatalog.supports(defeated.mapId())) {
            GameStateStore.FactionKarmaBalance before =
                    state.factionKarma(stateCharacter());
            int delta = ClassicWorldDesireCaveCatalog.monsterKarmaDelta(
                    defeated.npcId(), before.level());
            if (delta != 0) {
                GameStateStore.FactionKarmaMutation mutation =
                        state.addFactionKarma(stateCharacter(), delta);
                // The retained FA 57 d S_Karma layout conflicts with the
                // selected LiTo FA=S_LITO_CLAN producer. Keep the proven
                // faction value authoritative server-side until a selected
                // client producer establishes a compatible status packet.
                System.out.println("[LiTo] Desire-Cave karma player=" + playerName()
                        + " npc=" + defeated.npcId() + " before="
                        + mutation.before() + " after=" + mutation.after()
                        + " requested=" + mutation.requestedDelta());
            }
        }
        if (contributions == null || contributions.isEmpty()) return;
        awardClassicWorldRoyalTrialQuestDrop(defeated);
        awardClassicWorldCkewQuestDrop(defeated);
        completeClassicWorldCkewAltar(defeated);
        List<ClientSession> occupants = classicWorldMembers(defeated.mapId());
        Map<Long, ClientSession> eligible = new LinkedHashMap<>();
        for (ClientSession occupant : occupants) {
            if (occupant.phase == Phase.WORLD && !occupant.observer
                    && occupant.playerHp > 0) {
                eligible.put(occupant.playerObjectId(), occupant);
            }
        }
        ClassicWorldMonsterCatalog.MonsterTemplate template = defeated.template();
        Map<Long, Long> hateByPlayer = new LinkedHashMap<>();
        List<ClassicWorldRewardDistribution.Companion> companionContributions =
                new ArrayList<>();
        for (ClassicWorldMonsterPopulation.Contribution contribution : contributions) {
            if (!eligible.containsKey(contribution.playerObjectId())) continue;
            if (contribution.kind()
                    == ClassicWorldMonsterPopulation.ContributorKind.PLAYER) {
                hateByPlayer.merge(contribution.playerObjectId(),
                        contribution.hate(), Math::addExact);
                continue;
            }
            ClientSession owner = eligible.get(contribution.playerObjectId());
            BattleCompanion.Snapshot companion = owner == null ? null
                    : owner.classicWorldCompanionSnapshot(
                            contribution.sourceObjectId());
            if (companion == null || !companion.active()) continue;
            ClassicWorldMonsterPopulation.ContributorKind authoritativeKind =
                    companion.kind().earnsExperience()
                            ? ClassicWorldMonsterPopulation.ContributorKind.PET
                            : ClassicWorldMonsterPopulation.ContributorKind.SUMMON;
            if (authoritativeKind != contribution.kind()) continue;
            companionContributions.add(
                    new ClassicWorldRewardDistribution.Companion(
                            contribution.sourceObjectId(),
                            contribution.playerObjectId(), contribution.kind(),
                            contribution.hate()));
        }
        if (hateByPlayer.isEmpty() && companionContributions.isEmpty()) return;

        GameHub.ClassicPartyData party = hub.classicPartyData(sourceCharacterIdentity());
        boolean visibleCrownPartyLeader = party.inParty() && occupants.stream()
                .filter(occupant -> occupant.phase == Phase.WORLD)
                .filter(occupant -> party.leaderIdentity().equalsIgnoreCase(
                        occupant.sourceCharacterIdentity()))
                .filter(occupant -> occupant == this
                        || BattleSpellCatalog.isInNativeScreen(
                                positionX, positionY,
                                occupant.positionX, occupant.positionY))
                .map(ClientSession::selectedCharacterSummary)
                .anyMatch(character -> character != null && character.type() == 0);
        List<ClassicWorldRewardDistribution.Player> players = new ArrayList<>();
        for (ClientSession occupant : eligible.values()) {
            boolean partyMember = party.inParty() && party.memberIdentities().stream()
                    .anyMatch(identity -> identity.equalsIgnoreCase(
                            occupant.sourceCharacterIdentity()));
            players.add(new ClassicWorldRewardDistribution.Player(
                    occupant.playerObjectId(),
                    Math.max(1, occupant.playerClassicLevel),
                    hateByPlayer.getOrDefault(occupant.playerObjectId(), 0L),
                    partyMember,
                    occupant == this || BattleSpellCatalog.isInNativeScreen(
                            positionX, positionY, occupant.positionX, occupant.positionY)));
        }
        List<ClassicWorldRewardDistribution.Award> awards =
                ClassicWorldRewardDistribution.distribute(
                        template.experience(), template.lawful(), playerObjectId(),
                        party.inParty(), visibleCrownPartyLeader, players,
                        companionContributions);
        for (ClassicWorldRewardDistribution.Award award : awards) {
            if (award.recipientKind()
                    == ClassicWorldRewardDistribution.RecipientKind.PET) {
                ClientSession owner = eligible.get(award.ownerObjectId());
                if (owner != null) {
                    owner.applyClassicWorldPetReward(
                            award.objectId(), award.baseExperience());
                }
                continue;
            }
            ClientSession recipient = eligible.get(award.ownerObjectId());
            if (recipient == null) continue;
            recipient.applyClassicWorldNpcReward(
                    template, award.baseExperience(), award.sourceLawfulShare(),
                    award.hate(), award.totalHate());
        }
        distributeClassicWorldMonsterDrops(defeated, contributions, eligible);
    }

    private void handleClassicWorldWaterDragonDeath(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions)
            throws IOException {
        if (defeated == null
                || defeated.mapId() != ClassicWorldWaterDragonCatalog.MAP_ID
                || classicWorldInstanceId <= 0) return;
        int showId = classicWorldInstanceId;
        ClassicWorldWaterDragonCatalog.Door opened =
                hub.classicWorldWaterDragonGuardianDied(
                        showId, defeated.npcId());
        if (opened != null) {
            broadcastWaterDragonDoorOpen(
                    opened, showId, "guardian-" + defeated.npcId() + "-death");
        }
        if (ClassicWorldWaterDragonCatalog.bossPhase(defeated.npcId()) == null) {
            return;
        }
        Set<Long> hatePlayerIds = contributions == null ? Set.of()
                : contributions.stream()
                        .filter(contribution -> contribution.hate() > 0)
                        .map(ClassicWorldMonsterPopulation.Contribution::playerObjectId)
                        .collect(java.util.stream.Collectors.toCollection(
                                LinkedHashSet::new));
        Set<String> hateIdentities = hub.classicWorldMembers(
                        ClassicWorldWaterDragonCatalog.MAP_ID, showId).stream()
                .filter(member -> hatePlayerIds.contains(member.playerObjectId()))
                .map(ClientSession::sourceCharacterIdentity)
                .map(ClassicWorldWaterDragonInstances::normalize)
                .collect(java.util.stream.Collectors.toCollection(
                        LinkedHashSet::new));
        if (!hub.classicWorldWaterDragonBossDied(
                showId, defeated.npcId(), hateIdentities,
                System.nanoTime())) {
            throw new IOException("Water Dragon boss phase rejected show="
                    + showId + " npc=" + defeated.npcId());
        }
    }

    private void applyClassicWorldPetReward(
            long petObjectId, long baseExperience) throws IOException {
        BattleCompanion pet = ownedCompanion(petObjectId);
        BattleCompanion.Snapshot before = pet == null ? null : pet.snapshot();
        if (before == null || before.kind() != BattleCompanion.Kind.PET
                || !before.active() || before.hp() <= 0) return;
        SourcePetTemplate template;
        try {
            template = selectedSourceAccounts().petTemplate(before.npcId());
        } catch (Exception sourceFailure) {
            throw new IOException("cannot load selected-source pet growth row for NPC "
                    + before.npcId(), sourceFailure);
        }
        ClassicPetExperience.Progress progress = ClassicPetExperience.apply(
                before, baseExperience, config.classicWorldExperienceRate(), template,
                (minimum, maximum) -> ThreadLocalRandom.current()
                        .nextInt(minimum, maximum + 1));
        pet.updatePetProgress(progress.afterLevel(), progress.afterMaxHp(),
                progress.afterMaxMp(), progress.afterExperience());
        GameStateStore.PetState durable = pet.durablePetState();
        if (durable == null) throw new IOException("persistent pet identity disappeared");
        state.savePet(durable);
        BattleCompanion.Snapshot after = pet.snapshot();
        sendEncrypted(Protocol.classicPet(after, playerName(), true),
                "S_PUT_OBJECT persistent-pet-progress=" + after.objectId()
                        + " exp=" + progress.beforeExperience() + "->"
                        + progress.afterExperience() + " adjusted="
                        + progress.adjustedExperience() + " level="
                        + progress.beforeLevel() + "->" + progress.afterLevel()
                        + " hp-max=" + progress.beforeMaxHp() + "->"
                        + progress.afterMaxHp() + " mp-max="
                        + progress.beforeMaxMp() + "->" + progress.afterMaxMp()
                        + " exp-percent=" + progress.experiencePercentage());
        if (progress.levelChanged()) {
            sendEncrypted(Protocol.messageCode(320, after.name()),
                    "S_MESSAGE_CODE persistent-pet-level-up=320 pet=" + after.name());
        }
    }

    /** Retained SetDrop + DropShare modes for selected map4 monster resources. */
    private void distributeClassicWorldMonsterDrops(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible) throws IOException {
        List<RuntimeInventory.Item> releasedPetItems =
                hub.takeMonsterCarriedItems(
                        defeated.mapId(), classicWorldInstanceId,
                        defeated.objectId());
        if (!releasedPetItems.isEmpty()) {
            distributeReleasedPetItems(
                    defeated, contributions, eligible, releasedPetItems);
        }
        NativeMagicDollPowers dollPowers = activeMagicDollPowers();
        double dollDropMultiplier =
                dollPowers.percentMultiplier("PASSIVE_DROP_RATE");
        double effectiveItemRate = config.classicWorldDropItemRate()
                * dollDropMultiplier;
        List<ClassicWorldDropCatalog.RolledItem> rolled = new ArrayList<>(
                ClassicWorldDropCatalog.roll(
                        defeated.mapId(), defeated.npcId(),
                        effectiveItemRate,
                        config.classicWorldDropAdenaRate(), 1.0,
                        ThreadLocalRandom.current()));
        rolled.addAll(ClassicWorldRoyalTrialCatalog.rollOrdinaryDrops(
                defeated.mapId(), defeated.npcId(),
                effectiveItemRate,
                config.classicWorldDropAdenaRate(), 1.0,
                ThreadLocalRandom.current()));
        System.out.println("[LiTo] classic-world monster drop-rate player="
                + playerName() + " npc=" + defeated.npcId()
                + " server-rate=" + config.classicWorldDropItemRate()
                + " doll-percent=" + dollPowers.value("PASSIVE_DROP_RATE")
                + " effective-rate=" + effectiveItemRate);
        if (rolled.isEmpty()) return;

        int autoLoot = config.classicWorldDropAutoLoot();
        for (ClassicWorldDropCatalog.RolledItem rolledItem : rolled) {
            int objects = rolledItem.item().stackable() ? 1 : rolledItem.quantity();
            for (int index = 0; index < objects; index++) {
                ClassicWorldDropCatalog.RolledItem drop = rolledItem.item().stackable()
                        ? rolledItem : new ClassicWorldDropCatalog.RolledItem(
                                rolledItem.item(), 1, rolledItem.chanceRoll());
                ClientSession recipient = autoLoot == 0 ? null
                        : selectClassicWorldDropRecipient(
                                defeated, contributions, eligible, autoLoot);
                boolean granted = recipient != null
                        && recipient.receiveClassicWorldMonsterDrop(defeated, drop);
                if (granted) continue;

                int dropX;
                int dropY;
                if (recipient != null) {
                    // Retained PcItemGrantHelper: inventory overflow falls at the
                    // selected acquirer's feet, not at the dead monster.
                    dropX = recipient.positionX;
                    dropY = recipient.positionY;
                } else {
                    int[] location = classicWorldAdjacentDropLocation(defeated);
                    dropX = location[0];
                    dropY = location[1];
                }
                putClassicWorldMonsterDrop(defeated, drop, dropX, dropY,
                        recipient == null ? "monster-drop" : "autoloot-overflow");
            }
        }
    }

    /** Retained C15 monster executor: last attacker, active crown trial, 40%. */
    private void awardClassicWorldRoyalTrialQuestDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return;
        int fixtureRoll = config.classicWorldQuestDropFixtureRoll();
        int roll = fixtureRoll == 0
                ? ThreadLocalRandom.current().nextInt(100) : fixtureRoll - 1;
        ClassicWorldRoyalTrialCatalog.QuestDropDecision decision =
                ClassicWorldRoyalTrialCatalog.decideQuestDrop(
                        defeated.npcId(), character.type(),
                        state.storyQuests(stateCharacter()).effective(),
                        inventory.catalogCounts(), roll);
        if (decision == null) return;
        if (!decision.awarded()) {
            System.out.println("[LiTo] royal-trial quest drop skipped player="
                    + playerName() + " npc=" + defeated.npcId()
                    + " item=" + decision.itemId() + " crown=" + decision.crown()
                    + " active=" + decision.trialActive() + " owned="
                    + decision.alreadyOwned() + " roll=" + decision.roll());
            return;
        }

        InventoryCatalog.Definition definition = InventoryCatalog.find(decision.itemId());
        if (definition == null) {
            throw new IOException("royal trial quest item definition vanished "
                    + decision.itemId());
        }
        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        RuntimeInventory next = inventory.copy();
        // A synthetic transfer object always has id 1; direct catalog storage
        // must allocate/merge a real unique inventory object instead.
        boolean stored = next.add(definition, 1)
                && permitsInventoryAddition(inventory, definition, 1);
        if (stored) {
            RuntimeInventory previous = inventory;
            state.saveEconomyState(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY,
                    defeated.npcId());
            if (ground == null) {
                throw new IOException("royal trial quest item ground handoff failed");
            }
            broadcastClassicWorldGroundItem(
                    ground, "royal-trial-quest-drop-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, defeated.nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE royal-trial-quest-drop=143 npc="
                        + defeated.npcId() + " item=" + decision.itemId()
                        + " stored=" + stored + " roll=" + decision.roll());
        System.out.println("[LiTo] royal-trial quest item awarded player="
                + playerName() + " npc=" + defeated.npcId()
                + " item=" + decision.itemId() + " stored=" + stored
                + " roll=" + decision.roll());
    }

    /** Retained CKEW50_* death executors: last attacker, show-local and item guarded. */
    private void awardClassicWorldCkewQuestDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        if (defeated.mapId() != ClassicWorldCkewCatalog.MAP_ID
                || classicWorldInstanceId < 0) return;
        int fixtureRoll = config.classicWorldQuestDropFixtureRoll();
        int roll = fixtureRoll == 0
                ? ThreadLocalRandom.current().nextInt(100) : fixtureRoll - 1;
        Map<Long, Integer> counts = inventory.catalogCounts();
        long itemId = ClassicWorldCkewMonsterDeathExecutor.questItem(
                defeated.npcId(), activeStorySkillEffect(
                        ClassicWorldCkewCatalog.DESTRUCTION_MEDICINE_EFFECT,
                        System.nanoTime()),
                counts.containsKey(49165L), counts.containsKey(49166L),
                counts.containsKey(49168L), roll);
        if (itemId == 0) return;

        InventoryCatalog.Definition definition = InventoryCatalog.find(itemId);
        if (definition == null) {
            throw new IOException("CKEW quest item definition vanished " + itemId);
        }
        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        RuntimeInventory next = inventory.copy();
        boolean stored = next.add(definition, 1)
                && permitsInventoryAddition(inventory, definition, 1);
        if (stored) {
            RuntimeInventory previous = inventory;
            state.saveEconomyState(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates());
            NativeDeItemApplication.replace(this, next, 0);
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY,
                    defeated.npcId());
            if (ground == null) {
                throw new IOException("CKEW quest item ground handoff failed");
            }
            broadcastClassicWorldGroundItem(ground, "CKEW-quest-drop-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, defeated.nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE CKEW-quest-drop=143 show="
                        + classicWorldInstanceId + " npc=" + defeated.npcId()
                        + " item=" + itemId + " stored=" + stored
                        + " roll=" + roll);
        System.out.println("[LiTo] CKEW quest item awarded player="
                + playerName() + " show=" + classicWorldInstanceId
                + " npc=" + defeated.npcId() + " item=" + itemId
                + " stored=" + stored + " roll=" + roll);
    }

    /** Retained CKEW50_Altar: complete quest122 and award 49241 to the whole show. */
    private void completeClassicWorldCkewAltar(
            ClassicWorldMonsterPopulation.Snapshot defeated) throws IOException {
        if (defeated.mapId() != ClassicWorldCkewCatalog.MAP_ID
                || defeated.npcId() != 87000 || classicWorldInstanceId < 0) return;
        int showId = classicWorldInstanceId;
        for (ClientSession member : hub.classicWorldMembers(
                ClassicWorldCkewCatalog.MAP_ID, showId)) {
            member.serverClassicWorldCkewAltarCompleted(showId, defeated);
        }
    }

    private void serverClassicWorldCkewAltarCompleted(
            int showId, ClassicWorldMonsterPopulation.Snapshot altar)
            throws IOException {
        if (phase != Phase.WORLD
                || classicWorldMapId != ClassicWorldCkewCatalog.MAP_ID
                || classicWorldInstanceId != showId || altar == null) return;
        InventoryCatalog.Definition definition = InventoryCatalog.find(
                ClassicWorldCkewCatalog.ALTAR_PROOF);
        if (definition == null) {
            throw new IOException("CKEW altar proof definition vanished");
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        boolean alreadyOwned = next.catalogCounts().containsKey(
                (long) ClassicWorldCkewCatalog.ALTAR_PROOF);
        boolean stored = alreadyOwned || (permitsInventoryAddition(
                inventory, definition, 1) && next.add(definition, 1));
        Map<Integer, Integer> quests = new LinkedHashMap<>(
                state.storyQuests(stateCharacter()).effective());
        quests.put(ClassicWorldCkewCatalog.QUEST_ID,
                ClassicWorldCkewCatalog.QUEST_COMPLETED);
        state.saveEconomyStateAndStoryQuests(
                stateCharacter(), shopPoints, next.catalogCounts(),
                next.catalogItemStates(), quests);
        NativeDeItemApplication.replace(this, next, 0);
        if (alreadyOwned) return;

        RuntimeInventory.Item source = new RuntimeInventory.Item(
                1, definition, 1, false, 0, 0, true,
                RuntimeInventory.BLESSING_NORMAL);
        if (stored) {
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    altar.mapId(), classicWorldInstanceId,
                    source, 1, positionX, positionY, altar.npcId());
            if (ground == null) {
                throw new IOException("CKEW altar proof ground handoff failed");
            }
            broadcastClassicWorldGroundItem(ground, "CKEW-altar-proof-overflow");
        }
        sendEncrypted(Protocol.messageCode(
                        143, altar.template().nameId(), source.nativeViewName()),
                "S_MESSAGE_CODE CKEW-altar-proof=143 show=" + showId
                        + " item=" + ClassicWorldCkewCatalog.ALTAR_PROOF
                        + " stored=" + stored);
        System.out.println("[LiTo] CKEW altar completed player=" + playerName()
                + " show=" + showId + " quest-step="
                + ClassicWorldCkewCatalog.QUEST_COMPLETED
                + " proof-stored=" + stored);
    }

    /** A liberated pet keeps its former bag until the replacement monster dies. */
    private void distributeReleasedPetItems(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible,
            List<RuntimeInventory.Item> releasedItems) throws IOException {
        int autoLoot = config.classicWorldDropAutoLoot();
        for (RuntimeInventory.Item item : releasedItems) {
            ClientSession recipient = autoLoot == 0 ? null
                    : selectClassicWorldDropRecipient(
                            defeated, contributions, eligible, autoLoot);
            boolean granted = recipient != null
                    && recipient.receiveReleasedPetItem(defeated, item);
            if (granted) continue;
            int x;
            int y;
            if (recipient == null) {
                int[] location = classicWorldAdjacentDropLocation(defeated);
                x = location[0];
                y = location[1];
            } else {
                x = recipient.positionX;
                y = recipient.positionY;
            }
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    item, item.quantity(), x, y, defeated.npcId());
            if (ground == null) {
                throw new IllegalStateException(
                        "released pet item ground handoff was rejected");
            }
            broadcastClassicWorldGroundItem(ground,
                    recipient == null ? "released-pet-drop" : "released-pet-overflow");
            System.out.println("[LiTo] released pet item dropped wild="
                    + defeated.objectId() + " catalog="
                    + item.definition().catalogId() + " object=" + ground.objectId()
                    + " quantity=" + ground.quantity() + " x=" + x + " y=" + y);
        }
    }

    private boolean receiveReleasedPetItem(ClassicWorldMonsterPopulation.Snapshot snapshot, RuntimeInventory.Item item) throws IOException {
        RuntimeInventory runtimeInventory = this.inventory.copy();
        if (!runtimeInventory.add(item, (long)item.quantity()) || !this.permitsInventoryAddition(this.inventory, item.definition(), item.quantity())) {
            return false;
        }
        RuntimeInventory runtimeInventory2 = this.inventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 0);
        this.sendInventoryDelta(runtimeInventory2, this.inventory);
        this.sendEncrypted(Protocol.messageCode(143, snapshot.nameId(), item.nativeViewName()), "S_MESSAGE_CODE released-pet-autoloot=143 wild=" + snapshot.objectId() + " catalog=" + item.definition().catalogId() + " quantity=" + item.quantity());
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, this.inventory.catalogCounts(), this.inventory.catalogItemStates());
        return true;
    }

    private ClientSession selectClassicWorldDropRecipient(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            List<ClassicWorldMonsterPopulation.Contribution> contributions,
            Map<Long, ClientSession> eligible, int autoLoot) {
        List<ClassicWorldMonsterPopulation.Contribution> candidates = new ArrayList<>();
        long totalHate = 0;
        for (ClassicWorldMonsterPopulation.Contribution contribution : contributions) {
            ClientSession recipient = eligible.get(contribution.playerObjectId());
            if (recipient == null || contribution.hate() <= 0) continue;
            if (autoLoot == 1 && Math.max(
                    Math.abs(recipient.positionX - defeated.x()),
                    Math.abs(recipient.positionY - defeated.y()))
                    > config.classicWorldDropLootingRange()) continue;
            candidates.add(contribution);
            totalHate = Math.addExact(totalHate, contribution.hate());
        }
        if (totalHate <= 0) return null;
        long selected = ThreadLocalRandom.current().nextLong(totalHate);
        for (ClassicWorldMonsterPopulation.Contribution contribution : candidates) {
            if (selected < contribution.hate()) {
                return eligible.get(contribution.playerObjectId());
            }
            selected -= contribution.hate();
        }
        return eligible.get(candidates.get(candidates.size() - 1).playerObjectId());
    }

    private boolean receiveClassicWorldMonsterDrop(ClassicWorldMonsterPopulation.Snapshot snapshot, ClassicWorldDropCatalog.RolledItem rolledItem) throws IOException {
        ClassicWorldDropCatalog.ItemWire itemWire = rolledItem.item();
        InventoryCatalog.Definition definition = itemWire.inventoryDefinition();
        RuntimeInventory.Item item = new RuntimeInventory.Item(1L, definition, rolledItem.quantity(), false, 0, 0, false, itemWire.blessing());
        RuntimeInventory runtimeInventory = this.inventory.copy();
        if (!runtimeInventory.add(item, (long)rolledItem.quantity()) || !this.permitsInventoryAddition(this.inventory, definition, rolledItem.quantity())) {
            System.out.println("[LiTo] classic-world autoloot overflow player=" + this.playerName() + " npc=" + snapshot.npcId() + " catalog=" + itemWire.itemId() + " quantity=" + rolledItem.quantity());
            return false;
        }
        RuntimeInventory runtimeInventory2 = this.inventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 0);
        this.sendInventoryDelta(runtimeInventory2, this.inventory);
        this.sendEncrypted(Protocol.messageCode(143, snapshot.nameId(), ClientSession.classicWorldDropLogName(definition, rolledItem.quantity())), "S_MESSAGE_CODE classic-world-autoloot=143 npc=" + snapshot.npcId() + " catalog=" + itemWire.itemId() + " quantity=" + rolledItem.quantity());
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, this.inventory.catalogCounts(), this.inventory.catalogItemStates());
        System.out.println("[LiTo] classic-world autoloot player=" + this.playerName() + " npc=" + snapshot.npcId() + " catalog=" + itemWire.itemId() + " quantity=" + rolledItem.quantity() + " chance-roll=" + rolledItem.chanceRoll());
        return true;
    }

    private static String classicWorldDropLogName(
            InventoryCatalog.Definition definition, int quantity) {
        if (definition.stackable()) return definition.name() + " (" + quantity + ")";
        return definition.name();
    }

    private void putClassicWorldMonsterDrop(
            ClassicWorldMonsterPopulation.Snapshot defeated,
            ClassicWorldDropCatalog.RolledItem drop,
            int x, int y, String reason) throws IOException {
        int objects = drop.item().stackable() ? 1 : drop.quantity();
        int quantity = drop.item().stackable() ? drop.quantity() : 1;
        for (int index = 0; index < objects; index++) {
            ClassicWorldGroundItems.Item item = hub.putClassicWorldGroundItem(
                    defeated.mapId(), classicWorldInstanceId,
                    drop.item(), quantity, x, y, defeated.npcId());
            if (item == null) {
                throw new IllegalStateException("validated classic WORLD drop was rejected");
            }
            broadcastClassicWorldGroundItem(item, reason);
            System.out.println("[LiTo] classic-world ground drop npc=" + defeated.npcId()
                    + " catalog=" + drop.item().itemId() + " object=" + item.objectId()
                    + " quantity=" + item.quantity() + " x=" + x + " y=" + y
                    + " chance-roll=" + drop.chanceRoll() + " reason=" + reason);
        }
    }

    private int[] classicWorldAdjacentDropLocation(
            ClassicWorldMonsterPopulation.Snapshot defeated) {
        ClassicWorldMapCatalog.ClassicMap map =
                ClassicWorldMapCatalog.forMap(defeated.mapId());
        int start = ThreadLocalRandom.current().nextInt(CLASSIC_GROUND_DX.length);
        for (int offset = 0; offset < CLASSIC_GROUND_DX.length; offset++) {
            int direction = (start + offset) & 7;
            int x = defeated.x() + CLASSIC_GROUND_DX[direction];
            int y = defeated.y() + CLASSIC_GROUND_DY[direction];
            if (map.canStep(defeated.x(), defeated.y(), x, y)) {
                return new int[]{x, y};
            }
        }
        return new int[]{defeated.x(), defeated.y()};
    }

    private void applyClassicWorldNpcReward(
            ClassicWorldMonsterCatalog.MonsterTemplate npc,
            long baseExperience, int sourceLawfulShare,
            long hate, long totalHate) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null || phase != Phase.WORLD || playerHp <= 0) return;

        int requestedLawfulDelta = -((int) (
                sourceLawfulShare * config.classicWorldLawfulRate()));
        GameStateStore.LawfulMutation lawful = state.addLawful(
                stateCharacter(), nativeLawful(character.lawful()), requestedLawfulDelta);
        playerLawful = lawful.after();
        if (lawful.changed()) {
            byte[] packet = Protocol.changeAlignment(playerObjectId(), playerLawful);
            for (ClientSession viewer : classicWorldMembers(classicWorldMapId)) {
                if (viewer != this && !BattleSpellCatalog.isInNativeScreen(
                        viewer.positionX, viewer.positionY, positionX, positionY)) continue;
                viewer.sendEncrypted(packet,
                        "S_CHANGE_ALIGNMENT classic-world player=" + playerName()
                                + " object=" + playerObjectId() + " npc=" + npc.npcId()
                                + " source-share=" + sourceLawfulShare
                                + " requested-delta=" + lawful.requestedDelta()
                                + " applied-delta=" + lawful.appliedDelta()
                                + " lawful=" + lawful.before() + "->" + lawful.after());
            }
        }

        int sourceLevel = Math.max(1,
                Math.min(ClassicExperienceCatalog.MAXIMUM_LEVEL, character.level()));
        int fixedExperienceBonus = experienceGemStatus.snapshot(
                System.nanoTime()).bonusExperience();
        NativeMagicDollPowers dollPowers = activeMagicDollPowers();
        double dollExperienceMultiplier =
                dollPowers.percentMultiplier("PASSIVE_EXP_RATE");
        double effectiveExperienceRate = config.classicWorldExperienceRate()
                * dollExperienceMultiplier;
        GameStateStore.ClassicExperienceMutation experience =
                 state.addClassicExperience(
                        stateCharacter(), character.experience(), sourceLevel, baseExperience,
                        effectiveExperienceRate,
                        fixedExperienceBonus);
        playerClassicExperience = experience.afterExperience();
        playerClassicLevel = experience.afterLevel();
        if (experience.changed()) {
            if (experience.levelChanged()) {
                sendNativeBattleStatus(System.nanoTime(), "classic-world-level-up");
            } else {
                sendEncrypted(Protocol.experience(
                                playerClassicLevel, playerClassicExperience),
                        "S_EXP classic-world player=" + playerName()
                                + " npc=" + npc.npcId()
                                + " level=" + playerClassicLevel
                                + " experience=" + experience.beforeExperience()
                                + "->" + experience.afterExperience()
                                + " base=" + baseExperience
                                + " adjusted=" + experience.adjustedExperience());
            }
        }
        System.out.println("[LiTo] classic-world NPC reward player=" + playerName()
                + " npc=" + npc.npcId() + " hate=" + hate + "/" + totalHate
                + " exp-base=" + baseExperience
                + " exp-server-rate=" + config.classicWorldExperienceRate()
                + " exp-doll-percent=" + dollPowers.value("PASSIVE_EXP_RATE")
                + " exp-rate=" + effectiveExperienceRate
                + " dragon-gem-fixed=" + fixedExperienceBonus
                + " exp-adjusted=" + experience.adjustedExperience()
                + " exp=" + experience.beforeExperience() + "->"
                + experience.afterExperience() + " level="
                + experience.beforeLevel() + "->" + experience.afterLevel()
                + " lawful-source-share=" + sourceLawfulShare
                + " lawful-rate=" + config.classicWorldLawfulRate()
                + " lawful=" + lawful.before() + "->" + lawful.after());
    }

    private synchronized BattleCounterBarrier.Decision counterBarrierDecision(
            int attackerLevel, int attackerMagicResistance,
            boolean attackerBoss, int oneBasedRoll, long nowNanos) {
        BattleSpellCatalog.CounterBarrierSpell spell =
                BattleSpellCatalog.counterBarrierSpell(
                        BattleSpellCatalog.COUNTER_BARRIER);
        boolean active = abilityStatus.counterBarrier(nowNanos)
                .remainingSeconds() != 0;
        SourceWeaponPhysicalStats weapon = activePhysicalWeapon();
        if (active && !spell.supportsWeapon(weapon)) {
            abilityStatus.removeCounterBarrier();
            active = false;
            System.out.println("[LiTo] Counter Barrier removed player=" + playerName()
                    + " reason=trigger-without-two-hand-sword");
        }
        int holderMagicHit = Math.addExact(
                requiredEquipmentMagicStats().totalMagicHit(),
                dragonEyeStatus.snapshot(nowNanos).magicHit());
        return BattleCounterBarrier.decide(
                spell, active, weapon, battleLevel(), attackerLevel,
                holderMagicHit, attackerMagicResistance, attackerBoss,
                oneBasedRoll);
    }

