    private boolean completeClassicWorldRescueFollowerIfReady() throws IOException {
        ClassicWorldRescueFollowers.Snapshot owned =
                hub.classicWorldRescueFollowers().owned(sourceCharacterIdentity());
        if (owned == null) return false;
        ClassicWorldNpcCatalog.StaticNpc target = ClassicWorldNpcCatalog
                .all(ClassicWorldRescueFollowers.MAP_ID).stream()
                .filter(npc -> npc.npcId() == owned.definition().targetNpcId())
                .findFirst().orElseThrow(() -> new IOException(
                        "retained rescue target is unavailable npc="
                                + owned.definition().targetNpcId()));
        ClassicWorldRescueFollowers.Snapshot removed =
                hub.classicWorldRescueFollowers().completeIfNear(
                        sourceCharacterIdentity(), positionX, positionY,
                        target.x(), target.y());
        if (removed == null) return false;

        ClassicWorldRescueFollowers.Definition definition = removed.definition();
        ClassicWorldStoryQuestCatalog.Event event =
                ClassicWorldStoryQuestCatalog.all().stream()
                .filter(candidate -> candidate.id() == definition.completionEventId())
                .findFirst().orElseThrow(() -> new IOException(
                        "rescue completion story event is unavailable id="
                                + definition.completionEventId()));
        if (event.questId() != definition.questId()
                || event.givenItems().size() != 1
                || event.givenItems().get(0).itemId() != definition.rewardItemId()
                || event.givenItems().get(0).count() != 1) {
            hub.classicWorldRescueFollowers().restoreAfterFailedCompletion(removed);
            throw new IOException("rescue completion event diverged id=" + event.id());
        }

        RuntimeInventory previous = inventory;
        RuntimeInventory next = inventory.copy();
        InventoryCatalog.Definition reward = InventoryCatalog.find(
                definition.rewardItemId());
        if (reward == null) {
            hub.classicWorldRescueFollowers().restoreAfterFailedCompletion(removed);
            throw new IOException("rescue reward is unavailable item="
                    + definition.rewardItemId());
        }
        boolean rewardStored = permitsInventoryAddition(inventory, reward, 1)
                && next.add(reward, 1);
        if (!rewardStored) next = inventory.copy();
        Map<Integer, Integer> nextQuests =
                ClassicWorldStoryQuestCatalog.applyQuestMutation(
                        event, state.storyQuests(stateCharacter()).effective());
        try {
            state.saveEconomyStateAndStoryQuests(
                    stateCharacter(), shopPoints, next.catalogCounts(),
                    next.catalogItemStates(), nextQuests);
            NativeDeItemApplication.replace(this, next, 0);
        } catch (IOException | RuntimeException failure) {
            hub.classicWorldRescueFollowers().restoreAfterFailedCompletion(removed);
            throw failure;
        }

        if (rewardStored) {
            sendInventoryDelta(previous, inventory);
        } else {
            ClassicWorldGroundItems.Item ground = hub.putClassicWorldGroundItem(
                    classicWorldMapId, classicWorldInstanceId, reward, 1,
                    positionX, positionY, definition.followerNpcId());
            if (ground == null) {
                throw new IOException("rescue reward ground handoff failed item="
                        + definition.rewardItemId());
            }
            broadcastClassicWorldGroundItem(ground,
                    "rescue-completion-overflow-" + definition.kind());
        }
        broadcastClassicWorldRescueReplacement(removed, null, "quest-complete");
        System.out.println("[LiTo] rescue quest complete player=" + playerName()
                + " kind=" + definition.kind() + " quest=" + definition.questId()
                + " follower=" + removed.objectId()
                + " target-npc=" + target.npcId()
                + " reward=" + definition.rewardItemId()
                + " stored=" + rewardStored
                + " next-quests=" + nextQuests);
        return true;
    }

