    private int activeItemArmorEnchantModifier(long l) {
        int n = 0;
        for (RuntimeInventory.Item item : this.inventory.items()) {
            InventoryCatalog.NativeArmorStatus nativeArmorStatus = item.definition().sourceArmorStatus();
            if (!item.equipped() || nativeArmorStatus == null || nativeArmorStatus.armorType() != 2) continue;
            n += CombatWeaponBuffs.itemArmorModifier(this.itemArmorEnchantStatus, l, item.objectId(), this).armorClass();
        }
        return CombatWeaponBuffs.armor(n, this, l);
    }

