    private int ordinaryMagicDamage(int skillId, int attribute, int sourceDamage,
                                    int elementalResistance, int targetMagicResistance,
                                    int targetArmorReductionBase,
                                    String targetDescription) {
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int cookingSpellPower = spellPowerModifier(System.nanoTime());
        int magicIntelligence = BattleCookingCatalog.magicIntelligenceAfterCooking(
                equipment.magicIntelligenceTerm(baseIntelligence()), cookingSpellPower);
        int elementalDamage = BattleElementalResistance.magicDamage(
                sourceDamage, magicIntelligence, elementalResistance);
        CharacterSummary character = selectedCharacterSummary();
        int characterType = character == null ? 0 : character.type();
        int originalIntelligence = character == null
                ? 0 : Math.max(0, character.originalIntelligence());
        int criticalRoll = ThreadLocalRandom.current().nextInt(1, 101);
        int skillLevel = ((skillId - 1) >> 3) + 1;
        BattleMagicResistance.MagicAttackerResult attacker =
                BattleMagicResistance.attackerBonuses(
                        elementalDamage, skillLevel, criticalRoll,
                        characterType, originalIntelligence,
                        Math.addExact(equipment.totalMagicDamage(),
                                activeMagicDollPowers().value(
                                        "PASSIVE_MAGIC_DMG_MODIFIER")));
        int reductionOffset = targetArmorReductionBase > 10
                ? ThreadLocalRandom.current().nextInt(targetArmorReductionBase - 10) : 0;
        int armorReduction = BattleMagicResistance.armorDamageReduction(
                targetArmorReductionBase, reductionOffset);
        int preMrDamage = Math.max(attacker.damage() - armorReduction, 0);
        int originalMagicHit = originalMagicHit();
        int damage = BattleMagicResistance.damageAfterResistance(
                preMrDamage, targetMagicResistance, originalMagicHit);
        System.out.println("[LiTo] ordinary magic damage skill=" + skillId
                + " caster=" + playerName() + " target=" + targetDescription
                + " source-damage=" + sourceDamage + " base-int=" + baseIntelligence()
                + " effective-int=" + equipment.effectiveIntelligence(baseIntelligence())
                + " item-sp=" + equipment.itemSpellPower()
                + " cooking-sp=" + cookingSpellPower
                + " magic-int-term=" + magicIntelligence
                + " attr=" + attribute + " resistance=" + elementalResistance
                + " elemental-damage=" + elementalDamage
                + " critical-roll=" + criticalRoll
                + " critical-bonus=" + attacker.originalCriticalBonus()
                + " critical=" + attacker.critical()
                + " original-magic-damage=" + attacker.originalDamage()
                + " equipment-magic-damage=" + attacker.equipmentDamage()
                + " target-reduction-base=" + targetArmorReductionBase
                + " target-reduction=" + armorReduction
                + " pre-mr-damage=" + preMrDamage + " target-mr="
                + targetMagicResistance + " original-magic-hit=" + originalMagicHit
                + " damage=" + damage);
        return damage;
    }

    private int baseArmorClass() {
        CharacterSummary character = selectedCharacterSummary();
        if (character == null) return 10;
        // Saved source AC already contains the selection-time equipment.
        // Preserve every unresolved permanent layer and apply only the exact
        // retained equipment delta produced by a LiTo-side toggle.
        long currentModifier = requiredEquipmentMagicStats()
                .physical().armorClassModifier();
        long adjusted = Math.addExact((long) character.armorClass(),
                Math.subtractExact(currentModifier,
                        (long) sourceInitialArmorClassModifier));
        adjusted = Math.addExact(adjusted,
                inventory.equippedNativeArmorBonuses().armorClassModifier());
        return NumericBreakthrough.clampArmorClass(adjusted);
    }

