    void sendInventoryWeightOver(String source) throws IOException {
        sendEncrypted(Protocol.messageCode(82),
                "S_MESSAGE_CODE inventory-weight-over=82 source=" + source);
    }

    void sendInventoryCapacityOver(String source) throws IOException {
        sendEncrypted(Protocol.messageCode(263),
                "S_MESSAGE_CODE inventory-capacity-over=263 source=" + source);
    }

    void sendTradeAdmissionRejected(boolean recipient, boolean weight, String source)
            throws IOException {
        if (recipient) {
            if (weight) sendInventoryWeightOver(source);
            else sendInventoryCapacityOver(source);
            sendEncrypted(Protocol.messageCode(270),
                    "S_MESSAGE_CODE trade-recipient-over=270 source=" + source);
        } else {
            sendEncrypted(Protocol.messageCode(271),
                    "S_MESSAGE_CODE trade-partner-over=271 source=" + source);
        }
    }

