    private void tryMortalBodyArenaBotReflection(long l, List<ClientSession> list, String string) throws IOException {
        if (this.phase != Phase.BATTLE || this.currentRoomId != l || this.hub.botHp(l) <= 0) {
            return;
        }
        BattleMortalBody.Decision decision = CombatProbability.npcMortalDecision(this, 1, false, new Object[0]);
        if (!decision.triggered()) {
            return;
        }
        this.publishMortalBodyNpcReaction(2L, 0, list, decision, string);
        int n = this.hub.damageBot(l, decision.reflectedDamage());
        this.broadcastHitRatio(2L, n, 100, n == 0 ? "mortal-body-bot-death" : "mortal-body-bot-damage");
        if (n == 0) {
            byte[] byArray = Protocol.objectAction(2L, 8);
            for (ClientSession object : list) {
                object.sendEncrypted(byArray, "S_ACTION Mortal Body bot death");
            }
            BattleRules.Resolution resolution = new BattleRules.Resolution(true, false, Set.of(Long.valueOf(this.playerObjectId())), Set.of(), "arena-bot-defeated-by-mortal-body");
            for (ClientSession clientSession : list) {
                clientSession.serverEndBattle(resolution);
            }
            this.hub.endBattle(l);
        }
        System.out.println("[LiTo] Mortal Body triggered defender=" + this.playerName() + " npc-attacker=2 probability=" + decision.probability() + " roll=" + decision.roll() + " reflected-damage=" + decision.reflectedDamage() + " remaining=" + n + " source=" + string + " trigger-effect-gfx=none recursive-feedback-suppressed=true");
    }

    private void applyJoyOfPainArenaBotFeedback(
            long roomId, BattleJoyOfPainStatus.Lease lease,
            int feedbackDamage, List<ClientSession> recipients,
            String source) throws IOException {
        if (lease == null || !hub.consumeBotJoyOfPain(roomId, lease)) return;
        if (feedbackDamage <= 0 || hub.botHp(roomId) <= 0) return;
        byte[] reaction = Protocol.objectAction(2, BattleActionCodes.DAMAGE);
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(reaction,
                    "S_ACTION Joy-of-Pain-feedback bot=2 defender="
                            + playerObjectId() + " action="
                            + BattleActionCodes.DAMAGE + " source=" + source);
        }
        int remaining = hub.damageBot(roomId, feedbackDamage);
        broadcastHitRatio(2, remaining, GameHub.ARENA_BOT_MAX_HP,
                remaining == 0 ? "joy-of-pain-bot-death"
                        : "joy-of-pain-bot-damage");
        if (remaining == 0) {
            byte[] death = Protocol.objectAction(2, BattleActionCodes.DIE);
            for (ClientSession recipient : recipients) {
                recipient.sendEncrypted(death,
                        "S_ACTION Joy of Pain bot death");
            }
            BattleRules.Resolution resolution = new BattleRules.Resolution(
                    true, false, Set.of(playerObjectId()), Set.of(),
                    "arena-bot-defeated-by-joy-of-pain");
            for (ClientSession recipient : recipients) {
                recipient.serverEndBattle(resolution);
            }
            hub.endBattle(roomId);
        }
        System.out.println("[LiTo] Joy of Pain triggered bot=2 defender="
                + playerName() + " feedback-damage=" + feedbackDamage
                + " remaining=" + remaining + " source=" + source
                + " lease-consumed=true");
    }

