    /** Emits one server-owned Quest/Time-Attack actor transition. */
    void serverMonsterAiTick(GameHub.MonsterAiTick tick) throws IOException {
        if (tick == null || tick.target() != this || !hub.battleStarted(tick.roomId())) {
            return;
        }
        int actorX;
        int actorY;
        int actorNpcId;
        int actorLevel;
        int actorGfx;
        boolean actorFinalBoss = false;
        BattleQuestEncounter.Snapshot questActor = null;
        BattleTimeAttackEncounter.Snapshot timeActor = null;
        if (tick.mode() == BattleRules.Mode.QUEST_BATTLE) {
            BattleQuestEncounter.Snapshot actor = hub.questMonster(
                    tick.roomId(), tick.objectId());
            if (actor == null || actor.force() != tick.force()) return;
            questActor = actor;
            actorX = actor.x();
            actorY = actor.y();
            actorNpcId = actor.npcId();
            actorLevel = actor.level();
            actorGfx = actor.gfx();
        } else if (tick.mode() == BattleRules.Mode.TIME_ATTACK) {
            BattleTimeAttackEncounter.Snapshot actor = hub.timeAttackActor(
                    tick.roomId(), tick.objectId());
            if (actor == null) return;
            timeActor = actor;
            actorX = actor.x();
            actorY = actor.y();
            actorNpcId = actor.npcId();
            actorLevel = actor.level();
            actorGfx = actor.gfx();
            actorFinalBoss = actor.finalBoss();
        } else {
            return;
        }

        List<ClientSession> recipients = hub.battleRecipients(
                tick.roomId(), tick.force());
        if (!tick.attack()) {
            if (actorX != tick.destinationX() || actorY != tick.destinationY()) return;
            byte[] movement = new Protocol.Writer().c(Protocol.S_MOVE_OBJECT)
                    .d(tick.objectId()).h(tick.sourceX()).h(tick.sourceY())
                    .c(tick.heading()).bytes();
            for (ClientSession recipient : recipients) {
                recipient.sendEncrypted(movement,
                        "S_MOVE_OBJECT PvE-monster=" + tick.objectId()
                                + " mode=" + tick.mode()
                                + " source=" + tick.sourceX() + "," + tick.sourceY()
                                + " destination=" + tick.destinationX() + ","
                                + tick.destinationY() + " heading=" + tick.heading()
                                + " authority=" + tick.source());
            }
            return;
        }

        if (tick.summonSkill() != null) {
            if (actorX != tick.sourceX() || actorY != tick.sourceY()
                    || tick.summonSkill().npcId() != actorNpcId) return;
            if (tick.mode() == BattleRules.Mode.QUEST_BATTLE) {
                if (questActor == null) return;
                serverQuestMonsterSummon(tick, questActor, recipients);
            } else {
                if (timeActor == null) return;
                serverTimeAttackMonsterSummon(tick, timeActor, recipients);
            }
            return;
        }

        if (tick.groundSkill() != null) {
            if (tick.mode() != BattleRules.Mode.TIME_ATTACK || timeActor == null
                    || !battleAiTargetEligible(tick.roomId())
                    || actorX != tick.sourceX() || actorY != tick.sourceY()
                    || tick.groundSkill().npcId() != actorNpcId) return;
            serverTimeAttackMonsterGroundSkill(tick, timeActor, recipients);
            return;
        }

        if (tick.magicSkill() != null) {
            if (!battleAiTargetEligible(tick.roomId())
                    || actorX != tick.sourceX() || actorY != tick.sourceY()
                    || tick.magicSkill().npcId() != actorNpcId) return;
            if (tick.mode() == BattleRules.Mode.QUEST_BATTLE) {
                if (questActor == null) return;
                serverQuestMonsterMagicAttack(tick, questActor, recipients);
            } else {
                if (timeActor == null) return;
                serverTimeAttackMonsterMagicAttack(tick, timeActor, recipients);
            }
            return;
        }

        if (tick.visualSkill() != null) {
            if (tick.mode() != BattleRules.Mode.TIME_ATTACK || timeActor == null
                    || !battleAiTargetEligible(tick.roomId())
                    || actorX != tick.sourceX() || actorY != tick.sourceY()
                    || tick.visualSkill().npcId() != actorNpcId) return;
            serverTimeAttackMonsterVisualSkill(tick, timeActor, recipients);
            return;
        }

        int physicalRange = 1;
        int physicalLeverage = 10;
        int physicalAction = BattleActionCodes.ATTACK;
        BattleTimeAttackMagicSkillCatalog.PhysicalDefinition physical =
                tick.physicalSkill();
        if (physical != null) {
            if (physical.npcId() != actorNpcId) return;
            physicalRange = physical.attackRange();
            physicalLeverage = physical.leverage();
            physicalAction = physical.effectiveActionId();
        }
        if (tick.physicalSkill() != null
                && tick.physicalSkill().areaAttack()) {
            if (!battleAiTargetEligible(tick.roomId())
                    || actorX != tick.sourceX() || actorY != tick.sourceY()
                    || Math.max(Math.abs(actorX - positionX),
                        Math.abs(actorY - positionY)) > physicalRange) return;
            if (tick.mode() == BattleRules.Mode.QUEST_BATTLE) {
                if (questActor == null) return;
                serverQuestMonsterAreaPhysicalAttack(
                        tick, questActor, recipients, tick.physicalSkill());
            } else {
                if (timeActor == null) return;
                serverTimeAttackMonsterAreaPhysicalAttack(
                        tick, timeActor, recipients, tick.physicalSkill());
            }
            return;
        }
        if (!battleAiTargetEligible(tick.roomId())
                || actorX != tick.sourceX() || actorY != tick.sourceY()
                || Math.max(Math.abs(actorX - positionX),
                    Math.abs(actorY - positionY)) > physicalRange) return;
        int npcDistance = Math.max(Math.abs(actorX - positionX),
                Math.abs(actorY - positionY));
        SourceNpcPhysicalStats actorStats = null;
        try {
            actorStats = selectedSourceAccounts().npcPhysicalStats(actorNpcId);
        } catch (Exception sourceFailure) {
            System.err.println("[LiTo] Counter Barrier NPC source lookup failed npc="
                    + actorNpcId + " object=" + tick.objectId()
                    + " mode=" + tick.mode() + " reason="
                    + sourceFailure.getMessage());
        }
        int actorMagicResistance = actorStats == null
                ? 0 : Math.max(0, actorStats.magicResistance());
        boolean actorBoss = actorFinalBoss
                || actorStats != null && actorStats.boss();
        // A retained Quest/Time actor must have an authoritative source row
        // before it can participate in the probability formula.  Missing
        // level/MR/boss data degrades to the ordinary attack path instead of
        // silently granting a zero-MR, non-boss reflection opportunity.
        int npcPhysicalD20 = 0;
        int npcPhysicalD100 = 0;
        int npcPhysicalHitChance = 100;
        boolean npcPhysicalHit = true;
        boolean npcRangedAttack = actorStats != null
                && BattleStrikerGale.npcAttackEligible(
                        npcDistance, actorStats.bowActionId());
        int npcRangedEvasionRate = 0;
        int npcRangedEvasionRoll = 0;
        int targetDodgeModifier = effectivePhysicalDodge(System.nanoTime());
        int targetDodgeDown = effectivePhysicalDodgeDown(System.nanoTime());
        if (config.battlePhysicalHitEnabled() && actorStats != null) {
            npcPhysicalD20 = config.uncannyDodgeHitFixtureD20() > 0
                    ? config.uncannyDodgeHitFixtureD20()
                    : ThreadLocalRandom.current().nextInt(1, 21);
            int targetArmorClass = battleArmorClass();
            int negativeAcRoll = targetArmorClass < 0
                    ? ThreadLocalRandom.current().nextInt(1,
                        BattleNpcPhysicalAttack.negativeAcRollMaximum(
                                targetArmorClass) + 1)
                    : 0;
            // The selected NPC schema has no hit-up column. Its exact imported
            // contribution is therefore zero, while level still comes from the
            // authoritative encounter actor.
            npcPhysicalHitChance = BattleNpcPhysicalAttack.hitChance(
                    Math.max(1, actorLevel), 0, targetArmorClass,
                    targetDodgeModifier, targetDodgeDown,
                    npcPhysicalD20, negativeAcRoll);
            npcPhysicalD100 = config.uncannyDodgeHitFixtureD100() > 0
                    ? config.uncannyDodgeHitFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            npcPhysicalHit = BattleNpcPhysicalAttack.hits(
                    npcPhysicalHitChance, npcPhysicalD100);
            if (npcPhysicalHit && npcRangedAttack
                    && npcPhysicalHitChance > npcPhysicalD100) {
                npcRangedEvasionRate = effectiveRangedEvasionRate(
                        System.nanoTime());
                npcRangedEvasionRoll = config.rangedEvasionFixtureD100() > 0
                        ? config.rangedEvasionFixtureD100()
                        : ThreadLocalRandom.current().nextInt(1, 101);
                npcPhysicalHit = BattleRangedEvasion.hitsAfterEvasion(
                        npcRangedEvasionRate, npcRangedEvasionRoll);
            }
        }
        BattleCounterBarrier.Decision counterBarrier = !npcPhysicalHit
                || actorStats == null
                ? BattleCounterBarrier.Decision.inactive()
                : counterBarrierDecision(
                        Math.max(1, actorLevel), actorMagicResistance, actorBoss,
                        counterBarrierRoll(),
                        System.nanoTime());
        if (counterBarrier.triggered()) {
            String source = "PvE-" + tick.mode();
            publishNpcCounterBarrierTrigger(
                    tick.objectId(), counterBarrier, recipients, source);
            if (tick.mode() == BattleRules.Mode.QUEST_BATTLE) {
                applyQuestMonsterDamage(tick.objectId(),
                        counterBarrier.sourceDamage(), "counter-barrier");
            } else {
                applyTimeAttackActorDamage(tick.objectId(),
                        counterBarrier.sourceDamage(), "counter-barrier");
            }
            return;
        }
        int rawDamage = tick.damage();
        int acReduction = 0;
        int acRoll = 0;
        int appliedDamage = 0;
        if (npcPhysicalHit && actorStats != null
                && (tick.mode() == BattleRules.Mode.TIME_ATTACK
                    || tick.mode() == BattleRules.Mode.QUEST_BATTLE)) {
            CharacterSummary character = selectedCharacterSummary();
            if (character != null) {
                int configuredLevelRoll =
                        config.timeAttackMonsterPhysicalFixtureLevelRoll();
                int levelRoll = configuredLevelRoll >= 0
                        ? configuredLevelRoll
                        : ThreadLocalRandom.current().nextInt(actorLevel);
                int configuredCriticalRoll =
                        config.timeAttackMonsterPhysicalFixtureCriticalRoll();
                int criticalRoll = configuredCriticalRoll >= 0
                        ? configuredCriticalRoll
                        : ThreadLocalRandom.current().nextInt(100);
                int acMaximum = BattlePhysicalDefense.playerAcMaximum(
                        character.type(), battleArmorClass());
                int configuredAcRoll =
                        config.timeAttackMonsterPhysicalFixtureAcRoll();
                acRoll = configuredAcRoll >= 0
                        ? configuredAcRoll
                        : acMaximum == 0 ? 0
                            : ThreadLocalRandom.current().nextInt(acMaximum);
                int weaponBreakStacks = tick.mode() == BattleRules.Mode.TIME_ATTACK
                        ? hub.timeAttackActorWeaponBreakStacks(
                                currentRoomId, tick.objectId())
                        : hub.questMonsterWeaponBreakStacks(
                                currentRoomId, tick.objectId());
                int panicAbilityScoreModifier =
                        tick.mode() == BattleRules.Mode.TIME_ATTACK
                        ? hub.timeAttackActorPanicAbilityScoreModifier(
                                currentRoomId, tick.objectId(), System.nanoTime())
                        : hub.questMonsterPanicAbilityScoreModifier(
                                currentRoomId, tick.objectId(), System.nanoTime());
                try {
                    BattleTournamentNpcPhysicalDamage.Outcome outcome =
                            BattleTournamentNpcPhysicalDamage.againstPlayer(
                                    actorLevel, actorStats,
                                    requiredPhysicalGrowthStats(),
                                    physicalLeverage,
                                    weaponBreakStacks,
                                    character.type(),
                                    battleArmorClass(), levelRoll, criticalRoll,
                                    acRoll, System.currentTimeMillis(),
                                    panicAbilityScoreModifier);
                    rawDamage = outcome.sourceDamage();
                    acReduction = outcome.acReduction();
                    int armBreakerModifier = npcRangedAttack ? 0 :
                            tick.mode() == BattleRules.Mode.TIME_ATTACK
                            ? hub.timeAttackActorArmBreakerMeleeDamageModifier(
                                    currentRoomId, tick.objectId(), System.nanoTime())
                            : hub.questMonsterArmBreakerMeleeDamageModifier(
                                    currentRoomId, tick.objectId(), System.nanoTime());
                    rawDamage = Math.max(0,
                            Math.addExact(rawDamage, armBreakerModifier));
                    appliedDamage = combatPhysicalDamageAfterArmorAndCooking(
                            Math.max(0, Math.addExact(
                                    outcome.afterAcDamage(),
                                    armBreakerModifier)),
                            "tournament-monster-" + actorNpcId);
                } catch (IllegalArgumentException invalidFixture) {
                    rawDamage = 0;
                    acReduction = 0;
                    appliedDamage = 0;
                    System.err.println("[LiTo] Tournament physical source damage"
                            + " rejected npc=" + actorNpcId + " object="
                            + tick.objectId() + " mode=" + tick.mode()
                            + " reason="
                            + invalidFixture.getMessage());
                }
            }
        }
        appliedDamage = BattleStrikerGale.damageAfterStatus(
                appliedDamage, timedStatus.strikerGaleActive(System.nanoTime()),
                npcRangedAttack);
        if (appliedDamage > 0) {
            appliedDamage = earthBindProtectedCombatDamage(
                    appliedDamage, "pve-monster-" + tick.mode());
        }
        long npcProjectileSequence = npcRangedAttack
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        byte[] attack = npcRangedAttack
                ? Protocol.rangedPhysicalAttack(
                        physicalAction, tick.objectId(), playerObjectId(),
                        Math.min(0xFF, appliedDamage), tick.heading(),
                        npcProjectileSequence, actorStats.bowActionId(),
                        actorX, actorY, positionX, positionY)
                : new Protocol.Writer().c(Protocol.S_ATTACK)
                        .c(physicalAction).d(tick.objectId())
                        .d(playerObjectId()).c(Math.min(0xFF, appliedDamage))
                        .c(0).d(0).bytes();
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(attack,
                    "S_ATTACK PvE-monster=" + tick.objectId()
                            + " mode=" + tick.mode() + " target=" + playerObjectId()
                            + " damage=" + appliedDamage
                            + " raw-damage=" + rawDamage
                            + " ac-reduction=" + acReduction
                            + " ac-roll=" + acRoll
                            + " leverage=" + physicalLeverage
                            + " action=" + physicalAction
                            + " npc=" + actorNpcId
                            + " level=" + actorLevel
                            + " magic-resistance=" + actorMagicResistance
                            + " boss=" + actorBoss
                            + " target-ac=" + battleArmorClass()
                            + " target-dodge-modifier=" + targetDodgeModifier
                            + " target-dodge-down=" + targetDodgeDown
                            + " attack-roll-hit=" + npcPhysicalHit
                            + " hit-chance=" + npcPhysicalHitChance
                            + " d20=" + npcPhysicalD20
                            + " d100=" + npcPhysicalD100
                            + " ranged=" + npcRangedAttack
                            + " ranged-er=" + npcRangedEvasionRate
                            + " ranged-er-roll=" + npcRangedEvasionRoll
                            + " projectile-sequence=" + npcProjectileSequence
                            + " counter-barrier-active=" + counterBarrier.active()
                            + " counter-barrier-probability="
                            + counterBarrier.probability()
                            + " counter-barrier-roll=" + counterBarrier.roll()
                            + " counter-barrier-triggered=false"
                            + " authority=" + tick.source());
        }
        if (appliedDamage > 0) {
            BattleJoyOfPainStatus.Lease joyLease =
                    captureEncounterJoyOfPain(tick, System.nanoTime());
            int joyDamage = joyLease == null ? 0
                    : currentJoyOfPainFeedbackDamage();
            takePlayerDamage(appliedDamage, null);
            tryMortalBodyEncounterReflection(
                    tick, actorLevel, actorGfx, actorBoss, recipients,
                    "pve-monster-physical-" + tick.mode());
            applyJoyOfPainEncounterFeedback(
                    tick, joyLease, joyDamage, recipients,
                    "pve-monster-physical-" + tick.mode());
        }
    }

    private void serverQuestMonsterAreaPhysicalAttack(
            GameHub.MonsterAiTick tick,
            BattleQuestEncounter.Snapshot actor,
            List<ClientSession> recipients,
            BattleTimeAttackMagicSkillCatalog.PhysicalDefinition physical)
            throws IOException {
        if (tick == null || actor == null || recipients == null || physical == null
                || actor.objectId() != tick.objectId()
                || actor.npcId() != physical.npcId()
                || !physical.areaAttack()) return;

        List<ClientSession> targets = recipients.stream()
                .filter(target -> target.battleAiTargetEligible(tick.roomId()))
                .filter(target -> physical.areaContains(
                        actor.x(), actor.y(), tick.heading(),
                        target.positionX, target.positionY))
                .sorted(Comparator.comparingInt(target -> target == this ? 0 : 1))
                .toList();
        if (!targets.contains(this)) return;

        SourceNpcPhysicalStats actorStats = null;
        try {
            actorStats = selectedSourceAccounts().npcPhysicalStats(actor.npcId());
        } catch (Exception sourceFailure) {
            System.err.println("[LiTo] Quest area physical NPC source lookup"
                    + " failed npc=" + actor.npcId() + " object=" + actor.objectId()
                    + " reason=" + sourceFailure.getMessage());
        }
        for (ClientSession target : targets) {
            target.serverQuestMonsterAreaPhysicalHit(
                    tick, actor, recipients, physical, actorStats,
                    target == this, targets.size());
        }
    }

    private void serverQuestMonsterAreaPhysicalHit(
            GameHub.MonsterAiTick tick,
            BattleQuestEncounter.Snapshot actor,
            List<ClientSession> recipients,
            BattleTimeAttackMagicSkillCatalog.PhysicalDefinition physical,
            SourceNpcPhysicalStats actorStats,
            boolean primaryTarget,
            int targetCount) throws IOException {
        int distance = Math.max(Math.abs(actor.x() - positionX),
                Math.abs(actor.y() - positionY));
        int actorMagicResistance = actorStats == null
                ? 0 : Math.max(0, actorStats.magicResistance());
        boolean actorBoss = actorStats != null && actorStats.boss();
        int npcPhysicalD20 = 0;
        int npcPhysicalD100 = 0;
        int npcPhysicalHitChance = 100;
        boolean npcPhysicalHit = true;
        boolean npcRangedAttack = actorStats != null
                && BattleStrikerGale.npcAttackEligible(
                        distance, actorStats.bowActionId());
        int npcRangedEvasionRate = 0;
        int npcRangedEvasionRoll = 0;
        int targetDodgeModifier = effectivePhysicalDodge(System.nanoTime());
        int targetDodgeDown = effectivePhysicalDodgeDown(System.nanoTime());
        if (config.battlePhysicalHitEnabled() && actorStats != null) {
            npcPhysicalD20 = config.uncannyDodgeHitFixtureD20() > 0
                    ? config.uncannyDodgeHitFixtureD20()
                    : ThreadLocalRandom.current().nextInt(1, 21);
            int targetArmorClass = battleArmorClass();
            int negativeAcRoll = targetArmorClass < 0
                    ? ThreadLocalRandom.current().nextInt(1,
                        BattleNpcPhysicalAttack.negativeAcRollMaximum(
                                targetArmorClass) + 1)
                    : 0;
            npcPhysicalHitChance = BattleNpcPhysicalAttack.hitChance(
                    Math.max(1, actor.level()), 0, targetArmorClass,
                    targetDodgeModifier, targetDodgeDown,
                    npcPhysicalD20, negativeAcRoll);
            npcPhysicalD100 = config.uncannyDodgeHitFixtureD100() > 0
                    ? config.uncannyDodgeHitFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            npcPhysicalHit = BattleNpcPhysicalAttack.hits(
                    npcPhysicalHitChance, npcPhysicalD100);
            if (npcPhysicalHit && npcRangedAttack
                    && npcPhysicalHitChance > npcPhysicalD100) {
                npcRangedEvasionRate = effectiveRangedEvasionRate(
                        System.nanoTime());
                npcRangedEvasionRoll = config.rangedEvasionFixtureD100() > 0
                        ? config.rangedEvasionFixtureD100()
                        : ThreadLocalRandom.current().nextInt(1, 101);
                npcPhysicalHit = BattleRangedEvasion.hitsAfterEvasion(
                        npcRangedEvasionRate, npcRangedEvasionRoll);
            }
        }

        BattleCounterBarrier.Decision counterBarrier = !npcPhysicalHit
                || actorStats == null
                ? BattleCounterBarrier.Decision.inactive()
                : counterBarrierDecision(
                        Math.max(1, actor.level()), actorMagicResistance,
                        actorBoss, counterBarrierRoll(), System.nanoTime());
        if (counterBarrier.triggered()) {
            publishNpcCounterBarrierTrigger(
                    actor.objectId(), counterBarrier, recipients,
                    "PvE-QUEST_BATTLE-area-physical");
            applyQuestMonsterDamage(
                    actor.objectId(), counterBarrier.sourceDamage(),
                    "counter-barrier-area-physical");
            System.out.println("[LiTo] Quest area physical counter-barrier"
                    + " npc=" + actor.npcId() + " object=" + actor.objectId()
                    + " target=" + playerObjectId() + " primary=" + primaryTarget
                    + " act=" + physical.actNo());
            return;
        }

        int rawDamage = tick.damage();
        int acReduction = 0;
        int acRoll = 0;
        int appliedDamage = 0;
        if (npcPhysicalHit && actorStats != null) {
            CharacterSummary character = selectedCharacterSummary();
            if (character != null) {
                int configuredLevelRoll =
                        config.timeAttackMonsterPhysicalFixtureLevelRoll();
                int levelRoll = configuredLevelRoll >= 0
                        ? configuredLevelRoll
                        : ThreadLocalRandom.current().nextInt(actor.level());
                int configuredCriticalRoll =
                        config.timeAttackMonsterPhysicalFixtureCriticalRoll();
                int criticalRoll = configuredCriticalRoll >= 0
                        ? configuredCriticalRoll
                        : ThreadLocalRandom.current().nextInt(100);
                int acMaximum = BattlePhysicalDefense.playerAcMaximum(
                        character.type(), battleArmorClass());
                int configuredAcRoll =
                        config.timeAttackMonsterPhysicalFixtureAcRoll();
                acRoll = configuredAcRoll >= 0
                        ? configuredAcRoll
                        : acMaximum == 0 ? 0
                            : ThreadLocalRandom.current().nextInt(acMaximum);
                try {
                    BattleTournamentNpcPhysicalDamage.Outcome outcome =
                            BattleTournamentNpcPhysicalDamage.againstPlayer(
                                    actor.level(), actorStats,
                                    requiredPhysicalGrowthStats(),
                                    physical.leverage(),
                                    hub.questMonsterWeaponBreakStacks(
                                            currentRoomId, actor.objectId()),
                                    character.type(), battleArmorClass(),
                                    levelRoll, criticalRoll, acRoll,
                                    System.currentTimeMillis(),
                                    hub.questMonsterPanicAbilityScoreModifier(
                                            currentRoomId, actor.objectId(),
                                            System.nanoTime()));
                    rawDamage = outcome.sourceDamage();
                    acReduction = outcome.acReduction();
                    int armBreakerModifier = npcRangedAttack ? 0
                            : hub.questMonsterArmBreakerMeleeDamageModifier(
                                    currentRoomId, actor.objectId(),
                                    System.nanoTime());
                    rawDamage = Math.max(0,
                            Math.addExact(rawDamage, armBreakerModifier));
                    appliedDamage = combatPhysicalDamageAfterArmorAndCooking(
                            Math.max(0, Math.addExact(
                                    outcome.afterAcDamage(), armBreakerModifier)),
                            "quest-monster-area-" + actor.npcId());
                } catch (IllegalArgumentException invalidFixture) {
                    rawDamage = 0;
                    acReduction = 0;
                    appliedDamage = 0;
                    System.err.println("[LiTo] Quest area physical source"
                            + " damage rejected npc=" + actor.npcId()
                            + " object=" + actor.objectId() + " target="
                            + playerObjectId() + " reason="
                            + invalidFixture.getMessage());
                }
            }
        }
        appliedDamage = BattleStrikerGale.damageAfterStatus(
                appliedDamage, timedStatus.strikerGaleActive(System.nanoTime()),
                npcRangedAttack);
        if (appliedDamage > 0) {
            appliedDamage = earthBindProtectedCombatDamage(
                    appliedDamage, "pve-monster-QUEST_BATTLE-area");
        }

        long projectileSequence = npcRangedAttack
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        if (primaryTarget) {
            byte[] attack = npcRangedAttack
                    ? Protocol.rangedPhysicalAttack(
                            physical.effectiveActionId(), actor.objectId(),
                            playerObjectId(), Math.min(0xFF, appliedDamage),
                            tick.heading(), projectileSequence,
                            actorStats.bowActionId(), actor.x(), actor.y(),
                            positionX, positionY)
                    : new Protocol.Writer().c(Protocol.S_ATTACK)
                            .c(physical.effectiveActionId()).d(actor.objectId())
                            .d(playerObjectId()).c(Math.min(0xFF, appliedDamage))
                            .c(0).d(0).bytes();
            for (ClientSession recipient : recipients) {
                recipient.sendEncrypted(attack,
                        "S_ATTACK Quest-mobskill-area-physical="
                                + actor.objectId() + " target=" + playerObjectId()
                                + " targets=" + targetCount + " damage="
                                + appliedDamage + " raw-damage=" + rawDamage
                                + " ac-reduction=" + acReduction
                                + " ac-roll=" + acRoll + " leverage="
                                + physical.leverage() + " action="
                                + physical.effectiveActionId() + " act="
                                + physical.actNo() + " npc=" + actor.npcId()
                                + " hit=" + npcPhysicalHit + " hit-chance="
                                + npcPhysicalHitChance + " d20=" + npcPhysicalD20
                                + " d100=" + npcPhysicalD100 + " ranged="
                                + npcRangedAttack + " ranged-er="
                                + npcRangedEvasionRate + " ranged-er-roll="
                                + npcRangedEvasionRoll + " projectile-sequence="
                                + projectileSequence + " authority=" + tick.source());
            }
        }

        System.out.println("[LiTo] Quest area physical npc="
                + actor.npcId() + " object=" + actor.objectId()
                + " target=" + playerObjectId() + " primary=" + primaryTarget
                + " act=" + physical.actNo() + " action="
                + physical.effectiveActionId() + " source-damage=" + rawDamage
                + " damage=" + appliedDamage + " targets=" + targetCount);
        if (appliedDamage > 0) {
            BattleJoyOfPainStatus.Lease joyLease =
                    captureEncounterJoyOfPain(tick, System.nanoTime());
            int joyDamage = joyLease == null ? 0
                    : currentJoyOfPainFeedbackDamage();
            takePlayerDamage(appliedDamage, null);
            tryMortalBodyEncounterReflection(
                    tick, actor.level(), actor.gfx(), actorBoss, recipients,
                    "pve-monster-physical-QUEST_BATTLE-area");
            applyJoyOfPainEncounterFeedback(
                    tick, joyLease, joyDamage, recipients,
                    "pve-monster-physical-QUEST_BATTLE-area");
        }
    }

    private void serverTimeAttackMonsterAreaPhysicalAttack(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients,
            BattleTimeAttackMagicSkillCatalog.PhysicalDefinition physical)
            throws IOException {
        if (tick == null || actor == null || recipients == null || physical == null
                || actor.objectId() != tick.objectId()
                || actor.npcId() != physical.npcId()
                || !physical.areaAttack()) return;

        List<ClientSession> targets = hub.roomCombatants(tick.roomId()).stream()
                .filter(target -> target.battleAiTargetEligible(tick.roomId()))
                .filter(target -> physical.areaContains(
                        actor.x(), actor.y(), tick.heading(),
                        target.positionX, target.positionY))
                .sorted(Comparator.comparingInt(target -> target == this ? 0 : 1))
                .toList();
        if (!targets.contains(this)) return;

        SourceNpcPhysicalStats actorStats = null;
        try {
            actorStats = selectedSourceAccounts().npcPhysicalStats(actor.npcId());
        } catch (Exception sourceFailure) {
            System.err.println("[LiTo] Time Attack area physical NPC source lookup"
                    + " failed npc=" + actor.npcId() + " object=" + actor.objectId()
                    + " reason=" + sourceFailure.getMessage());
        }
        for (ClientSession target : targets) {
            target.serverTimeAttackMonsterAreaPhysicalHit(
                    tick, actor, recipients, physical, actorStats,
                    target == this, targets.size());
        }
    }

    private void serverTimeAttackMonsterAreaPhysicalHit(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients,
            BattleTimeAttackMagicSkillCatalog.PhysicalDefinition physical,
            SourceNpcPhysicalStats actorStats,
            boolean primaryTarget,
            int targetCount) throws IOException {
        int distance = Math.max(Math.abs(actor.x() - positionX),
                Math.abs(actor.y() - positionY));
        int actorMagicResistance = actorStats == null
                ? 0 : Math.max(0, actorStats.magicResistance());
        boolean actorBoss = actor.finalBoss()
                || actorStats != null && actorStats.boss();
        int npcPhysicalD20 = 0;
        int npcPhysicalD100 = 0;
        int npcPhysicalHitChance = 100;
        boolean npcPhysicalHit = true;
        boolean npcRangedAttack = actorStats != null
                && BattleStrikerGale.npcAttackEligible(
                        distance, actorStats.bowActionId());
        int npcRangedEvasionRate = 0;
        int npcRangedEvasionRoll = 0;
        int targetDodgeModifier = effectivePhysicalDodge(System.nanoTime());
        int targetDodgeDown = effectivePhysicalDodgeDown(System.nanoTime());
        if (config.battlePhysicalHitEnabled() && actorStats != null) {
            npcPhysicalD20 = config.uncannyDodgeHitFixtureD20() > 0
                    ? config.uncannyDodgeHitFixtureD20()
                    : ThreadLocalRandom.current().nextInt(1, 21);
            int targetArmorClass = battleArmorClass();
            int negativeAcRoll = targetArmorClass < 0
                    ? ThreadLocalRandom.current().nextInt(1,
                        BattleNpcPhysicalAttack.negativeAcRollMaximum(
                                targetArmorClass) + 1)
                    : 0;
            npcPhysicalHitChance = BattleNpcPhysicalAttack.hitChance(
                    Math.max(1, actor.level()), 0, targetArmorClass,
                    targetDodgeModifier, targetDodgeDown,
                    npcPhysicalD20, negativeAcRoll);
            npcPhysicalD100 = config.uncannyDodgeHitFixtureD100() > 0
                    ? config.uncannyDodgeHitFixtureD100()
                    : ThreadLocalRandom.current().nextInt(1, 101);
            npcPhysicalHit = BattleNpcPhysicalAttack.hits(
                    npcPhysicalHitChance, npcPhysicalD100);
            if (npcPhysicalHit && npcRangedAttack
                    && npcPhysicalHitChance > npcPhysicalD100) {
                npcRangedEvasionRate = effectiveRangedEvasionRate(
                        System.nanoTime());
                npcRangedEvasionRoll = config.rangedEvasionFixtureD100() > 0
                        ? config.rangedEvasionFixtureD100()
                        : ThreadLocalRandom.current().nextInt(1, 101);
                npcPhysicalHit = BattleRangedEvasion.hitsAfterEvasion(
                        npcRangedEvasionRate, npcRangedEvasionRoll);
            }
        }

        BattleCounterBarrier.Decision counterBarrier = !npcPhysicalHit
                || actorStats == null
                ? BattleCounterBarrier.Decision.inactive()
                : counterBarrierDecision(
                        Math.max(1, actor.level()), actorMagicResistance,
                        actorBoss, counterBarrierRoll(), System.nanoTime());
        if (counterBarrier.triggered()) {
            publishNpcCounterBarrierTrigger(
                    actor.objectId(), counterBarrier, recipients,
                    "PvE-TIME_ATTACK-area-physical");
            applyTimeAttackActorDamage(
                    actor.objectId(), counterBarrier.sourceDamage(),
                    "counter-barrier-area-physical");
            System.out.println("[LiTo] Time Attack area physical counter-barrier"
                    + " npc=" + actor.npcId() + " object=" + actor.objectId()
                    + " target=" + playerObjectId() + " primary=" + primaryTarget
                    + " act=" + physical.actNo());
            return;
        }

        int rawDamage = tick.damage();
        int acReduction = 0;
        int acRoll = 0;
        int appliedDamage = 0;
        if (npcPhysicalHit && actorStats != null) {
            CharacterSummary character = selectedCharacterSummary();
            if (character != null) {
                int configuredLevelRoll =
                        config.timeAttackMonsterPhysicalFixtureLevelRoll();
                int levelRoll = configuredLevelRoll >= 0
                        ? configuredLevelRoll
                        : ThreadLocalRandom.current().nextInt(actor.level());
                int configuredCriticalRoll =
                        config.timeAttackMonsterPhysicalFixtureCriticalRoll();
                int criticalRoll = configuredCriticalRoll >= 0
                        ? configuredCriticalRoll
                        : ThreadLocalRandom.current().nextInt(100);
                int acMaximum = BattlePhysicalDefense.playerAcMaximum(
                        character.type(), battleArmorClass());
                int configuredAcRoll =
                        config.timeAttackMonsterPhysicalFixtureAcRoll();
                acRoll = configuredAcRoll >= 0
                        ? configuredAcRoll
                        : acMaximum == 0 ? 0
                            : ThreadLocalRandom.current().nextInt(acMaximum);
                try {
                    BattleTimeAttackPhysicalDamage.Outcome outcome =
                            BattleTimeAttackPhysicalDamage.againstPlayer(
                                    actor.level(), actorStats,
                                    requiredPhysicalGrowthStats(),
                                    physical.leverage(),
                                    hub.timeAttackActorWeaponBreakStacks(
                                            currentRoomId, actor.objectId()),
                                    character.type(), battleArmorClass(),
                                    levelRoll, criticalRoll, acRoll,
                                    System.currentTimeMillis(),
                                    hub.timeAttackActorPanicAbilityScoreModifier(
                                            currentRoomId, actor.objectId(),
                                            System.nanoTime()));
                    rawDamage = outcome.sourceDamage();
                    acReduction = outcome.acReduction();
                    int armBreakerModifier = npcRangedAttack ? 0
                            : hub.timeAttackActorArmBreakerMeleeDamageModifier(
                                    currentRoomId, actor.objectId(),
                                    System.nanoTime());
                    rawDamage = Math.max(0,
                            Math.addExact(rawDamage, armBreakerModifier));
                    appliedDamage = combatPhysicalDamageAfterArmorAndCooking(
                            Math.max(0, Math.addExact(
                                    outcome.afterAcDamage(), armBreakerModifier)),
                            "time-attack-monster-area-" + actor.npcId());
                } catch (IllegalArgumentException invalidFixture) {
                    rawDamage = 0;
                    acReduction = 0;
                    appliedDamage = 0;
                    System.err.println("[LiTo] Time Attack area physical source"
                            + " damage rejected npc=" + actor.npcId()
                            + " object=" + actor.objectId() + " target="
                            + playerObjectId() + " reason="
                            + invalidFixture.getMessage());
                }
            }
        }
        appliedDamage = BattleStrikerGale.damageAfterStatus(
                appliedDamage, timedStatus.strikerGaleActive(System.nanoTime()),
                npcRangedAttack);
        if (appliedDamage > 0) {
            appliedDamage = earthBindProtectedCombatDamage(
                    appliedDamage, "pve-monster-TIME_ATTACK-area");
        }

        long projectileSequence = npcRangedAttack
                ? ATTACK_SPELL_SEQUENCE.incrementAndGet() : 0;
        if (primaryTarget) {
            byte[] attack = npcRangedAttack
                    ? Protocol.rangedPhysicalAttack(
                            physical.effectiveActionId(), actor.objectId(),
                            playerObjectId(), Math.min(0xFF, appliedDamage),
                            tick.heading(), projectileSequence,
                            actorStats.bowActionId(), actor.x(), actor.y(),
                            positionX, positionY)
                    : new Protocol.Writer().c(Protocol.S_ATTACK)
                            .c(physical.effectiveActionId()).d(actor.objectId())
                            .d(playerObjectId()).c(Math.min(0xFF, appliedDamage))
                            .c(0).d(0).bytes();
            for (ClientSession recipient : recipients) {
                recipient.sendEncrypted(attack,
                        "S_ATTACK Time-Attack-mobskill-area-physical="
                                + actor.objectId() + " target=" + playerObjectId()
                                + " targets=" + targetCount + " damage="
                                + appliedDamage + " raw-damage=" + rawDamage
                                + " ac-reduction=" + acReduction
                                + " ac-roll=" + acRoll + " leverage="
                                + physical.leverage() + " action="
                                + physical.effectiveActionId() + " act="
                                + physical.actNo() + " npc=" + actor.npcId()
                                + " hit=" + npcPhysicalHit + " hit-chance="
                                + npcPhysicalHitChance + " d20=" + npcPhysicalD20
                                + " d100=" + npcPhysicalD100 + " ranged="
                                + npcRangedAttack + " ranged-er="
                                + npcRangedEvasionRate + " ranged-er-roll="
                                + npcRangedEvasionRoll + " projectile-sequence="
                                + projectileSequence + " authority=" + tick.source());
            }
        }

        System.out.println("[LiTo] Time Attack area physical npc="
                + actor.npcId() + " object=" + actor.objectId()
                + " target=" + playerObjectId() + " primary=" + primaryTarget
                + " act=" + physical.actNo() + " action="
                + physical.effectiveActionId() + " source-damage=" + rawDamage
                + " damage=" + appliedDamage + " targets=" + targetCount);
        if (appliedDamage > 0) {
            BattleJoyOfPainStatus.Lease joyLease =
                    captureEncounterJoyOfPain(tick, System.nanoTime());
            int joyDamage = joyLease == null ? 0
                    : currentJoyOfPainFeedbackDamage();
            takePlayerDamage(appliedDamage, null);
            tryMortalBodyEncounterReflection(
                    tick, actor.level(), actor.gfx(), actorBoss, recipients,
                    "pve-monster-physical-TIME_ATTACK-area");
            applyJoyOfPainEncounterFeedback(
                    tick, joyLease, joyDamage, recipients,
                    "pve-monster-physical-TIME_ATTACK-area");
        }
    }

    private void serverQuestMonsterSummon(
            GameHub.MonsterAiTick tick,
            BattleQuestEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.SummonDefinition summon =
                tick.summonSkill();
        if (summon == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || summon.npcId() != actor.npcId()) return;

        for (ClientSession recipient : recipients) {
            for (BattleQuestEncounter.Snapshot spawned : tick.questSpawned()) {
                recipient.sendEncrypted(Protocol.questMonster(spawned),
                        "S_PUT_OBJECT Quest-mobskill-summon actor="
                                + spawned.objectId() + " npc=" + spawned.npcId()
                                + " gfx=" + spawned.gfx() + " caster="
                                + actor.objectId() + " authority=" + tick.source());
            }
            recipient.sendEncrypted(
                    Protocol.effectObject(actor.objectId(), summon.effectGfx()),
                    "S_EFFECT Quest-mobskill-summon caster="
                            + actor.objectId() + " gfx=" + summon.effectGfx()
                            + " trigger-roll=" + tick.magicTriggerRoll());
            recipient.sendEncrypted(
                    Protocol.objectAction(actor.objectId(), summon.actionId()),
                    "S_ACTION Quest-mobskill-summon caster="
                            + actor.objectId() + " action=" + summon.actionId()
                            + " spawned=" + tick.questSpawned().size()
                            + " authority=" + tick.source());
        }
    }

    private void serverQuestMonsterMagicAttack(
            GameHub.MonsterAiTick tick,
            BattleQuestEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.Definition skill = tick.magicSkill();
        if (skill == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || skill.npcId() != actor.npcId()) return;

        List<ClientSession> targets;
        if (skill.targeting()
                == BattleTimeAttackMagicSkillCatalog.Targeting.DIRECTIONAL) {
            int distance = Math.max(Math.abs(actor.x() - positionX),
                    Math.abs(actor.y() - positionY));
            if (distance > skill.maximumRange()) return;
            targets = List.of(this);
        } else {
            int centerX = actor.x();
            int centerY = actor.y();
            targets = recipients.stream()
                    .filter(target -> target.battleAiTargetEligible(tick.roomId()))
                    .filter(target -> Math.max(
                            Math.abs(centerX - target.positionX),
                            Math.abs(centerY - target.positionY))
                            <= skill.areaRadius())
                    .toList();
        }

        long damageNowNanos = System.nanoTime();
        int actorIntelligence = Math.max(1, Math.min(254,
                Math.addExact(actor.intelligence(),
                        hub.questMonsterPanicAbilityScoreModifier(
                                tick.roomId(), actor.objectId(), damageNowNanos))));
        SourceNpcPhysicalStats mirrorSourceStats = null;
        try {
            mirrorSourceStats = selectedSourceAccounts()
                    .npcPhysicalStats(actor.npcId());
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] Quest Counter Mirror source lookup failed npc="
                    + actor.npcId() + " reason=" + sourceFailure.getMessage());
        }
        boolean actorBoss = mirrorSourceStats != null && mirrorSourceStats.boss();
        boolean mirrorEligible = counterMirrorNpcEligible(
                actor.npcId(), mirrorSourceStats);
        List<TimeAttackMonsterMagicHit> hits = new ArrayList<>();
        for (ClientSession target : targets) {
            int sourceDamage = skill.baseDamage();
            for (int die = 0; die < skill.diceCount(); die++) {
                sourceDamage = Math.addExact(sourceDamage,
                        ThreadLocalRandom.current().nextInt(1, skill.dieSides() + 1));
            }
            int elementalResistance =
                    target.effectiveSpellElementalResistance(skill.attribute());
            int afterElement = ClassicWorldMonsterMagicDamage.afterElementAndLeverage(
                    sourceDamage, actorIntelligence, elementalResistance,
                    skill.leverage());
            int armorReductionBase = target.effectiveArmorMagicReductionBase();
            int armorReductionOffset = armorReductionBase <= 10 ? 0
                    : ThreadLocalRandom.current().nextInt(armorReductionBase - 10);
            int armorReduction = BattleMagicResistance.armorDamageReduction(
                    armorReductionBase, armorReductionOffset);
            BattleAbilityStatus.ReductionArmor reductionArmor =
                    target.abilityStatus.reductionArmor(damageNowNanos);
            if (reductionArmor.remainingSeconds() != 0) {
                armorReduction = Math.addExact(armorReduction,
                        BattleSpellCatalog.reductionArmorSpell(
                                BattleSpellCatalog.REDUCTION_ARMOR).reduction(
                                        target.battleLevel(), false));
            }
            int targetMagicResistance = target.effectiveBaseMagicResistance();
            int damage = ClassicWorldMonsterMagicDamage.afterArmorAndResistance(
                    afterElement, armorReduction, targetMagicResistance,
                    actorIntelligence);
            damage = target.combatDamageAfterCookingWithoutReductionArmor(
                    damage, "quest-monster-magic-" + skill.skillId());
            damage = target.earthBindProtectedCombatDamage(
                    damage, "quest-monster-magic-" + skill.skillId());
            BattleCounterMirrorStatus.Decision mirror =
                    target.counterMirrorDecision(
                            damage, mirrorEligible,
                            ThreadLocalRandom.current().nextInt(100),
                            damageNowNanos);
            if (mirror.triggered()) {
                target.publishNpcCounterMirrorTrigger(
                        actor.objectId(), actor.x(), actor.y(), mirror,
                        recipients, "quest-monster-magic-" + skill.skillId());
                target.applyQuestMonsterDamage(
                        actor.objectId(), mirror.reflectedDamage(),
                        "counter-mirror");
                damage = 0;
            }
            hits.add(new TimeAttackMonsterMagicHit(
                    target, sourceDamage, elementalResistance, armorReduction,
                    targetMagicResistance, damage));
        }

        long sequence = ATTACK_SPELL_SEQUENCE.getAndIncrement();
        byte[] packet;
        if (hits.isEmpty()) {
            packet = Protocol.objectAction(actor.objectId(), skill.actionId());
        } else if (skill.targeting()
                == BattleTimeAttackMagicSkillCatalog.Targeting.DIRECTIONAL) {
            TimeAttackMonsterMagicHit hit = hits.get(0);
            packet = Protocol.attackSpell(
                    skill.actionId(), actor.objectId(),
                    hit.target().playerObjectId(), hit.damage() > 0 ? 10 : 0,
                    tick.heading(), sequence, skill.effectGfx(),
                    actor.x(), actor.y(),
                    hit.target().positionX, hit.target().positionY);
        } else {
            packet = Protocol.attackMany(
                    skill.actionId(), actor.objectId(), actor.x(), actor.y(),
                    tick.heading(), sequence, skill.effectGfx(), 0,
                    hits.stream().map(hit -> new Protocol.AttackManyTarget(
                            hit.target().playerObjectId(), hit.damage() > 0)).toList());
        }

        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(packet,
                    (skill.targeting()
                            == BattleTimeAttackMagicSkillCatalog.Targeting.DIRECTIONAL
                                ? "S_ATTACK" : hits.isEmpty()
                                    ? "S_ACTION" : "S_ATTACK_MANY")
                            + " Quest-mobskill actor=" + actor.objectId()
                            + " npc=" + actor.npcId() + " skill=" + skill.skillId()
                            + " targets=" + hits.size() + " action=" + skill.actionId()
                            + " gfx=" + skill.effectGfx() + " sequence=" + sequence
                            + " trigger-roll=" + tick.magicTriggerRoll()
                            + " leverage=" + skill.leverage()
                            + " authority=" + tick.source());
        }

        for (TimeAttackMonsterMagicHit hit : hits) {
            System.out.println("[LiTo] Quest monster magic npc="
                    + actor.npcId() + " object=" + actor.objectId()
                    + " skill=" + skill.skillId() + " target="
                    + hit.target().playerObjectId() + " source-damage="
                    + hit.sourceDamage() + " caster-int=" + actorIntelligence
                    + " elemental-resistance=" + hit.elementalResistance()
                    + " leverage=" + skill.leverage() + " armor-reduction="
                    + hit.armorReduction() + " target-mr="
                    + hit.targetMagicResistance() + " damage=" + hit.damage());
            BattleJoyOfPainStatus.Lease joyLease = hit.damage() <= 0 ? null
                    : hit.target().captureEncounterJoyOfPain(
                            tick, System.nanoTime());
            int joyDamage = joyLease == null ? 0
                    : hit.target().currentJoyOfPainFeedbackDamage();
            hit.target().takePlayerDamage(hit.damage(), null);
            if (hit.damage() > 0) {
                hit.target().tryMortalBodyEncounterReflection(
                        tick, actor.level(), actor.gfx(), actorBoss, recipients,
                        "quest-monster-magic-" + skill.skillId());
                hit.target().applyJoyOfPainEncounterFeedback(
                        tick, joyLease, joyDamage, recipients,
                        "quest-monster-magic-" + skill.skillId());
            }
        }
        if (skill.drainsLife()) {
            int drained = hits.stream().mapToInt(TimeAttackMonsterMagicHit::damage)
                    .sum();
            BattleQuestEncounter.Healing healing = drained <= 0 ? null
                    : hub.healQuestMonster(
                            tick.roomId(), this, actor.objectId(), drained);
            if (healing != null && healing.restoredHp() > 0) {
                byte[] ratio = Protocol.hitRatio(
                        healing.after().objectId(), healing.after().hp(),
                        healing.after().maxHp());
                for (ClientSession recipient : recipients) {
                    recipient.sendEncrypted(ratio,
                            "S_HIT_RATIO Quest-vampiric-touch actor="
                                    + actor.objectId() + " restored="
                                    + healing.restoredHp() + " hp="
                                    + healing.after().hp() + "/"
                                    + healing.after().maxHp());
                }
            }
        }
    }

    private void serverTimeAttackMonsterSummon(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.SummonDefinition summon =
                tick.summonSkill();
        if (summon == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || summon.npcId() != actor.npcId()) return;

        // Retained L1MobSkillUse.summon materializes the actors first, then
        // broadcasts S_SkillSound(gfx761) and ACTION_SkillBuff(action19).
        for (ClientSession recipient : recipients) {
            for (BattleTimeAttackEncounter.Snapshot spawned : tick.spawned()) {
                recipient.sendEncrypted(Protocol.timeAttackActor(spawned),
                        "S_PUT_OBJECT Time-Attack-mobskill-summon actor="
                                + spawned.objectId() + " npc=" + spawned.npcId()
                                + " gfx=" + spawned.gfx() + " caster="
                                + actor.objectId() + " authority=" + tick.source());
            }
            recipient.sendEncrypted(
                    Protocol.effectObject(actor.objectId(), summon.effectGfx()),
                    "S_EFFECT Time-Attack-mobskill-summon caster="
                            + actor.objectId() + " gfx=" + summon.effectGfx()
                            + " trigger-roll=" + tick.magicTriggerRoll());
            recipient.sendEncrypted(
                    Protocol.objectAction(actor.objectId(), summon.actionId()),
                    "S_ACTION Time-Attack-mobskill-summon caster="
                            + actor.objectId() + " action=" + summon.actionId()
                            + " spawned=" + tick.spawned().size()
                            + " authority=" + tick.source());
        }
    }

    private void serverTimeAttackMonsterMagicAttack(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.Definition skill = tick.magicSkill();
        if (skill == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || skill.npcId() != actor.npcId()) return;

        List<ClientSession> targets;
        if (skill.targeting()
                == BattleTimeAttackMagicSkillCatalog.Targeting.DIRECTIONAL) {
            int distance = Math.max(Math.abs(actor.x() - positionX),
                    Math.abs(actor.y() - positionY));
            if (distance > skill.maximumRange()) return;
            targets = List.of(this);
        } else {
            if (skill.targeting()
                    == BattleTimeAttackMagicSkillCatalog.Targeting.TARGET_RADIUS) {
                int distance = Math.max(Math.abs(actor.x() - positionX),
                        Math.abs(actor.y() - positionY));
                if (distance > skill.maximumRange()) return;
            }
            int centerX = skill.targeting()
                    == BattleTimeAttackMagicSkillCatalog.Targeting.TARGET_RADIUS
                            ? positionX : actor.x();
            int centerY = skill.targeting()
                    == BattleTimeAttackMagicSkillCatalog.Targeting.TARGET_RADIUS
                            ? positionY : actor.y();
            targets = hub.roomCombatants(tick.roomId()).stream()
                    .filter(target -> target.battleAiTargetEligible(tick.roomId()))
                    .filter(target -> skill.targeting()
                            == BattleTimeAttackMagicSkillCatalog.Targeting.CASTER_SCREEN
                                ? BattleSpellCatalog.isInNativeScreen(
                                        actor.x(), actor.y(),
                                        target.positionX, target.positionY)
                                : Math.max(Math.abs(centerX - target.positionX),
                                        Math.abs(centerY - target.positionY))
                                        <= skill.areaRadius())
                    .toList();
        }

        long damageNowNanos = System.nanoTime();
        int actorIntelligence = timeAttackActorPanicAdjustedAbility(
                tick.roomId(), actor, actor.intelligence(), damageNowNanos);
        SourceNpcPhysicalStats mirrorSourceStats = null;
        try {
            mirrorSourceStats = selectedSourceAccounts()
                    .npcPhysicalStats(actor.npcId());
        } catch (Exception sourceFailure) {
            System.out.println("[LiTo] Time Attack Counter Mirror source"
                    + " lookup failed npc=" + actor.npcId() + " reason="
                    + sourceFailure.getMessage());
        }
        boolean mirrorEligible = counterMirrorNpcEligible(
                actor.npcId(), mirrorSourceStats);
        List<TimeAttackMonsterMagicHit> hits = new ArrayList<>();
        for (ClientSession target : targets) {
            int sourceDamage = skill.baseDamage();
            for (int die = 0; die < skill.diceCount(); die++) {
                sourceDamage = Math.addExact(sourceDamage,
                        ThreadLocalRandom.current().nextInt(1, skill.dieSides() + 1));
            }
            int elementalResistance =
                    target.effectiveSpellElementalResistance(skill.attribute());
            int afterElement = ClassicWorldMonsterMagicDamage.afterElementAndLeverage(
                    sourceDamage, actorIntelligence, elementalResistance,
                    skill.leverage());
            int armorReductionBase = target.effectiveArmorMagicReductionBase();
            int armorReductionOffset = armorReductionBase <= 10 ? 0
                    : ThreadLocalRandom.current().nextInt(armorReductionBase - 10);
            int armorReduction = BattleMagicResistance.armorDamageReduction(
                    armorReductionBase, armorReductionOffset);
            BattleAbilityStatus.ReductionArmor reductionArmor =
                    target.abilityStatus.reductionArmor(damageNowNanos);
            if (reductionArmor.remainingSeconds() != 0) {
                armorReduction = Math.addExact(armorReduction,
                        BattleSpellCatalog.reductionArmorSpell(
                                BattleSpellCatalog.REDUCTION_ARMOR).reduction(
                                        target.battleLevel(), false));
            }
            int targetMagicResistance = target.effectiveBaseMagicResistance();
            int damage = ClassicWorldMonsterMagicDamage.afterArmorAndResistance(
                    afterElement, armorReduction, targetMagicResistance,
                    actorIntelligence);
            damage = target.combatDamageAfterCookingWithoutReductionArmor(
                    damage, "time-attack-monster-magic-" + skill.skillId());
            damage = target.earthBindProtectedCombatDamage(
                    damage, "time-attack-monster-magic-" + skill.skillId());
            BattleCounterMirrorStatus.Decision mirror =
                    target.counterMirrorDecision(
                            damage, mirrorEligible,
                            ThreadLocalRandom.current().nextInt(100),
                            damageNowNanos);
            if (mirror.triggered()) {
                target.publishNpcCounterMirrorTrigger(
                        actor.objectId(), actor.x(), actor.y(), mirror,
                        recipients, "time-attack-monster-magic-"
                                + skill.skillId());
                target.applyTimeAttackActorDamage(
                        actor.objectId(), mirror.reflectedDamage(),
                        "counter-mirror");
                damage = 0;
            }
            hits.add(new TimeAttackMonsterMagicHit(
                    target, sourceDamage, elementalResistance, armorReduction,
                    targetMagicResistance, damage));
        }

        long sequence = ATTACK_SPELL_SEQUENCE.getAndIncrement();
        byte[] packet;
        if (hits.isEmpty()) {
            packet = Protocol.objectAction(actor.objectId(), skill.actionId());
        } else if (skill.targeting()
                == BattleTimeAttackMagicSkillCatalog.Targeting.DIRECTIONAL) {
            TimeAttackMonsterMagicHit hit = hits.get(0);
            packet = Protocol.attackSpell(
                    skill.actionId(), actor.objectId(),
                    hit.target().playerObjectId(), hit.damage() > 0 ? 10 : 0,
                    tick.heading(), sequence, skill.effectGfx(),
                    actor.x(), actor.y(),
                    hit.target().positionX, hit.target().positionY);
        } else {
            packet = Protocol.attackMany(
                    skill.actionId(), actor.objectId(), actor.x(), actor.y(),
                    tick.heading(), sequence, skill.effectGfx(),
                    skill.targeting()
                            == BattleTimeAttackMagicSkillCatalog.Targeting.TARGET_RADIUS
                                    ? 8 : 0,
                    hits.stream().map(hit -> new Protocol.AttackManyTarget(
                            hit.target().playerObjectId(), hit.damage() > 0)).toList());
        }

        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(packet,
                    (skill.targeting()
                            == BattleTimeAttackMagicSkillCatalog.Targeting.DIRECTIONAL
                                ? "S_ATTACK" : hits.isEmpty()
                                    ? "S_ACTION" : "S_ATTACK_MANY")
                            + " Time-Attack-mobskill actor=" + actor.objectId()
                            + " npc=" + actor.npcId() + " skill=" + skill.skillId()
                            + " targets=" + hits.size() + " action=" + skill.actionId()
                            + " gfx=" + skill.effectGfx() + " sequence=" + sequence
                            + " trigger-roll=" + tick.magicTriggerRoll()
                            + " leverage=" + skill.leverage()
                            + " authority=" + tick.source());
        }

        for (TimeAttackMonsterMagicHit hit : hits) {
            System.out.println("[LiTo] Time Attack monster magic npc="
                    + actor.npcId() + " object=" + actor.objectId()
                    + " skill=" + skill.skillId() + " target="
                    + hit.target().playerObjectId() + " source-damage="
                    + hit.sourceDamage() + " caster-int=" + actorIntelligence
                    + " elemental-resistance=" + hit.elementalResistance()
                    + " leverage=" + skill.leverage() + " armor-reduction="
                    + hit.armorReduction() + " target-mr="
                    + hit.targetMagicResistance() + " damage=" + hit.damage());
            BattleJoyOfPainStatus.Lease joyLease = hit.damage() <= 0 ? null
                    : hit.target().captureEncounterJoyOfPain(
                            tick, System.nanoTime());
            int joyDamage = joyLease == null ? 0
                    : hit.target().currentJoyOfPainFeedbackDamage();
            hit.target().takePlayerDamage(hit.damage(), null);
            if (hit.damage() > 0) {
                hit.target().tryMortalBodyEncounterReflection(
                        tick, actor.level(), actor.gfx(), actor.finalBoss(), recipients,
                        "time-attack-monster-magic-" + skill.skillId());
                hit.target().applyJoyOfPainEncounterFeedback(
                        tick, joyLease, joyDamage, recipients,
                        "time-attack-monster-magic-" + skill.skillId());
            }
        }
        if (skill.drainsLife()) {
            int drained = hits.stream().mapToInt(TimeAttackMonsterMagicHit::damage)
                    .sum();
            BattleTimeAttackEncounter.Healing healing = drained <= 0 ? null
                    : hub.healTimeAttackActor(
                            tick.roomId(), this, actor.objectId(), drained);
            if (healing != null && healing.restoredHp() > 0) {
                byte[] ratio = Protocol.hitRatio(
                        healing.after().objectId(), healing.after().hp(),
                        healing.after().maxHp());
                for (ClientSession recipient : recipients) {
                    recipient.sendEncrypted(ratio,
                            "S_HIT_RATIO Time-Attack-vampiric-touch actor="
                                    + actor.objectId() + " restored="
                                    + healing.restoredHp() + " hp="
                                    + healing.after().hp() + "/"
                                    + healing.after().maxHp());
                }
            }
        }
    }

    private void serverTimeAttackMonsterVisualSkill(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.VisualDefinition skill = tick.visualSkill();
        if (skill == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || skill.npcId() != actor.npcId()) return;
        int distance = Math.max(Math.abs(actor.x() - positionX),
                Math.abs(actor.y() - positionY));
        if (!skill.castDistance(distance)) return;

        // Selected skill31003 has no retained damage/status branch and a zero
        // duration. Preserve only the packets that L1SkillUse can prove: the
        // target-bound skill sound and the caster's configured action.
        byte[] effect = Protocol.effectObject(playerObjectId(), skill.effectGfx());
        byte[] action = Protocol.objectAction(actor.objectId(), skill.actionId());
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(effect,
                    "S_EFFECT Time-Attack-mobskill-visual actor=" + actor.objectId()
                            + " npc=" + actor.npcId() + " target="
                            + playerObjectId() + " skill=" + skill.skillId()
                            + " gfx=" + skill.effectGfx() + " duration-ms="
                            + skill.durationMillis() + " trigger-roll="
                            + tick.magicTriggerRoll() + " authority=" + tick.source());
            recipient.sendEncrypted(action,
                    "S_ACTION Time-Attack-mobskill-visual actor=" + actor.objectId()
                            + " npc=" + actor.npcId() + " skill=" + skill.skillId()
                            + " action=" + skill.actionId() + " leverage="
                            + skill.leverage() + " authority=" + tick.source());
        }
        System.out.println("[LiTo] Time Attack monster visual skill npc="
                + actor.npcId() + " object=" + actor.objectId() + " target="
                + playerObjectId() + " skill=" + skill.skillId() + " action="
                + skill.actionId() + " gfx=" + skill.effectGfx()
                + " damage=0 duration-ms=0");
    }

    private void serverTimeAttackMonsterGroundSkill(
            GameHub.MonsterAiTick tick,
            BattleTimeAttackEncounter.Snapshot actor,
            List<ClientSession> recipients) throws IOException {
        BattleTimeAttackMagicSkillCatalog.GroundDefinition skill =
                tick.groundSkill();
        if (skill == null || actor == null || recipients == null
                || actor.objectId() != tick.objectId()
                || skill.npcId() != actor.npcId()) return;
        int distance = Math.max(Math.abs(actor.x() - positionX),
                Math.abs(actor.y() - positionY));
        if (!skill.castDistance(distance)) return;

        BattleGroundEffects.CastResult placed = hub.placeTimeAttackGroundSpell(
                tick.roomId(), actor, skill, positionX, positionY,
                System.nanoTime());
        if (!placed.accepted()) return;

        byte[] action = Protocol.objectAction(actor.objectId(), skill.actionId());
        for (ClientSession recipient : recipients) {
            recipient.sendEncrypted(action,
                    "S_ACTION Time-Attack-ground caster=" + actor.objectId()
                            + " npc=" + actor.npcId() + " skill=" + skill.skillId()
                            + " action=" + skill.actionId() + " source-action="
                            + skill.sourceActionId() + " trigger-roll="
                            + tick.magicTriggerRoll() + " authority=" + tick.source());
            for (ArenaMapCatalog.Point point : placed.points()) {
                recipient.sendEncrypted(Protocol.effectLocation(
                                point.x(), point.y(), skill.effectGfx()),
                        "S_EFFECT_LOC Time-Attack-ground skill=" + skill.skillId()
                                + " npc-effect=" + skill.effectNpcId()
                                + " x=" + point.x() + " y=" + point.y()
                                + " gfx=" + skill.effectGfx());
            }
        }
        System.out.println("[LiTo] Time Attack monster ground skill npc="
                + actor.npcId() + " object=" + actor.objectId()
                + " skill=" + skill.skillId() + " points="
                + placed.points().size() + " duration-ms="
                + skill.durationMillis() + " pulse-ms="
                + skill.pulseIntervalMillis() + " pulse-count="
                + skill.pulseCount() + " fixed-damage=" + skill.fixedDamage());
    }

