    void serverCubeIgnitionDamage(long l, int n, int n2, ClientSession clientSession, BattleCubeIgnitionEffects.Event event) throws IOException {
        boolean bl;
        if (NativeSourceCubePlayer.damage(this, l, n, n2, clientSession, event)) {
            return;
        }
        if (clientSession == null || event == null || event.targetObjectId() != this.playerObjectId() || this.playerHp <= 0 || !this.cubeIgnitionContextMatches(l, n, n2)) {
            return;
        }
        long l2 = System.nanoTime();
        boolean bl2 = bl = this.timedStatus.freezeActive(l2) || this.timedStatus.absoluteBarrierActive(l2) || this.timedStatus.earthBindActive(l2);
        if (bl) {
            System.out.println("[LiTo] Cube: Ignition damage blocked target=" + this.playerName() + " object=" + event.cube().objectId() + " freeze=" + this.timedStatus.freezeActive(l2) + " absolute-barrier=" + this.timedStatus.absoluteBarrierActive(l2) + " earth-bind=" + this.timedStatus.earthBindActive(l2));
            return;
        }
        byte[] byArray = Protocol.objectAction(this.playerObjectId(), 2);
        for (ClientSession clientSession2 : this.cubeIgnitionRecipients(l, n, n2)) {
            if (n >= 0 && !BattleSpellCatalog.isInNativeScreen(clientSession2.positionX, clientSession2.positionY, this.positionX, this.positionY)) continue;
            clientSession2.sendEncrypted(byArray, "S_ACTION Cube-Ignition damage target=" + this.playerObjectId() + " caster=" + clientSession.playerObjectId());
        }
        this.takePlayerDamage(10, clientSession);
        System.out.println("[LiTo] Cube: Ignition damage target=" + this.playerName() + " caster=" + clientSession.playerName() + " damage=10 object=" + event.cube().objectId());
    }

    void serverCubeIgnitionBotDamage(
            long roomId, BattleCubeIgnitionEffects.Event event)
            throws IOException {
        if (event == null || phase != Phase.BATTLE || currentRoomId != roomId
                || hub.botHp(roomId) <= 0) return;
        byte[] reaction = Protocol.objectAction(2, BattleActionCodes.DAMAGE);
        for (ClientSession member : hub.roomMembers(roomId)) {
            member.sendEncrypted(reaction,
                    "S_ACTION Cube-Ignition bot damage caster=" + playerObjectId());
        }
        int remaining = hub.damageBot(
                roomId, BattleCubeIgnitionEffects.ENEMY_DAMAGE);
        broadcastHitRatio(2, remaining, GameHub.ARENA_BOT_MAX_HP,
                remaining == 0 ? "cube-ignition-bot-death"
                        : "cube-ignition-bot-damage");
        if (remaining == 0) {
            byte[] death = Protocol.objectAction(2, BattleActionCodes.DIE);
            for (ClientSession member : hub.roomMembers(roomId)) {
                member.sendEncrypted(death, "S_ACTION Cube-Ignition bot death");
            }
            BattleRules.Resolution resolution = new BattleRules.Resolution(
                    true, false, Set.of(playerObjectId()), Set.of(),
                    "arena-bot-defeated-by-cube-ignition");
            for (ClientSession member : hub.roomMembers(roomId)) {
                member.serverEndBattle(resolution);
            }
            hub.endBattle(roomId);
        }
    }

    void serverCubeIgnitionMonsterDamage(
            long roomId, int mapId, int instanceId,
            BattleCubeIgnitionEffects.Event event) throws IOException {
        if (event == null || event.targetKind()
                != BattleCubeIgnitionEffects.ActorKind.MONSTER) return;
        long targetObjectId = event.targetObjectId();
        long now = System.nanoTime();
        if (mapId < 0) {
            BattleQuestEncounter.Snapshot quest = hub.questMonster(
                    roomId, targetObjectId);
            if (quest != null) {
                if (hub.questMonsterFreezeActive(roomId, targetObjectId, now)
                        || hub.questMonsterEarthBindActive(
                                roomId, targetObjectId, now)) return;
                applyQuestMonsterDamage(targetObjectId,
                        BattleCubeIgnitionEffects.ENEMY_DAMAGE,
                        "cube-ignition-" + BattleSpellCatalog.CUBE_IGNITION);
                return;
            }
            BattleTimeAttackEncounter.Snapshot time = hub.timeAttackActor(
                    roomId, targetObjectId);
            if (time != null) {
                if (hub.timeAttackActorFreezeActive(roomId, targetObjectId, now)
                        || hub.timeAttackActorEarthBindActive(
                                roomId, targetObjectId, now)) return;
                applyTimeAttackActorDamage(targetObjectId,
                        BattleCubeIgnitionEffects.ENEMY_DAMAGE,
                        "cube-ignition-" + BattleSpellCatalog.CUBE_IGNITION);
            }
            return;
        }
        if (!cubeIgnitionContextMatches(roomId, mapId, instanceId)
                || hub.classicWorldMonsterFreezeActive(
                        mapId, instanceId, targetObjectId, now)) return;
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        mapId, instanceId, targetObjectId,
                        playerObjectId(), BattleCubeIgnitionEffects.ENEMY_DAMAGE);
        if (transition != null) {
            publishClassicWorldSpellMonsterDamage(
                    BattleSpellCatalog.CUBE_IGNITION, transition);
        }
    }

    private boolean cubeIgnitionContextMatches(
            long roomId, int mapId, int instanceId) {
        return mapId >= 0
                ? phase == Phase.WORLD && classicWorldMapId == mapId
                    && classicWorldInstanceId == instanceId
                : phase == Phase.BATTLE && currentRoomId == roomId;
    }

    private List<ClientSession> cubeIgnitionRecipients(
            long roomId, int mapId, int instanceId) {
        return mapId >= 0 ? hub.classicWorldMembers(mapId, instanceId)
                : hub.roomMembers(roomId);
    }

    private int effectiveCubeIgnitionFireResistance(long nowNanos) {
        if (phase == Phase.BATTLE) {
            return hub.cubeIgnitionFireResistance(
                    currentRoomId, this, nowNanos);
        }
        if (phase == Phase.WORLD) {
            return hub.classicWorldCubeIgnitionFireResistance(
                    classicWorldMapId, classicWorldInstanceId,
                    this, nowNanos);
        }
        return 0;
    }

