    void serverCubeShockNonPlayerStatus(
            long roomId, int mapId, int instanceId,
            BattleCubeShockEffects.Event event) throws IOException {
        if (event == null || event.targetKind()
                == BattleCubeShockEffects.ActorKind.PLAYER) return;
        if (event.kind() != BattleCubeShockEffects.EventKind.ALLY_APPLIED
                && event.kind() != BattleCubeShockEffects.EventKind.ENEMY_APPLIED) {
            return;
        }
        int gfx = event.kind() == BattleCubeShockEffects.EventKind.ALLY_APPLIED
                ? BattleCubeShockEffects.ALLY_GFX
                : BattleCubeShockEffects.ENEMY_GFX;
        byte[] effect = Protocol.effectObject(event.targetObjectId(), gfx);
        for (ClientSession recipient : cubeIgnitionRecipients(
                roomId, mapId, instanceId)) {
            recipient.sendEncrypted(effect,
                    "S_EFFECT Cube-Shock-NPC target=" + event.targetObjectId()
                            + " kind=" + event.targetKind() + " gfx=" + gfx);
        }
    }

