    void serverGroundBotPulse(long roomId, int skillId) throws IOException {
        if (skillId != BattleSpellCatalog.FIRE_WALL || phase != Phase.BATTLE
                || observer || currentRoomId != roomId || playerHp <= 0
                || hub.botHp(roomId) <= 0) {
            return;
        }
        int sourceDamage = fireWallDamage();
        // ArenaBot has no persisted/template fire modifier in the current
        // Tournament actor definition. Keep that proven value explicit.
        int fireResistance = 0;
        int damage = BattleElementalResistance.fireWallDamage(
                sourceDamage, fireResistance);
        byte[] reaction = new Protocol.Writer().c(Protocol.S_ACTION)
                .d(2).c(BattleActionCodes.DAMAGE).bytes();
        for (ClientSession member : hub.roomMembers(roomId)) {
            member.sendEncrypted(reaction,
                    "S_ACTION fire-wall bot damage caster=" + playerObjectId());
        }
        int remaining = hub.damageBot(roomId, damage);
        broadcastHitRatio(2, remaining, GameHub.ARENA_BOT_MAX_HP,
                remaining == 0 ? "fire-wall-bot-death" : "fire-wall-bot-damage");
        if (remaining == 0) {
            byte[] death = new Protocol.Writer().c(Protocol.S_ACTION).d(2)
                    .c(BattleActionCodes.DIE).bytes();
            for (ClientSession member : hub.roomMembers(roomId)) {
                member.sendEncrypted(death, "S_ACTION fire-wall bot death");
            }
            BattleRules.Resolution resolution = new BattleRules.Resolution(
                    true, false, Set.of(playerObjectId()), Set.of(),
                    "arena-bot-defeated-by-fire-wall");
            for (ClientSession member : hub.roomMembers(roomId)) {
                member.serverEndBattle(resolution);
            }
            hub.endBattle(roomId);
        }
        System.out.println("[LiTo] ground pulse skill=" + skillId
                + " caster=" + playerName() + " target=ArenaBot source-damage="
                + sourceDamage + " fire=" + fireResistance + " damage=" + damage
                + " remaining=" + remaining);
    }

    void serverClassicWorldGroundPlayerPulse(
            int mapId, int instanceId, ClientSession caster, int skillId)
            throws IOException {
        if (skillId != BattleSpellCatalog.FIRE_WALL || caster == null
                || phase != Phase.WORLD || observer || playerHp <= 0
                || classicWorldMapId != mapId
                || classicWorldInstanceId != instanceId
                || caster.phase != Phase.WORLD || caster.playerHp <= 0
                || !sameClassicWorldMap(caster)
                || sameNonemptyClan(caster)
                || ClassicWorldMapCatalog.forMap(mapId)
                    .isSafetyZone(positionX, positionY)) {
            return;
        }
        long pulseNow = System.nanoTime();
        boolean freezeProtected = timedStatus.freezeActive(pulseNow);
        int sourceDamage = caster.fireWallDamage();
        int fireResistance = effectiveFireResistance(pulseNow);
        int damage = BattleElementalResistance.fireWallDamage(
                sourceDamage, fireResistance);
        damage = combatDamageAfterCooking(
                damage, "classic-world-fire-wall-" + skillId);
        if (freezeProtected) {
            damage = 0;
        } else {
            damage = earthBindProtectedCombatDamage(
                    damage, "classic-world-fire-wall-" + skillId);
        }
        if (damage <= 0) {
            System.out.println("[LiTo] classic-world ground pulse blocked/zero"
                    + " skill=" + skillId + " caster=" + caster.playerName()
                    + " target=" + playerName() + " source-damage="
                    + sourceDamage + " fire=" + fireResistance
                    + " freeze=" + freezeProtected);
            return;
        }
        byte[] reaction = Protocol.objectAction(
                playerObjectId(), BattleActionCodes.DAMAGE);
        for (ClientSession member : hub.classicWorldMembers(mapId, instanceId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    positionX, positionY)) continue;
            member.sendEncrypted(reaction,
                    "S_ACTION classic-world Fire-Wall damage target="
                            + playerObjectId() + " caster="
                            + caster.playerObjectId());
        }
        takeClassicWorldPlayerDamage(damage, caster, false);
        System.out.println("[LiTo] classic-world ground pulse skill=" + skillId
                + " caster=" + caster.playerName() + " target=" + playerName()
                + " source-damage=" + sourceDamage + " fire="
                + fireResistance + " damage=" + damage);
    }

    void serverClassicWorldGroundMonsterPulse(
            int mapId, int instanceId,
            ClassicWorldMonsterPopulation.Snapshot target, int skillId)
            throws IOException {
        if (skillId != BattleSpellCatalog.FIRE_WALL || target == null
                || phase != Phase.WORLD || playerHp <= 0
                || classicWorldMapId != mapId
                || classicWorldInstanceId != instanceId) return;
        ClassicWorldMonsterPopulation.Snapshot current =
                hub.classicWorldMonster(
                        mapId, instanceId, target.objectId());
        if (current == null || !current.present() || !current.alive()
                || current.mapId() != mapId) return;
        long pulseNow = System.nanoTime();
        boolean protectedStatus = hub.classicWorldMonsterFreezeActive(
                mapId, instanceId, current.objectId(), pulseNow)
                || hub.classicWorldMonsterEarthBindActive(
                        mapId, instanceId, current.objectId(), pulseNow);
        int sourceDamage = fireWallDamage();
        int fireResistance =
                ClassicWorldMonsterMagicDamage.companionElementalResistance(
                        current.template().weakAttribute(),
                        BattleSpellCatalog.ATTRIBUTE_FIRE);
        int damage = protectedStatus ? 0
                : BattleElementalResistance.fireWallDamage(
                        sourceDamage, fireResistance);
        if (damage <= 0
                || !classicWorldCkewAttackAllowed(
                        current.npcId(), pulseNow)) {
            System.out.println("[LiTo] classic-world ground monster pulse"
                    + " blocked/zero skill=" + skillId + " caster="
                    + playerName() + " target=" + current.objectId()
                    + " npc=" + current.npcId() + " source-damage="
                    + sourceDamage + " fire=" + fireResistance
                    + " protected=" + protectedStatus);
            return;
        }
        byte[] reaction = Protocol.objectAction(
                current.objectId(), BattleActionCodes.DAMAGE);
        for (ClientSession member : hub.classicWorldMembers(mapId, instanceId)) {
            if (!BattleSpellCatalog.isInNativeScreen(
                    member.positionX, member.positionY,
                    current.x(), current.y())) continue;
            member.sendEncrypted(reaction,
                    "S_ACTION classic-world Fire-Wall monster-damage target="
                            + current.objectId() + " caster="
                            + playerObjectId());
        }
        ClassicWorldMonsterPopulation.Hit transition =
                hub.damageClassicWorldMonster(
                        mapId, instanceId, current.objectId(),
                        playerObjectId(), damage);
        if (transition == null) return;
        hub.provokeClassicWorldMonster(
                mapId, instanceId, current.objectId(), playerObjectId());
        publishClassicWorldSpellMonsterDamage(skillId, transition);
        System.out.println("[LiTo] classic-world ground monster pulse skill="
                + skillId + " caster=" + playerName() + " target="
                + current.objectId() + " npc=" + current.npcId()
                + " source-damage=" + sourceDamage + " fire="
                + fireResistance + " damage="
                + transition.appliedDamage());
    }

    private void expireRentalTownMerchantItems(long l) throws IOException {
        if (this.rentalTownInventory.size() == 0) {
            return;
        }
        RuntimeInventory runtimeInventory = this.rentalTownInventory.copy();
        List<RuntimeInventory.Item> list = runtimeInventory.expireTimedItems(l);
        if (list.isEmpty()) {
            return;
        }
        boolean bl = list.stream().anyMatch(item -> item.equipped() && item.definition().weapon());
        RuntimeInventory runtimeInventory2 = this.rentalTownInventory;
        NativeDeItemApplication.replace(this, runtimeInventory, 1);
        this.pendingRentalMerchantList = null;
        if (this.rentalTownRoomState && this.phase == Phase.BATTLE) {
            this.sendInventoryDelta(runtimeInventory2, this.rentalTownInventory, false);
            this.resetAndSendRentalTownStatus();
            if (bl) {
                int n = this.rentalTownWalkAction();
                byte[] byArray = Protocol.wield(this.playerObjectId(), n);
                for (ClientSession clientSession : this.rentalTownMembers()) {
                    if (clientSession != this && !BattleSpellCatalog.isInNativeScreen(clientSession.positionX, clientSession.positionY, this.positionX, this.positionY)) continue;
                    clientSession.sendEncrypted(byArray, "S_WIELD rental-town expired player=" + this.playerName() + " walk-action=" + n);
                }
            }
        }
        System.out.println("[LiTo] rental-town merchant items expired player=" + this.playerName() + " objects=" + String.valueOf(list.stream().map(RuntimeInventory.Item::objectId).toList()));
    }

    /** Retained one-minute ServerItemUserTimer inventory lifecycle. */
    void serverExpireTimedInventory(long nowEpochMillis) throws IOException {
        synchronized (this) {
            expireRentalTownMerchantItems(nowEpochMillis);
            if (inventoryCharacter.isBlank()) return;
            RuntimeInventory candidate = inventory.copy();
            List<RuntimeInventory.Item> expired = candidate.expireTimedItems(nowEpochMillis);
            if (expired.isEmpty()) return;

            Set<Long> expiredObjectIds = expired.stream()
                    .map(RuntimeInventory.Item::objectId)
                    .collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));
            Map<Long, Long> retainedEquipmentObjects =
                    new LinkedHashMap<>(sourceEquipmentObjects);
            Set<Long> consumedEquipmentObjects =
                    new LinkedHashSet<>(consumedSourceEquipmentObjects);
            Map<Long, Long> retainedProjectileObjects =
                    new LinkedHashMap<>(sourceProjectileObjects);
            Map<Long, SourceMagicDollType> retainedMagicDolls =
                    new LinkedHashMap<>(sourceMagicDolls);
            boolean removedSourceEquipment = false;
            boolean removedEquippedWeapon = false;
            boolean removedEquippedArmor = false;
            boolean removedEquippedLight = false;
            for (RuntimeInventory.Item item : expired) {
                Long sourceObjectId = retainedEquipmentObjects.remove(item.objectId());
                if (sourceObjectId != null) {
                    consumedEquipmentObjects.add(sourceObjectId);
                    removedSourceEquipment = true;
                }
                retainedProjectileObjects.entrySet().removeIf(
                        entry -> entry.getValue() == item.objectId());
                retainedMagicDolls.remove(item.objectId());
                if (item.equipped() && item.definition().weapon()) {
                    removedEquippedWeapon = true;
                }
                if (item.equipped() && item.definition().sourceArmor()) {
                    removedEquippedArmor = true;
                }
                if (item.equipped() && item.definition().light()) {
                    removedEquippedLight = true;
                }
            }

            SourceEquipmentEvaluation evaluation = null;
            if (removedSourceEquipment) {
                CharacterSummary character = selectedCharacterSummary();
                if (character == null) {
                    throw new IOException(
                            "expired source equipment has no selected character");
                }
                try {
                    evaluation = selectedSourceAccounts().equipmentEvaluation(
                            character.objectId(), sourceEquipmentOverrides(
                                    candidate, retainedEquipmentObjects,
                                    consumedEquipmentObjects));
                } catch (Exception sourceFailure) {
                    throw new IOException(
                            "cannot evaluate equipment after timed-item expiry",
                            sourceFailure);
                }
                if (evaluation.magic().matchedArmorRows()
                        != candidate.equippedSourceArmorCount()) {
                    throw new IOException(
                            "timed-item expiry source armor evaluation differs");
                }
            }

            state.saveEconomyStateExpiringTimedItems(
                    stateCharacter(), shopPoints, candidate.catalogCounts(),
                    candidate.catalogItemStates(), expiredObjectIds, nowEpochMillis);
            RuntimeInventory previous = inventory;
            NativeDeItemApplication.replace(this, candidate, 0);
            sourceEquipmentObjects = Map.copyOf(retainedEquipmentObjects);
            consumedSourceEquipmentObjects = Set.copyOf(consumedEquipmentObjects);
            sourceProjectileObjects = Map.copyOf(retainedProjectileObjects);
            sourceMagicDolls = Map.copyOf(retainedMagicDolls);
            if (evaluation != null) {
                sourceEquipmentMagicStats = evaluation.magic();
                sourceEquipmentVitalStats = evaluation.vital();
                sourceEquippedFireResistance = new SourceEquippedFireResistance(
                        NumericBreakthrough.clampElementalResistance(
                                sourceEquipmentMagicStats.totalFireResistance()),
                        sourceEquipmentMagicStats.matchedArmorRows());
            }
            if (removedEquippedWeapon) sourceWeaponSuppressed = true;
            synchronized (activeMagicDollObjectIds) {
                if (activeMagicDoll != null && expiredObjectIds.contains(
                        activeMagicDoll.backingItemObjectId())) {
                    recallNativeMagicDollLocked("backing-item-expired", true);
                }
                activeMagicDollObjectIds.removeAll(expiredObjectIds);
            }

            if (inventoryBootstrapSent) {
                sendInventoryDelta(previous, inventory, false);
                if (removedSourceEquipment) {
                    removeSolidCarriageUnlessEquipped("timed-item-expired");
                    cancelAbsoluteBarrier("timed-item-expired");
                    sendEquipmentStatusRefresh("timed-item-expired");
                }
                if (removedEquippedWeapon && phase == Phase.BATTLE) broadcastWieldState();
                if (removedEquippedLight && phase == Phase.BATTLE) {
                    broadcastLightState("timed-item-expired");
                }
            }
            System.out.println("[LiTo] timed inventory expired player=" + playerName()
                    + " objects=" + expiredObjectIds
                    + " source-equipment=" + removedSourceEquipment
                    + " equipped-armor=" + removedEquippedArmor);
        }
    }

    void serverExpireTimedStatuses(long l) throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$serverExpireTimedStatuses(l, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    /*
     * WARNING - Removed try catching itself - possible behaviour change.
     */
    private void serverAwakeningMpDrain(long l) throws IOException {
        int n;
        int n2;
        int n3;
        BattleAwakenStatus.Snapshot snapshot;
        ClientSession clientSession = this;
        synchronized (clientSession) {
            snapshot = this.awakenStatus.snapshot();
            if (!snapshot.active() || this.playerHp <= 0) {
                return;
            }
            n3 = CombatAwaken.pollMpDrainTicks(this.awakenStatus, l);
            if (n3 <= 0) {
                return;
            }
            long l2 = Math.multiplyExact((long)n3, snapshot.mpDrainAmount());
            n2 = this.playerMp;
            n = this.playerMp = (int)Math.max(0L, (long)this.playerMp - l2);
        }
        int n4 = n2 - n;
        String string = ClientSession.awakenLogName(snapshot.skillId());
        if (n4 > 0) {
            this.sendEncrypted(Protocol.manaPoint(n, this.playerMaxMp), "S_MANA_POINT " + string + "-drain=" + n + "/" + this.playerMaxMp + " amount=" + n4 + " ticks=" + n3);
        }
        System.out.println("[LiTo] " + string + " MP drain player=" + this.playerName() + " ticks=" + n3 + " requested=" + (long)n3 * (long)snapshot.mpDrainAmount() + " drained=" + n4 + " mp=" + n + "/" + this.playerMaxMp + " remains-active-at-zero=true");
    }

    private void serverNaturalHpRegen(long nowNanos, boolean activePhase) throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        int level = effectiveClassicLevel(character);
        int type = character == null ? 0 : character.type();
        int food = character == null ? 40 : character.food();
        boolean otherwiseActive = config.battleNaturalHpRegenEnabled()
                && activePhase && !observer && pendingPortal == null
                && playerHp > 0 && playerHp < playerMaxHp && food >= 3
                && !timedStatus.absoluteBarrierActive(nowNanos);
        int weight240 = otherwiseActive ? currentWeight240(nowNanos) : 0;
        boolean weightBypassActive = weightStatus.snapshot(nowNanos)
                .regenerationBypassActive();
        boolean active = otherwiseActive
                && BattleInventoryWeight.permitsNaturalHpRegen(
                        weight240, weightBypassActive);
        int due = naturalHpRegen.poll(nowNanos, active, level, type);
        if (due <= 0) return;

        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int baseConstitution = character == null ? 10 : Math.max(0, character.constitution());
        int constitution = effectiveConstitution();
        int originalConstitution = character == null ? constitution
                : Math.max(0, character.originalConstitution());
        int conHprMaximum = character != null && constitution == baseConstitution
                ? Math.max(1, character.constitutionHprMaximum())
                : BattleNaturalHpRegen.fallbackConHprMaximum(constitution);
        int equipmentHpr = equipment.totalHpRegen()
                + waterDragonBlessingHpRegen(nowNanos);
        BattleNaturalHpRegen.Profile profile = new BattleNaturalHpRegen.Profile(
                level, type, constitution, originalConstitution, food,
                conHprMaximum, equipmentHpr);
        boolean inLifeStream = phase == Phase.WORLD
                ? hub.inClassicWorldLifeStream(
                        classicWorldMapId, classicWorldInstanceId,
                        this, positionX, positionY, nowNanos)
                : hub.inLifeStream(
                        currentRoomId, this, positionX, positionY, nowNanos);
        int skillHpRegen = naturesTouchStatus.hpRegen(nowNanos);
        int previous = playerHp;
        int rolled = 0;
        for (int tick = 0; tick < due && playerHp < playerMaxHp; tick++) {
            int amount = BattleNaturalHpRegen.roll(profile, inLifeStream,
                    cookingHpRegen(nowNanos), skillHpRegen);
            rolled += amount;
            playerHp = Math.max(1, Math.min(playerMaxHp, playerHp + amount));
        }
        if (playerHp == previous) return;

        sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                        .h(playerHp).h(playerMaxHp).bytes(),
                "S_HIT_POINT natural-hpr=" + playerHp + "/" + playerMaxHp
                + " amount=" + (playerHp - previous)
                + " life-stream=" + inLifeStream);
        broadcastOwnHitRatio(inLifeStream ? "life-stream-hpr" : "natural-hpr");
        System.out.println("[LiTo] natural HPR player=" + playerName()
                + " ticks=" + due + " rolled=" + rolled
                + " applied=" + (playerHp - previous)
                + " life-stream=" + inLifeStream
                + " natures-touch-hpr=" + skillHpRegen
                + " cooking-hpr=" + cookingHpRegen(nowNanos)
                + " weight240=" + weight240
                + " hp=" + playerHp + "/" + playerMaxHp);
    }

    private void serverNaturalMpRegen(long nowNanos, boolean activePhase)
            throws IOException {
        CharacterSummary character = selectedCharacterSummary();
        int type = character == null ? 0 : character.type();
        int food = character == null ? 40 : character.food();
        boolean otherwiseActive = config.battleNaturalMpRegenEnabled()
                && activePhase && !observer && pendingPortal == null
                && playerHp > 0 && playerMp < playerMaxMp && food >= 3
                && !timedStatus.absoluteBarrierActive(nowNanos);
        int weight240 = otherwiseActive ? currentWeight240(nowNanos) : 0;
        boolean weightBypassActive = weightStatus.snapshot(nowNanos)
                .regenerationBypassActive();
        boolean active = otherwiseActive
                && BattleInventoryWeight.permitsNaturalRegen(
                        weight240, weightBypassActive);
        int due = naturalMpRegen.poll(nowNanos, active, type);
        if (due <= 0) return;

        // Same-family MprExecutor resets its counter first, then suppresses
        // natural MP on the wizard-trial dungeon map.
        int mapId = phase == Phase.WORLD
                ? classicWorldMapId : hub.roomRules(currentRoomId).mapId();
        if (mapId == 201 || (phase == Phase.WORLD
                && ClassicWorldMapRecoveryCatalog.disablesNaturalMp(
                        mapId, positionX, positionY))) return;

        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int wisdom = effectiveWisdom(nowNanos);
        int originalWisdom = character == null ? wisdom
                : Math.max(0, character.originalWisdom());
        int equipmentMpr = equipment.totalMpRegen()
                + waterDragonBlessingMpRegen(nowNanos);
        BattleNaturalMpRegen.Profile profile = new BattleNaturalMpRegen.Profile(
                type, wisdom, originalWisdom, equipmentMpr);
        boolean bluePotionActive = timedStatus.bluePotionActive(nowNanos);
        boolean meditationActive = timedStatus.meditationActive(nowNanos);
        boolean concentrationActive = timedStatus.concentrationActive(nowNanos);
        int cookingMpRegen = cookingMpRegen(nowNanos);
        int amountPerTick = BattleNaturalMpRegen.amount(profile, bluePotionActive,
                meditationActive, concentrationActive, cookingMpRegen);
        int previous = playerMp;
        long rolled = Math.multiplyExact((long) due, amountPerTick);
        playerMp = (int) Math.min((long) playerMaxMp,
                Math.max(0L, (long) playerMp + rolled));
        if (playerMp == previous) return;

        sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                "S_MANA_POINT natural-mpr=" + playerMp + "/" + playerMaxMp
                        + " amount=" + (playerMp - previous));
        System.out.println("[LiTo] natural MPR player=" + playerName()
                + " ticks=" + due + " amount-per-tick=" + amountPerTick
                + " applied=" + (playerMp - previous)
                + " wisdom=" + wisdom
                + " equipment-mpr=" + equipmentMpr
                + " blue-potion=" + bluePotionActive
                + " meditation=" + meditationActive
                + " concentration=" + concentrationActive
                + " cooking-mpr=" + cookingMpRegen
                + " weight240=" + weight240
                + " mp=" + playerMp + "/" + playerMaxMp);
    }

    private void serverClassicWorldMapRecovery(long nowNanos,
                                               boolean inClassicWorld)
            throws IOException {
        if (!inClassicWorld || observer || pendingPortal != null || playerHp <= 0) {
            classicWorldMapRecoveryClock.reset();
            return;
        }
        ClassicWorldMapRecoveryCatalog.Rule rule =
                ClassicWorldMapRecoveryCatalog.ruleFor(
                        classicWorldMapId, positionX, positionY);
        if (!classicWorldMapRecoveryClock.poll(
                classicWorldMapId, rule, nowNanos)) return;

        boolean inLifeStream = hub.inClassicWorldLifeStream(
                classicWorldMapId, classicWorldInstanceId,
                this, positionX, positionY, nowNanos);
        int configuredHp = rule.hp();
        boolean underwaterProtected = configuredHp < 0
                && (activeMagicDollUnderwaterBreath()
                    || timedStatus.breath(nowNanos).remainingSeconds() > 0);
        int hpDelta = configuredHp;
        if (hpDelta < 0 && (inLifeStream || underwaterProtected)) hpDelta = 0;
        if (inLifeStream) hpDelta = Math.addExact(hpDelta, 3);

        int previousHp = playerHp;
        int previousMp = playerMp;
        playerHp = (int) Math.max(1L, Math.min((long) playerMaxHp,
                Math.addExact((long) playerHp, hpDelta)));
        playerMp = (int) Math.max(0L, Math.min((long) playerMaxMp,
                Math.addExact((long) playerMp, rule.mp())));

        if (playerHp != previousHp) {
            sendEncrypted(new Protocol.Writer().c(Protocol.S_HIT_POINT)
                            .h(playerHp).h(playerMaxHp).bytes(),
                    "S_HIT_POINT map-recovery=" + playerHp + "/" + playerMaxHp
                            + " map=" + classicWorldMapId + " rule=" + rule.id()
                            + " amount=" + (playerHp - previousHp));
            broadcastOwnHitRatio("map-recovery");
        }
        if (playerMp != previousMp) {
            sendEncrypted(Protocol.manaPoint(playerMp, playerMaxMp),
                    "S_MANA_POINT map-recovery=" + playerMp + "/" + playerMaxMp
                            + " map=" + classicWorldMapId + " rule=" + rule.id()
                            + " amount=" + (playerMp - previousMp));
        }
        System.out.println("[LiTo] classic map recovery player=" + playerName()
                + " map=" + classicWorldMapId + " rule=" + rule.id()
                + " configured-hp=" + configuredHp + " configured-mp=" + rule.mp()
                + " applied-hp=" + (playerHp - previousHp)
                + " applied-mp=" + (playerMp - previousMp)
                + " life-stream=" + inLifeStream
                + " underwater-protected=" + underwaterProtected
                + " hp=" + playerHp + "/" + playerMaxHp
                + " mp=" + playerMp + "/" + playerMaxMp);
    }

    private int currentPoisonPalette(long l) {
        if (CombatPoisonParalysis.paletteFirst(this.timedStatus.freezeVisualLockActive(l), this.timedStatus, l)) {
            return 2;
        }
        if (this.timedStatus.paralysisVisualActive(l)) {
            if (this.classicWorldPoisonKind == ClassicWorldMonsterPoisonAttack.Kind.PARALYSIS) {
                return this.timedStatus.paralysisActive(l) ? 2 : 1;
            }
            return 2;
        }
        if (this.timedStatus.poisonActive(l) || this.timedStatus.poisonSilenceActive()) {
            return 1;
        }
        return 0;
    }

    private void cancelParalysis(String string) throws IOException {
        CombatPoisonLifecycle.Scope scope = CombatPoisonLifecycle.open();
        try {
            this.sourcePoisonBody$cancelParalysis(string, scope);
        }
        catch (Throwable throwable) {
            CombatPoisonLifecycle.failed(scope, throwable);
            throw throwable;
        }
        CombatPoisonLifecycle.finish(scope);
    }

    private void cancelSleep(String reason) throws IOException {
        if (!timedStatus.cancelSleep()
                || phase != Phase.BATTLE && phase != Phase.WORLD) return;
        sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.SLEEP_RELEASE),
                "S_PARALYSE mode=11 reason=" + reason);
    }

    private void cancelFreeze(String reason) throws IOException {
        if (!timedStatus.cancelFreeze()
                || phase != Phase.BATTLE && phase != Phase.WORLD
                || phase == Phase.BATTLE && currentRoomId == 0) return;
        // Same-family L1SkillStop clears the gray palette before releasing
        // LiTo's native freeze action group (modes 12/13).
        long nowNanos = System.nanoTime();
        broadcastPoisonState(currentPoisonPalette(nowNanos), reason);
        if (!timedStatus.freezeVisualLockActive(nowNanos)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.FREEZE_RELEASE),
                    "S_PARALYSE mode=13 reason=" + reason);
        }
    }

    private void cancelEarthBind(String reason) throws IOException {
        if (!timedStatus.cancelEarthBind()
                || phase != Phase.BATTLE || currentRoomId == 0) return;
        long nowNanos = System.nanoTime();
        broadcastPoisonState(currentPoisonPalette(nowNanos), reason);
        if (!timedStatus.freezeVisualLockActive(nowNanos)) {
            sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.FREEZE_RELEASE),
                    "S_PARALYSE mode=13 reason=" + reason);
        }
    }

    private void cancelShockStun(String reason) throws IOException {
        if (!timedStatus.cancelShockStun()
                || phase != Phase.BATTLE || currentRoomId == 0) return;
        // Death/teardown is the only early removal path in the retained
        // implementation; Cancellation and Remove Curse deliberately omit it.
        sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.STUN_RELEASE),
                "S_PARALYSE mode=23 reason=" + reason);
    }

    private void cancelThunderGrab(String reason) throws IOException {
        if (!timedStatus.cancelThunderGrab()
                || phase != Phase.BATTLE && phase != Phase.WORLD) return;
        sendEncrypted(Protocol.paralysis(Protocol.ParalysisMode.BIND_RELEASE),
                "S_PARALYSE mode=25 reason=" + reason);
    }

    private void breakSleepForStatusSpell(ClientSession playerTarget,
                                          BattleQuestEncounter.Snapshot questTarget,
                                          BattleTimeAttackEncounter.Snapshot timeTarget,
                                          String reason) throws IOException {
        if (playerTarget != null) {
            playerTarget.cancelSleep(reason);
        } else if (questTarget != null
                && hub.cancelQuestMonsterSleep(currentRoomId, questTarget.objectId())) {
            System.out.println("[LiTo] Quest monster sleep cancelled object="
                    + questTarget.objectId() + " reason=" + reason);
        } else if (timeTarget != null
                && hub.cancelTimeAttackActorSleep(currentRoomId, timeTarget.objectId())) {
            System.out.println("[LiTo] Time Attack actor sleep cancelled object="
                    + timeTarget.objectId() + " reason=" + reason);
        }
    }

    private void cancelMeditation(String reason) {
        if (!reason.equals("move") && !reason.equals("authoritative-move")
                && timedStatus.cancelAbsoluteBarrier()) {
            // Same-family Absolute Barrier has no compatible selected-client
            // stop icon. Accepted attack/spell/item/teleport ends authority.
            System.out.println("[LiTo] Absolute Barrier cancelled player=" + playerName()
                    + " reason=" + reason + " regen=resumed");
        }
        if (timedStatus.cancelMeditation()) {
            // Same-family L1SkillStop has no dedicated stop packet for skill 32.
            System.out.println("[LiTo] meditation cancelled player=" + playerName()
                    + " reason=" + reason);
        }
    }

    private void cancelAbsoluteBarrier(String reason) {
        if (timedStatus.cancelAbsoluteBarrier()) {
            System.out.println("[LiTo] Absolute Barrier cancelled player=" + playerName()
                    + " reason=" + reason + " regen=resumed");
        }
    }

