    private int magicResistanceModifier(long l) {
        int n = Math.addExact(Math.addExact(this.cookingMagicResistance(l), this.abilityStatus.royalAura(l).magicResistance()), this.abilityStatus.magicResistance(l).amount());
        return CombatSpecialBuffs.addScalar(Math.addExact(Math.addExact(n, this.awakenStatus.snapshot().magicResistanceModifier()), this.effectiveCubeShockMagicResistanceModifier(l)), this, l, "MR");
    }

