        int wireMagicResistance = NumericBreakthrough.clampMagicModifier(
                magicResistance);
        sendEncrypted(Protocol.magicStatus(wireSpellPower, wireMagicResistance),
                "S_MAGIC_STATUS " + reason + " player=" + playerName()
                        + " sp-modifier=" + spellPower
                        + " mr-modifier=" + magicResistance
                        + " wire-sp=" + wireSpellPower
                        + " wire-mr=" + wireMagicResistance);
