    private int combatDamageAfterCooking(
            int damage, String source, boolean playerPhysicalAttacker,
            int attackerWeaponType, boolean applyReductionArmor,
            boolean physicalDamage) {
        long now = System.nanoTime();
        BattleCookingStatus.Snapshot cooking = cookingStatus.active(now);
        int reduction = cooking.damageReduction();
        int applied = damage;
        if (reduction != 0) {
            applied = BattleCookingCatalog.damageAfterReduction(damage, reduction);
            System.out.println("[LiTo] cooking damage reduction player=" + playerName()
                    + " statuses=" + cooking.recipes().stream()
                        .map(recipe -> Integer.toString(recipe.statusId())).toList()
                    + " source=" + source
                    + " raw=" + damage + " reduction=" + reduction
                    + " applied=" + applied);
        }
        BattleAbilityStatus.ReductionArmor reductionArmor =
                abilityStatus.reductionArmor(now);
        if (applyReductionArmor && reductionArmor.remainingSeconds() != 0) {
            BattleSpellCatalog.ReductionArmorSpell spell =
                    BattleSpellCatalog.reductionArmorSpell(
                            BattleSpellCatalog.REDUCTION_ARMOR);
            int reducedDamage = spell.applyTo(
                    applied, battleLevel(), playerPhysicalAttacker);
            System.out.println("[LiTo] Reduction Armor damage reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " target-level=" + battleLevel()
                    + " player-physical-attacker=" + playerPhysicalAttacker
                    + " reduction=" + (applied - reducedDamage)
                    + " applied=" + reducedDamage);
            applied = reducedDamage;
        }
        boolean armorBreakActive = playerPhysicalAttacker
                && (phase == Phase.WORLD
                    ? classicWorldArmorBreakActive(now)
                    : currentRoomId != 0 && hub.armorBreakActive(
                            currentRoomId, playerObjectId(), now));
        int brokenDamage = BattleArmorBreak.damageAfterBreak(
                applied, armorBreakActive, attackerWeaponType);
        if (brokenDamage != applied) {
            System.out.println("[LiTo] Armor Break melee amplification player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " weapon-type=" + attackerWeaponType
                    + " percent=" + BattleArmorBreak.DAMAGE_PERCENT
                    + " applied=" + brokenDamage);
            applied = brokenDamage;
        }
        BattleDragonSkinStatus.Snapshot dragonSkin =
                dragonSkinStatus.snapshot(now);
        if (physicalDamage && dragonSkin.active()) {
            int reducedDamage = dragonSkin.applyTo(applied);
            System.out.println("[LiTo] Dragon Skin physical reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " reduction=" + dragonSkin.damageReduction()
                    + " applied=" + reducedDamage);
            applied = reducedDamage;
        }
        int patienceReduction = physicalDamage
                ? effectivePatiencePhysicalReduction(now) : 0;
        if (patienceReduction != 0) {
            int reducedDamage = Math.max(0, applied - patienceReduction);
            System.out.println("[LiTo] Patience physical reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied
                    + " original-reduction=" + patienceReduction
                    + " applied=" + reducedDamage);
            applied = reducedDamage;
        }
        BattleAbilityStatus.Protection protection =
                abilityStatus.immuneToHarm(now);
        if (protection.divisor() != 0) {
            int protectedDamage = protection.applyTo(applied);
            System.out.println("[LiTo] Immune to Harm damage reduction player="
                    + playerName() + " source=" + source
                    + " before=" + applied + " divisor=" + protection.divisor()
                    + " applied=" + protectedDamage);
            applied = protectedDamage;
        }
        return applied;
    }

    /** NPC/Pet physical order: AC is upstream, then armor reduction, then cooking. */
    private int combatPhysicalDamageAfterArmorAndCooking(int damage, String source) {
        int reductionBase = effectiveArmorMagicReductionBase();
        int reductionRoll = reductionBase <= 10 ? 0
                : ThreadLocalRandom.current().nextInt(reductionBase - 10);
        int reduction = BattlePhysicalDefense.armorReduction(
                reductionBase, reductionRoll);
        int afterArmor = Math.max(0, damage - reduction);
        if (reduction != 0) {
            System.out.println("[LiTo] physical armor reduction player=" + playerName()
                    + " source=" + source + " raw=" + damage
                    + " reduction-base=" + reductionBase
                    + " reduction-roll=" + reductionRoll
                    + " reduction=" + reduction + " applied=" + afterArmor);
        }
        return combatDamageAfterCooking(
                afterArmor, source, false, 0, true, true);
    }

