    private int effectiveFireResistance(long l) {
        int n = this.requiredEquipmentMagicStats().totalFireResistance() + this.activeMagicDollPowers().value("PASSIVE_DEF_FIRE") + this.inventory.activeFireResistance() + this.cookingStatus.active(l).allElementResistance() + this.awakenStatus.snapshot().allElementalResistance() + this.resistElementalStatus.modifier(l) + this.elementalProtectionStatus.modifier(2, l) + this.elementalFallDownStatus.modifier(2, l) + this.effectiveCubeIgnitionFireResistance(l);
        return NumericBreakthrough.clampElementalResistance(CombatSpecialBuffs.element(n, this, 2, l));
    }

    private int effectiveSpellElementalResistance(int n) {
        return this.effectiveSpellElementalResistance(n, System.nanoTime());
    }

    private int effectiveSpellElementalResistance(int n, long l) {
        if (n == 2) {
            return this.effectiveFireResistance(l);
        }
        if (n != 1 && n != 4 && n != 8) {
            return 0;
        }
        int n2 = this.requiredEquipmentMagicStats().physical().elemental().resistance(n);
        NativeMagicDollPowers nativeMagicDollPowers = this.activeMagicDollPowers();
        int n3 = n2 + nativeMagicDollPowers.value(switch (n) {
            case 1 -> "PASSIVE_DEF_EARTH";
            case 4 -> "PASSIVE_DEF_WATER";
            case 8 -> "PASSIVE_DEF_WIND";
            default -> "";
        }) + this.cookingStatus.active(l).allElementResistance() + this.awakenStatus.snapshot().allElementalResistance() + this.resistElementalStatus.modifier(l) + this.elementalProtectionStatus.modifier(n, l) + this.elementalFallDownStatus.modifier(n, l);
        if (n == 4) {
            n3 += this.waterDragonBlessingWaterResistance(l);
        }
        if (n == 1) {
            n3 += this.effectiveCubeQuakeEarthResistance(l);
        }
        if (n == 8) {
            n3 += this.effectiveCubeShockWindResistance(l);
        }
        return NumericBreakthrough.clampElementalResistance(CombatSpecialBuffs.element(n3, this, n, l));
    }

    private int effectiveWeaponAttributeResistance(int n) {
        if (n == 0) {
            return 0;
        }
        if (n == 2) {
            return this.effectiveFireResistance();
        }
        if (n == 16 || n == 32 || n == 64 || n == 128) {
            return this.effectiveBaseMagicResistance();
        }
        int n2 = this.requiredEquipmentMagicStats().physical().elemental().resistance(n);
        long l = System.nanoTime();
        NativeMagicDollPowers nativeMagicDollPowers = this.activeMagicDollPowers();
        int n3 = n2 + nativeMagicDollPowers.value(switch (n) {
            case 1 -> "PASSIVE_DEF_EARTH";
            case 4 -> "PASSIVE_DEF_WATER";
            case 8 -> "PASSIVE_DEF_WIND";
            default -> "";
        }) + this.cookingStatus.active(l).allElementResistance() + this.awakenStatus.snapshot().allElementalResistance() + this.resistElementalStatus.modifier(l) + this.elementalProtectionStatus.modifier(n, l) + this.elementalFallDownStatus.modifier(n, l);
        if (n == 4) {
            n3 += this.waterDragonBlessingWaterResistance(l);
        }
        if (n == 1) {
            n3 += this.effectiveCubeQuakeEarthResistance(l);
        }
        if (n == 8) {
            n3 += this.effectiveCubeShockWindResistance(l);
        }
        return NumericBreakthrough.clampElementalResistance(CombatSpecialBuffs.element(n3, this, n, l));
    }

    private int effectiveWisdom(long l) {
        CharacterSummary characterSummary = this.selectedCharacterSummary();
        int n = characterSummary == null ? 1 : characterSummary.wisdom();
        int n2 = this.requiredEquipmentMagicStats().effectiveMprWisdom(n);
        int n3 = this.clearMindStatus.snapshot(l).wisdomModifier();
        return NumericBreakthrough.clampAbility(CombatSpecialBuffs.add((long)n2 + (long)n3 + (long)this.activeMagicDollPowers().value("PASSIVE_WIS") + (long)CombatAwaken.ability(this.awakenStatus.snapshot(), "WIS") + (long)this.abilityStatus.insight(l).abilityScoreModifier() + (long)this.abilityStatus.panic(l).abilityScoreModifier(), this, "WIS"));
    }

    private int effectiveBaseMagicResistance() {
        return effectiveBaseMagicResistance(System.nanoTime());
    }

    private int effectiveBaseMagicResistance(long nowNanos) {
        if (sourceBaseMagicResistance == null) {
            throw new IllegalStateException(
                    "selected character has no qualified source base-MR snapshot");
        }
        SourceEquipmentMagicStats equipment = requiredEquipmentMagicStats();
        int effectiveWisdom = effectiveWisdom(nowNanos);
        int base = sourceBaseMagicResistance.classBase()
                + sourceBaseMagicResistance.levelBonus()
                + sourceBaseMagicResistance.originalBonus()
                + BattleMagicResistance.wisdomMagicResistance(effectiveWisdom);
        int normal = Math.max(0, base + equipment.totalDirectMagicResistance()
                + activeMagicDollPowers().value("PASSIVE_MR")
                + magicResistanceModifier(nowNanos));
        return eraseMagicStatus.effectiveMagicResistance(normal, nowNanos);
    }

    private int effectiveArmorMagicReductionBase() {
        return CombatSpecialBuffs.addScalar(Math.addExact(this.requiredEquipmentMagicStats().armorReductionBase(), Math.addExact(this.dragonEyeStatus.snapshot(System.nanoTime()).damageReduction(), this.activeMagicDollPowers().value("PASSIVE_DMG_REDUX"))), this, System.nanoTime(), "DMG_REDUX");
    }

