    private Map<Long, Boolean> sourceEquipmentOverrides(
            RuntimeInventory candidate) {
        return sourceEquipmentOverrides(candidate, sourceEquipmentObjects,
                consumedSourceEquipmentObjects);
    }

    private Map<Long, Boolean> sourceEquipmentOverrides(
            RuntimeInventory candidate, Map<Long, Long> equipmentObjects,
            Set<Long> consumedEquipmentObjects) {
        if (candidate == null) {
            throw new IllegalArgumentException("candidate inventory is required");
        }
        Map<Long, Boolean> overrides = new LinkedHashMap<>();
        for (Long sourceObjectId : consumedEquipmentObjects) {
            overrides.put(sourceObjectId, false);
        }
        for (Map.Entry<Long, Long> binding : equipmentObjects.entrySet()) {
            RuntimeInventory.Item item = candidate.item(binding.getKey());
            if (item == null || !item.sourceBound()
                    || (!item.definition().weapon()
                            && !item.definition().sourceArmor())) {
                throw new IllegalStateException(
                        "source equipment binding has no runtime object: "
                                + binding.getKey());
            }
            if (overrides.putIfAbsent(binding.getValue(), item.equipped()) != null) {
                throw new IllegalStateException(
                        "duplicate retained source equipment object: "
                                + binding.getValue());
            }
        }
        return Map.copyOf(overrides);
    }

