    private String litoDisplayName(String fallbackCharacterName) {
        String id = accountName().isBlank() ? fallbackCharacterName : accountName();
        String source = selectedClassicServerName == null ? "" : selectedClassicServerName;
        if (source.isBlank()) return truncateLegacyText(id, 27);
        String result = id + "(" + source + ")";
        if (result.getBytes(Protocol.LEGACY_TEXT).length <= 27) return result;
        int idBytes = id.getBytes(Protocol.LEGACY_TEXT).length;
        if (idBytes + 2 >= 27) return truncateLegacyText(id, 27);
        return id + "(" + truncateLegacyText(source, 27 - idBytes - 2) + ")";
    }

    private static String truncateLegacyText(String value, int maximumBytes) {
        if (value == null || maximumBytes <= 0) return "";
        StringBuilder result = new StringBuilder();
        int bytes = 0;
        for (int offset = 0; offset < value.length();) {
            int codePoint = value.codePointAt(offset);
            String next = new String(Character.toChars(codePoint));
            int nextBytes = next.getBytes(Protocol.LEGACY_TEXT).length;
            if (bytes + nextBytes > maximumBytes) break;
            result.append(next);
            bytes += nextBytes;
            offset += Character.charCount(codePoint);
        }
        return result.toString();
    }

