    int battleWalkAction() {
        if (petRaceBaseGfx != 0) return BattleActionCodes.WALK;
        int walkAction = inventory.equippedWalkAction();
        if (!inventory.hasEquippedWeapon() && !sourceWeaponSuppressed) {
            SourceEquipmentPhysicalStats physical = sourceEquipmentMagicStats == null
                    ? SourceEquipmentPhysicalStats.none()
                    : sourceEquipmentMagicStats.physical();
            if (physical.weapon().present()) {
                walkAction = physical.weapon().walkAction();
            }
        }
        // Runtime equipment selects the canonical action family; the imported
        // spr_action table remains the final authority for this actor gfx.
        // The original 3.81 chain-sword path falls back to spear 24/25 when
        // the active sprite does not provide the later 83/84 family.
        BattlePolymorphCatalog.Form polymorph =
                polymorphStatus.active(System.nanoTime());
        if (polymorph != null) return polymorph.resolveBattleWalkAction(walkAction);
        return BattleAnimationCatalog.get().resolveEquippedWalkAction(
                battleGfx(), walkAction);
    }

    int battleMoveSpeed() {
        return timedStatus.speed(System.nanoTime()).type();
    }

    int battleLightRange() {
        int itemRange = inventory.activeLightRange();
        BattleSpellCatalog.LightSpell light = BattleSpellCatalog.lightSpell(
                BattleSpellCatalog.LIGHT);
        return timedStatus.lightActive(System.nanoTime())
                ? Math.max(itemRange, light.lightRange()) : itemRange;
    }

