    private boolean minimapAlliedWith(ClientSession subject) {
        if (observer || subject == this) return false;
        return minimapAlliedWithForce(hub.forceOf(currentRoomId, subject));
    }

    private boolean minimapAlliedWithForce(int subjectForce) {
        if (observer || !hub.roomRules(currentRoomId).teamBased() || subjectForce == 0) return false;
        int ownForce = hub.forceOf(currentRoomId, this);
        return ownForce != 0 && ownForce == subjectForce;
    }

    private void notifyBuddyPresence(Protocol.LitoBuddyPresence presence) {
        if (currentChannelId < 0 || selectedCharacter.isBlank()) return;
        boolean online = presence.online();
        Protocol.LitoBuddyActivity activity = online
                ? buddyActivityState() : Protocol.LitoBuddyActivity.OFFLINE;
        for (ClientSession recipient : hub.connectedSessionsSnapshot()) {
            if (recipient == this || recipient.currentChannelId < 0
                    || recipient.selectedCharacter.isBlank()
                    || !hub.setBuddyPresence(
                            recipient.sourceCharacterIdentity(), playerName(), online)) continue;
            try {
                recipient.sendEncrypted(Protocol.buddyLogin(playerName(), presence),
                        "S_LITO_BUDDY_LOGIN buddy=" + playerName()
                                + " presence=" + presence);
                recipient.sendEncrypted(Protocol.buddyStatus(playerName(), activity),
                        "S_LITO_BUDDY_CHANGE_STATUS buddy=" + playerName()
                                + " activity=" + activity);
            } catch (IOException error) {
                System.out.println("[LiTo] buddy presence broadcast failed recipient="
                        + recipient.playerName() + " buddy=" + playerName()
                        + ": " + error.getMessage());
            }
        }
        publishClanRosterState(online
                ? Protocol.LitoClanActivity.fromBuddy(buddyActivityState())
                : Protocol.LitoClanActivity.OFFLINE, "presence-" + presence.name());
    }

    private void notifyBuddyActivity(Protocol.LitoBuddyActivity activity) {
        Objects.requireNonNull(activity, "buddy activity");
        if (currentChannelId < 0 || selectedCharacter.isBlank()) return;
        for (ClientSession recipient : hub.connectedSessionsSnapshot()) {
            if (recipient == this || recipient.currentChannelId < 0
                    || recipient.selectedCharacter.isBlank()
                    || !hub.setBuddyActivity(
                            recipient.sourceCharacterIdentity(), playerName(), activity)) continue;
            try {
                recipient.sendEncrypted(Protocol.buddyStatus(playerName(), activity),
                        "S_LITO_BUDDY_CHANGE_STATUS buddy=" + playerName()
                                + " activity=" + activity);
            } catch (IOException error) {
                System.out.println("[LiTo] buddy activity broadcast failed recipient="
                        + recipient.playerName() + " buddy=" + playerName()
                        + ": " + error.getMessage());
            }
        }
        publishClanRosterState(Protocol.LitoClanActivity.fromBuddy(activity),
                "activity-" + activity.name());
    }

    private boolean updateLocalClanRosterState(Protocol.LitoClanActivity activity) {
        return hub.setClanRosterState(sourceCharacterIdentity(), 0, 0,
                classicTitle, activity);
    }

    /**
     * S_F6 is the reachable native roster refresh. The two smaller historical
     * clan-presence routines beside the receivers have no dispatcher entry in
     * this LiTo.bin, so state changes refresh S_F6 instead of inventing one.
     */
    private void publishClanRosterState(Protocol.LitoClanActivity activity, String reason) {
        if (selectedCharacter.isBlank()
                || !updateLocalClanRosterState(activity)) return;
        GameHub.ClanData clan = hub.clanData(sourceCharacterIdentity());
        if (clan.name().isBlank()) return;
        byte[] roster = Protocol.clanInfo(clan);
        for (ClientSession recipient : hub.connectedClanSessions(
                sourceCharacterIdentity())) {
            if (recipient == this) continue;
            try {
                recipient.sendEncrypted(roster,
                        "S_LITO_CLAN_INFO activity=" + activity + " member="
                                + playerName() + " reason=" + reason);
            } catch (IOException error) {
                System.out.println("[LiTo] clan activity refresh failed recipient="
                        + recipient.playerName() + " member=" + playerName()
                        + ": " + error.getMessage());
            }
        }
    }

    Protocol.LitoBuddyActivity buddyActivityState() {
        if (currentChannelId < 0 || selectedCharacter.isBlank()) {
            return Protocol.LitoBuddyActivity.OFFLINE;
        }
        return phase == Phase.BATTLE
                ? Protocol.LitoBuddyActivity.FIGHTING
                : Protocol.LitoBuddyActivity.WAITING;
    }

