    private volatile long nextBattleClockSyncNanos;
    private volatile boolean battleClockPublished;

    void serverSynchronizeBattleClock(long nowNanos) throws IOException {
        if (phase != Phase.BATTLE || currentRoomId == 0) { nextBattleClockSyncNanos = 0; battleClockPublished = false; return; }
        if (!battleClockPublished) return;
        if (nowNanos < nextBattleClockSyncNanos) return;
        nextBattleClockSyncNanos = nowNanos + 5_000_000_000L;
        sendEncrypted(new Protocol.Writer().c(Protocol.S_LITO_TIMELIMIT).d(0).bytes(),
                "S_LITO_TIMELIMIT periodic authoritative sync");
    }

    private void sendEncrypted(byte[] byArray, String string) throws IOException {
        if (NativeSourceEquipmentOutput.capture(this, byArray, string)) {
            return;
        }
        if (NativeSourceNpcHpOutput.capture(this, byArray, string)) {
            return;
        }
        if (NativeLightAction.deferSelfSend(this, byArray, string)) {
            return;
        }
        this.nativeSelfOriginalSend(byArray, string);
    }

    void sendEncryptedFrame(byte[] byArray, String string) throws IOException {
        NativeStaticNpcMotion.frame(this, byArray, string);
    }

    private static long ipv4LittleEndian(String address) throws IOException {
        InetAddress parsed = InetAddress.getByName(address);
        if (!(parsed instanceof Inet4Address)) throw new IOException("advertised.host must be IPv4");
        byte[] bytes = parsed.getAddress();
        return Integer.toUnsignedLong((bytes[0] & 0xFF) | ((bytes[1] & 0xFF) << 8)
                | ((bytes[2] & 0xFF) << 16) | ((bytes[3] & 0xFF) << 24));
    }

    private static String littleEndianIpv4(long value) {
        return (value & 0xFF) + "." + ((value >>> 8) & 0xFF) + "."
                + ((value >>> 16) & 0xFF) + "." + ((value >>> 24) & 0xFF);
    }

    private static String packetNote(byte[] payload) {
        if (payload.length == 0) return "empty";
        int opcode = payload[0] & 0xFF;
        String masked = CaptureLog.maskedClientPayload(opcode, payload);
        return masked == null ? String.format("C opcode 0x%02X", opcode)
                : masked.substring("MASKED_".length()) + " sensitive fields masked";
    }

    private static String mask(String value) {
        if (value == null || value.isEmpty()) return "***";
        return value.substring(0, 1) + "***";
    }


    void serverExpireArenaBotHaste(long now) throws IOException {
        if (phase != Phase.BATTLE || currentRoomId == 0
                || !hub.expireArenaBotHaste(currentRoomId, now)) return;
        for (ClientSession member : hub.roomMembers(currentRoomId)) {
            member.sendEncrypted(Protocol.speed(2, Protocol.SpeedMode.NORMAL, 0),
                    "S_SPEED ArenaBot haste expired");
        }
    }

