    boolean nativeCastLegacyWindShackleAction(int n, String string) {
        long l = System.nanoTime();
        BattleWindShackleStatus.Snapshot snapshot = this.windShackleStatus.snapshot(l);
        if (!snapshot.active()) {
            return true;
        }
        BattleAnimationCatalog.Animation animation = BattleAnimationCatalog.get().requireTimedAction(this.battleGfx(), n);
        boolean bl = this.windShackleStatus.tryAction(l, animation.durationMillis());
        if (!bl) {
            System.out.println("[LiTo] Wind Shackle action throttled player=" + this.playerName() + " operation=" + string + " gfx=" + this.battleGfx() + " action=" + n + " native-ms=" + animation.durationMillis() + " multiplier=1.25 remaining=" + snapshot.remainingSeconds());
        }
        return bl;
    }

