    void nativeSelfOriginalSend(byte[] byArray, String object) throws IOException {
        if (byArray.length != 0 && (byArray[0] & 0xFF) == 233 && this.currentRoomId != 0L) {
            int n;
            int n2 = n = this.phase == Phase.BATTLE || this.battleClockPublished ? this.hub.matchTimerSeconds(this.currentRoomId) : -1;
            if (n == 0) {
                return;
            }
            byArray = new Protocol.Writer().c(233).d(Math.max(0, n)).bytes();
            object = "S_LITO_TIMELIMIT authoritative remaining=" + n;
        }
        this.sendEncryptedFrame(byArray, (String)object);
        if (byArray.length != 0 && (byArray[0] & 0xFF) == 210) {
            this.battleClockPublished = true;
            this.nextBattleClockSyncNanos = System.nanoTime() + 5000000000L;
            this.sendEncrypted(new Protocol.Writer().c(233).d(0L).bytes(), "S_LITO_TIMELIMIT initial authoritative sync");
        }
    }

