    NativeDeItemTransaction.Change nativeDeGrantPeriodicItem(int n, int n2) throws IOException {
        InventoryCatalog.Definition definition = InventoryCatalog.find(n);
        if (definition == null || n2 <= 0) {
            throw new IOException("magic-doll periodic item has no runtime definition: " + n);
        }
        RuntimeInventory runtimeInventory = this.inventory;
        RuntimeInventory runtimeInventory2 = this.inventory.copy();
        if (!runtimeInventory2.add(definition, (long)n2)) {
            throw new IOException("magic-doll periodic item grant rejected: " + n + " x" + n2);
        }
        NativeDeItemTransaction.Change change = new NativeDeItemTransaction.Change(runtimeInventory, runtimeInventory2, definition);
        this.state.saveEconomyState(this.stateCharacter(), this.shopPoints, runtimeInventory2.catalogCounts(), runtimeInventory2.catalogItemStates());
        NativeDeItemApplication.replace(this, runtimeInventory2, 0);
        return change;
    }

    void nativeDeGrantAndPublishPeriodicItem(int n, int n2) throws IOException {
        NativeDeItemTransaction.Change change = NativeDeItemTransaction.grant(this, n, n2);
        InventoryCatalog.Definition definition = change.definition();
        RuntimeInventory runtimeInventory = change.previous();
        this.sendInventoryDelta(runtimeInventory, change.next());
        this.sendEncrypted(Protocol.messageCode(403, definition.name()), "S_MESSAGE_CODE magic-doll-periodic-item=403 catalog=" + n + " count=" + n2);
    }

