    static int nativeSourceCubeQuestCommitted(ClientSession clientSession, BattleQuestEncounter.Hit hit, int n, String string, int n2, NativeSourceCubeNpc.Commit commit) throws IOException {
        BattleQuestEncounter.Damage damage = hit.damage();
        BattleQuestEncounter.Snapshot snapshot = damage.after();
        List<ClientSession> list = NativeSourceCubeNpc.recipients(NativeSourceCubeNpc.hub(clientSession, commit), NativeSourceCubeNpc.room(clientSession, commit), snapshot.force(), commit);
        byte[] byArray = NativeBattleTamedLifecycle.visualHitRatio(snapshot.objectId(), snapshot.hp(), snapshot.maxHp());
        for (ClientSession clientSession2 : list) {
            NativeSourceCubeNpc.send(clientSession2, byArray, "S_HIT_RATIO quest-monster=" + snapshot.objectId() + " force=" + snapshot.force() + " room=" + snapshot.roomNumber() + " hp=" + snapshot.hp() + "/" + snapshot.maxHp() + " source=" + string, commit);
            if (!damage.diedNow()) continue;
            if (n > 0) {
                NativeSourceCubeNpc.send(clientSession2, Protocol.poison(snapshot.objectId(), 0), "S_POISON quest-monster=" + snapshot.objectId() + " type=0 reason=death", commit);
            }
            NativeSourceCubeNpc.send(clientSession2, Protocol.objectAction(snapshot.objectId(), 8), "S_ACTION quest-monster=" + snapshot.objectId() + " action=8 source=" + string, commit);
        }
        if (damage.diedNow()) {
            NativeSourceCubeNpc.cancel(NativeSourceCubeNpc.hub(clientSession, commit), NativeSourceCubeNpc.room(clientSession, commit), snapshot.objectId(), commit);
            NativeSourceCubeNpc.lawful(clientSession, snapshot.npcId(), "quest-" + string, commit);
        }
        if (hit.waveCleared()) {
            ClientSession.nativeSourceCubeQuestWaveAdvance(clientSession, snapshot.force(), hit.clearedRoom(), hit.spawned(), hit.objectiveUnlocked(), string, commit);
        }
        System.out.println("[LiTo] Quest monster damaged room=" + NativeSourceCubeNpc.room(clientSession, commit) + " attacker=" + NativeSourceCubeNpc.name(clientSession, commit) + " object=" + snapshot.objectId() + " force=" + snapshot.force() + " quest-room=" + snapshot.roomNumber() + " damage=" + n2 + " hp=" + snapshot.hp() + "/" + snapshot.maxHp() + " died=" + damage.diedNow() + " wave-cleared=" + hit.waveCleared() + " objective-unlocked=" + hit.objectiveUnlocked() + " source=" + string);
        return Math.max(0, damage.before().hp() - damage.after().hp());
    }

